        public void ReloadErrorStrings()
        {
            if (formulaErrorStrings == null)
            {
                formulaErrorStrings = new ArrayList();
            }

            formulaErrorStrings.Clear();
            formulaErrorStrings.AddRange(FormulaErrorStrings);
        }

