        #region Constructors
        /// <summary>
        /// The constructor.
        /// </summary>
        /// <param name="ParentObject">The ICalcData from the underlying grid.</param>
        public CalcEngine(ICalcData ParentObject)
        {
#if !SILVERLIGHT && !WINDOWS_UWP && !WP && !NET_STANDARD
            if (Utilities.IsSecurityPermissionAvailable())
            {
                Utilities.ValidateLicense(typeof(CalcEngine));
            }
#endif

            ////set up ICalcData object
            this.grid = ParentObject;
            this.grid.WireParentObject();
            this.grid.ValueChanged += new ValueChangedEventHandler(this.grid_ValueChanged);

            ////other initializations
            this.InitLibraryFunctions();

            this.tokens = new char[]
            {
                TOKEN_add,
						TOKEN_subtract,
						TOKEN_multiply,
						TOKEN_divide,
						TOKEN_less,
						TOKEN_greater,
						TOKEN_equal,
						TOKEN_lesseq,
						TOKEN_greatereq,
						TOKEN_noequal,
						TOKEN_and,
						TOKEN_or
						};

            this.dateTime1900Double = 
#if WINDOWS_UWP
                Syncfusion.XlsIO.Implementation.DateTimeExtension.ToOADate(dateTime1900);
#else
                dateTime1900.ToOADate();
#endif
            this.refreshedCells = new Hashtable();
            this.formulaErrorStrings = new ArrayList(this.FormulaErrorStrings.Length);
            this.formulaErrorStrings.AddRange(this.FormulaErrorStrings);
        }

        ////needed to avoid problem with ASP.NET
        static CalcEngine()
        {
            formulaChar = '=';
        }
        #endregion

