        /// The default is 50. This is the number of recursive calls that can be made during calculations.</remarks>
        public static int MaxStackDepth
        {
            get
            {
                ////DT 26058 incident
                ////handle problems with threading by dynamically assigning the static values
                if (maxStackDepth == 0)
