        private Hashtable namedRangesNonScoped;
        /// <summary>
        /// A property that gets/sets the current named ranges.
        /// </summary>
        public Hashtable NamedRanges
        {
            get
            {
                if (this.namedRanges == null)
                {
                    this.namedRanges = new Hashtable();
                    namedRangesNonScoped = new Hashtable();
                }

                return this.namedRanges;
            }

            set
            {
                this.namedRanges = value;
                PopulateNamedRangesNonScoped();
            }
        }

        private void PopulateNamedRangesNonScoped()
        {
            if (this.namedRangesNonScoped == null)
            {
                this.namedRangesNonScoped = new Hashtable();
            }
            namedRangesNonScoped.Clear();
            
            foreach (string key in NamedRanges.Keys)
            {
                CheckAddNonScopedNamedRange(key);
            }
        }

        private void CheckAddNonScopedNamedRange(string key)
        {
            int loc = -1;
            if ((loc = key.IndexOf('!')) > -1)
            {
                string key1 = key.Substring(loc + 1);
                if (!this.namedRangesNonScoped.ContainsKey(key1))
                {
                    namedRangesNonScoped.Add(key1, NamedRanges[key]);
                }
            }
            
        }

