        private static void besselmfirstcheb(double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b0 = c;
            b1 = 0.0;
            b2 = 0.0;
        }

        private static void besselmnextcheb(double x,
           double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b2 = b1;
            b1 = b0;
            b0 = x * b1 - b2 + c;
        }

        private static void besselm1firstcheb(double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b0 = c;
            b1 = 0.0;
            b2 = 0.0;
        }

        private static void besselm1nextcheb(double x,
           double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b2 = b1;
            b1 = b0;
            b0 = x * b1 - b2 + c;
        }

        #region Stats Timer Code
#if _ENABLETIMERS

        public Hashtable t_timeMarks = new Hashtable();
        public Hashtable t_timeStats = new Hashtable();

        public void MarkTimeStart(string code)
        {
            if (!t_timeMarks.ContainsKey(code))
            {
                t_timeMarks.Add(code, DateTime.Now);
            }
            else
                t_timeMarks[code] = DateTime.Now;
        }

        public void MarkTimeEnd(string code)
        {
            if (!t_timeStats.ContainsKey(code))
            {
                t_timeStats.Add(code, new TimeSpan(0));
            }
            t_timeStats[code] = (TimeSpan)t_timeStats[code] + (DateTime.Now - (DateTime)t_timeMarks[code]);
        }

        public void DisplayTimeMarks(string mainProcess)
        {
            double totalTime = t_timeStats.ContainsKey(mainProcess) ? ((TimeSpan)t_timeStats[mainProcess]).TotalSeconds : 0;

             DataTable dt = new DataTable();
            dt.Columns.Add(new DataColumn("key"));
            dt.Columns.Add(new DataColumn("value", typeof(TimeSpan)));
            foreach (string s in t_timeStats.Keys)
            {
                dt.Rows.Add(new object[] { s, t_timeStats[s] });
            }

            dt.DefaultView.Sort = "value desc";

            Console.WriteLine();
            Console.WriteLine("______________________");
            foreach (DataRowView dr in dt.DefaultView)
            {
                double secs = ((TimeSpan)dr["value"]).TotalSeconds;
                if (totalTime > 0)
                {
                    Console.WriteLine("{0} {1:F3} secs ({2:F2}%)", (dr["key"].ToString() + new string(' ', 15)).Substring(0, 20), secs, 100 * secs / totalTime);
                }
                else
                {
                    Console.WriteLine("{0} {1:F3} secs", (dr["key"].ToString() + new string(' ', 15)).Substring(0, 20), secs);
                }
            }
            Console.WriteLine("---------------------");
            Console.WriteLine();
        }
#endif
