        ////Maintains a list of cells that a formula cell is dependent upon.
        private void AddToFormulaDependentCells(string s)
        {
            string cell1 = this.cell;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            if (family.SheetNameToParentObject != null && cell1.IndexOf(sheetToken) == -1)
#else
            if (family.ParentObjectToToken != null && family.ParentObjectToToken.ContainsKey(this.grid) && cell1.IndexOf(sheetToken) == -1)
#endif
            {
                string token = family.ParentObjectToToken[this.grid] as string;
                cell1 = token + cell1;
            }

            if (!DependentFormulaCells.ContainsKey(cell1))
            {
                this.DependentFormulaCells.Add(cell1, new Hashtable());
                ((Hashtable)DependentFormulaCells[cell1]).Add(s, s);
            }
            else if (!((Hashtable)DependentFormulaCells[cell1]).ContainsKey(s))
            {
                ((Hashtable)DependentFormulaCells[cell1]).Add(s, s);
            }
        }

        /// <summary>
        /// Accepts a possible parsed formula and returns the calculated value
        /// without quotes.
        /// </summary>
        /// <param name="range">The argument to be adjusted.</param>
        /// <remarks>
        /// This method is useful in custom functions if you want to allow
        /// your custom functions to handle parsed formulas as arguments. In
        /// this case, calling this method at the beginning of your custom function
        /// will allow you custom function to work only with computed values, and not
        /// have to handle parsed formulas directly.
        /// </remarks>
        public void AdjustRangeArg(ref string range)
        {
            if (range.Length > 1 && range[0] == BMARKER
                && range[range.Length - 1] == BMARKER
                && range.Substring(1, range.Length - 2).IndexOf(BMARKER) == -1)
            {
                range = this.ComputedValue(range);
            }

            if (range.Length > 1 && range[0] == this.TIC[0] &&
                range[range.Length - 1] == this.TIC[0])
            {
                range = range.Substring(1, range.Length - 2);
            }
        }

        private double binomdist(int trials, int successes, double p)
        {
            double pPow = 1;
            double pm1 = 1 - p;

            double p1Pow = Math.Pow(pm1, trials);

            double dist = 0;
            double cbn = pPow * Math.Pow(pm1, trials);
            if (cbn == 0)
            {
                return double.NaN;
            }

            for (int i = 0; i <= successes; ++i)
            {
                dist += cbn;
                cbn = cbn * p / pm1 * (trials - i) / (i + 1);
                if (double.IsInfinity(cbn) || double.IsNaN(cbn))
                {
                    dist = double.NaN;
                    break;
                }
            }

            return dist;
        }

        private bool CheckUnderTolerance(double d, double oldValue)
        {
            if (Math.Abs(oldValue) > this.ABSOLUTEZERO)
            {
                return Math.Abs((d - oldValue) / oldValue) < this.iterationMaxTolerance;
            }
            else
            {
                return Math.Abs(d - oldValue) < this.iterationMaxTolerance;
            }
        }

        ////uses guass quad to estimate the integral
        private double chidist(double x, double v)
        {
            double ex = v / 2;
            double mult = 1 / (Math.Pow(2, ex) * Math.Exp(this.gammaln(ex)));
            ex = ex - 1;

            double a = 0;
            double b = x;

             double midPt = (a + b) / 2;
            double radius = (b - a) / 2;

            double sum = 0;

            double offset;
            for (int i = 0; i < gauss_n; ++i)
            {
                offset = gauss_x[i] * radius;
                sum = sum + gauss_w[i] * (Math.Pow(midPt + offset, ex) * Math.Exp(-(midPt + offset) / 2)
                                            + Math.Pow(midPt - offset, ex) * Math.Exp(-(midPt - offset) / 2));
            }

            sum = mult * sum * radius;
            return sum;
        }

        private double chiinv(double p, double v)
        {
            double guess = p; ////Math.Sqrt(p);

            double lastIncrement = guess / 2;
            double gi = 0;
            double eps = 1e-7;
            int k = 100;
            int tries = 3;
            while (k == 100 && tries > 0)
            {
                tries--;
                guess = guess / 2;
                lastIncrement = guess / 2;

                for (k = 0; k < 100; ++k)
                {
                    gi = 1 - this.chidist(guess, v);
                    if (Math.Abs((gi - p) / p) < eps)
                    {
                        break;
                    }

                    if (gi > p)
                    {
                        guess += lastIncrement;
                    }
                    else
                    {
                        lastIncrement = lastIncrement / 2;
                        if (guess - lastIncrement < 0)
                        {
                            lastIncrement = guess / 2;
                        }

                        guess -= lastIncrement;
                    }
                }
            }

            if (k == 100)
            {
                guess = -1;
            }

            return guess;
        }

        ////When a formula cell changes, call this method to clear it from its dependent cells.
        internal void ClearFormulaDependentCells(string cell)
        {
            Hashtable ht = (Hashtable)this.DependentFormulaCells[cell];
            if (ht != null)
            {
                foreach (object o in ht.Keys)
                {
                    string s = o as string;
                    ArrayList al = this.DependentCells[s] as ArrayList;
                    al.Remove(cell);
                    if (al.Count == 0)
                    {
                        this.DependentCells.Remove(s);
                    }
                }

                this.DependentFormulaCells.Remove(cell);
            }
        }

