        /// <summary>
        /// The inverse of Cosh.
        /// </summary>
        /// <param name="args">Value >= 1.</param>
        /// <returns>Result of ACosh(value).</returns>
        public string ComputeAcosh(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeAcosh"; MarkTimeStart(ML);
#endif
            double z;
            string value =this.GetValueFromArg(args);
            if (ErrorStrings.Contains(value.Replace(this.TIC,"")))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return value;
            }
            if (!double.TryParse(value, NumberStyles.Any, null, out z))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            else if (z >= 1)
            {
                z = Math.Log(z + Math.Sqrt(z * z - 1));
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return z.ToString();
        }

        /// <summary>
        /// Returns the And of all values treated as logical values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers. Each item in the list is considered True if it is nonzero
        /// and False if it is zero.</param>
        /// <returns>A string holding the And of all values listed in the argument.</returns>
        public string ComputeAnd(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeAnd"; MarkTimeStart(ML);
#endif
            bool sum = true;
            string s1;
            double d;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                if (SplitArguments(r, ':').Length > 1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if (s.Equals("#VALUE!"))
                            return s;
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                            if (s1.Equals("#VALUE!"))
                                return s1;
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        sum &= s1.Equals(string.Empty)? bool.Parse(this.TRUEVALUESTR) : ((s1 == this.TRUEVALUESTR) ||
                               double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d);
                    }
                }
                else
                {
                    if (r.Equals("#VALUE!"))
                        return r;
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                        if(s1.Equals("#VALUE!"))
                            return s1;
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    sum &= (s1 == this.TRUEVALUESTR) ||
                               double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum ? this.TRUEVALUESTR : FALSEVALUESTR;
        }

        /// <summary>
        /// Computes angle whose sine is the argument.
        /// </summary>
        /// <param name="args">A cell reference, formula, or number.</param>
        /// <returns>A string holding an angle whose sine is the argument.</returns>
        public string ComputeAsin(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeAsin"; MarkTimeStart(ML);
            string v = ComputeMath(args, new MathFunc(Math.Asin)).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return this.ComputeMath(args, new MathFunc(Math.Asin)).ToString();
#endif
        }

        /// <summary>
        /// The inverse of Sinh.
        /// </summary>
        /// <param name="args">The given value.</param>
        /// <returns>Result of ASinh(value).</returns>
        public string ComputeAsinh(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeAsinh"; MarkTimeStart(ML);
#endif
            double z;
            if (double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out z))
            {
                z = Math.Sign(z) * Math.Log(Math.Abs(z) + Math.Sqrt(z * z + 1));
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return z.ToString();
        }

