        /// <summary>
        /// The ArcTangent of the x and y values.
        /// </summary>
        /// <param name="argList">x_value and y_value.</param>
        /// <returns>Angle whose tangent is y_value/x_value.</returns>
        public string ComputeAtan2(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeAtan2"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_2_args];
            }

            double x;
            double y = 0;
            double atan2 = 0;
            if (!(double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out x)
                && double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out y)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            else if (y == 0 && x == 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[3].ToString();
            }
            atan2 = Math.Atan2(y, x);
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return atan2.ToString();
        }

        /// <summary>
        /// The inverse of Tanh.
        /// </summary>
        /// <param name="args">|Value| &lt; 1.</param>
        /// <returns>Result of ATanh(value).</returns>
        public string ComputeAtanh(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeAtanh"; MarkTimeStart(ML);
#endif
            double z;
            double z1;
            if (!double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out z))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            else if ((z1 = Math.Abs(z)) < 1)
            {
                z = .5 * Math.Sign(z) * Math.Log((1 + z1) / (1 - z1));
            }
            else
            {

#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif

                return this.ErrorStrings[4].ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return z.ToString();
        }

        /// <summary>
        /// Returns the average deviation of all values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>A string holding the average deviation of all values listed in the argument.</returns>
        public string ComputeAvedev(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeAvedev"; MarkTimeStart(ML);
#endif
            double sum = 0;
            string s1;
            double d;
            ArrayList x = new ArrayList();

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Any, null, out d))
                            {
                                sum = sum + d;
                                x.Add(d);
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            sum = sum + d;
                            x.Add(d);
                        }
                        else if (this.ErrorStrings.Contains(s1))
                        {
                            return s1;
                        }
                    }
                }
            }

            if (x.Count > 0)
            {
                double ave = sum / x.Count;
                sum = 0;
                for (int i = 0; i < x.Count; ++i)
                {
                    sum += Math.Abs(((double)x[i]) - ave);
                }

                sum = sum / x.Count;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

