        /// <summary>
        /// Returns the binomial distribution.
        /// </summary>
        /// <param name="argList">Number of successes, number of trials, probability, cumulative.</param>
        /// <returns>The binomial distribution.</returns>
        public string ComputeBinomdist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeBinomdist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double successes;
            double trials;
            double p;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out successes)
                && double.TryParse(args[1], NumberStyles.Any, null, out trials)
                && double.TryParse(args[2], NumberStyles.Any, null, out p))
            {
                cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                if (cum == 0)
                {
                    dist = this.comb((int)successes, (int)trials) * Math.Pow(p, successes) * Math.Pow(1 - p, trials - successes);
                }
                else
                {
                    dist = this.binomdist((int)trials, (int)successes, p);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Computes the smallest whole number greater than or equal to the argument.
        /// </summary>
        /// <param name="args">A cell reference, formula, or number.</param>
        /// <returns>A string holding the smallest whole number greater than or equal to the argument.</returns>
        public string ComputeCeiling(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeCeiling"; MarkTimeStart(ML);
#endif
            string[] range = SplitArgsPreservingQuotedCommas(args);
            int argCount = range.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double d1, d2, d3 = 0;
            if (double.TryParse(this.GetValueFromArg(range[0]), NumberStyles.Any, null, out d1)
                && double.TryParse(this.GetValueFromArg(range[1]), NumberStyles.Any, null, out d2))
            {
                if (d1 == 0)
                    return d3.ToString();
                if (d2 <= 0)
                {
                    if (excelLikeComputations)
                    {
                        if (d1 * d2 == 0)
                            return "0";
                        return "#NUM!";
                    }
                       // return 
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                d3 = Math.Floor(d1 / d2) * d2;
                if (d2 > 0)
                {
                    while (d3 < d1)
                    {
                        d3 += d2;
                    }
                }
                else
                {
                    while (d3 > d1)
                    {
                        d3 += d2;
                    }
                }
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif

            return d3.ToString();
        }

        /// <summary>
        /// Returns the character whose number code is specified in the argument.
        /// </summary>
        /// <param name="arg">The number used to retrieve the character.</param>
        /// <returns>The character string.</returns>
        public string ComputeChar(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeChar"; MarkTimeStart(ML);
#endif
            string[] range = SplitArgsPreservingQuotedCommas(arg);
            int argCount = range.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string s = this.GetValueFromArg(range[0]);
            int i;
            if (int.TryParse(s, out i) && i > 0 && i < 256)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return ((char)i).ToString();
            }
            if(this.ErrorStrings.Contains(s))
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(s);
                return s;
#endif
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return "#VALUE!";
        }

        /// <summary>
        /// Returns the chi-squared distribution.
        /// </summary>
        /// <param name="argList">x, degrees of freedom.</param>
        /// <returns>The chi-squared distribution.</returns>
        public string ComputeChidist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeChidist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double v;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out v))
            {
                if (v == 1 && excelLikeComputations)
                {
                    //continue;
                }
                else if (v < 1)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    if (excelLikeComputations)
                        return "#NUM!";
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                dist = 1 - this.chidist(x, v);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif

            return dist.ToString();
        }

