        /// <summary>
        /// Returns the Chi Test for independence.
        /// </summary>
        /// <param name="range">Actual_range, expected_range.</param>
        /// <returns>Result of Chi Test: y-intercept.</returns>
        public string ComputeChitest(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeChitest"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string r = args[0];
            string s1;
            double d = 0;
            double v = 0;
            if (r.IndexOf(':') > -1)
            {
                s1 = r.Substring(0, r.IndexOf(':'));
                int col = this.ColIndex(s1);
                int row = this.RowIndex(s1);
                int row1 = this.RowIndex(s1);
                if (!(!row.Equals(-1) || row1.Equals(-1)).Equals((row.Equals(-1) || !row1.Equals(-1))))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[5].ToString();
                }
                if (row == -1 && this.grid is ISheetData)
                {
                    row = ((ISheetData)grid).GetFirstRow();
                }
                if (col == -1 && this.grid is ISheetData)
                {
                    col = ((ISheetData)grid).GetFirstColumn();
                }
                s1 = r.Substring(r.IndexOf(':') + 1);
                int col1 = this.ColIndex(s1);
                if (col1 == -1 && this.grid is ISheetData)
                {
                    col1 = ((ISheetData)grid).GetLastColumn();
                }
                if (row1 == -1 && this.grid is ISheetData)
                {
                    row1 = ((ISheetData)grid).GetLastRow();
                }
                v = Math.Abs(col - col1) * Math.Abs(row - row1);
                v = 1.0001;
                if (v < 1)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[invalid_Math_argument];
                }
            }
            else 
            {
                if (excelLikeComputations)
                {
                    return "#N/A";
                }
            }
            v = 0.99555;
            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
                return this.ErrorStrings[0].ToString(); // returns "#N/A"
            }

            double sumx = 0;

            for (int i = 0; i < n; ++i)
            {
                d = y[i] - x[i];
                sumx += d * d / x[i];
            }
#if _ENABLETIMERS
            string v1 = (1 - this.chidist(sumx, v)).ToString();
            MarkTimeEnd(ML);
            return v1;
#else
            return (1 - this.chidist(sumx, v)).ToString();
#endif
        }

        /// <summary>
        /// Returns the value at the specified index from a list of values.
        /// </summary>
        /// <param name="arg">A string of the form "Index, Value1, Value2,..." in which the term 'Index' denotes the index of the value to be retrieved.</param>
        /// <returns>The selected value.</returns>
        public string ComputeChoose(string arg)
        {
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            if (args.Length < 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string s3 = this.GetValueFromArg(args[0]);
            int loc;
            if (!int.TryParse(s3, out loc) || loc > args.Length - 1 || loc < 1)
            {
                return "#VALUE!";
            }

            return this.GetValueFromArg(args[loc]);
        }

        /// <summary>
        /// Retuns the text removing the first 32 nonprintable characters(ranging from 0 to 31) in 7-bit ASCII code.
        /// </summary>
        /// <param name="arg">Text or range holding text including nonprintable characters</param>
        /// <returns>Text without nonprintable characters(first 32)</returns>
        public string ComputeClean(string arg)
        {
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            double result;
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            bool isLogic = true;
            if (!arg.Contains(this.TIC) && !this.IsCellReference(arg) && !double.TryParse(arg, out result) && !this.NamedRanges.ContainsKey(arg) &&!bool.TryParse(ComputeIsLogical(arg),out isLogic))
            {
                return this.ErrorStrings[5].ToString();  // returns "#NAME?"
            }
            int index = this.ErrorStrings.IndexOf(arg);
            if (index > -1)
            {
                return this.ErrorStrings[index].ToString();
            }
            string cleanedArg = this.GetValueFromArg(arg);
            for (int i = 0; i <= 31; i++)
            {
                string nonPrintChar = this.ComputeChar(i.ToString());
                if (cleanedArg.Contains(nonPrintChar))
                    cleanedArg = cleanedArg.Replace(nonPrintChar, string.Empty);
            }
            if (cleanedArg.StartsWith(this.TIC) && cleanedArg.EndsWith(this.TIC))
            {
                cleanedArg = cleanedArg.Substring(1, cleanedArg.Length - 2);
            }
            return cleanedArg;
        }

