        /// <summary>
        /// The number of combinations of a given number of items.
        /// </summary>
        /// <param name="argList">Number, number_items.</param>
        /// <returns>The number of combinations.</returns>
        public string ComputeCombin(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeCombin"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_2_args];
            }

            ////N things taken k at the time.
            double nd;
            double kd;
            double combin = 0;
            if (double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out nd)
                && double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out kd))
            {
                int k = (int)(kd + 0.1);
                int n = (int)(nd + 0.1);
                if (n < k && excelLikeComputations)
                {
                    return "#NUM!";
                }
                combin = this.comb(k, n);
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return combin.ToString();
        }

