        /// <summary>
        /// Returns a single character string.
        /// </summary>
        /// <param name="range">List of strings to be concatenated.</param>
        /// <returns>A single string.</returns>
        public string ComputeConcatenate(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeConcatenate"; MarkTimeStart(ML);
#endif
            string text = string.Empty;
            System.Text.StringBuilder sb = new System.Text.StringBuilder(this.TIC);

            string[] ar = this.IsSeparatorInTIC(range) ////range.IndexOf(TIC) > 0
                          ? this.GetStringArray(range) : SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ar)
            {
                string toAppend = r;
                if (r == string.Empty || r[0] != this.TIC[0])
                {
                    toAppend = this.GetValueFromArg(r);
                }

                if (sb.Length > 1 && sb[sb.Length - 1] == this.TIC[0])
                {
                    sb.Length--;
                }

                if (toAppend.Length > 0 && toAppend[0] == this.TIC[0])
                {
                    sb.Append(toAppend.Substring(1));
                }
                else
                {
                    sb.Append(toAppend);
                }
            }

            if (sb[sb.Length - 1] != this.TIC[0])
            {
                sb.Append(this.TIC);
            }

            text = sb.ToString();
            if (text.IndexOf("#N/A") > -1)
            {
                text = "#N/A";
            }

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            if (excelLikeComputations)
            {
                string newText = text.Substring(text.IndexOf(this.TIC) + 1, text.LastIndexOf(this.TIC) - 1);
                return newText;
            }
            return text;
        }

        /// <summary>
        /// Returns a confidence interval radius.
        /// </summary>
        /// <param name="argList">Alpha, standard deviation, size.</param>
        /// <returns>Returns x such that normal distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeConfidence(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeConfidence"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double alpha;
            double s;
            double sz;
            double val = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out alpha)
                && double.TryParse(args[1], NumberStyles.Any, null, out s)
                && double.TryParse(args[2], NumberStyles.Any, null, out sz))
            {
                //// 1 - alpha  would be from -inf to 1-alpha. adding alpha + 2
                //// takes away the left tail making the integral from alpha-1 to 1-alpha.
                if (!ExcelLikeComputations)
                    val = this.normalinv(1 - alpha + alpha / 2, 0, 1);
                else
                    val = this.newnormalinv(1 - alpha + alpha / 2);
                val = val * s / Math.Sqrt(sz);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif

            return val.ToString();
        }

        /// <summary>
        /// Returns the correlation coefficient of the two sets of points.
        /// </summary>
        /// <param name="range">range1, range2.</param>
        /// <returns>Correlation coefficient.</returns>
        public string ComputeCorrel(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeCorrel"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);
            if (n <= 0 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumxb2 = 0;
            double sumyb2 = 0;
            double xb = 0;
            double yb = 0;

            for (int i = 0; i < n; ++i)
            {
                xb = x[i] - sumx;
                yb = y[i] - sumy;
                sumxy += xb * yb;
                sumxb2 += xb * xb;
                sumyb2 += yb * yb;
            }

#if _ENABLETIMERS
            string v = (sumxy / Math.Sqrt(sumxb2 * sumyb2)).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return (sumxy / Math.Sqrt(sumxb2 * sumyb2)).ToString();
#endif
        }

