        /// <summary>
        /// Counts the cells specified by some criteria.
        /// </summary>
        /// <param name="argList">The criteria range, the criteria.</param>
        /// <returns>Number of cells meeting the criteria.</returns>
        public string ComputeCountif(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeCountIF"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            double cellCount = 0;
            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                {
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                }
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string criteriaRange = args[0];
            string criteria = args[1];
            if (criteria.Length < 1)
            {
                return "0";
            }
            char op = TOKEN_equal;
            if (criteria[0] != this.TIC[0] && "=><".IndexOf(criteria[0]) == -1)
            {
                ////cell reference
                criteria = this.GetValueFromArg(criteria);
            }

            int offset = (criteria.Length > 0 && criteria[0] == this.TIC[0]) ? 1 : 0;
            double compare = double.MinValue;
            if (criteria.Substring(offset).StartsWith(">="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_greatereq;
            }
            else if (criteria.Substring(offset).StartsWith("<="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_lesseq;
            }
            else if (criteria.Substring(offset).StartsWith("<>"))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_noequal;
            }
            else if (criteria.Substring(offset).StartsWith("<"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_less;
            }
            else if (criteria.Substring(offset).StartsWith(">"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_greater;
            }
            else if (criteria.Substring(offset).StartsWith("="))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
            }

            criteria = criteria.Replace(this.TIC, string.Empty);
            bool numer = double.TryParse(criteria, out compare);
            string[] s1 = this.GetCellsFromArgs(criteriaRange);
            if (s1[0].Equals(this.ErrorStrings[5]))
            {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                {
                    throw new ArgumentException(this.FormulaErrorStrings[bad_index]);
                }
                return this.ErrorStrings[5].ToString();
            }
            int count = s1.GetLength(0);
            double sum = 0, d;
            string s;
            switch (op)
            {
                case TOKEN_equal:
                    {
                        if (criteria.Contains("*"))
                        {
                            int index1 = criteria.IndexOf("*");
                            criteria = criteria.Substring(0, index1);
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

                                if (!string.IsNullOrEmpty(s) && (s.Replace(this.TIC, string.Empty).Substring(0, index1) == criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d == compare)))
                                {
                                    cellCount++;
                                }
                            }
                        }
                        else
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

                                if (s.Replace(this.TIC, string.Empty) == criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d == compare))
                                {
                                    cellCount++;
                                }
                            }
                    }
                    break;
                case TOKEN_noequal:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;

                            if (s.Replace(this.TIC, string.Empty) != criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d != compare))
                            {
                                cellCount++;
                            }
                        }
                    }
                    break;
                case TOKEN_greatereq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d >= compare)
                                {
                                    cellCount++;
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_greater:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d > compare)
                                {
                                    cellCount++;
                                }
                            }
                        }
                    }
                    break;
                case TOKEN_less:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d < compare)
                                {
                                    cellCount++;
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_lesseq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d <= compare)
                                {
                                    cellCount++;
                                }
                            }
                        }
                    }

                    break;
                default:
                    break;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return cellCount.ToString();
        }

        /// <summary>
        /// Returns the covariance between the two sets of points.
        /// </summary>
        /// <param name="range">range1, range2.</param>
        /// <returns>The covariance.</returns>
        public string ComputeCovar(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeCovar"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;

            for (int i = 0; i < n; ++i)
            {
                sumxy += (x[i] - sumx) * (y[i] - sumy);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return (sumxy / n).ToString();
        }

        /// <summary>
        /// Returns the smallest value for which the cumulative binomial distribution is greater than or equal to a criterion value.
        /// </summary>
        /// <param name="argList">Number of trials, probability, alpha.</param>
        /// <returns>Returns the critical value.</returns>
        public string ComputeCritbinom(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeCritbinom"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double trials;
            double p;
            double alpha = 0;
            int dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out trials)
                && double.TryParse(args[1], NumberStyles.Any, null, out p)
                && double.TryParse(args[2], NumberStyles.Any, null, out alpha))
            {
                if (p > 0 && p < 1 && alpha > 0 && alpha < 1)
                {
                    dist = this.critbinom((int)trials, p, alpha);
                    if (dist == int.MaxValue)
                    {
#if _ENABLETIMERS
