            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.wrong_number_arguments];
            }

            double year;
            double month=0;
            double day=0;
            int days = 0;
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out year)
                && double.TryParse(args[1], NumberStyles.Any, null, out month)
                && double.TryParse(args[2], NumberStyles.Any, null, out day))
            {
                if (year < 1)
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
#endif
                }
                while (month > 12)
                {
                    month -= 12;
                    year++;
                }

                days = this.GetSerialDateFromDate((int)year, (int)month, (int)day);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            if (excelLikeComputations)
            {
                DateTime result;
                if (DateTime.TryParse(year.ToString() + "/" + month.ToString() + "/" + day.ToString(), out result))
                {
                    return 
#if SILVERLIGHT || WINDOWS_UWP
                    result.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern);
#else
                    result.ToShortDateString();
#endif
                }
            }
            return days.ToString();            
        }

        /// <summary>
        /// Returns the number of days since 01 Jan 1900.
        /// </summary>
        /// <param name="argList">Text containing a date.</param>
        /// <returns>Number of days.</returns>
        public string ComputeDatevalue(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeDatevalue"; MarkTimeStart(ML);
#endif
            argList = argList.Replace(this.TIC, string.Empty);
            DateTime dt;
            try
            {
                if (!DateTime.TryParse(argList, CultureInfo.CurrentCulture, DateTimeStyles.None, out dt))
                {
                    string[] ranges = argList.Split(ParseDateTimeSeparator);
                    int argCount = ranges.GetLength(0);
                    string arg = string.Empty;
                    for (int i = 0; i < argCount; ++i)
                    {
                        ranges[i] = this.ComputedValue(ranges[i]);
                        if (i < argCount - 1)
                            arg += ranges[i] + ParseDateTimeSeparator;
                        else
                            arg += ranges[i];
                    }
                    arg = arg.Replace(TIC, string.Empty);
                    dt = DateTime.Parse(arg);
                }
                
            }
            catch
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            int days = 1 + ((TimeSpan)(dt - this.dateTime1900)).Days;
            if (Treat1900AsLeapYear && days > 59)
            {
                days += 1;
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return days.ToString();
        }

