        /// <summary>
        /// Number of days between 2 dates using 360 day year.
        /// </summary>
        /// <param name="argList">Serial number date1, serial number date1 and method.</param>
        /// <returns>Days between the dates.</returns>
        public string ComputeDays360(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeDays360"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double serialdate1;
            double serialdate2;
            bool method = false;
            int days = 0;
            DateTime dt1 = this.dateTime1900, dt2 = this.dateTime1900;
            if ((double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out serialdate1) || DateTime.TryParse(this.GetValueFromArg(args[0]).Replace(this.TIC,string.Empty),CultureInfo.CurrentCulture,DateTimeStyles.None,out dt1))
                && (double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out serialdate2) || DateTime.TryParse(this.GetValueFromArg(args[1]).Replace(this.TIC, string.Empty), CultureInfo.CurrentCulture, DateTimeStyles.None, out dt2))
                && (argCount == 2 || (method = (args[2] == this.TRUEVALUESTR))))
            {
                dt1 = (serialdate1 > 0) ? this.GetDateFromSerialDate((int)serialdate1) : dt1;
                dt2 = (serialdate2 > 0) ? this.GetDateFromSerialDate((int)serialdate2) : dt2;
                bool flipSign = false;
                if (dt1.Day == 31)
                {
                    dt1 = dt1.AddDays(-1);
                }

                if (dt2.Day == 31 && !method && dt1.Day < 30)
                {
                    dt2 = dt2.AddDays(1);
                }
                else if (dt2.Day == 31)
                {
                    dt2 = dt2.AddDays(-1);
                }

                if (dt2 < dt1)
                {
                    flipSign = true;
                    DateTime t = dt1;
                    dt1 = dt2;
                    dt2 = t;
                }

                days = dt2.Day - dt1.Day;
                days += 30 * (dt2.Month - dt1.Month);
                days += 360 * (dt2.Year - dt1.Year);
                if (flipSign)
                {
                    days = -days;
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return days.ToString();
        }

        /// <summary>
        /// Computes the declining balance of an asset.
        /// </summary>
        /// <param name="argList">Delimited string containing the initial cost,
        /// salvage value, life of asset, period of calculation, and months in the initial year.</param>
        /// <returns>Declining balance.</returns>
        public string ComputeDb(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeDb"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double cost;
            double salvage;
            double life;
            double period;
            double month = 12;

            double deprec = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out cost) && cost > 0
                && double.TryParse(args[1], NumberStyles.Any, null, out salvage) && salvage > 0
                && double.TryParse(args[2], NumberStyles.Any, null, out life) && life > 0
                && double.TryParse(args[3], NumberStyles.Any, null, out period) && period > 0
                && (argCount == 4 || double.TryParse(args[4], NumberStyles.Any, null, out month)))
            {
                double rate = Math.Round(1 - Math.Pow(salvage / cost, 1 / life), 3);
                double priorDeprec = 0;
                for (int i = 1; i <= period; ++i)
                {
                    if (i == 1)
                    {
                        deprec = cost * rate * month / 12;
                    }
                    else if (i > life)
                    {
                        deprec = (cost - priorDeprec) * rate * (12 - month) / 12;
                    }
                    else
                    {
                        deprec = (cost - priorDeprec) * rate;
                    }

                    priorDeprec += deprec;
                }
            }
            else if (cost == 0)
            {
                return "0";
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);          
#else
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.ErrorStrings[4].ToString());
                return this.ErrorStrings[4].ToString();
#endif

            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return deprec.ToString();
        }

        /// <summary>
        /// Computes the double declining balance of an asset.
        /// </summary>
        /// <param name="argList">Delimited string containing the initial cost,
        /// salvage value, life of asset, period of calculation, and factor.</param>
        /// <returns>Double declining balance.</returns>
        public string ComputeDdb(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeDdb"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double cost;
            double salvage;
            double life;
            double period;
            double factor = 2;

            double deprec = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out cost)
                && double.TryParse(args[1], NumberStyles.Any, null, out salvage)
                && double.TryParse(args[2], NumberStyles.Any, null, out life)
                && double.TryParse(args[3], NumberStyles.Any, null, out period)
                && (argCount == 4 || double.TryParse(args[4], NumberStyles.Any, null, out factor)))
            {
                double rate = factor / life;
                double priorDeprec = 0;
                for (int i = 1; i <= period; ++i)
                {
                    if (i == life / 2 || factor == 12)
                    {
                        deprec = cost - salvage - priorDeprec;
                    }
                    else
                    {
                        deprec = (cost - priorDeprec) * rate;
                    }

                    priorDeprec += deprec;
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return deprec.ToString();
        }

