        /// <summary>
        /// Returns the sum of the squares of the mean deviations.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>Sum of the squares of the mean deviation.</returns>
        public string ComputeDevsq(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeDevsq"; MarkTimeStart(ML);
#endif
            double d;

            double[] x = this.GetDoubleArray(range);
            int n = x.GetLength(0);
            if (n <= 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
            }

            sumx = sumx / n;
            double sumx2 = 0;

            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumx2 += d * d;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sumx2.ToString();
        }

        /// <summary>
        /// Converts a number to text using currency format.
        /// </summary>
        /// <param name="args">Number and the number of digits.</param>
        /// <returns>Currency format string.</returns>
        public string ComputeDollar(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeDollar"; MarkTimeStart(ML);
#endif

            string[] argsArray = SplitArgsPreservingQuotedCommas(args);
            string s1 = argsArray[0];
            string s2 = "2";
            if (argsArray.GetLength(0) == 2)
            {
                s2 = argsArray[1];
            }

            s1 = this.GetValueFromArg(s1);
            s2 = this.GetValueFromArg(s2);

            double number, decimals;

            if (!double.TryParse(s1, NumberStyles.Any, null, out number))
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.ErrorStrings[3].ToString());
                return this.ErrorStrings[5].ToString();
#endif
            }
            if (!double.TryParse(s2, NumberStyles.Any, null, out decimals))
            {
                decimals = 2;
            }
            double round = 0.0;
            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            if (decimals > 0)
            {
#if !SILVERLIGHT && !WINDOWS_UWP
                round = Math.Round(number, (int)decimals, MidpointRounding.AwayFromZero);
#else
                round = Math.Round(number, (int)decimals);
#endif
                nfi.CurrencyDecimalDigits = (int)decimals;
            }
            else
            {
                double mult = Math.Pow(10, -decimals);
                round = Math.Round(number / mult) * mult;
                nfi.CurrencyDecimalDigits = 0;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return String.Format(nfi, "{0:C}", round);
        }

        /// <summary>
        /// Converts a number to text using currency format.
        /// </summary>
        /// <param name="args">Number and the number of digits.</param>
        /// <returns>Currency format string.</returns>
        public string ComputeDollarDe(string args)
        {
            string fraction = string.Empty;
            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeDollarDe"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                string s1 = argsArray[0];
                string s2 = "2";
                if (argsArray.GetLength(0) == 2)
                {
                    s2 = argsArray[1];
                }

                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                string[] splitArg = s1.Split(parseDecimalSeparator);
                double number, decimals;
                int argCount = s1.Length;
                if (argCount == 0)
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(FormulaErrorStrings[wrong_number_arguments]);
                    return FormulaErrorStrings[wrong_number_arguments];
#endif
                }
                if (!IsCellReference(s1) && s1.Contains(this.TIC))
                    s1 = s1.Replace(this.TIC, string.Empty);
                if (!IsCellReference(s2) && s2.Contains(this.TIC))
                    s2 = s2.Replace(this.TIC, string.Empty);
                double.TryParse(splitArg[0], NumberStyles.Any, null, out number);
                if (!double.TryParse(s2, NumberStyles.Any, null, out decimals))
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[1].ToString());
                    return this.ErrorStrings[1].ToString();
#endif
                }               
                if (decimals < 1)
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
#endif
                }
                else if (decimals > 0)
                {
                    string[] deci = SplitArguments(s1,ParseDecimalSeparator);
                    double decimalNumber = (deci.Length == 2) ? (double.Parse("0." + deci[1])) *100 : 0;
                    string[] deci1 = SplitArguments((decimalNumber / decimals).ToString(), ParseDecimalSeparator);
                    fraction = int.Parse(deci[0]).ToString() + ParseDecimalSeparator.ToString() + ((deci1.Length == 2) ? deci1[1] : deci1[0]);// double.Parse((decimalNumber / decimals).ToString());
                }
                else
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[3].ToString());
                    return this.ErrorStrings[3].ToString();
#endif
                }
                if (double.Parse(fraction) > 0)
                {
                    string[] digitArg = fraction.ToString().Split(parseDecimalSeparator);
                    if (digitArg.Length > 1 && digitArg[1].Length > 0)
                    {
                        int DecimalDigits = digitArg[1].Length;
                        nfi.CurrencyDecimalDigits = DecimalDigits;
                    }
                }
                else
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
#endif
                }
            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return ex.Message;
            }
            return string.Format(nfi, "{0}", fraction);
#endif
        }

        /// <summary>
        /// Converts a number to text using currency format.
        /// </summary>
        /// <param name="args">Number and the number of digits.</param>
        /// <returns>Currency format string.</returns>
        public string ComputeDollarFr(string args)
        {
            double fraction = 0;
            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeDollarFr"; MarkTimeStart(ML);
#endif

                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                string s1 = argsArray[0];
                string s2 = "2";
                if (argsArray.GetLength(0) == 2)
                {
                    s2 = argsArray[1];
                }
                if (argsArray.GetLength(0) >= 1 && string.IsNullOrEmpty(s1))
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(FormulaErrorStrings[wrong_number_arguments]);
                    return FormulaErrorStrings[wrong_number_arguments];
#endif
                }                
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                string[] splitArg = s1.Split(parseDecimalSeparator);
                double number, dollar;
                double.TryParse(s1, NumberStyles.Any, null, out number);
                double.TryParse(s2, NumberStyles.Any, null, out dollar);
                if (double.IsNaN(number) || double.IsNaN(dollar)) 
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                     if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[1].ToString());
                    return this.ErrorStrings[1].ToString();
#endif
                    
                }
                else if (dollar <= 0)
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[3].ToString());
                    return this.ErrorStrings[3].ToString();
#endif

                }
                // Return error if fraction is negative
                if (number < 0) 
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                     if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
#endif
                }

                // Return error if fraction is greater than or equal to 0 and less than 1
                if (number >= 0 && number < 1) 
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[3].ToString());
                    return this.ErrorStrings[3].ToString();
#endif
                }
                fraction = (int)number;
                fraction += (number % 1) * Math.Pow(10, -Math.Ceiling(Math.Log(dollar) / Math.Log(10))) * dollar;

                string[] digitArg = fraction.ToString().Split(parseDecimalSeparator);
                if (digitArg.Length > 1 && digitArg[1].Length > 0)
                {
                    int DecimalDigits = digitArg[1].Length;
                    nfi.CurrencyDecimalDigits = DecimalDigits;
                }

            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return ex.Message;
#endif
            }
#if _ENABLETIMERS
            string v = string.Format(nfi, "{0}", fraction);
            MarkTimeEnd(ML);
            return v;
#else
            return string.Format(nfi, "{0}", fraction);
#endif
        }

        /// <summary>
        ///  Returns the weighted average of the present value of the cash flows
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Number of years</returns>
        public string ComputeDuration(string args)
        {
            string year = string.Empty;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeDuration"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                string days = ComputeDays360(argsArray[0] + ParseArgumentSeparator + argsArray[1]);
                double month = double.Parse(days) / 12;
                double n = month / 60;
                double i = double.Parse(GetValueFromArg(argsArray[3])),
                    m = 100,
                    c = double.Parse(GetValueFromArg(argsArray[2])) * 100;
                int inc = 1;
                double bondPrice = 0;
                double p = 0;
                double mD = 0;
                while (inc <= n)
                {
                    bondPrice += (Math.Pow(c, inc)/Math.Pow((1 + i), inc));                    
                    inc++;
                }
                n = month / 30;
                mD = (bondPrice + ((c *100) / (Math.Pow((1 + i), n))));
                double val = (mD / (c * ((1 - (1 / (Math.Pow((1 + i), n))) / i) + (m / (Math.Pow((1 + i), n)))))+(c / 100));
                year = ((val / 2) + (c / 10)).ToString(); 
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
            }
            return year;
#endif
        }
