        /// <summary>
        ///  Returns the discount rate for a security.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Rate of Discount</returns>
        public string ComputeDisc(string args)
        {
            string discount = string.Empty;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeDisc"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                string Settlementdate = argsArray[0];
                string Maturitydate = argsArray[1];
                string Price = argsArray[2];
                string Redemptionvalue = argsArray[3];
                string Basis = string.Empty;
                if (argsArray.Length > 4)
                    Basis = argsArray[4];
                else
                    Basis = "0";
                Settlementdate = this.GetValueFromArg(Settlementdate);
                Maturitydate = this.GetValueFromArg(Maturitydate);
                Price = this.GetValueFromArg(Price);
                Redemptionvalue = this.GetValueFromArg(Redemptionvalue);
                Basis = this.GetValueFromArg(Basis);
                DateTime date1, date2 = DateTime.Now;
                double settlement = 0;
                double maturity = 0;
                if ((DateTime.TryParse(Settlementdate, out date1) || double.TryParse(Settlementdate, out settlement))
               && (DateTime.TryParse(Maturitydate, out date2) || double.TryParse(Maturitydate, out maturity)))
                {
                    if (date1.Year == 1 || date2.Year == 1)
                    {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                        return this.ErrorStrings[4].ToString();
                    }
                    if (settlement == 0)
                        settlement = date1.ToOADate();
                    if (maturity == 0)
                        maturity = date2.ToOADate();

                    double DSM = double.Parse(ComputeDays360(settlement + ParseArgumentSeparator.ToString() + maturity))+1;
                    switch (Basis)
                    {
                        case "0":
                            Basis = "360";
                            break;
                        case "1":
                            Basis = "365";
                            break;
                        case "2":
                            Basis = (DSM / 360).ToString();
                            break;
                        case "3":
                            Basis = (DSM / 365).ToString();
                            break;
                        case "4":
                            Basis = "30";
                            break;
                    }
                    double disc = (((double.Parse(Redemptionvalue) - double.Parse(Price)) / double.Parse(Redemptionvalue)) * (double.Parse(Basis) / DSM));
                    discount = disc.ToString();
                }
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return this.ErrorStrings[4].ToString();
            }

            return discount;
#endif
        }
       
        /// <summary>
        /// Returns the future value of an initial principal after applying a series of compound interest rates.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Number of future value</returns>
        public string ComputeFvschedule(string args)
        {
            double future = 0;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeFvschedule"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                string s1 = argsArray[0];
                string s2 = argsArray[1];
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                double principal = 0;
                double scheduleVal = 0;
                if (!double.TryParse(s1, NumberStyles.Any, null, out principal))
                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.ErrorStrings[5].ToString());
                    return this.ErrorStrings[5].ToString();
#endif
                }
                // Initialize future value
                future = principal;
                s2 = s2.Replace(TIC, "");

                string[] schedule = s2.Split(parseArgumentSeparator);

                // Apply all interests in schedule
                for (int i = 0; i < schedule.Length; i++)
                {
                    // Return error if schedule value is not a number

                    if (!double.TryParse(schedule[i], NumberStyles.Any, null, out scheduleVal))
                    {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(this.ErrorStrings[5].ToString());
                        return this.ErrorStrings[5].ToString();
#endif
                    }
                    if (double.IsNaN(scheduleVal))
                    {
                        return this.ErrorStrings[1].ToString();
                    }
                    // Apply scheduled interest
                    future *= 1 + scheduleVal;
                }

#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
            }
            // Return future value
            return future.ToString();
#endif
        }

        /// <summary>
        /// Returns the cumulative interest paid for an investment period with a constant interest rate.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Number of interest rate</returns>
        public string ComputeCUMIPMT(string args)
        {
            double interest = 0;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeCUMIPMT"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);

                if (argsArray.Length < 5)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string s1 = argsArray[0];
                string s2 = argsArray[1];
                string s3 = argsArray[2];
                string s4 = argsArray[3];
                string s5 = argsArray[4];
                string s6 = argsArray[5];
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                s3 = this.GetValueFromArg(s3);
                s4 = this.GetValueFromArg(s4);
                s5 = this.GetValueFromArg(s5);
                s6 = this.GetValueFromArg(s6);

                double rate = 0, periods = 0, value = 0, start = 0, end = 0, type = 0;
                if (!double.TryParse(s1, out rate) ||
                 !double.TryParse(s2, out periods) ||
                 !double.TryParse(s3, out value) ||
                 !double.TryParse(s4, out start) ||
                 !double.TryParse(s5, out end) ||
                 !double.TryParse(s6, out type))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[1].ToString());
                    return ErrorStrings[1].ToString();
                }

                // Return error if either rate, periods, or value are lower than or equal to zero
                if (rate <= 0 || periods <= 0 || value <= 0)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[1].ToString();
                }

                // Return error if start < 1, end < 1, or start > end
                if (start < 1 || end < 1 || start > end)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[1].ToString();
                }
                
                // Return error if type is neither 0 nor 1
                if (type != 0 && type != 1)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
                }

                // Compute cumulative interest
                double payment = double.Parse(ComputePmt(string.Format("{0},{1},{2},{3},{4}", rate, periods, value, 0, type)));
                
                interest = 0;
                if (start == 1)
                {
                    if (type == 0)
                    {
                        interest = -value;
                        start++;
                    }
                }
                for (int i = (int)start; i <= end; i++)
                {
                    if (type == 1)
                    {
                        interest += double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 2, payment, value, 1))) - payment;
                    }
                    else
                    {
                        interest += double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 1, payment, value, 0)));
                    }
                }
                interest *= rate;

               
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return ex.Message;
            }
            // Return cumulative interest
            return interest.ToString();
#endif
        }

       /// <summary>
        /// Calculates the accrued interest of a security in the case of periodic payments.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Accrued interest</returns>
        public string ComputeACCRINT(string args)
        {
            double accrint = 0;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeACCRINT"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                if (argsArray.Length < 5)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                string s1 = argsArray[0];
                string s2 = argsArray[1];
                string s3 = argsArray[2];
                string s4 = argsArray[3];
                string s5 = argsArray[4];
                string s6 = argsArray[5];
                string s7 = argsArray.Length < 7 ? "0" : argsArray[6];
                string s8 = argsArray.Length < 8 ? "0" : argsArray[7];
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                s3 = this.GetValueFromArg(s3);
                s4 = this.GetValueFromArg(s4);
                s5 = this.GetValueFromArg(s5);
                s6 = this.GetValueFromArg(s6);


                //issue, first, settlement, rate, par, frequency, basis, method
                double rate = 0, par = 0, factor = 0, yearfracER = 0.277777777;

                DateTime issue = new DateTime();
                DateTime settlement = new DateTime();
                DateTime firstSettlement = new DateTime();
                double issuedouble = 0, setdouble = 0, firstSetdouble = 0;
                if (!(DateTime.TryParse(s1.Replace(TIC, string.Empty), out issue) || double.TryParse(s1.Replace(TIC, string.Empty), out issuedouble)) || !(double.TryParse(s2.Replace(TIC, string.Empty), out firstSetdouble) || (DateTime.TryParse(s2.Replace(TIC, string.Empty), out firstSettlement))) || !(double.TryParse(s3.Replace(TIC, string.Empty), out setdouble) || (DateTime.TryParse(s3.Replace(TIC, string.Empty), out settlement))))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(ErrorStrings[1].ToString());
                    return ErrorStrings[1].ToString();
                }
                double frequency = 0;
                double.TryParse(s6, out frequency);
                double.TryParse(s4, out rate);
                double.TryParse(s5, out par);
                if (issuedouble > 0 || setdouble > 0)
                    issue = this.GetDateFromSerialDate((int)issuedouble);
                if (setdouble > 0)
                    settlement = this.GetDateFromSerialDate((int)setdouble);
                if (firstSetdouble > 0)
                    firstSettlement = this.GetDateFromSerialDate((int)firstSetdouble);
                if (this.dateTime1900.Year > issue.Year || this.dateTime1900.Year > settlement.Year || this.dateTime1900.Year > firstSettlement.Year )
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(ErrorStrings[4].ToString());
                    return ErrorStrings[4].ToString();
                }
                string iss = this.TIC + this.Parse("DATE(" + issue.Year + ParseArgumentSeparator + issue.Month + ParseArgumentSeparator + issue.Day + ")") + this.TIC;
                string set = this.TIC + this.Parse("DATE(" + settlement.Year + ParseArgumentSeparator + settlement.Month + ParseArgumentSeparator + settlement.Day + ")") + this.TIC;
                switch (s7)
                {
                    case "0":
                        // US (NASD) 30/360
                    case "1":
                        // Actual/actual
                    case "2":
                        // Actual/360
                    case "3":
                        // Actual/365
                    case "4":
                        // European 30/360
                        factor = double.Parse(ComputeYearFrac(string.Format("{0},{1},{2}", iss, set, s7)));
                        break;
                    default:
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(ErrorStrings[4].ToString());
                        return ErrorStrings[4].ToString();
                }
                double firstValue = par * (rate / (int)frequency);
                accrint = firstValue * factor * (int)frequency;
                accrint = ((int)frequency == 4) ? (accrint + yearfracER) : accrint;
            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return ex.Message;
#endif
            }
            return accrint.ToString();
        }


        /// <summary>
        /// Returns the cumulative principal paid for an investment period with a constant interest rate.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Cumulative principal value</returns>
        public string ComputeCUMPRINC(string args)
        {
            double principal = 0;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeCUMPRINC"; MarkTimeStart(ML);
#endif
                string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                if (argsArray.Length < 5)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string s1 = argsArray[0];
                string s2 = argsArray[1];
                string s3 = argsArray[2];
                string s4 = argsArray[3];
                string s5 = argsArray[4];
                string s6 = argsArray[5];
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                s3 = this.GetValueFromArg(s3);
                s4 = this.GetValueFromArg(s4);
                s5 = this.GetValueFromArg(s5);
                s6 = this.GetValueFromArg(s6);

                double rate = 0, periods = 0, value = 0, start = 0, end = 0, type = 0;
                if (!double.TryParse(s1, out rate) ||
               !double.TryParse(s2, out periods) ||
               !double.TryParse(s3, out value) ||
               !double.TryParse(s4, out start) ||
               !double.TryParse(s5, out end) ||
               !double.TryParse(s6, out type))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[1].ToString());
                    return ErrorStrings[1].ToString();
                }

                // Return error if either rate, periods, or value are lower than or equal to zero
                if (rate <= 0 || periods <= 0 || value <= 0)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[1].ToString();
                }

                // Return error if start < 1, end < 1, or start > end
                if (start < 1 || end < 1 || start > end)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[1].ToString();
                }

                // Return error if type is neither 0 nor 1
                if (type != 0 && type != 1)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new Exception(ErrorStrings[4].ToString());
                    return this.ErrorStrings[4].ToString();
                }
                                
                double payment = double.Parse(ComputePmt(string.Format("{0},{1},{2},{3},{4}", rate, periods, value, 0, type)));

                if (start == 1)
                {
                    if (type == 0)
                    {
                        principal = payment + value * rate;
                    }
                    else
                    {
                        principal = payment;
                    }
                    start++;
                }
                for (double i = start; i <= end; i++)
                {
                    if (type > 0)
                    {
                        principal += payment - (double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 2, payment, value, 1))) - payment) * rate;
                    }
                    else
                    {
                        principal += payment - double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 1, payment, value, 0))) * rate;
                    }
                }


#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
                return ex.Message;
            }
            // Return cumulative interest
            return principal.ToString();
#endif
        }
