        /// <summary>
        /// returns the fraction of the year represented by the number of whole days between two given dates
        /// </summary>
        /// <param name="argList">startDate, endDate, basis (optional)</param>
        /// <returns>returns the fraction of the year</returns>
        public string ComputeYearFrac(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeYearFrac"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            List<DateTime> holidays = new List<DateTime>();
            double yearFracValue = 0;
            if (argCount != 2 && argCount > 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            string startDate = this.GetValueFromArg(args[0].Replace(this.TIC, ""));
            string endDate = this.GetValueFromArg(args[1].Replace(this.TIC, ""));
            string basis = (argCount == 3) ? this.GetValueFromArg(args[2]).Replace(this.TIC, "") : "0";
            DateTime startDateTime = dateTime1900;
            DateTime endDateTime = dateTime1900;
            double basisValue;
            double startDateValue = -1;
            double endDateValue = -1;
            if (!((double.TryParse(startDate, NumberStyles.Any, CultureInfo.CurrentUICulture, out startDateValue) || DateTime.TryParse(startDate, CultureInfo.CurrentCulture, DateTimeStyles.None, out startDateTime))
                && (DateTime.TryParse(endDate, CultureInfo.CurrentCulture, DateTimeStyles.None, out endDateTime) || double.TryParse(endDate, NumberStyles.Any, CultureInfo.CurrentUICulture, out endDateValue)) && double.TryParse(basis, NumberStyles.Any, CultureInfo.CurrentUICulture, out basisValue)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[1].ToString();
            }
            if ((basisValue > 4 && basisValue < 0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[4].ToString();
            }
            if (startDateValue > 0)
            {
                startDateTime = this.GetDateFromSerialDate((int)startDateValue);
                startDate = startDateTime.ToShortDateString();
            }
            if (endDateValue > 0)
            {
                endDateTime = this.GetDateFromSerialDate((int)endDateValue);
                endDate = endDateTime.ToShortDateString();
            }
            double noofDays = double.Parse(this.ComputeDatevalue(endDate)) - double.Parse(this.ComputeDatevalue(startDate));
            if (noofDays < 0)
            {
                startDateTime = DateTime.Parse(endDate);
                endDateTime = DateTime.Parse(startDate);
            }
            double startYear = startDateTime.Year;
            double startMonth = startDateTime.Month;
            double startDay = startDateTime.Day;
            double endYear = endDateTime.Year;
            double endMonth = endDateTime.Month;
            double endDay = endDateTime.Day;
            double startDatysInMonth = DateTime.DaysInMonth(startDateTime.Year, startDateTime.Month);
            double endDaysInMonth = DateTime.DaysInMonth(endDateTime.Year, endDateTime.Month);
            switch (basis)
            {
                case "0":
                    if (startDay == 31 && endDay == 31)
                    {
                        startDay = 30;
                        endDay = 30;
                    }
                    else if (startDay == 31)
                    {
                        startDay = 30;
                    }
                    else if (startDay == 30 && endDay == 31)
                    {
                        endDay = 30;
                    }
                    else if (startMonth == 1 && endMonth == 1 && startDatysInMonth == startDay && endDaysInMonth == endDay)
                    {
                        startDay = 30;
                        endDay = 30;
                    }
                    else if (startMonth == 1 && startDatysInMonth == startDay)
                    {
                       startDay = 30;
                    }
                    yearFracValue = ((endDay + endMonth * 30 + endYear * 360) - (startDay + startMonth * 30 + startYear * 360));
                    yearFracValue = yearFracValue / 360;
                    break;
                case "1":
                    double ylength = 366;
                    if (startYear == endYear || ((startYear + 1) == endYear) && ((startMonth > endMonth) || ((startMonth == endMonth) && (startDay >= endDay))))
                    {
                        if (startYear == endYear && DateTime.IsLeapYear(int.Parse(startYear.ToString())))
                        {
                            ylength = 366;
                        }
                        else if (Daysfeb29(startDateTime, endDateTime) || (endMonth == 1 && endDay == 29))
                        {
                            ylength = 366;
                        }
                        yearFracValue = noofDays / ylength;
                    }
                    else
                    {
                        double years = (endYear - startYear) + 1;
                        DateTime newEndTime = new DateTime(endDateTime.Year + 1, 0, 1);
                        DateTime newStartTime = new DateTime(startDateTime.Year + 1, 0, 1);
#if SILVERLIGHT || WINDOWS_UWP
                        double days = double.Parse(this.ComputeDatevalue(newEndTime.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - double.Parse(this.ComputeDatevalue(newStartTime.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));
#else
                        double days = double.Parse(this.ComputeDatevalue(newEndTime.ToShortDateString())) - double.Parse(this.ComputeDatevalue(newStartTime.ToShortDateString()));
#endif
                        double average = days / years;
                        yearFracValue = noofDays / average;
                    }
                    break;
                case "2":
                    yearFracValue = noofDays / 360;
                    break;
                case "3":
                    yearFracValue = noofDays / 365;
                    break;
                case "4":
                    if (startDay == 31)
                        startDay = 30;
                    if (endDay == 31)
                        endDay = 30;
                    // Remarkably, do NOT change February 28 or February 29 at ALL
                    yearFracValue = ((endDay + endMonth * 30 + endYear * 360) - (startDay + startMonth * 30 + startYear * 360)) / 360;
                    break;
                default:
                    break;
            }
#endif
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return yearFracValue.ToString();
        }
        /// <summary>
        /// Evaluates a parsed formula.
        /// </summary>
        /// <param name="formula">A string holding a valid parsed formula.</param>
        /// <returns>The computed value of the formula.</returns>
        /// <remarks>The string passed into this function must be previously parsed
        /// using ParseFormula. </remarks>
        public string ComputedValue(string formula)
        {
            if (TextIsEmpty(formula))
            {
                return formula;
            }

            try
            {
                this.computedValueLevel++;

                if (this.computedValueLevel > maximumRecursiveCalls)
                {
                    this.computedValueLevel = 0;
                    throw new ArgumentException(this.FormulaErrorStrings[too_complex]);
                }

                Stack _stack = new Stack(MaxStackDepth);

                int i = 0;
                _stack.Clear();
                string sheet = string.Empty;

                if (this.AllowShortCircuitIFs && EnsureIFCallDuringShortCircuit)
                {
                    int loc = -1;
                    do
                    {
                        ////code peels all only the outer most IF functions  and relies on a custom IF to handle the proper alternative
                        if (i < formula.Length && (i = formula.IndexOf(this.IFMarker, i)) > -1)
                        {
                            loc = this.MatchingRightBracket(formula.Substring(i));
                            if (loc > -1)
                            {
                                LibraryFunction func = (LibraryFunction)this.LibraryFunctions["IF"];
                                string result = string.Empty;
                                try
                                {
                                    result = func(formula.Substring(i + this.IFMarker.Length, loc - this.IFMarker.Length));
                                }
                                catch (Exception ex)
                                {
                                    if (RethrowLibraryComputationExceptions)
                                    {
                                        libraryComputationException = ex;
                                        throw ex;
                                    }
                                }

                                MarkupResultToIncludeInFormula(ref result);

                                //double d = 0;
                                //if (double.TryParse(result, out d))
                                //{
                                //    if (d < 0)
                                //    {
                                //        result = "nu" + (-d).ToString();
                                //    }
                                //    else
                                //    {
                                //        result = "n" + d.ToString();
                                //    }
                                //}
                                string rightPiece = string.Empty;
                                if (i + loc + 1 < formula.Length)
                                    rightPiece = formula.Substring(i + loc + 1);
                                formula = formula.Substring(0, i) + result + rightPiece;
                            }
                        }
                    }
                    while (formula.Contains(this.IFMarker) && loc > -1);
                }

                i = 0;
                while (i < formula.Length)
                {
                    if (formula[i] == BMARKER)
                    {
                        i = i + 1;
                        continue;
                    }

                    bool uFound = formula[i] == 'u';
                    if (uFound)
                    {
                        i++;
                        if (i >= formula.Length)
                        {
                            continue; ////error case....
                        }

                        if (formula[i] == BMARKER)
                        {
                            i++;
                        }

                        if (i >= formula.Length)
                        {
                            continue; ////error case....
                        }
                    }

                    ////defect 8729
                    ////************
                    //// The % is the last thing in the cell contents here
                    if (formula[i] == '%' && _stack.Count > 0)
                    {
                        object o = _stack.Peek();
                        double d;
                        if (double.TryParse(o.ToString(), NumberStyles.Any, null, out d))
                        {
                            _stack.Pop(); ////remove it
                            _stack.Push(d / 100); ////push it back
                        }

                        i = i + 1;
                        continue;
                    }

                    ////****************
                    if (formula[i] == sheetToken)
                    {
                        sheet = formula[i].ToString();
                        i++;
                        while (i < formula.Length && formula[i] != sheetToken)
                        {
                            sheet += formula[i];
                            i++;
                        }

                        if (i < formula.Length)
                        {
                            sheet += formula[i];
                            i++;
                        }
                        else
                        {
                            continue; ////skip out as something is wrong
                        }
                    }

                    if (formula.Substring(i).StartsWith(this.TRUEVALUESTR))
                    {
                        _stack.Push(this.TRUEVALUESTR);
                        i += this.TRUEVALUESTR.Length;
                    }
                    else if (formula.Substring(i).StartsWith(this.FALSEVALUESTR))
                    {
                        _stack.Push(this.FALSEVALUESTR);
                        i += this.FALSEVALUESTR.Length;
                    }
                    else if (formula[i] == this.TIC[0] || formula[i] == '|' )
                    {
                        if (_stack.Count == 3)
                            _stack = CombineStack(formula, i - 2, _stack);
                        string s = formula[i].ToString();
                        i++;
                        
                        //int last = formula.LastIndexOf(this.TIC[0]);
                        //while (i < formula.Length && i != last)
                        while (i < formula.Length && formula[i] != this.TIC[0])
                        {
                            s = s + formula[i];
                            i = i + 1;
                        }
                        if (multiTick)
                        {
                            s= s.Replace("|", this.TIC);
                        }
                        _stack.Push(s + this.TIC);
                        i += 1;
                        
                    }
                    else if (char.IsUpper(formula[i]))
                    {
                        ////cell loc
                        string s = this.ProcessUpperCase(ref formula, ref i, ref sheet);

                        if (uFound)
                        {
                            s = this.GetValueFromParentObject(s);
                            double d3;
                            if (double.TryParse(s, out d3))
                            {
                                d3 = -d3;
                                _stack.Push(d3.ToString());
                            }
                            else
                            {
                                _stack.Push(s);
                            }
                        }
                        else
                        {
                            _stack.Push(this.GetValueFromParentObject(s));
                        }
                    }
                    else if (formula[i] == 'q')
                    {
                        ////library
                        formula = this.ComputeInteriorFunctions(formula);

                        int ii = formula.Substring(i + 1).IndexOf(this.LEFTBRACKET);
                        if (ii > 0)
                        {
                            int bracketCount = 0;
                            bool bracketFound = false;
                            int start = ii + i + 2;
                            int k = start;
                            while (k < formula.Length && (formula[k] != this.RIGHTBRACKET || bracketCount > 0))
                            {
                                if (formula[k] == this.LEFTBRACKET)
                                {
                                    bracketCount++;
                                    bracketFound = true;
                                }
                                else if (formula[k] == this.LEFTBRACKET)
                                {
                                    bracketCount--;
                                }

                                k++;
                            }

                            if (bracketFound)
                            {
                                string s = formula.Substring(start, k - start - 2);
                                string s1 = string.Empty;
                                string[] splits = SplitArgsPreservingQuotedCommas(s);
                                foreach (string t in splits)
                                {
                                    if (s1.Length > 0)
                                    {
                                        s1 += ",";
                                    }

                                    int j = this.FindLastqNotInBrackets(t);
                                    if (j > 0)
                                    {
                                        s1 += t.Substring(0, j) + this.ComputedValue(t.Substring(j));
                                    }
                                    else
                                    {
                                        s1 += this.ComputedValue(t);
                                    }
                                }

                                formula = formula.Substring(0, start) + s1 + formula.Substring(k - 2);
                            }

                            string name = formula.Substring(i + 1, ii);
                            if (name == "AVG" && excelLikeComputations)
                            {
                                return FormulaErrorStrings[bad_index];
                            }
                            if (this.LibraryFunctions[name] != null)
                            {
                                int j = formula.Substring(i + ii + 1).IndexOf(this.RIGHTBRACKET);
                                string args = formula.Substring(i + ii + 2, j - 1);
                                try
                                {
                                    LibraryFunction func = (LibraryFunction)this.LibraryFunctions[name];
                                    String result = func(args);
                                    _stack.Push(result);
                                }
                                catch (Exception ex)
                                {
                                    if (this.rethrowLibraryComputationExceptions)
                                    {
                                        this.libraryComputationException = ex;
                                        throw ex;
                                    }

                                    return ex.Message;
                                }

                                i += j + ii + 2;
                            }
                            else
                            {
                                return this.FormulaErrorStrings[missing_formula];
                            }
                        }
                        else if (formula[0] == BMARKER)
                        {
                            ////Restart the processing with the formula without library finctions.
                            i = 0;
                            _stack.Clear();
                            continue;
                        }
                        else
                        {
                            return this.FormulaErrorStrings[improper_formula];
                        }
                    }
                    else if (char.IsDigit(formula[i]) || formula[i] == 'u')
                    {
                        string s = string.Empty;
                        if (formula[i] == 'u' || uFound)
                        {
                            s = "-";
                            if (!uFound)
                            {
                                i++;
                            }
                            else
                            {
                                uFound = false;
                            }
                        }

                        if (i < formula.Length && char.IsUpper(formula[i]))
                        {
                            s = s + this.GetValueFromParentObject(ProcessUpperCase(ref formula, ref i, ref sheet));
                        }
                        else
                        {
                            while (i < formula.Length && (char.IsDigit(formula[i]) || formula[i] == ParseDecimalSeparator))
                            {
                                s = s + formula[i];
                                i = i + 1;
                            }
                        }

                        _stack.Push(s);
                    }
                    else
                    {
                        switch (formula[i])
                        {
                            case '#':
                                {
                                    int errIndex = 0;
                                    if (formula.IndexOf('!', i) == -1)
                                    {
                                        errIndex = formula.IndexOf('?', i) + 1;
                                    }
                                    else
                                        errIndex = formula.IndexOf('!', i) + 1;
                                    _stack.Push(formula.Substring(i, errIndex - i));
                                    i = errIndex;
                                    break;
                                }

                            case 'n':
                                {
                                    i = i + 1;

                                    string s = string.Empty;
                                    if (formula.Substring(i).StartsWith("Infinity"))
                                    {
                                        s = "Infinity";
                                        i += s.Length;
                                    }
                                    else if (formula.Substring(i).StartsWith("uInfinity"))
                                    {
                                        s = "Infinity";
                                        i += s.Length + 1;
                                    }
                                    else if (formula.Substring(i).StartsWith(this.TRUEVALUESTR))
                                    {
                                        s = this.TRUEVALUESTR;
                                        i += s.Length;
                                    }
                                    else if (formula.Substring(i).StartsWith(this.FALSEVALUESTR))
                                    {
                                        s = this.FALSEVALUESTR;
                                        i += s.Length;
                                    }
                                    else if (i <= formula.Length - 3 && formula.Substring(i, 3) == "NaN")
                                    {
                                        i += 3;
                                        s = "0";
                                    }
                                    else
                                    {
                                        if (formula[i] == 'u' || uFound)
                                        {
                                            s = "-";
                                            if (!uFound)
                                            {
                                                i = i + 1;
                                            }
                                            else
                                            {
                                                uFound = false;
                                            }
                                        }

                                        while (i < formula.Length && (char.IsDigit(formula[i]) || formula[i] == ParseDecimalSeparator))
                                        {
                                            s = s + formula[i];
                                            i = i + 1;
                                        }

                                        if (i < formula.Length && formula[i] == '%')
                                        {
                                            i = i + 1;

                                            ////defect 8729
                                            ////**************
                                            if (s == string.Empty)
                                            {
                                                if (_stack.Count > 0)
                                                {
                                                    object o = _stack.Peek();
                                                    double d;
                                                    if (double.TryParse(o.ToString(), NumberStyles.Any, null, out d))
                                                    {
                                                        _stack.Pop(); ////remove it
                                                        s = (d / 100).ToString(); ////push it back
                                                    }
                                                }
                                            }
                                            else
                                            {
                                                ////**************
                                                s = (double.Parse(s) / 100).ToString();
                                            }
                                        }
                                        else if (i < formula.Length - 2 && formula[i] == 'E' && (formula[i + 1] == '+' || formula[i + 1] == '-'))
                                        {
                                            s += formula.Substring(i, 4);
                                            i += 4;
                                        }
                                    }

                                    _stack.Push(s);
                                }

                                break;
                            case TOKEN_add:
                                {
                                    double d = this.Pop(_stack);
                                    int x;
                                    if (int.TryParse(d.ToString(),out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    double d1 = this.Pop(_stack);
                                    if (int.TryParse(d1.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    if (d.Equals(double.NaN) || d1.Equals(double.NaN) || d.Equals("#VALUE!") || d1.Equals("#VALUE!"))
                                    {
                                        _stack.Push("#VALUE!");
                                    }
                                    else
                                    {
                                        _stack.Push((d1 + d).ToString());
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_subtract:
                                {
                                    double d = this.Pop(_stack);
                                    int x;
                                    if (int.TryParse(d.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    double d1 = this.Pop(_stack);
                                    if (int.TryParse(d1.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    
                                    if (d.Equals(double.NaN) || d1.Equals(double.NaN) || d.Equals("#VALUE!") || d1.Equals("#VALUE!"))
                                    {
                                        _stack.Push("#VALUE!");
                                    }
                                    else
                                    {
                                        _stack.Push((d1 - d).ToString());
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_multiply:
                                {
                                    double d = this.Pop(_stack);
                                    int x;
                                    if (int.TryParse(d.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    double d1 = this.Pop(_stack);
                                    if (int.TryParse(d1.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    if (d.Equals(double.NaN) || d1.Equals(double.NaN) || d.Equals("#VALUE!") || d1.Equals("#VALUE!"))
                                    {
                                        _stack.Push("#VALUE!");
                                    }
                                    else
                                    {
                                        _stack.Push((d1 * d).ToString());
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_divide:
                                {
                                    double d = this.Pop(_stack);
                                    int x;
                                    if (int.TryParse(d.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    double d1 = this.Pop(_stack);
                                    if (int.TryParse(d1.ToString(), out x) && isErrorString)
                                    {
                                        isErrorString = false;
                                        return this.ErrorStrings[x].ToString();
                                    }
                                    if (d.Equals(double.NaN) || d1.Equals(double.NaN) || d.Equals("#VALUE!") || d1.Equals("#VALUE!"))
                                    {
                                        _stack.Push("#VALUE!");
                                    }
                                    else if (d.Equals(0))
                                    {
                                        _stack.Push(this.ErrorStrings[3]);
                                    }
                                    else
                                    {
                                        _stack.Push((d1 / d).ToString());
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_EP:
                                {
                                    double d = this.Pop(_stack);
                                    double d1 = this.Pop(_stack);

                                    _stack.Push((d1 * Math.Pow(10, d)).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_EM:
                                {
                                    double d = this.Pop(_stack);
                                    double d1 = this.Pop(_stack);

                                    _stack.Push((d1 * Math.Pow(10, -d)).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_less:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty && treatStringsAsZero)
                                    {
                                        s1 = "0";
                                    }

                                    if (s2 == string.Empty && treatStringsAsZero)
                                    {
                                        s2 = "0";
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, null, out d)
                                        && double.TryParse(s2, NumberStyles.Any, null, out d1))
                                    {
                                        val = (d1 < d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (s1.Equals("#VALUE!") || s2.Equals("#VALUE!"))
                                            val = "#VALUE!";
                                        else
                                            val = (s2.ToUpper().Replace(this.TIC, string.Empty).CompareTo(s1.ToUpper().Replace(this.TIC, string.Empty)) < 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_greater:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty)
                                    {
                                        if (this.TreatStringsAsZero)
                                            s1 = "0";
                                        else
                                            s1 = s2 + 1;
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        if (this.TreatStringsAsZero)
                                            s2 = "0";
                                        else
                                            s2 = s1 + 1;
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, null, out d)
                                        && double.TryParse(s2, NumberStyles.Any, null, out d1))
                                    {
                                        val = (d1 > d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (s1.Equals("#VALUE!") || s2.Equals("#VALUE!"))
                                            val = "#VALUE!";
                                        else
                                            val = (s2.ToUpper().Replace(this.TIC, string.Empty).CompareTo(s1.ToUpper().Replace(this.TIC, string.Empty)) > 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_equal:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty && TreatStringsAsZero)
                                    {
                                        s1 = "0";
                                    }

                                    if (s2 == string.Empty && TreatStringsAsZero)
                                    {
                                        s2 = "0";
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, null, out d)
                                        && double.TryParse(s2, NumberStyles.Any, null, out d1))
                                    {
                                        val = (d1 == d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if ((s1.Length > 0 && s1[0] == '#' && this.ErrorStrings.IndexOf(s1) > -1)
                                            || (s2.Length > 0 && s2[0] == '#' && this.ErrorStrings.IndexOf(s2) > -1))
                                        {
                                            val = s1;
                                        }
                                        else if ((s1.Length > 0 && this.formulaErrorStrings.IndexOf(s1) > -1)
                                            || (s2.Length > 0 && this.formulaErrorStrings.IndexOf(s2) > -1))
                                        {
                                            val = "#VALUE!";
                                        }
                                        else
                                        {
                                            val = (s1.ToUpper().Replace(this.TIC, string.Empty) == s2.ToUpper().Replace(this.TIC, string.Empty)) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_lesseq:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty)
                                    {
                                        if (!treatStringsAsZero)
                                        {
                                            s1 = "NaN";
                                        }
                                        else
                                        {
                                            s1 = "0";
                                        }
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        if (!treatStringsAsZero)
                                        {
                                            s2 = "NaN";
                                        }
                                        else
                                        {
                                            s2 = "0";
                                        }
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, null, out d)
                                        && double.TryParse(s2, NumberStyles.Any, null, out d1))
                                    {
                                        val = (d1 <= d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (s1.Equals("#VALUE!") || s2.Equals("#VALUE!"))
                                            val = "#VALUE!";
                                        else
                                            val = (s1.ToUpper().Replace(this.TIC, string.Empty).CompareTo(s2.ToUpper().Replace(this.TIC, string.Empty)) <= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_greatereq:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty)
                                    {
                                        if (!treatStringsAsZero)
                                        {
                                            s1 = "NaN";
                                        }
                                        else
                                        {
                                            s1 = "0";
                                        }
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        if (!treatStringsAsZero)
                                        {
                                            s2= "NaN";
                                        }
                                        else
                                        {
                                            s2 = "0";
                                        }
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, CultureInfo.CurrentUICulture, out d)
                                        && double.TryParse(s2, NumberStyles.Any,CultureInfo.CurrentUICulture, out d1))
                                    {
                                        val = (d1 >= d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (s1.Equals("#VALUE!") || s2.Equals("#VALUE!"))
                                            val = "#VALUE!";
                                        else
                                            val = (s1.ToUpper().Replace(this.TIC, string.Empty).CompareTo(s2.ToUpper().Replace(this.TIC, string.Empty)) >= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_noequal:
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);
                                    if (s1 == string.Empty && TreatStringsAsZero)
                                    {
                                        s1 = "0";
                                    }

                                    if (s2 == string.Empty && TreatStringsAsZero)
                                    {
                                        s2 = "0";
                                    }

                                    double d, d1;
                                    string val;
                                    if (double.TryParse(s1, NumberStyles.Any, null, out d)
                                        && double.TryParse(s2, NumberStyles.Any, null, out d1))
                                    {
                                        val = (d1 != d) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        val = (s1.ToUpper().Replace(this.TIC, string.Empty) != s2.ToUpper().Replace(this.TIC, string.Empty)) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_and: ////and strings....
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2=string.Empty;
                                    if (_stack.Count > 0)
                                        s2 = this.PopString(_stack);

                                    if (this.useNoAmpersandQuotes)
                                    {
                                        _stack.Push(s2 + s1);
                                    }
                                    else
                                    {
                                        _stack.Push(this.TIC + s2 + s1 + this.TIC);
                                    }

                                    i = i + 1;
                                }

                                break;
                            case TOKEN_or:// exponential
                                {
                                    double d = this.Pop(_stack);
                                    double d1 = this.Pop(_stack);

                                    _stack.Push(Math.Pow(d1, d).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_ORop:// or operation
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);

                                    double d;
                                    string val;
                                    if (s1 == string.Empty)
                                    {
                                        s1 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s1, NumberStyles.Any, null, out d))
                                    {
                                        s1 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        s2 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s2, NumberStyles.Any, null, out d))
                                    {
                                        s2 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    val = (s1.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR
                                             || s2.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR) ? TRUEVALUESTR : FALSEVALUESTR;

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_ANDop:// AND operation
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);

                                    double d;
                                    string val;
                                    if (s1 == string.Empty)
                                    {
                                        s1 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s1, NumberStyles.Any, null, out d))
                                    {
                                        s1 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        s2 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s2, NumberStyles.Any, null, out d))
                                    {
                                        s2 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    val = (s1.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR
                                             && s2.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR) ? TRUEVALUESTR : FALSEVALUESTR;

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_XORop:// XOR operation
                                {
                                    string s1 = this.PopString(_stack);
                                    string s2 = this.PopString(_stack);

                                    double d;
                                    string val;
                                    if (s1 == string.Empty)
                                    {
                                        s1 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s1, NumberStyles.Any, null, out d))
                                    {
                                        s1 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    if (s2 == string.Empty)
                                    {
                                        s2 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s2, NumberStyles.Any, null, out d))
                                    {
                                        s2 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    val = ((s1.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR && s2.ToUpper().Replace(this.TIC, string.Empty) != TRUEVALUESTR)
                                             || (s2.ToUpper().Replace(this.TIC, string.Empty) == TRUEVALUESTR && s1.ToUpper().Replace(this.TIC, string.Empty) != TRUEVALUESTR))
                                               ? this.TRUEVALUESTR : FALSEVALUESTR;

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_NOTop:// NOTR operation
                                {
                                    string s1 = this.PopString(_stack);
                                    double d;
                                    string val;
                                    if (s1 == string.Empty)
                                    {
                                        s1 = this.FALSEVALUESTR;
                                    }
                                    else if (double.TryParse(s1, NumberStyles.Any, null, out d))
                                    {
                                        s1 = (d != 0) ? this.TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    val = (s1.ToUpper().Replace(this.TIC, string.Empty) == FALSEVALUESTR)
                                        ? this.TRUEVALUESTR : FALSEVALUESTR;

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            default:
                                {
                                    this.computedValueLevel = 0;
                                    throw new ArgumentException(this.FormulaErrorStrings[invalid_expression]);
                                }
                        }
                    }
                }

                if (this.checkDanglingStack && _stack.Count > 1 && formula.Length > 1 &&
                    (!formula.StartsWith(BMARKER.ToString()) || !formula.EndsWith(BMARKER.ToString())
                     || formula.IndexOf(BMARKER2) > -1))
                {
                    this.computedValueLevel = 0;
                    return this.FormulaErrorStrings[improper_formula];
                }

                if (_stack.Count == 0)
                {
                    return string.Empty;
                }
                else
                {
                    string s = string.Empty;
                    double d; 
                    int cc = _stack.Count;
                    do
                    {
                        s = _stack.Pop().ToString() + s;
                        if (!this.checkDanglingStack && double.TryParse(s, out d))
                        {
                           return s;
                        }
                        cc--;
                    }
                    while (cc > 0 && !(s.Contains(this.FALSEVALUESTR) || s.Contains(this.TRUEVALUESTR)));
                    ////This check moved below in Pop as result of DT26064
                    ////if(TextIsEmpty(s))
                    ////    s = "0"; //Empty is zero in calculations.
                    return s;
                }
            }
            catch (Exception ex)
            {
                this.computedValueLevel = 0;
                if (ex.Message.IndexOf(this.FormulaErrorStrings[circular_reference_]) > -1
                    || (this.rethrowLibraryComputationExceptions && LibraryComputationException != null))
                {
                    if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                    {
                        throw this.LibraryComputationException;
                    }

                    throw ex;
                }

                if (ex.Message.IndexOf(this.FormulaErrorStrings[cell_empty]) > -1)
                {
                    return string.Empty;
                }
                else
                {
                    if (this.RethrowLibraryComputationExceptions)
                    {
                        this.libraryComputationException = ex;
                        throw ex;
                    }
                    return ex.Message;
                }
            }
            finally
            {
                this.computedValueLevel--;
                if (this.computedValueLevel < 0)
                {
                    this.computedValueLevel = 0;
                }
            }
        }

        private Stack CombineStack(string formula, int i, Stack _tempStack)
        {

            string combineString = string.Empty;
            if (_tempStack.Count == 2)
            {
                int j = 3;
                string checkString = formula.Substring(i);
                while (j > 1)
                {
                    string popStringValue = _tempStack.Pop().ToString();
                    combineString = (popStringValue.Equals(this.TIC + this.TIC)) ? combineString + this.TIC : popStringValue + combineString;
                    checkString = (j == 3) ? popStringValue : checkString;
                    j--;
                }
                if (_tempStack.Peek().Equals(this.TIC + this.TIC))
                    _tempStack.Pop();
                combineString = (formula.Length == i && string.IsNullOrEmpty(checkString.Replace(this.TIC, string.Empty))) ? combineString + checkString : combineString;
                //string stem = _stack.Pop().ToString();
                //_stack.Push(stem + this.TIC);
                _tempStack.Push(combineString);
            }
            return _tempStack;
        }

        /// <summary>
        /// Rounds up to larger in magnitude even number.
        /// </summary>
        /// <param name="args">Number to be rounded.</param>
        /// <returns>Rounded even value.</returns>
        public string ComputeEven(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeEven"; MarkTimeStart(ML);
#endif
            double number;
            double even = 0;
            if (double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out number))
            {
                int sgn = Math.Sign(number);
                number = Math.Abs(number);
                if ((int)number != number)
                {
                    number = (int)(number + 1);
                }

                if ((number % 2) == 1)
                {
                    even = sgn * (number + 1);
                }
                else
                {
                    even = sgn * number;
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return even.ToString();
        }

        /// <summary>
        /// Returns whether or not the two arguments passed in are exactly the same.
        /// </summary>
        /// <param name="range">A string holding two arguments (separated by commas) of
        /// cell references, strings,
        /// formulas, or numbers.</param>
        /// <returns>True if the arguments are exactly the same ignoring formats, false other wise.</returns>
        public string ComputeExact(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeExact"; MarkTimeStart(ML);
#endif
            this.AdjustRangeArg(ref range);
            string[] args = SplitArgsPreservingQuotedCommas(range);
            if (args.GetLength(0) != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_2_args];
            }

            string s1, s2;
            double d;
            s1 = this.GetValueFromArg(args[0]);
            s2 = this.GetValueFromArg(args[1]);

            if (double.TryParse(s1, out d))
            {
                s1 = d.ToString();
            }

            if (double.TryParse(s2, out d))
            {
                s2 = d.ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s1 == s2 ? this.TRUEVALUESTR : FALSEVALUESTR;
        }

        /// <summary>
        /// Computes e raised to the value of the argument.
        /// </summary>
        /// <param name="args">A cell reference, formula, or number.</param>
        /// <returns>A string holding the e raised to the value of the argument.</returns>
        public string ComputeExp(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeExp"; MarkTimeStart(ML);
            string v = ComputeMath(args, new MathFunc(Math.Exp)).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return this.ComputeMath(args, new MathFunc(Math.Exp)).ToString();
#endif
        }

        /// <summary>
        /// Returns the exponential distribution.
        /// </summary>
        /// <param name="argList">x, lambda, cumulative.</param>
        /// <returns>The exponential distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function.
        /// </remarks>
        public string ComputeExpondist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeExpondist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double lambda;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out lambda))
            {
                cum = (args[2] == this.TRUEVALUESTR) ? 1 : 0;
                if (cum == 0)
                {
                    dist = lambda * Math.Exp(-lambda * x);
                }
                else
                {
                    dist = 1 - Math.Exp(-lambda * x);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Factorial of a given number.
        /// </summary>
        /// <param name="args">The given value, x.</param>
        /// <returns>Factorial of x.</returns>
        public string ComputeFact(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeFact"; MarkTimeStart(ML);
#endif
            double number;
            double fact = 0;
            if (!double.TryParse(this.GetValueFromArg(args).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            else if (number < 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            else
            {
                int x = (int)number;
                if (x > 12)
                {
                    fact = factorialTable[12];
                    for (int i = 13; i <= x; i++)
                    {
                        fact *= i;
                    }
                }
                else
                {
                    fact = factorialTable[x];
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return fact.ToString();
        }

