        /// <summary>
        /// Returns the F (Fisher) probability distribution.
        /// </summary>
        /// <param name="argList">x, degreesfreedom1, degreesfreedom2.</param>
        /// <returns>Returns the F probability distribution.</returns>
        public string ComputeFdist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeFdist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double df1 = 0;
            double df2 = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out df1)
                && double.TryParse(args[2], NumberStyles.Any, null, out df2))
            {
                if (df1 < 1 || df2 < 1)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException("Numerator and denominator should not be less than one");
                    return this.ErrorStrings[4].ToString();// "#NUM!";
                }
                double mult = Math.Exp(
                    this.gammaln((df1 + df2) / 2) -
                    this.gammaln(df1 / 2) -
                    this.gammaln(df2 / 2) +
                    (df1 / 2) * Math.Log(df1 / df2));

                dist = 1 - mult * this.fdist(x, (int)df1, (int)df2);
                if (x == 1 && df1 == 1 && df2 == 1)
                {
                    dist = Math.Round(Math.Exp(this.gammaln((df1 + df2) / 2)) / 2, 2);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Finds the first occurrence of one string in another string.
        /// </summary>
        /// <param name="arg">Conatins two or three arguments. The first argument is the string
        /// to find. The second string is the string that is being searched. The third argument
        /// is the start location in the second string for the search.</param>
        /// <returns>The location of the found string.</returns>
        /// <remarks>The location count starts at 1. If the third argument is missing, it defaults to 1.
        /// If the first string does not appear in the second string, #VALUE! is returned. The searches are done
        /// in a case sensitive manner.
        /// </remarks>
        public string ComputeFind(string arg)
        {
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            if (args.Length != 2 && args.Length != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            ////strip off outside tics (if any) on the evaluated arguments
            string lookFor = this.StripTics0(GetValueFromArg(args[0]));
            string lookIn = this.StripTics0(GetValueFromArg(args[1]));
            int start = 1;
            if (args.Length == 3)
            {
                string s3 = this.GetValueFromArg(args[2]);
                if (!int.TryParse(s3, out start))
                {
                    start = 1;
                }
            }

            if (start <= 0 || start > lookIn.Length)
            {
                return "#VALUE!";
            }

            int loc = lookIn.IndexOf(lookFor, start - 1);
            if (loc < 0)
            {
                return "#VALUE!";
            }

            return (loc + 1).ToString();
        }

        /// <summary>
        /// Returns the inverse of F distribution.
        /// </summary>
        /// <param name="argList">p, degreesfreedom1, degreesfreedom2.</param>
        /// <returns>Returns x such that F distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeFinv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeFinv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p;
            double df1;
            double df2;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && (p > 0 && p < 1)
                && double.TryParse(args[1], NumberStyles.Any, null, out df1)
                && double.TryParse(args[2], NumberStyles.Any, null, out df2))
            {
                if (df1 <= 1 || df2 <= 1)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException("Numerator and denominator should not be less than one");
                    return this.ErrorStrings[4].ToString();// "#NUM!";
                }
                invdist = this.finv(p, (int)df1, (int)df2);
            }

            if (invdist <= 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[iterations_dont_converge];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
