        }

        /// <summary>
        /// Returns the Fisher transformation of the input variable.
        /// </summary>
        /// <param name="argList">Input variable x.</param>
        /// <returns>Fisher transformation of x.</returns>
        /// <remarks>
        /// X should be between -1 and 1.
        /// </remarks>
        public string ComputeFisher(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeFisher"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double z = 0;

            string s = this.GetValueFromArg(args[0]);

            if (double.TryParse(s, NumberStyles.Any, null, out x)
                && (x > -1 && x < 1))
            {
                z = 0.5 * Math.Log((1 + x) / (1 - x));
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return z.ToString();
        }

        /// <summary>
        /// Returns the inverse of Fisher transformation.
        /// </summary>
        /// <param name="argList">Input variable y.</param>
        /// <returns>The value x such that the Fisher transformation y is x.</returns>
        public string ComputeFisherinv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeFisherinv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double y;
            double x = 0;

            string s = this.GetValueFromArg(args[0]);

            if (double.TryParse(s, NumberStyles.Any, null, out y))
            {
                double d = Math.Exp(2 * y);
                x = (d - 1) / (d + 1);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return x.ToString();
        }

        /// <summary>
        /// Rounds a number to the specified number of decimals, formats the number
        /// in decimal format using a period and commas, and return the result as text.
        /// </summary>
        /// <param name="args">
        /// Number, number of digits, a flag that prevents from include
        /// commas in the returned text.
        /// </param>
        /// <returns>Formatted number as string.</returns>
        public string ComputeFixed(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeFixed"; MarkTimeStart(ML);
#endif
            string[] argsArray = SplitArgsPreservingQuotedCommas(args);
            string s1 = argsArray[0];
            string s2 = "2";
            string s3 = "FALSE";

            int argCount = argsArray.GetLength(0);
            if (argCount > 1)
            {
                s2 = argsArray[1];
            }

            if (argCount > 2)
            {
                s3 = argsArray[2];
            }

            s1 = this.GetValueFromArg(s1);
            s2 = this.GetValueFromArg(s2);
            s3 = this.GetValueFromArg(s3);

            double number, decimals;
            double.TryParse(s1, NumberStyles.Any, null, out number);
            if (!double.TryParse(s2, NumberStyles.Any, null, out decimals))
            {
                decimals = 2;
            }

            double no_commas_flag;
            bool no_commas;
            if (double.TryParse(s3, NumberStyles.Any, null, out no_commas_flag))
            {
                if (no_commas_flag == 0)
                {
                    no_commas = false;
                }
                else
                {
                    no_commas = true;
                }
            }
            else
            {
                if (s3.ToUpper() == this.FALSEVALUESTR)
                {
                    no_commas = false;
                }
                else
                {
                    if (s3.ToUpper() == this.TRUEVALUESTR)
                    {
                        no_commas = true;
                    }
                    else
                    {
                        return "#NAME?";
                    }
                }
            }

            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            if (decimals > 0)
            {
#if !SILVERLIGHT && !WINDOWS_UWP
                number = Math.Round(number, (int)decimals, MidpointRounding.AwayFromZero);
#else
                number = Math.Round(number, (int)decimals);
#endif
                nfi.NumberDecimalDigits = (int)decimals;
            }
            else
            {
                double mult = Math.Pow(10, -decimals);
                number = Math.Round(number / mult) * mult;
                nfi.NumberDecimalDigits = 0;
            }
            if (no_commas)
            {
                nfi.NumberGroupSeparator = string.Empty;
            }

#if _ENABLETIMERS
            string s = string.Format(nfi, "{0:N}", number);
            MarkTimeEnd(ML);
            return s;
#else
            return string.Format(nfi, "{0:N}", number);
#endif
        }

        /// <summary>
        /// Computes the largest whole number less than or equal to the argument.
        /// </summary>
        /// <param name="args">A cell reference, formula, or number.</param>
        /// <returns>A string holding the largest whole number less than or equal to the argument.</returns>
        public string ComputeFloor(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeFloor"; MarkTimeStart(ML);
#endif
            string[] range = SplitArgsPreservingQuotedCommas(args);
            int argCount = range.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double d1, d2, d3 = 0;
            if (double.TryParse(this.GetValueFromArg(range[0]), NumberStyles.Any, null, out d1)
                && double.TryParse(this.GetValueFromArg(range[1]), NumberStyles.Any, null, out d2))
            {
                if (d1 == 0)
                    return d3.ToString();
                if (d1 * d2 <= 0 && !(d1 < 0))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                d3 = Math.Ceiling(d1 / d2) * d2;
                if (d2 > 0)
                {
                    while (d3 > d1)
                    {
                        d3 -= d2;
                    }
                }
                else
                {
                    while (d3 < d1)
                    {
                        d3 -= d2;
                    }
                }
                if (d2 == 0.1)
                {
                    d3 = d1;
                }
            }
          
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return d3.ToString();
        }

        /// <summary>
        /// Returns a forecasted value based on two sets of points using least square fit regression.
        /// </summary>
        /// <param name="range">x, rangex, rangey.</param>
        /// <returns>Forecasted value.</returns>
        public string ComputeForecast(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeForecast"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x0, d;
            string s1 = this.GetValueFromArg(args[0]);
            if (!double.TryParse(s1, NumberStyles.Any, null, out x0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            double[] y = this.GetDoubleArray(args[1]);
            double[] x = this.GetDoubleArray(args[2]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }

            double b = sumxy / sumx2;
            double a = sumy - b * sumx;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return (a + b * x0).ToString();
        }

        /// <summary>
        /// A method that computes a parsed formula.
        /// </summary>
        /// <param name="parsedFormula">The parsed formula to be computed.</param>
        /// <returns>A string holding the computed value.</returns>
        public string ComputeFormula(string parsedFormula)
        {
            if (this.throwCircularException)
            {
                if (this.iterationMaxCount > 0)
                {
                    if (this.computedValueLevel == 0)
                    {
                        this.circCheckList.Clear();
                        this.circCheckList.Add(this.cell);
                    }
                    else if (this.circCheckList.IndexOf(this.cell) > -1)
                    {
                        if (!IterationValues.ContainsKey(this.cell))
                        {
                            this.IterationValues.Add(cell, "0");
                        }

                        return this.IterationValues[cell].ToString();
                    }
                }
                else
                {
                    if (this.computedValueLevel == 0)
                    {
                        this.circCheckList.Clear();
                    }
                    else if (this.circCheckList.IndexOf(this.cell) > -1)
                    {
                        this.computedValueLevel = 0;
                        this.circCheckList.Clear();
                        throw new ArgumentException(this.FormulaErrorStrings[circular_reference_]);
                    }

                    this.circCheckList.Add(this.cell);
                }
            }

            string s = this.ComputedValue(parsedFormula);

            if (this.UseNoAmpersandQuotes && s.Length > 1
                            && s[0] == this.TIC[0]
                            && s[s.Length - 1] == this.TIC[0])
            {
                s = s.Substring(1, s.Length - 2);
            }
            return s;
        }

        /// <summary>
        /// Computes the future value of an investment.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period,
        /// number of periods, payment per period, present value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Future value of the investment.</returns>
        public string ComputeFv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeFv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double nper;
            double pmt = 0;
            double pv = 0;
            double type = 0;

            double fv = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out nper)
                && double.TryParse(args[2], NumberStyles.Any, null, out pmt)
                && (argCount == 3 || double.TryParse(args[3], NumberStyles.Any, null, out pv))
                && (argCount <= 4 || double.TryParse(args[4], NumberStyles.Any, null, out type)))
            {
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }
                ////FV   = (PMT*(1+rate*type)*(1-(1+ rate)^NPER)/rate)-PV*(1+rate)^NPER
                double pow = Math.Pow((1 + rate), nper);
                fv = (pmt * (1 + rate * type) * (1 - pow) / rate) - pv * pow;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return fv.ToString();
        }

        /// <summary>
        /// Returns the gamma distribution.
        /// </summary>
        /// <param name="argList">X, alpha, beta, cumulative.</param>
        /// <returns>The gamma distribution.</returns>
        /// <remarks>
        /// X, alpha, and beta should be positive real numbers. Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function. The distribution value
        /// is computed interactively using Trapezoidal Rule to six to seven significant digits
        /// or 20 iteration maximum.
        /// </remarks>
        public string ComputeGammadist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeGammadist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double a;
            double b;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out a)
                && double.TryParse(args[2], NumberStyles.Any, null, out b))
            {
                if (argCount != 3)
                {
                    cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                }

                if (cum == 0)
                {
                    //// excel version     dist = 1 / (Math.Pow(b, a) * gammaln(a)) * Math.Pow(x, a - 1) * Math.Exp(-x / b);
                    //// http://www.itl.nist.gov/div898/handbook/eda/section3/eda366b.htm
                    dist = this.gammadensity(a, b, x); ////Math.Pow(x/b, a-1) * Math.Exp(-x/b) / (b * Math.Exp(gammaln(a)));
                }
                else
                {
                    ////integrates the density function
                    dist = this.gammadist(a, b, x);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Returns the inverse of gamma distribution.
        /// </summary>
        /// <param name="argList">p, alpha, beta</param>
        /// <returns>Returns x such that gamma distribution at x is p.</returns>
        /// <remarks>
        /// P, alpha, and beta should be positive real numbers, with p between 0 and 1.
        /// </remarks>
        public string ComputeGammainv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeGammainv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p = 0;
            double a = 0;
            double b = 0;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && (p > 0 && p < 1)
                && double.TryParse(args[1], NumberStyles.Any, null, out a)
                && double.TryParse(args[2], NumberStyles.Any, null, out b))
            {
                if(a <= 0 || b <= 0)
                    return "#NUM!";
                invdist = this.gammainv(p, a, b);
            }

            if (p < 0 || p > 1)
                return "#NUM!";
            else if (p == 0 || a == 0 || b == 0)
                return "#VALUE!";

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            if (invdist <= 0)
            {
                return "#N/A"; // return this.FormulaErrorStrings[iterations_dont_converge];
            }

            return invdist.ToString();
        }

        /// <summary>
        /// Returns the natural logarithm of the gamma function.
        /// </summary>
        /// <param name="argList">The value to be evaluated.</param>
        /// <returns>The natural logarithm of the gamma function.</returns>
        public string ComputeGammaln(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeGammaln"; MarkTimeStart(ML);
#endif
