            if (double.TryParse(this.GetValueFromArg(argList), NumberStyles.Any, null, out x) && x > 0)
            {
                x = this.gammaln(x);
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
