            return x.ToString();
        }

        /// <summary>
        /// Returns the geometric mean of all values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>The geometric mean all values listed in the argument.</returns>
        public string ComputeGeomean(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeGeomean"; MarkTimeStart(ML);
#endif
            double sum = 1d;
            string s1;
            double d;
            int count = 0;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Any, null, out d))
                            {
                                count++;
                                sum = sum * d;
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            count++;
                            sum = sum * d;
                        }
                        else if (this.ErrorStrings.Contains(s1))
                        {
                            return s1;
                        }
                    }
                }
            }

            if (count > 0)
            {
                sum = Math.Pow(sum, 1d / (double)count);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

        /// <summary>
        /// Returns the harmonic mean of all values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>The harmonic mean all values listed in the argument.</returns>
        public string ComputeHarmean(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeHarmean"; MarkTimeStart(ML);
#endif
            double sum = 0d;
            string s1;
            double d;
            int count = 0;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0)
                            {
                                count++;
                                sum = sum + 1 / d;
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0)
                        {
                            count++;
                            sum = sum + 1 / d;
                        }
                        else if (this.ErrorStrings.Contains(s1))
                        {
                            return s1;
                        }
                    }
                }
            }

            if (count > 0)
            {
                sum = ((double)count) / sum;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

        /// <summary>
        /// Returns a horizontal table look up value.
        /// </summary>
        /// <param name="range">Contains search value, table, return index and match properties.</param>
        /// <returns>Matching value found in the table.</returns>
        /// <remarks> For example, =HLOOKUP("Axles",A1:C4,2,TRUE) looks for the exact
        /// match for Axles in A1:C1 and returns the corresponding value in A2:C2.
        /// </remarks>
        public string ComputeHLookUp(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeHLookUp"; MarkTimeStart(ML);
#endif
            bool cachingEnabled = IsHLookupCachingEnabled();
            bool optimizedMatchesEnabled = IsOptimizedMatchesEnabled();
            if (cachingEnabled && lookupTables == null) lookupTables = new Dictionary<string, LookUps>();

            string[] s = SplitArgsPreservingQuotedCommas(range);
            string lookUp = this.GetValueFromArg(s[0]);
            lookUp = lookUp.Replace(this.TIC, string.Empty).ToUpper();
            string r = s[1].Replace("\"", string.Empty);
            string o1 = this.GetValueFromArg(s[2]).Replace("\"", string.Empty);
            double d = 0;
            if (!double.TryParse(o1, NumberStyles.Any, null, out d))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#N/A";
            }

            ////int row = int.Parse(o1);
            int row = (int)d;

            bool match = true;
            if (s.GetLength(0) == 4)
            {
                match = this.GetValueFromArg(s[3]) == TRUEVALUESTR;
            }

            bool typeIsNumber = match ? double.TryParse(lookUp, NumberStyles.Any, null, out d) : false;

            int i = r.IndexOf(":");
            ////single cell
            if (i == -1)
            {
                r = r + ":" + r;
                i = r.IndexOf(":");
            }

            int k = r.Substring(0, i).LastIndexOf(sheetToken);
            ICalcData grd = this.grid;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

            if (k > -1)
            {
                this.grid = (ICalcData)family.TokenToParentObject[r.Substring(0, k + 1)];
            }

            int row1 = this.RowIndex(r.Substring(0, i));
            int row2 = this.RowIndex(r.Substring(i + 1));
            if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[5].ToString();
            }
            if (row1 == -1 && this.grid is ISheetData)
            {
                row1 = ((ISheetData)grid).GetFirstRow();
            }
            int col1 = this.ColIndex(r.Substring(0, i));
            if (col1 == -1 && this.grid is ISheetData)
            {
                col1 = ((ISheetData)grid).GetFirstColumn();
            }
            if (row2 == -1 && this.grid is ISheetData)
            {
                row2 = ((ISheetData)grid).GetLastRow();
            }
            int col2 = this.ColIndex(r.Substring(i + 1));
            if (col2 == -1 && this.grid is ISheetData)
            {
                col2 = ((ISheetData)grid).GetLastColumn();
            }
            bool newTable = false;
            string key = string.Empty;
            List<string> lookUpTable = null;
            Dictionary<string, int> matchedTable = null;
            if (cachingEnabled)
            {
                key = string.Format("{0}_{1}_{2}_{3}", row1, col1, col2, grid.GetHashCode());

                if (!lookupTables.ContainsKey(key))
                {
                    if (optimizedMatchesEnabled)
                    {
                        LookUps _lookUp = new LookUps();
                        _lookUp.MatchLookUpList = new Dictionary<string, int>();
                        _lookUp.LinearLookUpList = new List<string>() ;
                        lookupTables.Add(key, _lookUp);
                    }
                    else
                    {
                        LookUps _lookUp = new LookUps();
                        _lookUp.LinearLookUpList = new List<string>() ;
                        lookupTables.Add(key, _lookUp);
                    }
                    newTable = true;
                }
                lookUpTable = lookupTables[key].LinearLookUpList;
                if (optimizedMatchesEnabled)
                {
                    matchedTable = lookupTables[key].MatchLookUpList;
                }
            }

            string val = string.Empty;
            int lastCol = col1;
            string s1 = string.Empty;
            double d1 = 0;
            bool doLastColMark = true;
            bool exactMatch = false;
            if (cachingEnabled && optimizedMatchesEnabled && matchedTable.ContainsKey(lookUp))
            {
                lastCol = matchedTable[lookUp];
                s1 = lookUp;
            }
            else
            {
                for (int col = col1; col <= col2; ++col)
                {
                    if (!cachingEnabled || col - col1 >= lookUpTable.Count || newTable)
                    {
                        s1 = this.GetValueFromParentObject(grid, row1, col).ToString().ToUpper().Replace("\"", string.Empty);
                        if (cachingEnabled)
                        {
                            lookUpTable.Add(s1);
                            if (optimizedMatchesEnabled)
                            {
                                matchedTable.Add(s1, col);
                            }
                        }
                    }
                    else
                    {
                        s1 = lookUpTable[col - col1];
                    }

                    if (s1 == lookUp ||
                        (match && (typeIsNumber
                        ? (double.TryParse(s1, NumberStyles.Any, null, out d1) && (d1.CompareTo(d) > 0))
                        : (s1.CompareTo(lookUp) > 0))))
                    {
                        if (s1 == lookUp)
                        {
                            lastCol = col;
                            match = true;
                            exactMatch = true;
                        }

                        if (!newTable)
                            break;
                        else
                            doLastColMark = false;
                    }
                    if (doLastColMark)
                        lastCol = col;
                    match = newTable = true;
                }
            }

            if (match || s1.Equals(lookUp))
            {
                if (!exactMatch && !typeIsNumber)
                {
                    this.grid = grd;
                    return "#N/A";
                }
                val = this.GetValueFromParentObject(grid, row + row1 - 1, lastCol).ToString();
                if (val.Length > 0 && val[0] == CalcEngine.FormulaCharacter)
                {
                    val = this.ParseFormula(val);
                }

                d = 0;
                if (val.Length > 0 && val[0] != this.TIC[0] && !double.TryParse(val, NumberStyles.Any, null, out d))
                {
                    val = this.TIC + val + this.TIC;
                }
            }
            else
            {
                val = "#N/A";
            }

            ////val = "\"#N/A\"";
            this.grid = grd;

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val;
        }

        /// <summary>
        /// Returns the hour of the given time.
        /// </summary>
        /// <param name="argList">Given time.</param>
        /// <returns>Hour of given time.</returns>
        public string ComputeHour(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeHour"; MarkTimeStart(ML);
#endif
            double time;
            DateTime dt = DateTime.Now;
            argList = this.GetValueFromArg(argList);
            if (argList.IndexOf(this.TIC) > -1)
            {
                argList = argList.Replace(this.TIC, string.Empty);
                dt = DateTime.Parse(argList);
            }
            else
            {
                try
                {
                    dt = DateTime.Parse(argList);
                }
                catch
                {
                    if (double.TryParse(argList, NumberStyles.Any, null, out time))
                    {
                        dt = 
#if WINDOWS_UWP
                            Syncfusion.XlsIO.Implementation.DateTimeExtension.FromOADate(time);
#else
                            DateTime.FromOADate(time);
#endif
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dt.Hour.ToString();
        }

        /// <summary>
        /// Returns the hypergeometric distribution.
        /// </summary>
        /// <param name="argList">Number of sample successes, number of sample, number of population successes, number of population.</param>
        /// <returns>Returns the gamma distribution.</returns>
        public string ComputeHypgeomdist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeHypgeomdist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double xnss = 0;
            double xns = 0;
            double xnps = 0;
            double xnp = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Integer, null, out xnss)
                && double.TryParse(args[1], NumberStyles.Integer, null, out xns)
                && double.TryParse(args[2], NumberStyles.Integer, null, out xnps)
                && double.TryParse(args[3], NumberStyles.Integer, null, out xnp))
            {
                int nss = (int)xnss;
                int ns = (int)xns;
                int nps = (int)xnps;
                int np = (int)xnp;
                if (nss < 0 || ns < nss || nps < 0 || np < nps || nss > nps || ns > np)
                {
                    return this.FormulaErrorStrings[invalid_Math_argument];
                }

                dist = this.comb(nss, nps) * this.comb(ns - nss, np - nps) / this.comb(ns, np);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Conditionally computes one of two alternatives depending upon a logical expression.
        /// </summary>
        /// <remarks>
        ///	The first argument is
        /// treated as a logical expression with a non-zero value considered True and a zero value considered False.
        /// The value of only one of the alternatives is computed depending upon the logical expression.
        /// </remarks>
        /// <param name="args">A string holding a list of three arguments.
        /// </param>
        /// <returns>Returns a string holding the second argument if the first argument is True (non-zero). Otherwise, it returns a string holding the third argument.</returns>
        public string ComputeIf(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeIf"; MarkTimeStart(ML);
#endif

            string s1 = string.Empty;
            ////parsed formula
            if (args.Length > 0 && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1) 
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[requires_3_args];
            }
            else
            {
                string[] s = this.GetCellsFromArgs(args);

                if (s.GetLength(0) >= 2)
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s[0]);
                        double d = 0;
                        if (s1.Equals(this.TRUEVALUESTR) ||
                            (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d))
                        {
                            s1 = this.GetValueFromArg(s[1]);
                        }
                        else if (s1.Equals(this.FALSEVALUESTR) || s1 == string.Empty ||
                            (double.TryParse(s1, NumberStyles.Any, null, out d) && d == 0d))
                        {
                            s1 = s.GetLength(0) == 3 ? this.GetValueFromArg(s[2]) : FALSEVALUESTR;
                        }
                        else
                        {
                            if (s[0].Contains(TIC))
                            {
                                int first = s[0].IndexOf(TIC) + 1;
                                int last = s[0].LastIndexOf(TIC) - 1;
                                string st = s[0].Substring(first, last - first + 1);
                                foreach (string err in this.FormulaErrorStrings)
                                {
                                    if (st.Equals(err))
                                        return err;
                                }
                            }
                            s1 = "NaN";
                        }
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }
                }
                else
                {
                    return this.FormulaErrorStrings[requires_3_args];
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s1;
        }

        /// <summary>
        /// Returns the value at a specified row and column from within a given range.
        /// </summary>
        /// <param name="arg">look_range, row, col</param>
        /// <returns>The value.</returns>
        /// <remarks>
        /// Only the array form of this function is supported.
        /// </remarks>
        public string ComputeIndex(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeIndex";  MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            int argCount = args.GetLength(0);
            if (argCount > 3 || argCount == 0)
            {
#if _ENABLETIMERS
                     MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string r = args[0];
            r = r.Replace(TIC, string.Empty); 
            int i = r.IndexOf(":");
            ////single cell
            if (i == -1)
            {
#if _ENABLETIMERS
                     MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            if (arg.IndexOf("#N/A") > -1 || arg.IndexOf("#N~A") > -1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#N/A";
            }
            if (arg.IndexOf("#DIV/0!") > -1 || arg.IndexOf("#DIV~0!") > -1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#DIV/0!";
            }
            string sheet = this.GetSheetTokenFromReference(r);

            double d;
            int row = (argCount == 1) ? 1 : double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Integer, null, out d) ? (int)d : -1;
            int col = (argCount <= 2) ? 1 : double.TryParse(this.GetValueFromArg(args[2]), NumberStyles.Integer, null, out d) ? (int)d : -1;
            if (row == -1 || col == -1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#REF!";
            }

            int top = this.RowIndex(r.Substring(0, i));
            int bot = this.RowIndex(r.Substring(i + 1));
            if (!(!top.Equals(-1) || bot.Equals(-1)).Equals((top.Equals(-1) || !bot.Equals(-1))))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[5].ToString();
            }
            if (top == -1 && this.grid is ISheetData)
            {
                top = ((ISheetData)grid).GetFirstRow();
            }
            if (bot == -1 && this.grid is ISheetData)
            {
                bot = ((ISheetData)grid).GetLastRow();
            }
            int left = this.ColIndex(r.Substring(0, i));
            int right = this.ColIndex(r.Substring(i + 1));
            if (left == -1 && this.grid is ISheetData)
            {
                left = ((ISheetData)grid).GetFirstColumn();
            }
            if (right == -1 && this.grid is ISheetData)
            {
                right = ((ISheetData)grid).GetLastColumn();
            }
            if (row > bot - top + 1 || col > right - left + 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#REF!";
            }

            row = this.RowIndex(r.Substring(0, i)) + row - 1;
            if (this.RowIndex(r.Substring(0, i)) == -1 && this.grid is ISheetData)
            {
                row = row + 2;
            }
            col = this.ColIndex(r.Substring(0, i)) + col - 1;
            if (this.ColIndex(r.Substring(0, i)) == -1 && this.grid is ISheetData)
            {
                col = col + 2;
            }
#if _ENABLETIMERS
            string v = this.GetValueFromArg(string.Format("{2}{0}{1}", RangeInfo.GetAlphaLabel(col), row, sheet));
            MarkTimeEnd(ML);
            return v;
#else
            string result = this.GetValueFromArg(string.Format("{2}{0}{1}", RangeInfo.GetAlphaLabel(col), row, sheet));
            if (string.IsNullOrEmpty(result))
                return "0";
            return result;
#endif
        }

