        /// <summary>
        /// Returns the reference specified by a text string. References are immediately evaluated to display their contents.
        /// <para>Syntax: INDIRECT(CellRefString, [IsA1Style])</para>
        /// </summary>
        /// <param name="args">Cell reference string.</param>
        /// <returns>Cell reference.</returns>
        public string ComputeIndirect(string args)
        {
            if (args[args.Length - 1] == BMARKER)
            {
                args = this.GetValueFromArg(args);
            }

            string[] arg = SplitArgsPreservingQuotedCommas(args);
            if (arg.Length == 0 || arg.Length > 2)
            {
                throw new ArgumentException("No. of argument cant be less than 1 or more than 2.");
            }

            arg[0] = arg[0].ToUpper();
            this.PutTokensForSheets(ref arg[0]);
            string sheetToken1 = this.SheetToken(arg[0].Replace(TIC, string.Empty));

            ////Remove SheetToken
            if (!String.IsNullOrEmpty(sheetToken1))
            {
                arg[0] = arg[0].Replace(sheetToken1, string.Empty);
            }

            if (arg.Length == 2 && arg[1] == this.FALSEVALUESTR)
            {
                bool hasTIC = arg[0].StartsWith(this.TIC) && arg[0].EndsWith(this.TIC);
                string rcCell = arg[0].ToUpper().Replace(this.TIC, string.Empty);
                string[] cells = rcCell.Split(new char[] { ':' }, StringSplitOptions.RemoveEmptyEntries);

                string[] rc = cells[0].Split(new char[] { 'R', 'C' }, StringSplitOptions.RemoveEmptyEntries);
                if (cells.Length > 2)
                {
                    return "#REF!";
                }

                arg[0] = RangeInfo.GetAlphaLabel(Convert.ToInt32(rc[1])) + rc[0];

                if (cells.Length == 2)
                {
                    string st = this.SheetToken(cells[1]);
                    if (!String.IsNullOrEmpty(st))
                    {
                        cells[1] = cells[1].Replace(st, string.Empty);
                    }

                    rc = cells[1].Split(new char[] { 'R', 'C' }, StringSplitOptions.RemoveEmptyEntries);
                    arg[0] += ":" + RangeInfo.GetAlphaLabel(Convert.ToInt32(rc[1])) + rc[0];
                }

                if (hasTIC)
                {
                    arg[0] = this.TIC + arg[0] + this.TIC;
                }
            }

            string cellReference = string.Empty;
            ////String
            if (arg[0].StartsWith(this.TIC)) 
            {
                cellReference = sheetToken1 + arg[0].Replace(this.TIC, string.Empty);
            }
            else
            {
                if (this.IsCellReference(arg[0]))
                {
                    string scopedRange = string.Empty;
                    cellReference = this.GetValueFromArg(sheetToken1 + arg[0]);
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    if (this.NamedRanges.Contains(cellReference.ToUpper()))
#else
                    if (this.NamedRanges.ContainsKey(cellReference.ToUpper()))
#endif
                    {
                        cellReference = Convert.ToString(this.NamedRanges[cellReference.ToUpper()]);
                        cellReference = cellReference.ToUpper(); 
                        cellReference = cellReference.Replace(STRING_fixedreference, STRING_empty);
                        this.PutTokensForSheets(ref cellReference); 
                        if (!cellReference.StartsWith(sheetToken.ToString()))
                        {
                            cellReference = sheetToken1 + cellReference;
                        }
                    }
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    else if (CheckIfScopedRange(cellReference.ToUpper(), out scopedRange))
                     
#else
                    else if (CheckIfScopedRange(cellReference.ToUpper(), out scopedRange))
#endif
                    {
                        cellReference = Convert.ToString(scopedRange);
                        cellReference = cellReference.ToUpper();
                        cellReference = cellReference.Replace(STRING_fixedreference, STRING_empty);
                        this.PutTokensForSheets(ref cellReference);
                        if (!cellReference.StartsWith(sheetToken.ToString()))
                        {
                            cellReference = sheetToken1 + cellReference;
                        }
                    }
                    else if (this.IsCellReference(cellReference))
                    {
                        return this.GetValueFromArg(cellReference);
                    }
                    else
                    {
                        return cellReference;
                    }
                }
                else
                {
                    cellReference = arg[0];
                }
            }

            if (!IsCellReference(cellReference))
            {
                string scopedRange = string.Empty;
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                if (this.NamedRanges.Contains(cellReference.ToUpper()))
#else
                if (this.NamedRanges.ContainsKey(cellReference.ToUpper()))
#endif
                {
                    cellReference = Convert.ToString(this.NamedRanges[cellReference.ToUpper()]);
                    if (!cellReference.StartsWith(sheetToken.ToString()))
                    {
                        cellReference = sheetToken1 + cellReference;
                    }
                }
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                //else if (this.namedRangesNonScoped.Contains(cellReference.ToUpper()))
                else if(CheckIfScopedRange(cellReference.ToUpper(), out scopedRange))
#else
                //else if (this.namedRangesNonScoped.ContainsKey(cellReference.ToUpper()))
                    else if(CheckIfScopedRange(cellReference.ToUpper(), out scopedRange))
#endif
                {
                    cellReference = Convert.ToString(scopedRange);
                    if (!cellReference.StartsWith(sheetToken.ToString()))
                    {
                        cellReference = sheetToken1 + cellReference;
                    }
                }
                else
                {
                    return "#REF!";
                }
            }

            if (cellReference.Contains(":"))
            {
                if (cellReference.Contains(STRING_fixedreference))
                {
                    return cellReference.Replace(STRING_fixedreference, string.Empty);
                }
                else
                    return cellReference;
            }

            return this.GetValueFromArg(cellReference);
        }

        /// <summary>
        /// Returns the integer value.
        /// </summary>
        /// <param name="range">Number to be truncated.</param>
        /// <returns>An integer.</returns>
        public string ComputeInt(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeInt"; MarkTimeStart(ML);
#endif
            range = this.GetValueFromArg(range);
            double d;
            if (double.TryParse(range, NumberStyles.Any, null, out d))
            {
                double d1 = (d < 0) ? -1 : 1;
                double d2 = (d < 0) ? 1 : 0;
#if _ENABLETIMERS
                string v = (d1 * Math.Floor(d2 + Math.Abs(d))).ToString("F0");
                MarkTimeEnd(ML);
                return v;
#else
                return (d1 * Math.Floor(d2 + Math.Abs(d))).ToString("F0");
#endif
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return "0";
        }

        /// <summary>
        /// Returns the y-intercept of the least square fit line through the given points.
        /// </summary>
        /// <param name="range">y_range, x_range.</param>
        /// <returns>y-intercept for the given points.</returns>
        public string ComputeIntercept(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeIntercept"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += (double)x[i];
                sumy += (double)y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = (double)x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return (sumy - sumxy / sumx2 * sumx).ToString();
        }

        internal string ComputeInteriorFunctions(string formula)
        {
            try
            {
                if (TextIsEmpty(formula))
                {
                    return formula;
                }

                this.computeFunctionLevel++;

                ////int q = formula.LastIndexOf('q');
                int q = this.FindLastqNotInBrackets(formula);
                while (q > 0)
                {
                    int last = formula.Substring(q).IndexOf(this.RIGHTBRACKET);
                    if (last == -1)
                    {
                        return this.FormulaErrorStrings[bad_formula];
                    }

                    string s = formula.Substring(q, last + 1);
                    s = this.ComputedValue(s);
                    if (!string.IsNullOrEmpty(s) 
                            && s[0] == this.TIC[0]
                            && s[s.Length - 1] == this.TIC[0])
                    {
                        string newS = s.Substring(1, s.Length - 2);
                        if (newS.IndexOf(this.TIC) != -1)
                        {
                            multiTick = true;
                            newS = newS.Replace(this.TIC, "|");
                        }
                        s = this.TIC + newS + this.TIC;
                    }
                    MarkupResultToIncludeInFormula(ref s);

                    formula = formula.Substring(0, q) + s + formula.Substring(q + last + 1);
                    q = this.FindLastqNotInBrackets(formula);
                }
            }
            catch (Exception ex)
            {
                if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                {
                    throw this.LibraryComputationException;
                }

                return ex.Message;
            }
            finally
            {
                this.computeFunctionLevel--;
            }

            return formula;
        }

        private void MarkupResultToIncludeInFormula(ref string s)
        {
            double d3;
            if (s.Length > 0 && s[0] == '-' && double.TryParse(s, out d3))
            {
                s = "nu" + s.Substring(1);
            }
            else if (s.Length > 0 &&
                (s[0] == this.TIC[0] || s[0] == BMARKER || s[0] == '#'))
            {
                ////Pass on the string...
            }
            else if (s.StartsWith(this.TRUEVALUESTR) || s.StartsWith(FALSEVALUESTR))
            {
                ////Pass on the bool...
            }
            else
            {
                double d = 0;

                ////if(double.TryParse(s, NumberStyles.Any, null, out d))
                if (double.TryParse(s, out d))
                {
                    // s = d.ToString(); ////defect 8721
                    s = string.Format("{0:d}", s);
                    s = s.Replace(CalcEngine.ParseArgumentSeparator,  (char)32);
                    
                    s = 'n' + s;
                }
                else
                {
                    if (!this.IsRange(s))
                    {
                        s = this.TIC + s + this.TIC;
                    }
                }
            }
           
        }

        /// <summary>
        /// Computes the interest payment for a period.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period, the period,
        /// number of periods, present value, future value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Interest payment.</returns>
        public string ComputeIpmt(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeIpmt"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 6 && argCount != 5 && argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double per;
            double nper;
            double pv = 0;
            double fv = 0;
            double type = 0;

            double impt = 0;
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out per)
                && double.TryParse(args[2], NumberStyles.Any, null, out nper)
                && double.TryParse(args[3], NumberStyles.Any, null, out pv)
                && (argCount == 4 || double.TryParse(args[4], NumberStyles.Any, null, out fv))
                && (argCount <= 5 || double.TryParse(args[5], NumberStyles.Any, null, out type)))
            {
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }

                double x0 = Math.Pow((1 + rate), nper);
                double x1 = Math.Pow((1 + rate), per);
                double pmt = (rate * (fv + pv * x0)) / ((1 + rate * type) * (1 - x0));
                double fv1 = (pmt * (1 + rate * type) * (1 - x1) / rate) - pv * x1;
                double x2 = Math.Pow((1 + rate), per - 1);
                double fv2 = (pmt * (1 + rate * type) * (1 - x2) / rate) - pv * x2;

                impt = pmt - fv2 + fv1;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return impt.ToString();
        }

        /// <summary>
        /// Computes the internal rate of return of a series of cash flows.
        /// </summary>
        /// <param name="argList">Delimited string containing a range of cells and an initial guess.</param>
        /// <returns>Internal rate of return.</returns>
        /// <remarks>
        /// This IRR calculation uses Newton's method to approximate a root of
        ///           f(r) = Sum( values[i]/(1+r)^i) = 0
        /// where the Sum index is i = 1 to the number of values. The algorithm returns a value if
        /// the relative difference between root approximations is less than 1e-5. It fails if this
        /// accuracy is not attained in 20 iterations.
        /// </remarks>
        public string ComputeIrr(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeIrr"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 1 && argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double guess = .1;
            string arg1 = args[0];
            if (argCount == 2)
            {
                double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out guess);
            }

            args = this.GetCellsFromArgs(arg1);
            argCount = args.GetLength(0);
            double[] values = new double[argCount];
            int i = 0;
            double d;
            foreach (string s in args)
            {
                if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out d))
                {
                    values[i] = d;
                }

                ++i;
            }

            int iteration = 0;
            double gp1, numer, denom, powgp1;
            ////hard coded excel values
            while (iteration < 20) 
            {
                numer = 0;
                denom = 0;
                gp1 = Math.Abs(guess + 1);
                powgp1 = gp1;

                for (i = 0; i < argCount; ++i)
                {
                    numer += values[i] / powgp1;
                    powgp1 *= gp1;
                    denom += (i + 1) * values[i] / powgp1;
                }

                numer = numer / denom;

                ////hard coded excel values
                if (Math.Abs(numer / guess) < 1e-5)
                {
                    guess = guess + numer;
                    break;
                }

                guess = guess + numer;
                iteration++;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            ////hard coded excel values
            if (iteration >= 20)	
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            else
            {
                return guess.ToString();
            }
        }

