        ///<summary>
        /// Returns a number corresponding to the predefined error values(#NULL!, #VALUE!, #REF!, #NAME?, #NUM!, #N/A, "#GETTING_DATA). Returns #N/A if not or any value enclosed within double quotes.
        ///</summary>
        public string ComputeErrorType(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeErrorType"; MarkTimeStart(ML);
#endif
            string cellReference = string.Empty;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            int argCount = arg.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[requires_a_single_argument];
            }
            if (this.IsCellReference(args))
            {
                cellReference = this.GetValueFromArg(args);
            }
            else
            {
                cellReference = args;
            }
            if (cellReference.Length > 1
                           && cellReference[0] == this.TIC[0]
                           && cellReference[cellReference.Length - 1] == this.TIC[0])
            {
                return "#N/A";
            }
            if (cellReference.Equals("#NULL!"))
                return "1";
            else if (cellReference.Equals("#DIV/0!"))
                return "2";
            else if (cellReference.Equals("#VALUE!"))
                return "3";
            else if (cellReference.Equals("#REF!"))
                return "4";
            else if (cellReference.Equals("#NAME?"))
                return "5";
            else if (cellReference.Equals("#NUM!"))
                return "6";
            else if (cellReference.Equals("#N/A"))
                return "7";
            else if (cellReference.Equals("#GETTING_DATA"))
                return "8";
            return "#N/A";
        }

