        /// <summary>
        /// Returns the kurtosis of the passed in values.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>The kurtosis of the data.</returns>
        public string ComputeKurt(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeKurt"; MarkTimeStart(ML);
#endif
            double[] xx = this.GetDoubleArray(range);
            int n = xx.GetLength(0);
            if (n <= 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.wrong_number_arguments];
            }

            double ssd4 = Math.Pow(this.var(xx), 2);
            double sumx = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += xx[i];
            }

            sumx = sumx / n;
            double sum = 0;
            for (int i = 0; i < n; ++i)
            {
                sum += Math.Pow(xx[i] - sumx, 4);
            }

            sum = n * (n + 1) / ((n - 1) * (n - 2) * (n - 3) * ssd4) * sum - 3 * (n - 1) * (n - 1) / ((n - 2) * (n - 3));
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

        /// <summary>
        /// Returns the Kth largest value in the range.
        /// </summary>
        /// <param name="range">range, k.</param>
        /// <returns>Kth largest value.</returns>
        public string ComputeLarge(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeLarge"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x0;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Integer, null, out x0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            int k = (int)x0;
            double[] dd = this.GetDoubleArray(args[0]);
            int n = dd.GetLength(0);
            if (k < 1 || k > n)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            Array.Sort(dd);
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dd[n - k].ToString();
        }

        /// <summary>
        /// Returns the left so many characters in the given string.
        /// </summary>
        /// <param name="range">Contains the string and the number of characters.</param>
        /// <returns>A left sub string..</returns>
        public string ComputeLeft(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeLeft"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 1 && argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string s1 = args[0];
            if (!this.IsCellReference(args[0]) && !args[0].Contains(this.TIC))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                return this.ErrorStrings[5].ToString();
            }
            s1 = this.GetValueFromArg(s1);
            bool hasTics = s1.StartsWith(this.TIC) && s1.EndsWith(this.TIC);
            string s2 = (argCount == 2) ? args[1] : "1";
            s2 = this.ComputedValue(s2);
            int len = int.Parse(s2) + (hasTics ? 1 : 0);
            len = (s1.Length >= len) ? len : s1.Length;
            s1 = s1.Substring(0, len);
            if (hasTics && !s1.EndsWith(this.TIC))
            {
                s1 = s1 + this.TIC;
            }
            if (this.UseNoAmpersandQuotes && s1.Length > 1
                           && s1[0] == this.TIC[0]
                           && s1[s1.Length - 1] == this.TIC[0])
            {
                s1 = s1.Substring(1, s1.Length - 2);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s1;
        }

        /// <summary>
        /// Returns an array of argument strings from a single string where the arguments are delimited by <see cref="CalcEngine.ParseArgumentSeparator"/>.
        /// </summary>
        /// <param name="args">Contains the argument list.</param>
        /// <returns>A string array of arguments.</returns>
        /// <remarks>This method properly preserves any quoted strings that contain the <see cref="CalcEngine.ParseArgumentSeparator"/> character.</remarks>
        public string[] SplitArgsPreservingQuotedCommas(string args)
        {
            if (args.IndexOf(TIC) == -1)
            {
                return args.Split(new char[] { parseArgumentSeparator });
            }

            Hashtable formulaStrings = this.SaveStrings(ref args); ////replaces quoted strings with tokens
            string[] results = args.Split(new char[] { ParseArgumentSeparator });
            List<string> pieces = new List<string>();
            foreach (string s in results)
            {
                string s1 = s;
                this.SetStrings(ref s1, formulaStrings); ////replace tokens with original strings
                pieces.Add(s1);
            }

            return pieces.ToArray();

        }

        /// <summary>
        /// A method to split the arguments using argument seperator.
        /// </summary>
        /// <param name="args">arguments to split.</param>
        /// <param name="argSeperator">argument seperator used to split.</param>
        /// <returns>A string array.</returns>
        private string[] SplitArguments(string args, char argSeperator)
        {
            ArrayList splitArg = new ArrayList();
            int start = 0;
            int ticCount = 0;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i].Equals('"'))
                {
                    if (ticCount == 0)
                        ticCount++;
                    else
                        ticCount = 0;
                }
                if ((args[i].Equals(argSeperator) && !ticCount.Equals(1)))
                {
                    splitArg.Add(args.Substring(start, i - start));
                    start = i + 1;
                }
                if (i.Equals(args.Length - 1))
                {
                    splitArg.Add(args.Substring(start, i - start + 1));
                }
            }
            
            String[] argList = new String[splitArg.Count];
            Array.Copy(splitArg.ToArray(), argList, argList.Length);
            return argList;
        }

