        /// <summary>
        /// Finds the index a specified value in a lookup_range.
        /// </summary>
        /// <param name="arg">look_value, lookup_range, match_type</param>
        /// <returns>The relative index of the lookup_value in the lookup_range.</returns>
        /// <remarks>
        /// Lookup_range should be a either a single row range or a single column range.
        /// If match_type is 0, the relative index of the first exact match (ignoring case)
        /// in the specified range is returned. If match_type is 1, the values in the range
        /// should be in ascending order, and the index of the largest value less than or
        /// equal to the lookup_value is returned. If match_type is -1, the values in the range
        /// should be in descending order, and the index of the smallest value greater than or
        /// equal to the lookup_value is returned.
        /// </remarks>
        public string ComputeMatch(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeMatch"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            int argCount = args.GetLength(0);
            if (argCount != 3 && argCount != 2)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string r = args[1].Replace(this.TIC, string.Empty);
            int i = r.IndexOf(":");
            int m = 1;
            if (argCount == 3)
            {
                double d;
                string thirdArg = this.GetValueFromArg(args[2]);
                thirdArg = thirdArg.Replace(this.TIC, string.Empty);
                m = double.TryParse(thirdArg, NumberStyles.Integer, null, out d) ? (int)d : 1;
                if (thirdArg.Contains(this.TIC) && (thirdArg.Contains(this.TRUEVALUESTR) || thirdArg.Contains(this.FALSEVALUESTR)))
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    if (rethrowLibraryComputationExceptions)
                        throw new ArgumentException("Passed arguments contains invalid argument");
                    else
                        return ErrorStrings[1].ToString();
                }
                else if (thirdArg == this.FALSEVALUESTR)
                    m = 0;
                else if (thirdArg == this.TRUEVALUESTR)
                    m = 1;
                else if (thirdArg.Contains(this.TIC) && this.ComputeIsText(thirdArg) == this.TRUEVALUESTR)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    if (rethrowLibraryComputationExceptions)
                        throw new ArgumentException("Passed arguments contains invalid argument");
                    else
                        return ErrorStrings[1].ToString();
                }
            }

            string searchItem = this.GetValueFromArg(args[0]).Replace(this.TIC, string.Empty).ToUpper();
            if (i > -1)
            {
                int row1 = this.RowIndex(r.Substring(0, i));
                int row2 = this.RowIndex(r.Substring(i + 1));
                if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[5].ToString();
                }
                if (row1 == -1 && this.grid is ISheetData)
                {
                    row1 = ((ISheetData)grid).GetFirstRow();
                }
                int col1 = this.ColIndex(r.Substring(0, i));
                if (col1 == -1 && this.grid is ISheetData)
                {
                    col1 = ((ISheetData)grid).GetFirstColumn();
                }
                if (row2 == -1 && this.grid is ISheetData)
                {
                    row2 = ((ISheetData)grid).GetLastRow();
                }
                int col2 = this.ColIndex(r.Substring(i + 1));
                if (col2 == -1 && this.grid is ISheetData)
                {
                    col2 = ((ISheetData)grid).GetLastColumn();
                }
            }
            string[] cells = this.GetCellsFromArgs(this.StripTics(r));
            int index = 1;
            string oldValue = string.Empty;
            string newValue;
            foreach (string s in cells)
            {
                newValue = this.GetValueFromArg(s).Replace(this.TIC, string.Empty).ToUpper();
                if (oldValue != string.Empty)
                {
                    if (m == 1)
                    {
                        if (this.matchCompare(newValue, oldValue) < 0)
                        {
                            index--;
                            break;
                        }
                    }
                    else if (m == -1)
                    {
                        if (this.matchCompare(newValue, oldValue) > 0)
                        {
                            index = -1;
                            break;
                        }
                    }
                }

                if (m == 0 && newValue == searchItem)
                {
                    break;
                }
                else if (m == 1 && this.matchCompare(searchItem, newValue) < 0)
                {
                    index--;
                    break;
                }
                else if (m == -1 && this.matchCompare(searchItem, newValue) > 0)
                {
                    index--;
                    break;
                }

                index++;
                oldValue = newValue;
            }

            if (m != 0 && index == cells.Length + 1)
            {
                index = cells.Length;
            }

#if _ENABLETIMERS
            string v;
            if (index > 0 && index <= cells.Length)
                v = index.ToString();
            else
                v =  "#N/A";
            MarkTimeEnd(ML);
            return v;
#else
            if (index > 0 && index <= cells.Length)
            {
                return index.ToString();
            }
            else
            {
                return "#N/A";
            }
#endif
        }

        private string ComputeMath(string args, MathFunc func)
        {
            double ans = 0;
            double d1;
            string s1;

            ////Only work with first arg.
            if (args.Length > 0)
            {
                args = SplitArgsPreservingQuotedCommas(args)[0].Replace(this.TIC, "");
            }

            ////parsed formula
            if (args.Length > 0 && ((!char.IsLetter(args[0]) && args[0] != sheetToken && args[0] != BMARKER) || (args[0] == 'u' && char.IsDigit(args[1])))
                && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1)
            {
                ////Swap out unary minus.
                args = args.Replace('u', '-').Replace("n", string.Empty);

                if (double.TryParse(args, NumberStyles.Number | NumberStyles.AllowExponent, null, out d1))
                {
                    ans = func(d1);
                }
                else
                {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[4].ToString();
                }
            }
            else if (args.Length > 0 && (args[0] == BMARKER || args[0] == 'u' || args[0] == 'n' || args.IndexOfAny(this.tokens) > -1))
            {
                ////parsed formula
                args = args.Replace('{', '(');
                args = args.Replace('}', ')');

                try
                {
                    s1 = this.ComputedValue(args);
                }
                catch (Exception ex)
                {
                    if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                    {
                        throw this.LibraryComputationException;
                    }

                    return ex.Message;
                }

                if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d1))
                {
                    ans = func(d1);
                   // ans = Math.Sin(d1);
                }
                else
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[1].ToString();
            }
            else
            {
                ////Swap out unary minus.
                args = args.Replace('u', '-');

                foreach (string s in this.GetCellsFromArgs(args))
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s);
                    }
                    catch (Exception ex)
                    {
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d1))
                        {
                            ans = func(d1);
                        }
                        else
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[1].ToString();
                    }

                    break; ////Do only the first one... ignore any others.
                }
            }
            if (this.ComputeIsErr(ans.ToString()) == this.TRUEVALUESTR)
            {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            return ans.ToString();
        }

        /// <summary>
        /// Returns the maximum value of all values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>A string holding the maximum value of all values listed in the argument.</returns>
        public string ComputeMax(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeMax"; MarkTimeStart(ML);
#endif
            double max = double.MinValue;
            double d;
            string s1;

