        /// <summary>
        /// Returns the median value in the range.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>Median value.</returns>
        public string ComputeMedian(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeMedian"; MarkTimeStart(ML);
#endif
            double[] dd = this.GetDoubleArray(range);
            Array.Sort(dd);
            int n = dd.GetLength(0) / 2;
            string s1 = string.Empty;
            if (dd.GetLength(0) % 2 == 1)
            {
                s1 = dd[n].ToString();
            }
            else
            {
                s1 = ((dd[n] + dd[n - 1]) / 2).ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s1;
        }

        /// <summary>
        /// Returns a substring of the given string.
        /// </summary>
        /// <param name="range">Contains the original string, start position of the substring,
        /// and the number of characters in the substring.</param>
        /// <returns>A substring.</returns>
        public string ComputeMid(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeMid"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string s1 = args[0];
            s1 = this.GetValueFromArg(s1);
            bool hasTics = s1.StartsWith(this.TIC) && s1.EndsWith(this.TIC);
            string s2 = this.GetValueFromArg(args[2]);
            int len = int.Parse(s2);
            if (args[1].IndexOf("#VALUE!") > -1)
            {
                return "#VALUE!";
            }

            s2 = this.GetValueFromArg(args[1]);
            int start = int.Parse(s2) + (hasTics ? 0 : -1);

            if (start + len > s1.Length)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            s1 = s1.Substring(start, len);
            if (hasTics && !s1.StartsWith(this.TIC))
            {
                s1 = this.TIC + s1;
            }

            if (hasTics && !s1.EndsWith(this.TIC))
            {
                s1 = s1 + this.TIC;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s1;
        }

