        /// <summary>
        /// Returns the minute of the given time.
        /// </summary>
        /// <param name="argList">Given time.</param>
        /// <returns>Minute of given time.</returns>
        public string ComputeMinute(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeMinute"; MarkTimeStart(ML);
#endif
            double time;
            DateTime dt = DateTime.Now;
            argList = this.GetValueFromArg(argList);
            if (argList.IndexOf(this.TIC) > -1)
            {
                argList = argList.Replace(this.TIC, string.Empty);
                dt = DateTime.Parse(argList);
            }
            else
            {
                try
                {
                    dt = DateTime.Parse(argList);
                }
                catch
                {
                    if (double.TryParse(argList, NumberStyles.Any, null, out time))
                    {
                        dt =
#if WINDOWS_UWP
                            Syncfusion.XlsIO.Implementation.DateTimeExtension.FromOADate(time);
#else
                            DateTime.FromOADate(time);
#endif
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dt.Minute.ToString();
        }

        /// <summary>
        /// Computes the modified internal rate of return of a series of cash flows.
        /// </summary>
        /// <param name="argList">Delimited string containing a range of cells,
        /// finance interest rate, and a reinvested interest rate.</param>
        /// <returns>Modified internal rate of return.</returns>
        public string ComputeMirr(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeMirr"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double val = 0;
            double frate = .1;
            double rrate = .1;
            double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out frate);
            double.TryParse(this.GetValueFromArg(args[2]), NumberStyles.Any, null, out rrate);

            string arg1 = args[0];
            args = this.GetCellsFromArgs(arg1);
            argCount = args.GetLength(0);
            double[] values = new double[argCount];
            int i = 0;
            double d;
            foreach (string s in args)
            {
                if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out d))
                {
                    values[i] = d;
                }

                ++i;
            }

            double posValues = 0;
            double negValues = 0;
            double rpow = 1;
            double fpow = 1 + frate;

            for (i = 0; i < argCount; ++i)
            {
                rpow *= 1 + rrate;

                if (values[i] > 0)
                {
                    posValues += values[i] / rpow;
                }
                else
                {
                    negValues += values[i] / fpow;
                }

                fpow *= 1 + frate;
            }

            posValues = -posValues * rpow;
            negValues = negValues * (1 + frate);
            val = Math.Pow(posValues / negValues, 1d / (argCount - 1d)) - 1d;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val.ToString();
        }

