            return v;
#else
            return (int.Parse(s1) % int.Parse(s2)).ToString();
#endif
        }

        /// <summary>
        /// Returns the most frequent value in the range.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>The most frequent value.</returns>
        public string ComputeMode(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeMode"; MarkTimeStart(ML);
#endif
            double[] dd = this.GetDoubleArray(range);
            double[] ddSave = dd.Clone() as Double[];
            int n = dd.GetLength(0);
            if (n <= 1)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return "#N/A";
            }

            Array.Sort(dd);
            ArrayList ties = new ArrayList();
            double mode = double.NaN;
            int count = 0;
            int maxCount = 0;

            for (int i = 1; i < n; ++i)
            {
                if (dd[i] == dd[i - 1])
                {
                    count++;
                }
                else
                {
                    if (count > maxCount)
                    {
                        maxCount = count;
                        mode = dd[i - 1];
                        ties.Clear();
                        ties.Add(mode);
                    }
                    else if (count == maxCount)
                    {
                        ties.Add(dd[i - 1]);
                    }

                    count = 0;
                }
            }

            if (count > maxCount)
            {
                maxCount = count;
                mode = dd[n - 1];
                ties.Clear();
                ties.Add(mode);
            }

            if (maxCount > 0)
            {
                if (count == maxCount)
                {
                    ties.Add(dd[n - 1]);
                }

                if (ties.Count > 1)
                {
                    foreach (double d in ddSave)
                    {
                        if (ties.IndexOf(d) > -1)
                        {
                            mode = d;
                            break;
                        }
                    }
                }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return mode.ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return "#N/A";
        }

        /// <summary>
        /// Returns the month of the given date.
        /// </summary>
        /// <param name="argList">given time</param>
        /// <returns>Month of given date.</returns>
        public string ComputeMonth(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeMonth"; MarkTimeStart(ML);
#endif
             double month = 1;
            DateTime date;
            string s = this.GetValueFromArg(argList);
            if (DateTime.TryParse(s.Replace(TIC, string.Empty), out date))
            {
                month = date.Month;
            }
            else
            {

                double serialdate;
                if (double.TryParse(this.GetValueFromArg(argList), NumberStyles.Any, null, out serialdate))
                {
                    ////serialdate = serialdate - 1 - ((Treat1900AsLeapYear && serialdate > 59) ?  1 : 0);
                    if (serialdate < 1)
                    {
                        month = 1;
                    }
                    else
                    {
                        date = this.GetDateFromSerialDate((int)serialdate); ////dateTime1900.AddDays(serialdate);
                        month = date.Month;
                    }
                }
                else
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[invalid_arguments];
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return month.ToString();
        }

        /// <summary>
        /// Determines the Multinominal value of given range of numbers.
        /// </summary>
        /// <param name="range">Given numbers</param>
        /// <returns>Multinominal value of given range of numbers.</returns>
        public string ComputeMultinomial(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeMultinomial"; MarkTimeStart(ML);
#endif
            double d;
            string s1;
            string str = string.Empty;
            int arrayList = 0, elements = 0;
            string total = ComputeSum(range);
            string totalFact = ComputeFact(total);
            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                            elements++;
                    }
                }
            }
            string[] ranges2 = new string[elements];
            foreach (string r in ranges)
            {
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.FormulaErrorStrings[26];
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Any, null, out d))
                            {
                                string fact = ComputeFact(d.ToString());
                                ranges2[arrayList] = fact;
                                arrayList++;
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        return this.FormulaErrorStrings[26];
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            if (d > 0)
                            {
                                string fact = ComputeFact(d.ToString());
                                ranges2[arrayList] = fact;
                                arrayList++;
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                            else
                            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                                return this.ErrorStrings[4].ToString();
                            }
                        }
                        else
                        {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[1].ToString();
                        }
                    }
                }
            }
            str = ranges2[0];
            for (int i = 1; i < ranges2.Length; i++)
            {
                str = str + "," + ranges2[i];
            }
            string multi = ComputeProduct(str);
            double totalFactVal = double.Parse(totalFact);
            double multiValue = double.Parse(multi);
            double multinominalVal = totalFactVal / multiValue;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return multinominalVal.ToString();
        }

        /// <summary>
        /// Determines the number rounded to the given multiple.
        /// </summary>
        /// <param name="argList">Number, Multible both are required</param>
        /// <returns>Mround value of given number</returns>
        public string ComputeMround(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeMround"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.wrong_number_arguments];
            }
            double x = 0;
            double digits = 0;
            double numberstr, mround;
            string round;
            string numStr = this.GetValueFromArg(args[0]).Replace(this.TIC, string.Empty);
            string digStr = this.GetValueFromArg(args[1]).Replace(this.TIC, string.Empty);
            if(! (double.TryParse(numStr, NumberStyles.Any, null, out x) && double.TryParse(digStr, NumberStyles.Any, null, out digits)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            if (digits == 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return digStr;
            }
            if (ComputeSign(numStr) != ComputeSign(digStr))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            else
            {

                numberstr = x / digits;
                round = ComputeRound(numberstr.ToString());
                double round1 = double.Parse(round);
                mround = round1 * digits;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return mround.ToString();
        }

        /// <summary>
        /// Returns a random integer number between the specified two numbers.
        /// </summary>
        /// <param name="argList">StartNumber, EndNumber</param>
        /// <returns>Random numberbetween two value</returns>
        public string ComputeRandbetween(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeRandbetween"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.wrong_number_arguments];
            }
            string arg1 = this.GetValueFromArg(args[0]).Replace(this.TIC, string.Empty);
            string arg2 = this.GetValueFromArg(args[1]).Replace(this.TIC, string.Empty);
            double bottom, top;
            if (!double.TryParse(arg1, NumberStyles.Any, null, out bottom) || !double.TryParse(arg2, NumberStyles.Any, null, out top))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            string number1 = ComputeRound(arg1);
            string number2 = ComputeRound(arg2);
            if (!double.TryParse(arg1, NumberStyles.Any, null, out bottom) || !double.TryParse(arg2, NumberStyles.Any, null, out top))
                return "#NAME?";
            if (bottom > top)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            if (this.rand == null)
                this.rand = new Random();
#if _ENABLETIMERS
            string v = rand.Next(bottom,top).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return this.rand.Next(int.Parse(number1), int.Parse(number2)).ToString();
#endif
        }

        /// <summary>
        /// Returns the square root of product of given number with PI.
        /// </summary>
        /// <param name="args">Number</param>
        /// <returns>Sqrtpi value of given number</returns>
        public string ComputeSqrtpi(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeSqrtpi"; MarkTimeStart(ML);
#endif
            double sqrtValue, number;
            string s1 = string.Empty;
            string sqrtpi = string.Empty;
            string[] numList = SplitArgsPreservingQuotedCommas(args);
            if (numList.GetLength(0) > 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }
            if (args.Length > 0 && !char.IsLetter(args[0]) && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1)
            {
                if (!double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out number))
                {
#if _ENABLETIMERS
                   MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[1].ToString();
                }
                else if (number < 0)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[4].ToString();
                }
                else
                {

                    sqrtValue = number * Math.PI;
                    sqrtpi = ComputeSqrt(sqrtValue.ToString());
                }
            }
            else if (args.Length > 0 && (args[0] == BMARKER || args[0] == 'u' || args[0] == 'n' || args.IndexOfAny(this.tokens) > -1))
            {
                ////parsed formula
                args = args.Replace('{', '(');
                args = args.Replace('}', ')');

                try
                {
                    s1 = this.GetValueFromArg(args).Replace(this.TIC, string.Empty);
                }
                catch (Exception ex)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                    {
                        throw this.LibraryComputationException;
                    }

                    return this.FormulaErrorStrings[26];
                }
                if (double.TryParse(s1, NumberStyles.Any, null, out number) && number >= 0)
                {
                    sqrtValue = number * Math.PI;
                    sqrtpi = ComputeSqrt(sqrtValue.ToString());
                }
                else if (this.ErrorStrings.Contains(s1))
                {
                    return s1;
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[4].ToString();
                }
            }
            else
            {
                foreach (string s in this.GetCellsFromArgs(args))
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s1).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }
                        return this.FormulaErrorStrings[26];
                    }
                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out number) && number >= 0)
                        {
                            sqrtValue = number * Math.PI;
                            sqrtpi = ComputeSqrt(sqrtValue.ToString());
                            break; //Skip out after first value.
                        }
                        else if (this.ErrorStrings.Contains(s1))
                        {
                            return s1;
                        }
                        else
                        {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[4].ToString();
                        }
                    }
                }
            }

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sqrtpi;
        }
