        /// <summary>
        /// Returns the Double factorial value for given number.
        /// </summary>
        /// <param name="args">number to find FactDouble</param>
        /// <returns>FactDouble of given number. </returns>
        public string ComputeFactdouble(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeFactdouble"; MarkTimeStart(ML);
#endif
            double number;
            double fact = 1;
            string[] numList = SplitArgsPreservingQuotedCommas(args);
            if (numList.GetLength(0) > 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }
            if (!double.TryParse(this.GetValueFromArg(args).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number))
             {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            else if (number < 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            else
            {
                int x = (int)number;
                int n = x;
                if (x > 3)
                {
                    while (n > 0)
                    {
                        fact = fact * n;
                        n = n - 2;
                    }
                }
                else if (x == 0)
                    fact = 1;
                else
                    fact = x;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return fact.ToString();
        }
        /// <summary>
        /// Returns the largest integer that divide the given numbers without any reminders.
        /// </summary>
        /// <param name="range">number1,number2,...</param>
        /// <returns>Returns the GCD value of given arguments</returns>
        public string ComputeGcd(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeGcd"; MarkTimeStart(ML);
#endif
            int arrayList = 0;
            int reminder, elements = 0;
            double number;
            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            if (range.Contains("u"))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.ErrorStrings[4].ToString());
                return this.ErrorStrings[4].ToString();// "#NUM!";
            }
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            int[] ranges2 = new int[elements];
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if ((double.TryParse(this.GetValueFromArg(s).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number) || s.Length > 0) && (int)number > 0)
                        {
                            ranges2[arrayList] = (int)number;
                            arrayList++;
                        }
                        else
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[4].ToString();
                    }
                }
                else
                {
                    if (!double.TryParse(this.GetValueFromArg(r).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number))
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[1].ToString();
                    }
                    else if ((r.Length > 0) && (int)number >= 0)
                    {
                        ranges2[arrayList] = (int)number;
                        arrayList++;
                    }
                    else
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[4].ToString();
                    }
                }
            }
            if (ranges2.Length == 1)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return ranges2[0].ToString();
            }
            for (int i = 0; i < ranges2.Length - 1; i++)
            {
                while (ranges2[1] != 0)
                {
                    reminder = ranges2[0] % ranges2[1];
                    ranges2[0] = ranges2[1];
                    ranges2[1] = reminder;
                }
                if (ranges2.Length > 2 && i < ranges2.Length - 2)
                    ranges2[1] = ranges2[i + 2];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return ranges2[0].ToString();
        }

        /// <summary>
        /// returns the smallest positive integer that is a multiple of all given values.
        /// </summary>
        /// <param name="range">Number1,Number2,...</param>
        /// <returns>The LCM value of given aruments</returns>
        public string ComputeLcm(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeLcm"; MarkTimeStart(ML);
#endif
            int arrayList = 0, elements = 0;
            double number;
            string gcd, str = string.Empty;
            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            int[] ranges2 = new int[elements];
            foreach (string r in ranges)
            {
                //is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if (!double.TryParse(this.GetValueFromArg(s).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number))
                        {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[1].ToString();
                        }
                        if (s.Length > 0 && (int)number >= 0)
                        {
                            ranges2[arrayList] = (int)number;
                            arrayList++;
                        }
                        else
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[4].ToString();
                    }
                }
                else
                {
                    if (!double.TryParse(this.GetValueFromArg(r).Replace(this.TIC, string.Empty), NumberStyles.Any, null, out number))
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[1].ToString();
                    }
                    if (r.Length > 0)
                    {
                        ranges2[arrayList] = (int)number;
                        arrayList++;
                    }
                    else
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[4].ToString();
                }
            }
            if (ranges2.Length == 1)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return ranges2[0].ToString();
            }
            int multi = ranges2[0] * ranges2[1];
            str = ranges2[0].ToString() + ParseArgumentSeparator + ranges2[1].ToString();
            gcd = ComputeGcd(str);
            int lcm = multi / int.Parse(gcd);
            for (int i = 2; i < ranges2.Length; i++)
            {
                multi = lcm * ranges2[i];
                str = lcm.ToString() + ParseArgumentSeparator + ranges2[i].ToString();
                gcd = ComputeGcd(str);
                lcm = multi / int.Parse(gcd);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return lcm.ToString();
        }

