                || range.StartsWith("-NAN")
                || range.StartsWith("INFINITY")
                || range.StartsWith("-INFINITY")
                || range.StartsWith("#")
                || range.StartsWith("n#")
                )
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                        return GetValueFromArg(argsArray[1]);
                }

                range = argsArray[0];

                range = GetValueFromArg(range).ToUpper().Replace(TIC, string.Empty);
            }
            catch
            {
                range = range.ToUpper();
            }
            if (range.StartsWith("NAN")
                || range.StartsWith("-NAN")
                || range.StartsWith("INFINITY")
                || range.StartsWith("-INFINITY")
                || range.StartsWith("#")
                || range.StartsWith("n#")
                )
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return GetValueFromArg(argsArray[1]);
            else
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return GetValueFromArg(argsArray[0]);
        }
        /// <summary>
        /// Returns the string or text referred by the given value.
        /// </summary>
        /// <param name="args">value to find the referred text - Required </param>
        /// <returns>Returns the referred text</returns>
        public string ComputeT(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeT"; MarkTimeStart(ML);
#endif
            int elements = 0;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            if (arg.Length > 0)
            {
                foreach (string r in arg)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s1 in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            if (elements > 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string s = GetValueFromArg(args);
            DateTime d;
            string pattern = @"[a-zA-Z0-9!#$%&'()*+,/:;<=>?@\^_`{|}~-]";
            if (ComputeIsNumber(args) == "TRUE" || ComputeIsLogical(args) == "TRUE" || (UseDatesInCalculations && IsDate(s, out d)))
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return string.Empty;
            }
            else if (Regex.IsMatch(s, pattern))
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                s = s.Replace(this.TIC, string.Empty);
                return s;
            }
            else
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return string.Empty;
            }
        }

        /// <summary>
        /// Returns the negative binomial distribution.
        /// </summary>
        /// <param name="argList">Number of failures, success threshold, probability, cumulative.</param>
        /// <returns>The negative binomial distribution.</returns>
        public string ComputeNegbinomdist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNegbinomdist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double successes;
            double failures;
            double p;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out failures)
                && double.TryParse(args[1], NumberStyles.Any, null, out successes)
                && double.TryParse(args[2], NumberStyles.Any, null, out p))
            {
                dist = this.negbinomdensity((int)failures, (int)successes, p);
            }

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Returns the normal distribution.
        /// </summary>
        /// <param name="argList">x, mean, standarddev, cumulative.</param>
        /// <returns>The normal distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function. The distribution value
        /// is computed interactively using Trapezoidal Rule to six to seven significant digits
        /// or 20 iteration maximum.
        /// </remarks>
        public string ComputeNormdist(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNormdist"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double u;
            double s;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out u)
                && double.TryParse(args[2], NumberStyles.Any, null, out s))
            {
                if (argCount != 3)
                {
                    cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                }

                if (cum == 0)
                {
                    dist = this.normaldensity(x, u, s);
                }
                else
                {
                    dist = this.normaldist(x, u, s);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Returns the inverse of normal distribution.
        /// </summary>
        /// <param name="argList">P, mean, standard deviation.</param>
        /// <returns>Returns x such that normal distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeNorminv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNorminv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p;
            double u;
            double s;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && (p > 0 && p < 1)
                && double.TryParse(args[1], NumberStyles.Any, null, out u)
                && double.TryParse(args[2], NumberStyles.Any, null, out s))
            {
                invdist = this.normalinv(p, u, s);
            }

            if (invdist <= 0)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[iterations_dont_converge];
            }

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return invdist.ToString();
        }

        /// <summary>
        /// Returns the standard normal cumulative distribution function. The distribution has a mean of 0 (zero) and a standard deviation of one.
        /// <para>Syntax: NORMSDIST(z)</para>
        /// </summary>
        /// <param name="argList">Z is the value for which you want the distribution.</param>
        /// <returns>Standard normal cumulative distribution.</returns>
        public string ComputeNormsDist(string argList)
        {
            string args = argList + ", 0, 1, " + this.TRUEVALUESTR;
            return this.ComputeNormdist(args);
        }

        /// <summary>
        /// Returns the inverse of the standard normal cumulative distribution. The distribution has a mean of zero and a standard deviation of one.
        /// <para>Syntax: NORMSINV(p)</para>
        /// </summary>
        /// <param name="argList">p is a probability corresponding to the normal distribution.</param>
        /// <returns>Inverse of standard normal cumulative distribution.</returns>
        /// <remarks>
        /// p should be between 0 and 1.
        /// </remarks>
        public string ComputeNormsInv(string argList)
        {

            bool IsMinus = false;
            argList = GetValueFromArg(argList);
            if (!ExcelLikeComputations)
            {
                if (char.IsLetter(argList, 0))
                {
                }
                else
                {
                    double p = double.Parse(argList);
                    if (p < 0 || p > 1)
                    {
                        return "#NUM!";
                    }
                    else if (p < 0.5)
                    {
                        argList = (1 - p).ToString();
                        IsMinus = true;
                    }
                    else if (p == 0.5)
                    {
                        return "0";
                    }
                }
                string args = argList + ", 0, 1";
                if (IsMinus)
                {
                    return string.Format("-{0}", this.ComputeNorminv(args));
                }
                return this.ComputeNorminv(args);
            }
            return this.newnormalinv(double.Parse(argList)).ToString();
        }

        /// <summary>
        ///  Flips the logical value represented by the argument.
        /// </summary>
        /// <remarks>
        ///	The argument is
        /// treated as a logical expression with a non-zero value considered True and a zero value considered False.
        /// </remarks>
        /// <param name="args">A string holding either a single argument consisting of a
        /// cell reference, formula, or number.
        /// </param>
        /// <returns>Returns 0 if the argument evaluates to a non-zero value. Otherwise, it returns 1.</returns>
        public string ComputeNot(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeNot"; MarkTimeStart(ML);
#endif
            double d1;
            string s = args;
            ////parsed formula
            if (args.Length > 0 && !char.IsLetter(args[0]) && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) > -1) 
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[requires_a_single_argument];
            }
            else
            {
                try
                {
                    s = this.GetValueFromArg(s);
                    if (s.Equals(this.TRUEVALUESTR))
                    {
                        s = this.FALSEVALUESTR;
                    }
                    else if (s.Equals(this.FALSEVALUESTR))
                    {
                        s = this.TRUEVALUESTR;
                    }
                    else if (double.TryParse(s, NumberStyles.Number | NumberStyles.AllowExponent, null, out d1))
                    {
                        ////Flip the value.
                        if (Math.Abs(d1) > 1e-10)
                        {
                            s = "0";
                        }
                        else
                        {
                            s = "1";
                        }
                    }
                }
                catch (Exception ex)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                    {
                        throw this.LibraryComputationException;
                    }

                    return ex.Message;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s;
        }

