        /// <summary>
        /// Computes the number of periods an investment.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period,
        /// payment per period, present value, future value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Number of periods.</returns>
        public string ComputeNper(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNper"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double pmt = 0;
            double pv = 0;
            double fv = 0;
            double type = 0;

            double val = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out pmt)
                && double.TryParse(args[2], NumberStyles.Any, null, out pv)
                && (argCount == 3 || double.TryParse(args[3], NumberStyles.Any, null, out fv))
                && (argCount <= 4 || double.TryParse(args[4], NumberStyles.Any, null, out type)))
            {
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }

                ////NPER = LOG10((PMT*(1+rate*type)-FV*rate)/(PMT*(1+rate*type)+PV*rate))/ LOG10(1+rate)
                val = Math.Log10((pmt * (1 + rate * type) - fv * rate)
                                    / (pmt * (1 + rate * type) + pv * rate)) / Math.Log10(1 + rate);
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val.ToString();
        }

        /// <summary>
        /// Computes the net present value an investment.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period
        /// and a list of invested values.</param>
        /// <returns>Net present value.</returns>
        public string ComputeNpv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNpv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount < 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out rate);

            double val = 0;
            double denom = 1;
            double d;

            for (int i = 1; i < argCount; ++i)
            {
                string r = args[i];
                ////is a cellrange
                if (r.IndexOf(':') > -1) 
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out d))
                        {
                            denom *= 1 + rate;
                            val += d / denom;
                        }
                    }
                }
                else
                {
                    if (double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out d))
                    {
                        denom *= 1 + rate;
                        val += d / denom;
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val.ToString();
        }

        /// <summary>
        /// Rounds up to larger in magnitude odd number.
        /// </summary>
        /// <param name="args">Number to be rounded.</param>
        /// <returns>Rounded odd value.</returns>
        public string ComputeOdd(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeOdd"; MarkTimeStart(ML);
#endif
            double number;
            double odd = 0;
            if (double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out number))
            {
                int sgn = Math.Sign(number);
                number = Math.Abs(number);
                if ((int)number != number)
                {
                    number = (int)(number + 1);
                }

                if ((number % 2) == 0)
                {
                    odd = sgn * (number + 1);
                }
                else
                {
                    odd = sgn * number;
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return odd.ToString();
        }

        /// <summary>
        /// Returns a range that is the offset of the reference range by rows and cols.
        /// </summary>
        /// <param name="arg">reference, rows, cols, [height], [width]</param>
        /// <returns>A range offset.</returns>
        /// <remarks>The returned range is the range passed in through the reference variable offset
        /// by the number of rows in the rows variable and number of columns in the cols variable. If height and
        /// width are present in the argument list, they determine the number of rows and columns
        /// in the returned range. Otherwise, the dimensions of the returned range match the input range.
        /// </remarks>
        public string ComputeOffSet(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeOffSet"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            int argCount = args.GetLength(0);
            if (argCount < 3 || argCount > 5)
            {
#if _ENABLETIMERS
                     MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string r = args[0], result = string.Empty;
            double d;
            DateTime dt;
            int rows = double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Integer, null, out d) ? (int)d : -1;
            int cols = double.TryParse(this.GetValueFromArg(args[2]), NumberStyles.Integer, null, out d) ? (int)d : -1;
            int width = -1;
            int height = -1;
            height = (argCount >= 4) ? ((double.TryParse(this.GetValueFromArg(args[3]), NumberStyles.Integer, null, out d) ? (int)d : 2) - 1) : -1;
            width = (argCount == 5) ? ((double.TryParse(this.GetValueFromArg(args[4]), NumberStyles.Integer, null, out d) ? (int)d : 2) - 1) : -1;

            int i = r.IndexOf(":");
            bool singleCell = i == -1;
            ////single cell
            if (singleCell)
            {
                r = r + ":" + r;
                i = r.IndexOf(":");
            }

            singleCell &= width <= 0 && height <= 0; ////only treat as single cell if no hieght or width given...
            if (width == -1)
                singleCell = true;
            string sheet = this.GetSheetTokenFromReference(r);

            int row1 = this.RowIndex(r.Substring(0, i)) + rows;
            int row2 = this.RowIndex(r.Substring(i + 1)) + rows;
            if (!(!this.RowIndex(r.Substring(0, i)).Equals(-1) || this.RowIndex(r.Substring(i + 1)).Equals(-1)).Equals((this.RowIndex(r.Substring(0, i)).Equals(-1) || !this.RowIndex(r.Substring(i + 1)).Equals(-1))))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[5].ToString();
            }
            if (row1 == rows - 1 && this.grid is ISheetData)
            {
                row1 = ((ISheetData)grid).GetFirstRow() + rows;
            }
            int col1 = this.ColIndex(r.Substring(0, i)) + cols;
            if (col1 == cols - 1 && this.grid is ISheetData)
            {
                col1 = ((ISheetData)grid).GetFirstColumn() + cols;
            }
            if (row2 == rows - 1 && this.grid is ISheetData)
            {
                row2 = ((ISheetData)grid).GetLastRow() + rows;
            }
            int col2 = this.ColIndex(r.Substring(i + 1)) + cols;
            if (col2 == cols - 1 && this.grid is ISheetData)
            {
                col2 = ((ISheetData)grid).GetLastColumn() + cols;
            }
            if (row1 <= 0 || col1 <= 0)
            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[2].ToString();

            }
            if ((height > 0 && width < 0) || (height < 0 && width > 0))
            {
                row1 = this.RowIndex(this.cell);
            }
            if (col2 == (int.Parse(ComputeColumn(r)) - 1))
                singleCell = true;
#if _ENABLETIMERS

            int row1 = this.RowIndex(r.Substring(0, i));
            if(row1 == -1 && this.grid is ISheetData)
            {
                row1 = ((ISheetData)grid).GetFirstRow();
            }
            int col1 = this.ColIndex(r.Substring(0, i));
            if(col1 == -1 && this.grid is ISheetData)
            {
                col1 = ((ISheetData)grid).GetFirstColumn();
            }
            int row2 = this.RowIndex(r.Substring(i + 1));
            if (row2 == -1 && this.grid is ISheetData)
            {
                row2 = ((ISheetData)grid).GetLastRow();
            }
            int col2 = this.ColIndex(r.Substring(i + 1));
            if(col2 == -1 && this.grid is ISheetData)
            {
                col2 = ((ISheetData)grid).GetLastColumn();
            }
            bool newTable = false;
            
            string v = string.Format("{4}{0}{1}:{2}{3}", RangeInfo.GetAlphaLabel(col1), row1, RangeInfo.GetAlphaLabel(col1 + width), row1 + height, sheet);
            MarkTimeEnd(ML);
            return v;
#else
            result = singleCell ? this.ComputedValue(string.Format("{2}{0}{1}", RangeInfo.GetAlphaLabel(col1), row1, sheet))
                : string.Format("{4}{0}{1}:{2}{3}", RangeInfo.GetAlphaLabel(col1), row1, RangeInfo.GetAlphaLabel(col1 + width), row1 + height, sheet);
            if (DateTime.TryParse(result, out dt))
            {
                return GetSerialDateTimeFromDate(dt).ToString();
            }
            else
                return result;
#endif
        }

        /// <summary>
        /// Returns the inclusive Or of all values treated as logical values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers. Each item in the list is considered True if it is nonzero
        /// and False if it is zero.</param>
        /// <returns>A string holding the Or of all values listed in the argument.</returns>
        public string ComputeOr(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeOr"; MarkTimeStart(ML);
#endif
            bool sum = false;
            string s1;
            double d;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1 && this.IsCellReference(r))
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        sum |= (s1.Equals(this.TRUEVALUESTR)) ||
                               (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d);
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    sum |= (s1.Equals(this.TRUEVALUESTR)) ||
                               (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum ? this.TRUEVALUESTR : FALSEVALUESTR;
        }

