        /// <summary>
        /// Returns the percentile position in the range.
        /// </summary>
        /// <param name="range">Range, k.</param>
        /// <returns>Percentile position.</returns>
        /// <remarks>K is a value between 0 and 1.</remarks>
        public string ComputePercentile(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputePercentile"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double k;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Any, null, out k) && (k < 0 || k > 1))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            double[] dd = this.GetDoubleArray(args[0]);
            int n = dd.GetLength(0);

            Array.Sort(dd);

            double h = 1d / (n - 1);
            double d = dd[n - 1];
            for (int i = 0; i < n - 1; ++i)
            {
                if ((i + 1) * h > k)
                {
                    k = (k - i * h) / h;
                    d = dd[i] + k * (dd[i + 1] - dd[i]);
                    break;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return d.ToString();
        }

        /// <summary>
        /// Returns the percentage rank in the range.
        /// </summary>
        /// <param name="range">Range, x, significant digits.</param>
        /// <returns>Percentile position.</returns>
        /// <remarks>Significant digits are optional, defaulting to 3.</remarks>
        public string ComputePercentrank(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputePercentrank"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double signif = 3;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Any, null, out x))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            if (argCount == 3)
            {
                s1 = this.GetValueFromArg(args[2]);
                if (!double.TryParse(s1, NumberStyles.Integer, null, out signif) && signif < 1)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[invalid_arguments];
                }
            }

            double[] dd = this.GetDoubleArray(args[0]);
            int n = dd.GetLength(0);

            Array.Sort(dd);

            double d = 1;
            for (int i = 0; i < n; ++i)
            {
                if (dd[i] > x)
                {
                    int k = 0;
                    while (k + i < n && dd[k + i] == x)
                    {
                        k++;
                    }

                    d = ((double)(i - 1)) / (i + n - i - k - 1);

                    if (i > 0 && dd[i - 1] < x)
                    {
                        double di = ((double)i) / (n - 1);
                        d = di + (d - di) * (1 - (x - dd[i - 1]) / (dd[i] - dd[i - 1]));
                    }

                    break;
                }
            }

            string fmt = "0." + new string('#', (int)signif);
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return d.ToString(fmt);
        }

        /// <summary>
        /// The number of permutations of n items taken k at the time.
        /// </summary>
        /// <param name="argList">n, k</param>
        /// <returns>The number of combinations.</returns>
        public string ComputePermut(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputePermut"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_2_args];
            }

            ////N things taken k at the time.
            double nd;
            double kd;
            double combin = 0;
            if (double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out nd)
                && double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out kd))
            {
                int k = (int)(kd + 0.1);
                int n = (int)(nd + 0.1);

                double top = 1;
                for (int i = (n - k) + 1; i <= n; ++i)
                {
                    top = top * i;
                }

                combin = top;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return combin.ToString();
        }

