        /// <summary>
        /// Computes the payment for a loan.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period,
        /// number of periods, present value, future value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Payment amount.</returns>
        public string ComputePmt(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputePmt"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount < 3 || argCount > 5)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double nper = 0;
            double pv = 0;
            double fv = 0;
            double type = 0;

            double val = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i].Replace(this.TIC, string.Empty));
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out nper)
                && double.TryParse(args[2], NumberStyles.Any, null, out pv)
                && (argCount == 3 || double.TryParse(args[3], NumberStyles.Any, null, out fv))
                && (argCount <= 4 || double.TryParse(args[4], NumberStyles.Any, null, out type)))
            {
                if (nper == 0) //The total number of payments for the loan. It should not be 0.
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[invalid_Math_argument]);
                    return this.ErrorStrings[4].ToString(); //#NUM!
                }
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }
                if (rate == 0)
                {
                    val = (1 * (fv + pv)) / ((1 + rate * type) * (1 - (nper + 1)));
                }
                else
                {
                    double pow = Math.Pow(1 + rate, nper);
                    val = (rate * (fv + pv * pow)) / ((1 + rate * type) * (1 - pow));
                }

            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[invalid_arguments]);
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val.ToString();
        }

        /// <summary>
        /// Returns the Poisson distribution.
        /// </summary>
        /// <param name="argList">x, mean, cumulative</param>
        /// <returns>Returns the exponential distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function.
        /// </remarks>
        public string ComputePoisson(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputePoisson"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double u;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out u))
            {
                cum = (args[2] == this.TRUEVALUESTR) ? 1 : 0;
                int n = (int)x;
                if (cum == 0)
                {
                    double prod = 1;
                    for (int i = 2; i <= n; ++i)
                    {
                        prod *= i;
                    }

                    dist = Math.Exp(-u) * Math.Pow(u, n) / prod;
                }
                else
                {
                    double prod = 1;
                    dist = 0;
                    double ui = 1;
                    for (int i = 0; i <= n; ++i)
                    {
                        dist += ui / prod;
                        prod *= i + 1;
                        ui *= u;
                    }

                    dist = Math.Exp(-u) * dist;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        /// Returns a specified number raised to the specified power.
        /// </summary>
        /// <param name="args">String containing two parameters separated by commas:
        /// the first being base number,
        /// the second being the exponent.</param>
        /// <returns>A string holding the value of the base number raised to the exponent.</returns>
        public string ComputePow(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputePow"; MarkTimeStart(ML);
#endif
            double pow = 0;
            double d1, d2;
            string s1, s2;
            ////parsed formula
            if (args.Length > 0 && !char.IsLetter(args[0]) && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1) 
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[requires_2_args];
            }
            else
            {
                string[] s = this.GetCellsFromArgs(args);

                if (s.GetLength(0) == 2)
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s[0]);
                        s2 = this.GetValueFromArg(s[1]);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d1)
                        && double.TryParse(s2, NumberStyles.Number | NumberStyles.AllowExponent, null, out d2))
                    {
                        pow = Math.Pow(d1, d2);
                    }
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[requires_2_args];
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return pow.ToString();
        }

        /// <summary>
        /// Computes the principal payment for a period.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period, the period,
        /// number of periods, present value, future value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Principal payment.</returns>
        public string ComputePpmt(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputePpmt"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 6 && argCount != 5 && argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double per;
            double nper;
            double pv = 0;
            double fv = 0;
            double type = 0;

            double ppmt = 0;
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out per)
                && double.TryParse(args[2], NumberStyles.Any, null, out nper)
                && double.TryParse(args[3], NumberStyles.Any, null, out pv)
                && (argCount == 4 || double.TryParse(args[4], NumberStyles.Any, null, out fv))
                && (argCount <= 5 || double.TryParse(args[5], NumberStyles.Any, null, out type)))
            {
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }

                double x0 = Math.Pow((1 + rate), nper);
                double pmt = (rate * (fv + pv * x0)) / ((1 + rate * type) * (1 - x0));
                double ipmt = 0;
                double.TryParse(this.ComputeIpmt(argList), NumberStyles.Any, null, out ipmt);

                ppmt = pmt - ipmt;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return ppmt.ToString();
        }

        /// <summary>
        /// Returns the probability that a value in the given range occurs.
        /// </summary>
        /// <param name="range">xrange1, prange2, lowerbound, upperbound.</param>
        /// <returns>The probability.</returns>
        public string ComputeProb(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeProb"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 3 && argCount != 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string s1 = this.GetValueFromArg(args[2]);
            double lower = 0;
            if (!double.TryParse(s1, NumberStyles.Any, null, out lower))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double upper = lower;
            if (argCount == 4)
            {
                s1 = this.GetValueFromArg(args[3]);
                double.TryParse(s1, NumberStyles.Any, null, out upper);
            }

            double[] y = this.GetDoubleArray(args[1]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sum = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = x[i];
                if (d >= lower && d <= upper)
                {
                    sum += y[i];
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

        /// <summary>
        /// Returns the product of the arguments in the list.
        /// </summary>
        /// <param name="range">List of arguments.</param>
        /// <returns>Product of the arguments.</returns>
        public string ComputeProduct(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeProduct"; MarkTimeStart(ML);
#endif
            double prod = 1;
            double d;
            string s1;
            bool nohits = true;
            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1) 
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Any, null, out d))
                            {
                                prod = prod * d;
                                nohits = false;
                            }
                            else if (this.ErrorStrings.Contains(s1))
                            {
                                return s1;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            prod = prod * d;
                            nohits = false;
                        }
                        else if (this.ErrorStrings.Contains(s1))
                        {
                            return s1;
                        }
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return nohits ? "0" : prod.ToString();
        }

        /// <summary>
        /// Computes the present value of an investment.
        /// </summary>
        /// <param name="argList">Delimited string containing the rate as percentage per period,
        /// number of periods, payment per period, future value, and payment type (0 = end of period, 1 = start of period).</param>
        /// <returns>Present value.</returns>
        public string ComputePv(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputePv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double rate;
            double nper;
            double pmt = 0;
            double fv = 0;
            double type = 0;

            double pv = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out rate)
                && double.TryParse(args[1], NumberStyles.Any, null, out nper)
                && double.TryParse(args[2], NumberStyles.Any, null, out pmt)
                && (argCount == 3 || double.TryParse(args[3], NumberStyles.Any, null, out fv))
                && (argCount <= 4 || double.TryParse(args[4], NumberStyles.Any, null, out type)))
            {
                if (Math.Abs(type) > 0.5)
                {
                    type = 1;
                }
                else
                {
                    type = 0;
                }

                ////PV   = (PMT*(1+rate*type)*(1-(1+rate)^NPER)-rate*FV)/(rate*(1+rate)^NPER)
                double pow = Math.Pow(1 + rate, nper);
                pv = (pmt * (1 + rate * type) * (1 - pow) - rate * fv) / (rate * pow);
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return pv.ToString();
        }

