        }

        /// <summary>
        /// Converts degrees into radians.
        /// </summary>
        /// <param name="args">Value in degrees.</param>
        /// <returns>Radians for the given degrees.</returns>
        public string ComputeRadians(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeRadians"; MarkTimeStart(ML);
#endif
