            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return radians.ToString();
        }

        /// <summary>
        /// Returns an evenly distributed random number &gt;= 0 and &lt; 1.
        /// </summary>
        /// <param name="args">Ignored. Can be empty.</param>
        /// <returns>
        /// A string holding the random number.
        /// </returns>
        public string ComputeRand(string args)
        {
#if _ENABLETIMERS
