        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRound(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeRound"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
#if _ENABLETIMERS
                string v = ComputeMath(argList, new MathFunc(Math.Round)).ToString();
                MarkTimeEnd(ML);
                return v;
#else
                return this.ComputeMath(argList, new MathFunc(Math.Round)).ToString();
#endif
            }

            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double x = 0;
            double digits = 0;
            double round = 0;
            string numStr = this.GetValueFromArg(args[0]);
            string digStr = this.GetValueFromArg(args[1]);

            if ((numStr == string.Empty || double.TryParse(numStr, NumberStyles.Any, null, out x))
            && (digStr== string.Empty || double.TryParse(digStr, NumberStyles.Any, null, out digits)))
            {
                if (digits > 0)
                {
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                   round = Math.Round(x, (int)digits, MidpointRounding.AwayFromZero);
#else
                   round = Math.Round(x, (int)digits);
#endif
                }
                else
                {
                    double mult = Math.Pow(10, -digits);

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    round = Math.Round(x / mult, MidpointRounding.AwayFromZero) * mult;
#else
                    round = Math.Round(x / mult) * mult;
#endif
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return round.ToString();
        }

        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRounddown(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeRounddown"; MarkTimeStart(ML);
#endif
            double x = 0;

            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
                double.TryParse(this.GetValueFromArg(argList), NumberStyles.Any, null, out x);
                x = x - .4999999999d * Math.Sign(x);
#if _ENABLETIMERS
                 string v = ComputeRound(string.Format("{0}", x));
                 MarkTimeEnd(ML);
                 return v;
#else
                return this.ComputeRound(string.Format("{0}", x));
#endif
            }
            else if (argCount != 2)
            {
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double digits = 0;
            double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out x);
            double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out digits);
            if (!x.Equals(double.NaN))
            {
                x = x - .4999999999d * Math.Pow(10, -digits) * Math.Sign(x);
#if _ENABLETIMERS
             string v1 = ComputeRound(string.Format("{0}{1}{2}", x, ParseArgumentSeparator, digits));
             MarkTimeEnd(ML);
             return v1;
#else
                return this.ComputeRound(string.Format("{0}{1}{2}", x, ParseArgumentSeparator, digits));
#endif
            }
            return "#VALUE!";
        }

        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRoundup(string argList)
        {
            double x = 0;

            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
                double.TryParse(this.GetValueFromArg(argList), NumberStyles.Any, null, out x);
                if (x > 0)
                {
                    x += .4999999999d;
                }
                else if (x < 0)
                {
                    x -= .4999999999d;
                }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                x = Math.Round(x, 0, MidpointRounding.AwayFromZero);
#else
                x = Math.Round(x, 0);
#endif
                return string.Format("{0}", x);
            }
            else if (argCount != 2)
            {
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double digits = 0;
            double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out x);
            double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out digits);
            digits = Math.Ceiling(digits);
            if (digits >= 0)
            {
                if (x > 0)
                {
                    x += .4999999999d / Math.Pow(10, digits);
                }
                else if (x < 0)
                {
                    x -= .4999999999d / Math.Pow(10, digits);
                }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                x = Math.Round(x, (int)digits, MidpointRounding.AwayFromZero);
#else
                x = Math.Round(x, (int)digits);
#endif
            }
            else
            {
                if (x > 0)
                {
                    x = (x / Math.Pow(10, -digits)) + .49999;
                }
                else if (x < 0)
                {
                    x = (x / Math.Pow(10, -digits)) - .49999;
                }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                x = Math.Round(x, 0, MidpointRounding.AwayFromZero) * Math.Pow(10, -digits);
#else
                x = Math.Round(x, 0) * Math.Pow(10, -digits);
#endif
            }

            return string.Format("{0}", x);
        }

