        public string ComputeAsc(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeAsc"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstStr = this.StripTics0(GetValueFromArg(args[0]));
            string strReturn = "";

            char[] sbcChr = firstStr.ToCharArray();
            for (int i = 0; i < sbcChr.Length; i++)
            {
                if (sbcChr[i] == 12288)
                {
                    sbcChr[i] = (char)32;
                    continue;
                }
                if (sbcChr[i] > 65280 && sbcChr[i] < 65375)
                    sbcChr[i] = (char)(sbcChr[i] - 65248);
            }
            strReturn = new string(sbcChr);

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return strReturn;
        }

        public string ComputeJis(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputeJis"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstStr = this.StripTics0(GetValueFromArg(args[0]));
            string strReturn = "";

            char[] dbcChr = firstStr.ToCharArray();
            for (int i = 0; i < dbcChr.Length; i++)
            {
                if (dbcChr[i] == 32)
                {
                    dbcChr[i] = (char)12288;
                    continue;
                }
                if (dbcChr[i] < 127)
                    dbcChr[i] = (char)(dbcChr[i] + 65248);
            }
            strReturn = new string(dbcChr);
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return strReturn;
        }


        /// <summary>
        /// replaces part of a text string, based on the number of characters, with a different text string
        /// </summary>
        /// <param name="argList">Text in which is want to replace, The position of the character in old_text., The number of characters in old_text </param>
        /// <returns>returns replaced text</returns>
        public string ComputeReplaceB(string argList)
        {
#if _ENABLETIMERS
    string ML = "ComputeReplaceB"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            int startIndex = 0, noOfChar = 0;
            if (argCount != 4)
            {
#if _ENABLETIMERS
        MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstText = this.StripTics0(GetValueFromArg(args[0]));
            string newText = this.StripTics0(GetValueFromArg(args[3]));
            string resultText = string.Empty;
            if (int.TryParse(GetValueFromArg(args[1]), out startIndex) && int.TryParse(GetValueFromArg(args[2]), out noOfChar))
            {
                try
                {
                    string replaceText = string.Empty;
                    if (string.IsNullOrEmpty(firstText))
                    {
                        return newText;
                    }
                    if (firstText.Length <= startIndex && startIndex > noOfChar)
                    {
                        resultText = firstText + newText;
                    }
                    else if (firstText.Length <= startIndex)
                    {
                        replaceText = firstText;
                        resultText = firstText.Replace(replaceText, newText);
                    }
                    else
                    {
                        replaceText = firstText.Substring(startIndex, noOfChar);
                        resultText = firstText.Replace(replaceText, newText);
                    }
                }
                catch (Exception ex)
                {
#if _ENABLETIMERS
    MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw ex;
                    else
                        return this.ErrorStrings[1].ToString();
                }
            }
            else
            {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                else
                    return this.ErrorStrings[1].ToString();

            }
#if _ENABLETIMERS
    MarkTimeEnd(ML);
#endif
            return resultText;
        }


        /// <summary>
        /// Returns the second of the given time.
        /// </summary>
        /// <param name="argList">Given time.</param>
        /// <returns>Second of given time.</returns>
        public string ComputeSecond(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeSecond"; MarkTimeStart(ML);
#endif
            double time;
            DateTime dt = DateTime.Now;
            argList = this.GetValueFromArg(argList);
            if (argList.IndexOf(this.TIC) > -1)
            {
                argList = argList.Replace(this.TIC, string.Empty);
                dt = DateTime.Parse(argList);
            }
            else
            {
                try
                {
                    dt = DateTime.Parse(argList);
                }
                catch
                {
                    if (double.TryParse(argList, NumberStyles.Any, null, out time))
                    {
                        dt =
#if WINDOWS_UWP
                        Syncfusion.XlsIO.Implementation.DateTimeExtension.FromOADate(time);
#else
                        DateTime.FromOADate(time);
#endif
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dt.Second.ToString();
        }

        /// <summary>
        /// Returns a number indicating the sign of the argument.
        /// </summary>
        /// <param name="args">A cell reference, formula, or number.</param>
        /// <returns>A string holding a number representing the sign of the argument.</returns>
        public string ComputeSign(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeSign"; MarkTimeStart(ML);
#endif
            int sign = 0;
            double d;
            string s1;
            ////parsed formula
            if (args.Length > 0 && !char.IsLetter(args[0]) && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1) 
            {
                if (double.TryParse(args, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                {
                    sign = Math.Sign(d);
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[invalid_Math_argument];
                }
            }
            else if (args.Length > 0 && (args[0] == BMARKER || args[0] == 'u' || args[0] == 'n' || args.IndexOfAny(this.tokens) > -1)) 
            {
                ////parsed formula
                args = args.Replace('{', '(');
                args = args.Replace('}', ')');

                try
                {
                    s1 = this.ComputedValue(args);
                }
                catch (Exception ex)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                    {
                        throw this.LibraryComputationException;
                    }

                    return ex.Message;
                }

                if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                {
                    sign = Math.Sign(d);
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[invalid_Math_argument];
                }
            }
            else
            {
                foreach (string s in this.GetCellsFromArgs(args))
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                        {
                            sign = Math.Sign(d);
                            break; ////Skip out after first value.
                        }
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sign.ToString();
        }

