        /// <summary>
        /// Returns the skewness of a distribution.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>Skewness of a distribution.</returns>
        public string ComputeSkew(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSkew"; MarkTimeStart(ML);
#endif
            double[] x = this.GetDoubleArray(range);
            int n = x.GetLength(0);

            if (n < 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double xbar = 0;
            double sdev = this.sd(x, out xbar);
            double skew = 0;
            for (int i = 0; i < n; ++i)
            {
                skew += Math.Pow((x[i] - xbar) / sdev, 3);
            }
#if _ENABLETIMERS
            string v = (n * skew / (n - 1) / (n - 2)).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return (n * skew / (n - 1) / (n - 2)).ToString();
#endif
        }

        /// <summary>
        /// Computes the straight-line depreciation of an asset per period.
        /// </summary>
        /// <param name="argList">Delimited string containing the cost,
        /// salvage value, and life.</param>
        /// <returns>Depreciation of the asset.</returns>
        public string ComputeSln(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeSln"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_3_args];
            }

            double cost;
            double salvage;
            double life;

            double sln = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out cost)
                && double.TryParse(args[1], NumberStyles.Any, null, out salvage)
                && double.TryParse(args[2], NumberStyles.Any, null, out life))
            {
                sln = (cost - salvage) / life;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sln.ToString();
        }

        /// <summary>
        /// Returns the slope of the least square fit line through the given points.
        /// </summary>
        /// <param name="range">Y_range, x_range.</param>
        /// <returns>Y-intercept for the given points.</returns>
        public string ComputeSlope(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSlope"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 2 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return (sumxy / sumx2).ToString();
        }

        /// <summary>
        /// Returns the kth smallest value in the range.
        /// </summary>
        /// <param name="range">Range, k.</param>
        /// <returns>Kth smallest value.</returns>
        public string ComputeSmall(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSmall"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x0;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Integer, null, out x0))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }

            int k = (int)x0;
            double[] dd = this.GetDoubleArray(args[0]);
            if (k < 1 || k > dd.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            Array.Sort(dd);
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dd[k - 1].ToString();
        }

