        /// <summary>
        /// Returns the standard error of the least square fit line through the given points.
        /// </summary>
        /// <param name="range">Y_range, x_range.</param>
        /// <returns>Standard error.</returns>
        public string ComputeSteyx(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSteyx"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 2 || n != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double sumy2 = 0;
            double dy = 0;
            double d = 0;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                dy = y[i] - sumy;
                sumxy += d * dy;
                sumx2 += d * d;
                sumy2 += dy * dy;
            }

#if _ENABLETIMERS
            string v = (Math.Sqrt((sumy2 - sumxy * sumxy / sumx2) / (n - 2))).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return Math.Sqrt((sumy2 - sumxy * sumxy / sumx2) / (n - 2)).ToString();
#endif
        }

        /// <summary>
        /// In a given string, this method substitutes an occurrence of one string with another string.
        /// </summary>
        /// <param name="range">A list of 3 or 4 arguments: the original string, the search string, the
        /// replacement string, and optionally, an integer representing the occurrence to be replaced.
        ///    </param>
        /// <returns>The modified string.</returns>
        public string ComputeSubstitute(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSubstitute"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            if (args.Length != 3 && args.Length != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            ////strip off outside tics (if any) on the evaluated arguments
            string s1 = this.StripTics0(GetValueFromArg(args[0]));
            string s2 = this.StripTics0(GetValueFromArg(args[1]));
            string s3 = this.StripTics0(GetValueFromArg(args[2]));
            if (args.Length == 3)
            {
                s1 = s1.Replace(s2, s3);
            }
            else
            {
                string s4 = this.GetValueFromArg(args[3]);
                double d = 0;
                if (double.TryParse(s4, NumberStyles.Integer, null, out d))
                {
                    int count = (int)d;
                    int loc = -1;
                    while (count > 0 && (loc = s1.IndexOf(s2, loc + 1)) > -1)
                    {
                        count--;
                    }

                    if (count == 0)
                    {
                        s1 = s1.Substring(0, loc) + s3 + s1.Substring(loc + s2.Length);
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return this.TIC + s1 + this.TIC;
        }

        /// <summary>
        /// Returns the sum of all values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>A string holding the sum of all values listed in the argument.</returns>
        public string ComputeSum(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSum"; MarkTimeStart(ML);
#endif
            double sum = 0;
            string s1;
            double d;
			string adjustRange;
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
				adjustRange = r;
                this.AdjustRangeArg(ref range);
                ////is a cellrange
                if (adjustRange.IndexOf(':') > -1) 
                {
                    foreach (string s in this.GetCellsFromArgs(adjustRange))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC,string.Empty);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1 != string.Empty)
                        {
                            if (s1 == "NaN")
                            {
                                s1 = string.Empty;
                            }
                            else if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                            {
                                sum = sum + d;
                            }
                            else if (this.ErrorStrings.Contains(s1))
