               MarkTimeEnd(ML);
#endif
                    if (RethrowParseExceptions)
                        return (ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR || ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2)) == TRUEVALUESTR) ? "Paramater is not valid" : value.Substring(0, minus);
                    else
                        return (ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR || ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : value.Substring(0, minus);

                }
            }
            else
            {
                if (unit)
                {
                    if (RethrowLibraryComputationExceptions)
