        /// <summary>
        /// Obtains the complex number for the given real and imaginary part.
        /// </summary>
        /// <param name="argList">Given real and Imaginary part.</param>
        /// <returns>The complex number derived from the real and imaginary part.</returns>
        public string ComputeComplex(string argList)
        {
#if _ENABLETIMERS
               string ML = "ComputeComplex"; MarkTimeStart(ML);
#endif
            string[] ranges = SplitArgsPreservingQuotedCommas(argList);
            if (ranges.Length < 2 || ranges.Length > 3)
            {
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException("Agument Should be two or three");
                else
                    return FormulaErrorStrings[13].ToString();
            }
            string real = ranges[0];
            real = real.Replace(this.TIC,"");
            string imaginary = ranges[1];
            imaginary = imaginary.Replace(this.TIC,"");

            if (double.IsInfinity(double.Parse(real)) || double.IsInfinity(double.Parse(imaginary)) || double.IsNaN(double.Parse(real)) || double.IsNaN(double.Parse(imaginary)))
            {
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException();
                else
                    return ErrorStrings[4].ToString();
            }

            string suffix;
            try
              {  
            if ((ranges.Length <= 3))
            {
                // Return error if either number is a non-numeric value
                if (this.ComputeIsText(real) == TRUEVALUESTR || this.ComputeIsText(imaginary) == TRUEVALUESTR)
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException("Argument is not valid");
                    else
                        return "#VALUE!";
                }
                // Set suffix
                if (ranges.Length == 3)
                    suffix = ranges[2];
                else
                    suffix = "";
                suffix = (suffix == "") ? "i" : suffix = ranges[2];
                suffix = suffix.Replace(TIC, string.Empty);

                // Return error if suffix is neither "i" nor "j"
                if (suffix != "i" && suffix != "j")
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                {
                    if (rethrowLibraryComputationExceptions)
                        throw new ArgumentException("Suffix is not Appropriate");
                    else
                        return ErrorStrings[5].ToString();
                }
                // Return complex number
                if (double.Parse(real) == 0 && double.Parse(imaginary) == 0)
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return "0";
                else if (double.Parse(real) == 0)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return
                        (double.Parse(imaginary) == 1) ? suffix : imaginary.ToString() + suffix;
                }
                else
                    if (double.Parse(imaginary) == 0)
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return real;
                    else
                    {
                        string sign = (double.Parse(imaginary) > 0) ? "+" : "";
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return real + sign + ((double.Parse(imaginary) == 1) ? suffix : imaginary + suffix);
                    }    
                }
            
             else
            {
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException("The number of Argument is wrong");
                else
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return FormulaErrorStrings[21].ToString();                
            }
               
            }
        
            catch
            {
                if (rethrowLibraryComputationExceptions)
                    throw new ArgumentException("The Parameters are not correct");
                else
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    if (ComputeIsText(real) == TRUEVALUESTR || ComputeIsText(imaginary) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (real == "" || imaginary == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(real) < 0 || double.Parse(imaginary) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }

        }
