        /// <summary>
        /// Computes the Product of the given Complex Numbers
        /// </summary>
        /// <param name="argList">Input Complex Numbers</param>
        /// <returns>The multiplied result of the two complex numbers.</returns>
        public string ComputeImProduct(string argList)
        {
#if _ENABLETIMERS
               string ML = "ImConjugate"; MarkTimeStart(ML);
#endif
            string[] ranges = SplitArgsPreservingQuotedCommas(argList);
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, "");
            string a = ComputeReal(result);
            string b = ComputeImaginary(result);

            if (result == "")
            {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                if (rethrowLibraryComputationExceptions)
                    throw new ArgumentException("The parameter is not valid");
                else
                    return ErrorStrings[4].ToString();
            }
            if (ranges.Length < 1)
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                return ErrorStrings[5].ToString();
            // Loop on all numbers
            for (int i = 1; i < ranges.Length; i++)
            {
                // Lookup coefficients of two complex numbers
               
                string c = ComputeReal(ranges[i]);
                string d = ComputeImaginary(ranges[i]);

                // Return error if either coefficient is not a number
                if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
                {
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException("Paramater is not valid");
                    else
                        return ErrorStrings[4].ToString();
                }
                try
                {
                    // Complute product of two complex numbers
                    int x1 = int.Parse(a);
                    int x2 = int.Parse(b);
                    int x3 = int.Parse(c);
                    int x4 = int.Parse(d);

                    int res1 = (x1 * x3) - (x2 * x4);
                    int res2 = (x1 * x4) + (x2 * x3);

                    result = ComputeComplex(res1.ToString() + parseArgumentSeparator + res2.ToString());
                }
                catch (Exception ex)
                {
                    if (rethrowLibraryComputationExceptions)
                        throw ex;
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[21].ToString();
                }
            }
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
            return result;
        }

