        /// <summary>
        /// Returns the argument  (theta), an angle expressed in radians
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The argument  (theta), an angle expressed in radians</returns>
        public string ComputeImArgument(string argList)
        {

#if _ENABLETIMERS
            string ML = "ComputeImaginaryArgument"; MarkTimeStart(ML);
#endif
            string[] ranges = SplitArgsPreservingQuotedCommas(argList);

            if (ranges.Length > 1 || ranges.Length < 1)
            {
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException("Only a single Argument is required");
                else
                    return FormulaErrorStrings[10].ToString();
            }

            string inumber = this.GetValueFromArg(ranges[0]);
            inumber = inumber.Replace(this.TIC, "");

            if (inumber == "")
            {
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException("The argument is not valid");
                else
                return ErrorStrings[4].ToString();
            }
            string x = ComputeReal(inumber);
            string y = ComputeImaginary(inumber);

            try
            {
                double a = double.Parse(x);
                double b = double.Parse(y);

                // Return error if either coefficient is not a number
                if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException("coefficient is not a number");
                    else
                        return ErrorStrings[4].ToString();

                // Return error if inumber is equal to zero
                if (a == 0 && b == 0)
                {
                    if (rethrowLibraryComputationExceptions)
                        throw new ArgumentException("Paramater is not valid");
                    else
                        return ErrorStrings[3].ToString();
                }
                // Return PI/2 if x is equal to zero and y is positive
                if (a == 0 && b > 0) return (Math.PI / 2).ToString();

                // Return -PI/2 if x is equal to zero and y is negative
                if (a == 0 && b < 0) return (-Math.PI / 2).ToString();

                // Return zero if x is negative and y is equal to zero
                if (b == 0 && a > 0) return "0";

                // Return zero if x is negative and y is equal to zero
                if (b == 0 && a < 0) return (-Math.PI).ToString();

                // Return argument of complex number
                if (a > 0)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return (Math.Atan(b / a).ToString());
                }
                else if (a < 0 && b >= 0)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return (Math.Atan(b / a) + Math.PI).ToString();
                }
                else
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return (Math.Atan(b / a) - Math.PI).ToString();
                }
            }
            catch (Exception ex)
            {
                if (rethrowLibraryComputationExceptions)
                    throw ex;
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
        }

