        /// Returns the Hyperbolic Sine value of the given Complex Number.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The Hyperbolic Sine Value of the given Complex Number.</returns>
        public string ComputeImSinH(string argList)
        {
#if _ENABLETIMERS
            string ML = "ImSinH"; MarkTimeStart(ML);
#endif
            string[] ranges = SplitArgsPreservingQuotedCommas(argList);
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC,"");

            // Return error if inumber is a logical value
            //if (result == true || result == false) return "#VALUE!";


