                unit = (unit == "i" || unit == "j") ? unit : "i";


                int a = int.Parse(x);
                int b = int.Parse(y);

                double r1 = Math.Cos(b) * ((Math.Exp(a) - Math.Exp(-a)) / 2);
                double r2 = Math.Sin(b) * (Math.Exp(a) + Math.Exp(-a)) / 2;

