        /// <summary>
        /// Calculates the Output to the concerned base.
        /// </summary>
        /// <param name="argList">Data to be converted.</param>
        /// <param name="from">Base of the Given Data</param>
        /// <param name="to">Base to be obtained.</param>
        /// <returns>The data concerning to the base in 'to' parameter</returns>

        public string BaseToBase(string argList, int from, int to)
        {
            argList = argList.Replace(this.TIC, string.Empty);
            return Convert.ToString(Convert.ToInt64(argList, from), to);
        }

        /// <summary>
        /// Sums the cells specified by some criteria.
        /// </summary>
        /// <param name="argList">The criteria range, the criteria, and the sum range.</param>
        /// <returns>A string holding the sum.</returns>
        public string ComputeSumif(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeSumif"; MarkTimeStart(ML);
#endif

            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string criteriaRange = args[0];
            string criteria = args[1]; ////.Replace(TIC, string.Empty);
            if (criteria.Length < 1)
            {
                return "0";
            }

            char op = TOKEN_equal;
            if (criteria[0] != this.TIC[0] && "=><".IndexOf(criteria[0]) == -1)
            {    
                ////cell reference
                criteria = this.GetValueFromArg(criteria);
            }

            int offset = (criteria.Length > 0 && criteria[0] == this.TIC[0]) ? 1 : 0;
            double compare = double.MinValue;
            if (criteria.Substring(offset).StartsWith(">="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_greatereq;
            }
            else if (criteria.Substring(offset).StartsWith("<="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_lesseq;
            }
            else if (criteria.Substring(offset).StartsWith("<"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_less;
            }
            else if (criteria.Substring(offset).StartsWith(">"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_greater;
            }
            else if (criteria.Substring(offset).StartsWith("<>"))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_noequal;
            }
            else if (criteria.Substring(offset).StartsWith("="))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
            }

            criteria = criteria.Replace(this.TIC, string.Empty);
            bool numer = double.TryParse(criteria, out compare);

            string sumRange = (argCount == 2) ? criteriaRange : args[2];

            string[] s1 = this.GetCellsFromArgs(criteriaRange);
            string[] s2 = this.GetCellsFromArgs(sumRange);
            if (s1[0].Equals(this.ErrorStrings[5]) || s2[0].Equals(this.ErrorStrings[5]))
            {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[5].ToString();
            }

            int count = s1.GetLength(0);

            if (count > s2.GetLength(0))
            {
                int i = sumRange.IndexOf(':');
                if (i > -1)
                {
                    int startRow = this.RowIndex(sumRange.Substring(0, i));
                    int row = this.RowIndex(sumRange.Substring(i + 1));
                    if (!(!startRow.Equals(-1) || row.Equals(-1)).Equals((startRow.Equals(-1) || !row.Equals(-1))))
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[5].ToString();
                    }
                    if (startRow == -1 && this.grid is ISheetData)
                    {
                        startRow = ((ISheetData)grid).GetFirstRow();
                    }
                    int startCol = this.ColIndex(sumRange.Substring(0, i));
                    if (startCol == -1 && this.grid is ISheetData)
                    {
                        startCol = ((ISheetData)grid).GetFirstColumn();
                    }
                    if (row == -1 && this.grid is ISheetData)
                    {
                        row = ((ISheetData)grid).GetLastRow();
                    }
                    int col = this.ColIndex(sumRange.Substring(i + 1));
                    if (col == -1 && this.grid is ISheetData)
                    {
                        col = ((ISheetData)grid).GetLastColumn();
                    }
                    if (startRow != row)
                    {
                        row += count - s2.GetLength(0);
                    }
                    else if (startCol != col)
                    {
                        col += count - s2.GetLength(0);
                    }

                    sumRange = sumRange.Substring(0, i + 1) + RangeInfo.GetAlphaLabel(col) + row.ToString();
                    s2 = this.GetCellsFromArgs(sumRange);
                }
            }

            double sum = 0;

            double d;
            string s;
            switch (op)
            {
                case TOKEN_equal:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;

                            if (s.Replace(this.TIC, string.Empty) == criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d == compare))
                            {
                                s = s2[index];
                                s = this.GetValueFromArg(s);
                                if (double.TryParse(s, NumberStyles.Any, null, out d))
                                {
                                    sum += d;
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_noequal:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;

                            if (s.Replace(this.TIC, string.Empty) != criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d != compare))
                            {
                                s = s2[index];
                                s = this.GetValueFromArg(s);
                                if (double.TryParse(s, NumberStyles.Any, null, out d))
                                {
                                    sum += d;
                                }
                            }
                        }
                    }
                    break;
                case TOKEN_greatereq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d >= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, out d))
                                    {
                                        sum += d;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_greater:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d > compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_less:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d < compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_lesseq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d <= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                    }
                                }
                            }
                        }
                    }

                    break;
                default:
                    break;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif

            return sum.ToString();
        }

        /// <summary>
        /// Returns the sum of the products of corresponding values.
        /// </summary>
        /// <param name="range">Two cell ranges.</param>
        /// <returns>Sum of the products.</returns>
        public string ComputeSumProduct(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSumProduct"; MarkTimeStart(ML);
#endif
            double sum = 0;
            int count = 0;
            double d;
            double[] vector = null;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                if (r.IndexOf(':') > -1)
                {
                    int i = r.IndexOf(":");
                    int row1 = this.RowIndex(r.Substring(0, i));
                    int row2 = this.RowIndex(r.Substring(i + 1));
                    if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        return this.ErrorStrings[5].ToString();
                    }
                    if (row1 == -1 && this.grid is ISheetData)
                    {
                        row1 = ((ISheetData)grid).GetFirstRow();
                    }
                    int col1 = this.ColIndex(r.Substring(0, i));
                    if (col1 == -1 && this.grid is ISheetData)
                    {
                        col1 = ((ISheetData)grid).GetFirstColumn();
                    }
                    if (row2 == -1 && this.grid is ISheetData)
                    {
                        row2 = ((ISheetData)grid).GetLastRow();
                    }
                    int col2 = this.ColIndex(r.Substring(i + 1));
                    if (col2 == -1 && this.grid is ISheetData)
                    {
                        col2 = ((ISheetData)grid).GetLastColumn();
                    }

                    if (vector == null)
                    {
                        count = (row2 - row1 + 1) * (col2 - col1 + 1);
                        vector = new double[count];
                        for (i = 0; i < count; ++i)
                        {
                            vector[i] = 1d;
                        }
                    }

                    GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
                    string s = this.GetSheetTokenFromReference(r);
                    ICalcData grd = (s == null || s == string.Empty ) ? this.grid : (ICalcData)family.TokenToParentObject[s];
                    i = 0;
                    for (int row = row1; row <= row2; ++row)
                    {
                        for (int col = col1; col <= col2; ++col)
                        {
                            if (double.TryParse(this.GetValueFromParentObject(grd, row, col).Replace(TIC, string.Empty), NumberStyles.Any, null, out d))
                            {
                                vector[i] = vector[i] * d;
                            }
                            else
                            {
                                vector[i] = 0;
                            }

                            i++;
                        }
                    }
                }
                else
                {
                    break;
                }
            }

            for (int i = 0; i < count; ++i)
            {
                sum += vector[i];
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

