        /// cell references,
        /// formulas, or numbers.</param>
        /// <returns>A string holding the sum of the squares of all values listed in the argument.</returns>
        public string ComputeSumsq(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSumsq"; MarkTimeStart(ML);
#endif
            double sum = 0;
            string s1;
            double d;

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1) 
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                            {
                                sum = sum + d * d;
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                        {
                            sum = sum + d * d;
                        }
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

        /// <summary>
        /// Returns the sum of the differences of squares of the two ranges.
        /// </summary>
        /// <param name="range">x_range and y_range.</param>
        /// <returns>A string holding sum of the differences of squares.</returns>
        public string ComputeSumx2my2(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeSumx2my2"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.requires_2_args];
            }

            string x_range = args[0];
            string y_range = args[1];

            string[] x = this.GetCellsFromArgs(x_range);
            string[] y = this.GetCellsFromArgs(y_range);

            int len = x.GetLength(0);
            if (len != y.GetLength(0))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double sum = 0;
            double x1 = 0;
            double y1 = 0;
            for (int i = 0; i < len; ++i)
            {
                if (double.TryParse(this.GetValueFromArg(x[i]), NumberStyles.Any, null, out x1)
                    && double.TryParse(this.GetValueFromArg(y[i]), NumberStyles.Any, null, out y1))
                {
                    sum += x1 * x1 - y1 * y1;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return sum.ToString();
        }

