        /// <summary>
        /// Returns a quoted string from a date or number.
        /// </summary>
        /// <param name="range">Value to be converted to a string.</param>
        /// <returns>Quoted string.</returns>
        public string ComputeText(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeText"; MarkTimeStart(ML);
#endif
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            string s1 = ranges[0];
            string s2 = ranges[1].Replace(this.TIC, string.Empty);
            s1 = this.GetValueFromArg(s1);
            double d;

            DateTime dtime = this.dateTime1900;
            if (double.TryParse(s1, NumberStyles.Any, null, out d) || DateTime.TryParse(s1.Replace(this.TIC, string.Empty), out dtime))
            {
                if (s2.Length > 0 && s2.ToUpper().IndexOfAny(new char[] { 'M', 'D', 'Y', 'S', 'T' }) > -1)
                {
                    s2 = s2.Replace('Y', 'y').Replace('D', 'd').Replace('H', 'h').Replace('S', 's').Replace('m', 'M').Replace("AM/PM", "tt");
                    char[] formatChar = s2.ToCharArray();
                    bool isH = false, isMFound = false, isFirstM = false; ;
                    int i = 0, mcount = 0;
                    int lastCharIndex = 0, totalCharforM = 0;
                    foreach (char c in formatChar)
                    {

                        if (c == 's' && formatChar[lastCharIndex] == 'M')
                        {
                            formatChar[lastCharIndex] = 'm';
                            if (formatChar[lastCharIndex - 1] == 'M')
                                formatChar[lastCharIndex - 1] = 'm';
                        }
                        if (Char.IsLetter(c))
                        {
                            lastCharIndex = i;
                            if (c == 'M')
                            {
                                mcount++;
                                totalCharforM++;
                            }
                        }
                        else if (totalCharforM > 1)
                            totalCharforM++;
                        if (c == 'M' && isH)
                        {

                            formatChar[i] = 'm';
                            isMFound = true;
                            isFirstM = (mcount == 1);
                        }
                        if (c == 'M' && totalCharforM == mcount)
                            formatChar[i] = 'm';
                        if (c == 'h')
                        {
                            isH = true;
                        }
                        else if (Char.IsLetter(c) && c != 'M' && c != 'h' && !isMFound)
                        {
                            isH = false;
                            isMFound = false;
                        }
                        i++;
                    }
                    s2 = new string(formatChar);
                    DateTime dt =
#if WINDOWS_UWP
                    Syncfusion.XlsIO.Implementation.DateTimeExtension.FromOADate(d);
#else
                    DateTime.FromOADate(d);
#endif
                    if (d == 0)
                        dt = dtime;
                    s1 = dt.ToString(s2);
                }
                else
                {
                    s2 = string.Format("{{0:{0}}}", s2);
                    s1 = string.Format(s2, d);
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return this.TIC + s1 + this.TIC;
        }

        /// <summary>
        /// Returns a fraction of a day.
        /// </summary>
        /// <param name="argList">Hour, minute, and second.</param>
        /// <returns>Fraction of a day.</returns>
        public string ComputeTime(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeTime"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.wrong_number_arguments];
            }

            double hour;
            double minute;
            double second;
            double time = 0;
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out hour)
                && double.TryParse(args[1], NumberStyles.Any, null, out minute)
                && double.TryParse(args[2], NumberStyles.Any, null, out second))
            {
                time = (hour + (minute + second / 60d) / 60d) / 24d;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return time.ToString("0.0########");
        }

        /// <summary>
        /// Returns a fraction of a day.
        /// </summary>
        /// <param name="argList">Time as a text string.</param>
        /// <returns>Fraction of a day.</returns>
        public string ComputeTimevalue(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeTimevalue"; MarkTimeStart(ML);
#endif
            double time;
            DateTime dt = DateTime.Now;
            argList = this.GetValueFromArg(argList);
            try
            {
                if (argList.IndexOf(this.TIC) > -1)
                {
                    argList = argList.Replace(this.TIC, string.Empty);
                    dt = DateTime.Parse(argList);
                    time = (dt.Hour + (dt.Minute + dt.Second / 60d) / 60d) / 24d;
                }
                else
                {
                    dt = DateTime.Parse(argList);
                    time = (dt.Hour + (dt.Minute + dt.Second / 60d) / 60d) / 24d;
                }
            }
            catch
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[this.invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return time.ToString("0.0###########");
        }

        /// <summary>
        /// Returns the current date as a date serial number.
        /// </summary>
        /// <param name="argList">Parameter Ignored.</param>
        /// <returns>Current date as date serial number.</returns>
        public string ComputeToday(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeToday"; MarkTimeStart(ML);
#endif
            DateTime dt = DateTime.Now;

            if (ExcelLikeComputations )
            {
                DateTime result;
                if (DateTime.TryParse(dt.Year.ToString() + "/" + dt.Month.ToString() + "/" + dt.Day.ToString(), out result))
                {
                    return
#if WINDOWS_UWP
                    result.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern);
#else
                    result.ToShortDateString();
#endif
                }
            }
#if _ENABLETIMERS
            string v = this.GetSerialDateFromDate(dt.Year, dt.Month, dt.Day).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return this.GetSerialDateFromDate(dt.Year, dt.Month, dt.Day).ToString();
#endif
        }

        /// <summary>
        /// Removes all leading and trailing white-space characters.
        /// </summary>
        /// <param name="args">Value to trim.</param>
        /// <returns>
        /// The string that remains after all leading and trailing white-space characters
        /// were removed.
        /// </returns>
        public string ComputeTrim(string args)
        {
#if _ENABLETIMERS
            string ML = "ComputeTrim"; MarkTimeStart(ML);
#endif
            string s = this.GetValueFromArg(args).Trim(new char[] { '\"', ' ' });
            int len = 0;

            ////strip out interior double, triple, etc spaces...
            while (s.Length != len)
            {
                len = s.Length;
                s = s.Replace("  ", " ");
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return s;
        }

        /// <summary>
        /// Returns the mean of the range after removing points on either extreme.
        /// </summary>
        /// <param name="range">Range, percent.</param>
        /// <returns>Kth smallest value.</returns>
        public string ComputeTrimmean(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeTrimmean"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double percent;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Any, null, out percent))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            double[] dd = this.GetDoubleArray(args[0]);
            int n = dd.GetLength(0);
            int k = (int)(percent * n);
            k = k / 2;
            if (k < 1 || 2 * k >= n)
            {
#if _ENABLETIMERS
             MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }

            Array.Sort(dd);

            double sum = 0;
            n = n - k;
            for (int i = k; i < n; ++i)
            {
                sum += dd[i];
            }
#if _ENABLETIMERS
            string v = (sum / (n - k)).ToString();
            MarkTimeEnd(ML);
            return v;
#else
            return (sum / (n - k)).ToString();
#endif
        }

