        /// <summary>
        /// Returns a value you specify if a formula evaluates to #N/A
        /// otherwise, returns the result of the formula.
        /// </summary>
        /// <param name="range">String to be tested.</param>
        /// <returns>Returns the computed value.</returns>
        public string ComputeIfNA(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeIfNA"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            string arg1 = string.Empty;
            int index = -1;
            double result;

            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            
            if (this.ComputeIsNA(args[0]).Equals(bool.TrueString.ToUpper()))
            {
                if (!args[1].Contains(this.TIC) && !this.IsCellReference(args[1]) && !double.TryParse(args[1], out result) && !this.NamedRanges.ContainsKey(args[1]))
                {
                    return this.ErrorStrings[5].ToString();  // returns "#NAME?"
                }
                arg1 = this.GetValueFromArg(args[1]);
            }
            else
            {
                if (IsRange(args[0]))
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    arg1 = this.ErrorStrings[1].ToString();
                }
                else
                {
                    if (!args[0].Contains(this.TIC) && !this.IsCellReference(args[0]) && !double.TryParse(args[0], out result) && !this.NamedRanges.ContainsKey(args[0]))
                    {
                        return this.ErrorStrings[5].ToString();  // returns "#NAME?"
                    }
                    arg1 = this.GetValueFromArg(args[0]);
                }
            }
            if (arg1.StartsWith(this.TIC) && arg1.EndsWith(this.TIC))
            {
                arg1 = arg1.Substring(1, arg1.Length - 2);
            }
            return arg1;
        }

        
        /// <summary>
        /// Truncates a number to an integer.
        /// </summary>
        /// <param name="range">Value and number of digits.</param>
        /// <returns>Truncated value.</returns>
        public string ComputeTrunc(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeTrunc"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(range);
            int argCount = args.GetLength(0);
            double digits = 0;

            if (argCount == 2)
            {
                ////ignore return value...
                double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Integer, null, out digits);
            }

            range = this.GetValueFromArg(args[0]);

            double d;
            if (double.TryParse(range, NumberStyles.Any, null, out d))
            {
                string format = digits == 0 ? "F0" : ("0." + new string('0', (int)digits));
                double normalizer = Math.Pow(10, digits);
                double d1 = (d < 0) ? -1 : 1;
#if _ENABLETIMERS
                string v = d1 * Math.Floor(normalizer * Math.Abs(d)) / normalizer).ToString(format);
                MarkTimeEnd(ML);
                return v;
#else
                return (d1 * Math.Floor(normalizer * Math.Abs(d)) / normalizer).ToString(format);
#endif
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return "0";
        }

