        /// <summary>
        /// Returns a number.
        /// </summary>
        /// <param name="range">A date or number string.</param>
        /// <returns>A number in the given string.</returns>
        public string ComputeValue(string range)
        {
            string val = string.Empty;
            try
            {
#if _ENABLETIMERS
            string ML = "ComputeValue"; MarkTimeStart(ML);
            MarkTimeEnd(ML);
#endif
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount > 0)
                {
                    string s1 = args[0];
                    bool ticContains = false;
                    bool quotation = false;
                    if (s1.Contains(TIC))
                        ticContains = true;
                    if (!string.IsNullOrEmpty(s1) && !IsCellReference(s1) && ticContains)
                    {
                        s1 = s1.Replace(this.TIC, string.Empty);
                        quotation = true;
                    }                    
                    s1 = this.GetValueFromArg(s1);
                    if (string.IsNullOrEmpty(s1) && ticContains)
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(this.ErrorStrings[1].ToString());
                        return this.ErrorStrings[1].ToString();
                    }
                    else if (string.IsNullOrEmpty(s1) && !ticContains)
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(FormulaErrorStrings[invalid_arguments]);
                        return FormulaErrorStrings[invalid_arguments];
                    }
                    if (s1.StartsWith("$"))
                    {
                        s1 = s1.Replace("$", string.Empty);
                    }
                    if (s1.StartsWith("%") || s1.EndsWith("%"))
                    {
                        s1 = s1.Replace("%", string.Empty);
                        double per = 0;
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out per))
                        {
                            s1 = (per / 100).ToString();
                        }
                    }
                    DateTime dt;
                    TimeSpan ts;
                    double dous = 0;
                    if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out dous))
                    {
                        val = dous.ToString();
                    }
                    else if (TimeSpan.TryParse(s1, out ts))
                    {
                        if (quotation)
                            val = ComputeTimevalue(ts.ToString());
                        else
                        {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                            if (RethrowLibraryComputationExceptions)
                                throw new ArgumentException(FormulaErrorStrings[invalid_arguments]);
                            return FormulaErrorStrings[invalid_arguments];
                        }
                    }
                    else if (IsDate(s1, out dt))
                    {
                        val = ComputeDatevalue(dt.ToString());
                    }
                    else
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(this.ErrorStrings[1].ToString());
                        return this.ErrorStrings[1].ToString();
                    }
                }
                else
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(FormulaErrorStrings[wrong_number_arguments]);
                    return FormulaErrorStrings[wrong_number_arguments];
                }
            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw ex;
                return this.ErrorStrings[1].ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
            return val.ToString();
#endif
        }

