        /// <summary>
        /// Computes the variable declining balance of an asset.
        /// </summary>
        /// <param name="argList">Delimited string containing the initial cost,
        /// salvage value, life of asset, period of calculation, and factor.</param>
        /// <returns>Variable declining balance.</returns>
        public string ComputeVdb(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeVdb"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 5 && argCount != 6 && argCount != 7)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double cost;
            double salvage;
            double life;
            double start;
            double end;
            double factor = 2;
            double no_switch = 0;

            double deprec = 0;
            double vdb = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out cost)
                && double.TryParse(args[1], NumberStyles.Any, null, out salvage)
                && double.TryParse(args[2], NumberStyles.Any, null, out life)
                && double.TryParse(args[3], NumberStyles.Any, null, out start)
                && double.TryParse(args[4], NumberStyles.Any, null, out end)
                && (argCount == 5 || double.TryParse(args[5], NumberStyles.Any, null, out factor))
                && (argCount <= 6 || double.TryParse(args[6], NumberStyles.Any, null, out no_switch)))
            {
                double rate = factor / life;
                double priorDeprec = 0;
                double sldeprec = (cost - salvage) / life;

                bool change = Math.Abs(no_switch) > .5;

                ////for(int i = 1; i <= end; ++i)
                int i = 0;
                while (i < end)
                {
                    i += 1;
                    if (i == life)
                    {
                        deprec = cost - salvage - priorDeprec;
                    }
                    else
                    {
                        deprec = (cost - priorDeprec) * rate;
                        if (change && deprec < sldeprec)
                        {
                            deprec = sldeprec;
                        }
                    }

                    priorDeprec += deprec;
                    if (i > start && i <= end)
                    {
                        vdb += deprec;
                    }
                    else if (i - end < .99 && i - end > 0)
                    {
                        ////1
                        vdb += deprec * (end - i + 1);
                    }
                }
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[invalid_arguments];
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return vdb.ToString();
        }

#region support table caching for look ups

        LookupCachingMode enableLookupTableCaching = LookupCachingMode.None;

        private bool IsOptimizedMatchesEnabled()
        {
            return (this.enableLookupTableCaching & LookupCachingMode.OptimizeForMatches) != 0;
        }

        private bool IsVLookupCachingEnabled()
        {
            return ((this.enableLookupTableCaching & LookupCachingMode.Both) != 0) || ((this.enableLookupTableCaching & LookupCachingMode.VLOOKUP) != 0);
        }

        private bool IsHLookupCachingEnabled()
        {
            return ((this.enableLookupTableCaching & LookupCachingMode.Both) != 0) || ((this.enableLookupTableCaching & LookupCachingMode.HLOOKUP) != 0);
        }

        private bool IsLookupCachingEnabled()
        {
            return ((this.enableLookupTableCaching & LookupCachingMode.Both) != 0) || ((this.enableLookupTableCaching & LookupCachingMode.VLOOKUP) != 0) || ((this.enableLookupTableCaching & LookupCachingMode.HLOOKUP) != 0);
        }

        /// <summary>
        /// Gets or sets whether lookup tables used in the VLookUp and HLookUp functions are cached.
        /// </summary>
        /// <remarks>
        /// Depending upon your use case, caching look up tables can greatly speed up calculations involving HLookUp
        /// and VLookUp. If you make multiple calls to these functions passing in the same look up tables, and if these
        /// look up tables are relatively static (don't dynamically change as the look ups are taking place), then caching
        /// these tables will likely improve performance.
        /// </remarks>
        public LookupCachingMode EnableLookupTableCaching
        {
            get { return enableLookupTableCaching; }
            set { enableLookupTableCaching = value; }
        }

        /// <summary>
        /// Clears all look up caches used in HLookUp and VLookUp calculations so they will be recreated the
        /// next time one of these functions is used.
        /// </summary>
        public void LookupCachingClearAll()
        {
            if (lookupTables == null) lookupTables = new Dictionary<string, LookUps>();
            lookupTables.Clear();
        }

        public void LookupCachingClearSheet(ICalcData grd)
        {
            if (lookupTables == null)
            {
                lookupTables = new Dictionary<string, LookUps>();
                return;
            }

            string keyEnd = string.Format("_{0}", grd.GetHashCode());
            List<string> removeThese = new List<string>();
            foreach (string key in lookupTables.Keys)
            {
                if (key.EndsWith(keyEnd))
                    removeThese.Add(key);
            }
            foreach (string key in removeThese)
            {
                lookupTables.Remove(key);
            }
        }

        Dictionary<string, LookUps> lookupTables = null;

        class LookUps
        {
            private List<string> _linearLookUpList;
            private Dictionary<string, int> _matchLookUpList;
             public List<string> LinearLookUpList
             {
                 get
                 {
                     return _linearLookUpList;
                 }
                 set
                 {
                     _linearLookUpList = value;
                 }
             }
             public Dictionary<string, int> MatchLookUpList
             {
                 get
                 {
                     return _matchLookUpList;
                 }
                 set
                 {
                     _matchLookUpList = value;
                 }
             }
        }
#endregion

        /// <summary>
        /// Returns a vertical table look up value.
        /// </summary>
        /// <param name="range">Contains search value, table, return index and match properties.</param>
        /// <returns>Matching value found in the table.</returns>
        /// <remarks> For example, =VLOOKUP("Axles",A1:C4,2,TRUE) looks for the exact
        /// match for Axles in A1:A4 and returns the corresponding value in B1:B4.
        /// </remarks>
        public string ComputeVLookUp(string range)
        {
#if _ENABLETIMERS
            string ML = "ComputeVLookUp"; MarkTimeStart(ML);
#endif
            bool cachingEnabled = IsVLookupCachingEnabled();
            bool optimizedMatchesEnabled = IsOptimizedMatchesEnabled();
            if (cachingEnabled && lookupTables == null) lookupTables = new Dictionary<string, LookUps>();

            string[] s = SplitArgsPreservingQuotedCommas(range);
            string lookUp = this.GetValueFromArg(s[0]);
            lookUp = lookUp.Replace(this.TIC, string.Empty).ToUpper();
            string r = s[1].Replace("\"", string.Empty);
            if (r == "#REF!")
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return r;
            }
            string o1 = this.GetValueFromArg(s[2]).Replace("\"", string.Empty);

            double d = 0;
            if (this.ComputeIsLogical(o1).Equals(this.TRUEVALUESTR))
                d = double.Parse(this.ComputeN(o1));
            else if (!double.TryParse(o1, NumberStyles.Any, null, out d) || o1 == "NaN")
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return "#N/A";
            }
            if (d < 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[1].ToString();
            }
            int col = (int)d;
            bool match = true, rangeLookup = true;
            if (s.GetLength(0) == 4)
            {
                match = rangeLookup = (this.GetValueFromArg(s[3]) == TRUEVALUESTR) || (this.GetValueFromArg(s[3].Replace(this.TIC,string.Empty)) == "1");
            }

            bool typeIsNumber = double.TryParse(lookUp, NumberStyles.Any, null, out d);

            int i = r.IndexOf(":");
            ////single cell
            if (i == -1)
            {
                r = r + ":" + r;
                i = r.IndexOf(":");
            }

            int k = r.Substring(0, i).LastIndexOf(sheetToken);
            ICalcData grd = this.grid;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

            if (k > -1)
            {
                this.grid = (ICalcData)family.TokenToParentObject[r.Substring(0, k + 1)];
            }
            int row1 = this.RowIndex(r.Substring(0, i));
            int row2 = this.RowIndex(r.Substring(i + 1));
            if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[5].ToString();
            }
            if (row1 == -1)
            {
                row1 = ((ISheetData)this.grid).GetFirstRow();
            }
            int col1 = this.ColIndex(r.Substring(0, i));
            if (col1 == -1)
            {
                col1 = ((ISheetData)this.grid).GetFirstColumn();
            }
            if (row2 == -1)
            {
                row2 = ((ISheetData)this.grid).GetLastRow();
            }
            int col2 = this.ColIndex(r.Substring(i + 1));
            if (col2 == -1)
            {
                col2 = ((ISheetData)this.grid).GetLastColumn();
            }
            bool newTable = true;
            string key = string.Empty;
            List<string> lookUpTable = null;
            Dictionary<string, int> matchTable = null;
            if (cachingEnabled)
            {
                key = string.Format("{0}_{1}_{2}_{3}", col1, row1, row2, grid.GetHashCode());
                
                if (!lookupTables.ContainsKey(key))
                {
                    if (optimizedMatchesEnabled)
                    {
                        LookUps _lookUp = new LookUps();
                        _lookUp.LinearLookUpList = new List<string>();
                        _lookUp.MatchLookUpList = new Dictionary<string, int>();
                        lookupTables.Add(key, _lookUp);
                    }
                    else
                    {
                         LookUps _lookUp = new LookUps();
                         _lookUp.LinearLookUpList = new List<string>();
                         lookupTables.Add(key, _lookUp);
                    }
                    newTable = true;
                }
                lookUpTable = lookupTables[key].LinearLookUpList;
                if (optimizedMatchesEnabled)
                {
                    matchTable = lookupTables[key].MatchLookUpList;
                }
            }
            string val = string.Empty;
            int lastRow = row1, matchCount = 0;
            string s1 = string.Empty;
            double d1 = 0;
            bool doLastRowMark = true;
            bool exactMatch = false;
            List<string> tableValues = new List<string>();
            if (cachingEnabled && optimizedMatchesEnabled && matchTable.ContainsKey(lookUp))
            {
                lastRow = matchTable[lookUp];
                s1 = lookUp;
            }
            else
            {
                for (int row = row1; row <= row2; ++row)
                {
                    if (!cachingEnabled || row - row1 >= lookUpTable.Count || newTable)
                    {
                        s1 = this.GetValueFromParentObject(grid, row, col1).ToString().ToUpper().Replace("\"", string.Empty);
                        if (!tableValues.Contains(s1))
                            tableValues.Add(s1);
                        if (cachingEnabled)
                        {
                            if (!lookUpTable.Contains(s1))
                                lookUpTable.Add(s1);
                            if (optimizedMatchesEnabled && !matchTable.ContainsKey(s1))
                            {
                                matchTable.Add(s1, row);
                            }
                        }
                    }
                    else
                    {
                        s1 = lookUpTable[row - row1];
                    }
                    if (s1.Equals(lookUp) ||
                        (match && (typeIsNumber
                            ? (double.TryParse(s1, NumberStyles.Any, null, out d1) && (d1.CompareTo(d) > 0))
                            : (s1.CompareTo(lookUp) > 0))))
                    {
                        if (s1.ToUpper().Equals(lookUp))
                        {
                            lastRow = row;
                            match = true;
                            exactMatch = true;
                            matchCount++;
                        }
                        if (!newTable)
                            break;
                        else
                            doLastRowMark = false;
                    }

                    if (doLastRowMark)
                        lastRow = row;
                    if (matchCount == 0)
                        newTable = true;
                    else
                        newTable = false;
                    match = true;
                }
            }

            if (match || s1.Equals(lookUp))
            {
                if (lookUpTable != null && lookUpTable.Count > 0)
                {
                    lookUpTable.Sort();
                    lookUpTable[0] = (lookUpTable[0] == string.Empty) ? "0" : lookUpTable[0];
                }
                if (tableValues != null && tableValues.Count > 0)
                {
                    tableValues.Sort();
                    tableValues[0] = (tableValues[0] == string.Empty) ? "0" : tableValues[0];
                }
                if ((!exactMatch && (!typeIsNumber || (typeIsNumber && tableValues != null && double.Parse(tableValues[0]) > double.Parse(lookUp)))) || (cachingEnabled && typeIsNumber && lookUpTable != null && double.Parse(lookUpTable[0]) > double.Parse(lookUp)) || (!rangeLookup && !exactMatch))
                {
                    this.grid = grd;
                    return "#N/A";
                }
                val = this.GetValueFromParentObject(grid, lastRow, col + col1 - 1).ToString();
                if (val.Length > 0 && val[0] == CalcEngine.FormulaCharacter)
                {
                    val = this.ParseFormula(val);
                }

                d = 0;
                if (val.Length > 0 && val[0] != this.TIC[0] && !double.TryParse(val, NumberStyles.Any, null, out d))
                {
                    val = this.TIC + val + this.TIC;
                }
            }
            else
            {
                val = "#N/A";
            }

            this.grid = grd;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return val;
        }
        /// <summary>
        /// Returns a value from result table either from a one-row or one-column range or from an array 
        /// </summary>
        /// <param name="range">Lookup Value, lookup range, result range</param>
        /// <returns>Matching value found in the table</returns>
        public string ComputeLookUp(string range)
        {
            bool cachingEnabled = IsLookupCachingEnabled();
            bool optimizedMatchesEnabled = IsOptimizedMatchesEnabled();
            if (cachingEnabled && lookupTables == null) lookupTables = new Dictionary<string, LookUps>();
            string[] s = SplitArgsPreservingQuotedCommas(range);
            string lookUp = this.GetValueFromArg(s[0]).Replace(this.TIC, string.Empty);
            string finalResult = string.Empty;
            lookUp = lookUp.Replace(this.TIC, string.Empty).ToUpper();
            s[1] = s[1].Replace(this.TIC, string.Empty);
            if (s.Length == 3)
            {
                s[2] = s[2].Replace(this.TIC, string.Empty);
            }
            string r = s[1].Replace("\"", string.Empty);
            string tempLookUp = this.GetValueFromArg(s[0]);
            List<string> cellValue = new List<string>();
            List<string> resultValue = new List<string>();
            if (s.Length == 2)
            {
                string secondOne = s[1];
                string[] stringArg = SplitArgsPreservingQuotedCommas(s[1]);
                string[] sepArg = SplitArguments(s[1], ';');
                if (sepArg.Length == 2)
                {
                    string[] strin1 = SplitArgsPreservingQuotedCommas(sepArg[0].ToUpper());
                    string[] strin2 = SplitArgsPreservingQuotedCommas(sepArg[1].ToUpper());
                    foreach (string cell in strin1)
                    {
                        cellValue.Add(this.GetValueFromArg(cell).ToUpper());
                    }
                    foreach (string cell in strin2)
                    {
                        resultValue.Add(this.GetValueFromArg(cell).ToUpper());
                    }
                }
                else
                    for (int y = 0; y < sepArg.Length; y++)
                    {
                        string[] strin1 = SplitArgsPreservingQuotedCommas(sepArg[y].ToUpper());
                        cellValue.Add(this.GetValueFromArg(strin1[0]).ToUpper());
                        resultValue.Add(this.GetValueFromArg(strin1[1]).ToUpper());
                    }
                int ind = secondOne.IndexOf(parseArgumentSeparator);
            }
            else if (s.Length == 3)
            {
                if (r.IndexOf(':') > -1)
                {
                    foreach (string cell in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            cellValue.Add(this.GetValueFromArg(cell));
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[0].ToString();
                        }
                    }
                }
                else
                {
                    string[] s2 = SplitArgsPreservingQuotedCommas(s[1]);
                    foreach (string cell in s2)
                    {
                        try
                        {
                            cellValue.Add(this.GetValueFromArg(cell));
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[0].ToString();
                        }
                    }
                }
                string result = s[2];
                if (result.IndexOf(':') > -1)
                {
                    foreach (string cell in this.GetCellsFromArgs(result))
                    {
                        try
                        {
                            resultValue.Add(this.GetValueFromArg(cell).ToUpper());
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[0].ToString();
                        }
                    }
                }
                else
                {
                    string[] s2 = SplitArgsPreservingQuotedCommas(result);
                    foreach (string cell in s2)
                    {
                        try
                        {
                            resultValue.Add(this.GetValueFromArg(cell));
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            return this.ErrorStrings[0].ToString();
                        }
                    }
                }
            }
            if (!cellValue.Contains(lookUp))
            {
                string temp = cellValue[1];
                int valCount = 0;
                for (int x = 1; x < cellValue.Count; x++)
                {
                    if ((cellValue[x].CompareTo(temp) == 1 && lookUp.CompareTo(cellValue[x]) == 1 && temp.CompareTo(lookUp) == 1) || lookUp.CompareTo(cellValue[x]) == 1)// || temp.CompareTo(cellValue[x]) ==1)// && temp.CompareTo(cellValue[x]) == 1 && cellValue[x].CompareTo(temp) !=1)
                    {
                        temp = cellValue[x];
                        valCount++;
                    }
                    else if (valCount != 0)
                        break;
                }
                if (valCount == 0)
                {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[0].ToString();
                }
                lookUp = temp;
            }
            int no = 0;
            int index = 0;
            if (s.Length == 3 && s[2].IndexOf(':') > -1)
            {
                for (int y = 0; y < cellValue.Count; y++)
                {
                    if (cellValue[y] == lookUp)
                    {
                        index = cellValue.IndexOf(lookUp);
                        no++;
                    }
                    else if (no != 0)
                        break;
                }

                finalResult = resultValue[index + no - 1];
            }
            else
            {
                for (int y = 0; y < cellValue.Count; y++)
                {
                    if (cellValue[y] == lookUp)
                    {
                        index = cellValue.IndexOf(lookUp);
                        no++;
                    }
                    else if (no != 0)
                        break;
                }
                finalResult = resultValue[index + no - 1];
            }
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
            return finalResult;

        }
        /// <summary>
        /// Day of the week.
        /// </summary>
        /// <param name="argList">Serial number date1 and return_type.</param>
        /// <returns>Days between the dates.</returns>
        public string ComputeWeekday(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeWeekday"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 1 && argCount != 2)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double serialdate;
            double return_type = 1;

            double day = 0;

            DateTime dateTime;
            if (DateTime.TryParse(this.GetValueFromArg(args[0]), out dateTime)
                && (argCount == 1 || double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out return_type)))
            {
                day = (int)dateTime.DayOfWeek;
            }

            else if (double.TryParse(this.GetValueFromArg(args[0]), NumberStyles.Any, null, out serialdate)
                && (argCount == 1 || double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Any, null, out return_type)))
            {
                DateTime dt1 = this.GetDateFromSerialDate((int)serialdate);
                day = (int)dt1.DayOfWeek;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return day.ToString();
            }

            if (return_type == 1)
            {
                day += 1;
            }
            else
            {
                if (day == 0)
                {
                    day = 7;
                }

                if (return_type == 3)
                {
                    day -= 1;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return day.ToString();
        }

        /// <summary>
        /// Returns the Weibull distribution.
        /// </summary>
        /// <param name="argList">X, alpha, beta, cumulative.</param>
        /// <returns>The Weibull distribution.</returns>
        public string ComputeWeibull(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeWeibull"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 4 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double a;
            double b;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out a)
                && double.TryParse(args[2], NumberStyles.Any, null, out b))
            {
                if (argCount != 3)
                {
                    cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                }

                if (cum == 0)
                {
                    dist = a / Math.Pow(b, a) * Math.Pow(x, a - 1) * Math.Exp(-Math.Pow(x / b, a));
                }
                else
                {
                    dist = 1 - Math.Exp(-Math.Pow(x / b, a));
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

        /// <summary>
        ///  Computes the internal rate of return for a schedule of possibly non-periodic cash flows.
        /// </summary>
        /// <param name="argList">A list of two or three arguments. The first argument contains a range of cash flows, the second argument
        /// contains a list of corresponding date serial number values, and the third argument contains an initial guess at the return value.</param>
        /// <returns>The internal rate of return.</returns>
        /// <remarks>The computation uses a root finding algorithm. If the algorithm does not converge to a result within 100 iterations,
        /// an error is returned. The convergence requirement is an absolute error of 0.000001. The first date must be the earliest date,
        /// and the dates must be date serial numbers. Also, there must be at least one positive cash flow and at least one negative cash
        /// flow in the cash flow values.
        /// </remarks>
        public string ComputeXirr(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeXirr"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double guess = .1;
            string arg1 = args[0];
            if (argCount == 3)
            {
                double.TryParse(this.GetValueFromArg(args[2]), NumberStyles.Any, null, out guess);
            }

            string[] args1 = this.GetCellsFromArgs(arg1);
            argCount = args1.GetLength(0);
            double[] values = new double[argCount];
            int i = 0;
            double d;
            int posCount = 0;
            int negCount = 0;
            foreach (string s in args1)
            {
                if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out d))
                {
                    values[i] = d;
                }

                if (d < 0)
                {
                    negCount++;
                }
                else if (d > 0)
                {
                    posCount++;
                }

                ++i;
            }

            if (posCount == 0 || negCount == 0)
            {
                return "#NUM!";
            }

            arg1 = args[1];
            args = this.GetCellsFromArgs(arg1);
            int dateCount = args.GetLength(0);
            if (dateCount != argCount)
            {
                return "#NUM!";
            }

            int[] dates = new int[argCount];
            i = 0;
            int dt;
            DateTime dt1;
            foreach (string s in args)
            {
                string s1 = this.GetValueFromArg(s);
                bool b = int.TryParse(s1, out dt);

                if (!b && DateTime.TryParse(s1, out dt1))
                {
                    dates[i] = (int)GetSerialDateTimeFromDate(dt1);
                }
                else if (b)
                {
                    dates[i] = dt;
                }
                else
                {
                    return "#VALUE!";
                }

                if (dates[i] < dates[0])
                {
                    return "#NUM!";
                }

                ++i;
            }

            int iteration = 0;
            double sumF, sumFP, gp1, gPower, xpon, error;
            ////hard coded excel values
            while (iteration < 100) 
            {
                sumF = 0;
                sumFP = 0;
                gp1 = guess + 1;

                for (i = 0; i < argCount; ++i)
                {
                    xpon = (dates[0] - dates[i]) / 365d;
                    gPower = Math.Pow(gp1, xpon);
                    sumF = sumF + values[i] * gPower;
                    sumFP = sumFP + values[i] * xpon * gPower / gp1;
                }

                error = sumF / sumFP;
                guess = guess - error;
                ////hard coded excel values
                if (Math.Abs(error) < 1e-6) 
                {
                    break;
                }

                iteration++;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            ////hard coded excel values
            if (iteration >= 100)	
            {
                return "#NUM!"; ////FormulaErrorStrings[invalid_arguments];
            }
            else
            {
                return guess.ToString();
            }
        }

