                                if (s.Replace(this.TIC, string.Empty).Substring(0, index1) == criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d == compare))
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                        else
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

