                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                    }
                    break;
                case TOKEN_noequal:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;

                            if (s.Replace(this.TIC, string.Empty) != criteria || (double.TryParse(s, NumberStyles.Any, null, out d) && d != compare))
                            {
                                s = s2[index];
                                s = this.GetValueFromArg(s);
                                if (double.TryParse(s, NumberStyles.Any, null, out d))
                                {
                                    sum += d;
                                    cellCount++;
                                }
                            }
                        }
                    }
                    break;
                case TOKEN_greatereq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d >= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_greater:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d > compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_less:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d < compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_lesseq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d <= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                default:
                    break;
            }
            double average = sum / cellCount;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif

            return average.ToString();
        }
