                                            {
                                                sum += d;
                                            }
                                        }
                                    }
                                    else
                                        s2[index] = null;
                                }
                            }
                        }

                        break;
                    case TOKEN_lesseq:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;
                                if (double.TryParse(s, out d))
                                {
                                    if (d <= compare)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                        else
                                            s2[index] = null;
                                    }
                                }
                            }
                        }

                        break;
                    default:
                        break;
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif

           return sum.ToString();
       }
        /// <summary>
        /// Returns the number of whole workdays between two dates, week end and holidays are not consider as working days
        /// </summary>
        /// <param name="argList">start_date, end_date,weekend (optional), holidays (optional)</param>
        /// <returns>return the work days</returns>
        public string ComputeNetworkDaysintl(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeNetworkDaysintl"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            string adjustRange, s1;
            DateTime date;
            List<DateTime> holidays = new List<DateTime>();

            if (argCount != 2 && argCount >4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            DateTime startDateTime;
            DateTime endDateTime;
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[4].ToString();
            }
            if (argCount == 4)
            {
                adjustRange = args[3];
                this.AdjustRangeArg(ref adjustRange);
                ////is a cellrange
                if (adjustRange.IndexOf(':') > -1 || adjustRange.IndexOf(',') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(adjustRange))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                           {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1 != string.Empty)
                        {
                            if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6)
                            {
                                holidays.Add(date);
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(adjustRange).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6)
                        {
                            holidays.Add(date);
                        }
                    }
                }
           }

            int weekend = 0;
            if (!(argCount > 2 && int.TryParse(args[2], out weekend)))
            {
                weekend = 1;
            }
            else
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[4].ToString();
            }
            ArrayList weekendDays = new ArrayList();
            weekendDays.AddRange(SplitArguments(WeekEndType[weekend].ToString(), ','));
            int noofDays = int.Parse(this.ComputeDatevalue(endDate)) - int.Parse(this.ComputeDatevalue(startDate)) +1;
            int netWorkDays = noofDays;
           int j=1;
            DateTime  tempStartDate =startDateTime;
            while (j < noofDays)
            {
                int dayofweek = (int)tempStartDate.DayOfWeek;
                if (weekendDays.IndexOf(dayofweek.ToString()) >= 0)
                {
                    netWorkDays--;
                }
                else if (holidays.IndexOf(tempStartDate) >= 0)
                {
                    netWorkDays--;
                }
                tempStartDate = tempStartDate.AddDays(1);
                j++;
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return netWorkDays.ToString();
        }

        public string ComputeNetworkDays(string argList)
        {
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            string adjustRange, s1;
            DateTime date;
            List<DateTime> holidays = new List<DateTime>();

            if (argCount != 2 && argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            DateTime startDateTime;
            DateTime endDateTime;
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ErrorStrings[4].ToString();
            }
            if (argCount == 3)
            {
                adjustRange = args[2];
                this.AdjustRangeArg(ref adjustRange);
                ////is a cellrange
                if (adjustRange.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(adjustRange))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception ex)
                        {
#if _ENABLETIMERS
                            MarkTimeEnd(ML);
#endif
                            if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                            {
                                throw this.LibraryComputationException;
                            }

                            return ex.Message;
                        }

                        if (s1 != string.Empty)
                        {
                            if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6) 
                            {
                                holidays.Add(date);
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(adjustRange).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception ex)
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        if (this.rethrowLibraryComputationExceptions && LibraryComputationException != null)
                        {
                            throw this.LibraryComputationException;
                        }

                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6) 
                        {
                            holidays.Add(date);
                        }
                    }
                }
            }

            int numberOfWorkingDays = 0;

            int noofDays = int.Parse(this.ComputeDatevalue(endDate)) - int.Parse(this.ComputeDatevalue(startDate));

            int startWeekDay = (int)startDateTime.DayOfWeek;
            int endWeekDay = (int)endDateTime.DayOfWeek;
            int excesStartDays = startWeekDay - 1;
            int excesEndDays = 7 - endWeekDay;
            noofDays = noofDays + excesStartDays + excesEndDays;

            int noofholidays = (noofDays / 7) * 2;

            numberOfWorkingDays = noofDays - excesStartDays - excesEndDays - noofholidays + 1 - holidays.Count;
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return numberOfWorkingDays.ToString();
        }

