        private double sdP(double[] x, out double xbar)
        {
            int n = x.GetLength(0);
            xbar = 0;
            for (int i = 0; i < n; ++i)
            {
                xbar += x[i];
            }

            xbar = xbar / n;
            double sumx2 = 0;
            double d = 0;

            for (int i = 0; i < n; ++i)
            {
                d = x[i] - xbar;
                sumx2 += d * d;
            }

            return Math.Sqrt(sumx2 / n);
        }
