        private double StdevdotP(double[] range)
        {
            int n = range.GetLength(0);
            double mean = 0;
            double sigma = 0;
            int count = 0;

            for (int i = 0; i < n; ++i)
                mean += range[i];
            mean = mean / n;
            for (int i = 0; i < n; i++)
            {
                sigma += Math.Pow(range[i] - mean, 2);
                count++;
            }

            return Math.Sqrt(sigma / count);
        }
