            string ML = "ComputeFOinv"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p;
            double df1;
            double df2;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && double.TryParse(args[1], NumberStyles.Any, null, out df1)
                && double.TryParse(args[2], NumberStyles.Any, null, out df2))
            {
                if ((p < 0 || p > 1) || (df1 < 1 || df2 < 1))
                {
