            {
                if (RethrowLibraryComputationExceptions)
                {
                    throw new Exception("#VALUE! Passed argument value is incorrect");
                }
                return this.errorStrings[1].ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return dist.ToString();
        }

