        /// <summary>
        /// Convert the text to number
        /// </summary>
        /// <param name="argList">text, </param>
        /// <returns>decimal separator,group separator </returns>
        public string ComputeNumberValue(string argList)
        {
#if _ENABLETIMERS
                string ML = "ComputeNumberValue"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            char decimalseparator = ParseDecimalSeparator;
            char groupseparator = parseArgumentSeparator;
            if (argCount > 3)
            {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string text = this.StripTics0(GetValueFromArg(args[0]));
            if (argCount > 1)
            {
                try
                {
                    string deci = this.StripTics0(GetValueFromArg(args[1]));
                    string gro = this.StripTics0(GetValueFromArg(args[2]));
                    if ((deci.Equals("invalid expression") || gro.Equals("invalid expression")) || (string.IsNullOrEmpty(deci) && string.IsNullOrEmpty(gro)))
                    {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentException(this.ErrorStrings[1].ToString());
                        return this.ErrorStrings[1].ToString();
                    }
                    else
                    {
                        decimalseparator = this.StripTics0(deci)[0];
                        groupseparator = this.StripTics0(gro)[0];
                    }
                }
                catch (Exception ex)
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(ex.Message);
                    return this.ErrorStrings[1].ToString();
                }
            }
            if (string.IsNullOrEmpty(text))
            {
                return "0";
            }
            int indexDecimal = text.IndexOf(decimalseparator);
            int indexGroup = text.IndexOf(groupseparator);
            if ((indexGroup >= indexDecimal) && (indexDecimal != -1 || indexGroup != -1))
            {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.ErrorStrings[1].ToString());
                return this.ErrorStrings[1].ToString();
            }
            text = text.Replace(this.TIC, string.Empty);
            text = text.Replace(" ", string.Empty);
            text = text.Replace(groupseparator.ToString(), string.Empty);
            text = text.Replace(decimalseparator, ParseDecimalSeparator);
            string compText = this.ComputeValue(text);
            if (ComputeIsNumber(compText) != this.TRUEVALUESTR || text.EndsWith("$"))
            {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                TimeSpan ts;
                if (TimeSpan.TryParse(text, out ts))
                {
                    return ts.TotalDays.ToString();
                }
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.ErrorStrings[1].ToString());
                return this.ErrorStrings[1].ToString();
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return compText;
        }

