        /// <summary>
        /// return the sheet number of the given value 
        /// </summary>
        /// <param name="argList">SheetName or cell or named range </param>
        /// <returns>sheet number</returns>
        public string ComputeSheet(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeSheet"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            string value = string.Empty;
            if (argCount > 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string cellReference = args[0].Replace(this.TIC, "").ToUpper();
            cellReference = (string.IsNullOrEmpty(cellReference)) ? this.cell : cellReference;
            if (this.ErrorStrings.Contains(cellReference))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return cellReference;
            }
            if (!this.IsCellReference(cellReference) && !this.NamedRanges.ContainsKey(cellReference) && !this.SortedSheetNames.Contains(cellReference))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                return this.ErrorStrings[0].ToString();
            }
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            string sheet1 = this.GetSheetTokenFromReference(cellReference); // this.SheetToken(cell);
            int sheetNumber = 0;
            if (string.IsNullOrEmpty(sheet1) && !this.SortedSheetNames.Contains(cellReference) && !cellReference.Contains(sheetToken.ToString()))
            {
                sheetNumber = this.GetSheetID(this.grid) + 1;
            }
            else if (sheet1.Length > 0)
            {
                sheetNumber = int.Parse(sheet1.Replace(sheetToken.ToString(), string.Empty)) + 1;
            }
            else
            {
                try
                {
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    foreach (DictionaryEntry griddata in family.TokenToParentObject)
#else
                    foreach (System.Collections.Generic.KeyValuePair<object,object> griddata in family.TokenToParentObject)
#endif
                    {
                        if (family.SheetNameToParentObject[cellReference].Equals(griddata.Value))
                        {
                            ICalcData gg = griddata.Value as ICalcData;
                            sheetNumber = GetSheetID(gg) + 1;
                            break;
                        }
                    }
                }
                catch (Exception e)
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw e;
                    return this.ErrorStrings[2].ToString();

                }
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return sheetNumber.ToString();
        }

