        /// <summary>
        /// Retuns the number into text for the given radix base
        /// </summary>
        /// <param name="argList"></param>
        /// <returns></returns>
        public string ComputeBase(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeBase"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount < 2 || argCount > 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            int number = 0, radix = 0, length = 1;
            try
            {
                number = int.Parse(this.GetValueFromArg(args[0]).Replace(this.TIC, ""));
                radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
                length = (argCount == 3) ? int.Parse(this.GetValueFromArg(args[2]).Replace(this.TIC, "")) : 1;
            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[invalid_Math_argument] + ex.Message);
                return this.ErrorStrings[5].ToString();
            }
            const int BitsInLong = 64;
            const string Digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

            if (radix < 2 || radix > Digits.Length)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentOutOfRangeException("Base requested outside range, it should be from 2 - 16");
                return this.ErrorStrings[1].ToString();
            }

            if (number == 0)
                return "0";

            int index = BitsInLong - 1;
            long currentNumber = Math.Abs(number);
            char[] charArray = new char[BitsInLong];

            while (currentNumber != 0)
            {
                int remainder = (int)(currentNumber % radix);
                charArray[index--] = Digits[remainder];
                currentNumber = currentNumber / radix;
            }

            string result = new String(charArray, index + 1, BitsInLong - index - 1);
            StringBuilder outputString = new StringBuilder();
            for (int i = 0; i < length - result.Length ; i++)
            {
                outputString.Append("0");
            }
            result = outputString.ToString() + result;
            if (number < 0)
            {
                result = "-" + result;
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return result.ToString();
        }

        /// <summary>
        /// Returns the decimal number of the given text to the given base.
        /// </summary>
        /// <param name="argList">text,base</param>
        /// <returns>Decimal number.</returns>
        public string ComputeDecimal(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeDecimal"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            if (argCount > 3)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            const string Base64 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/";
            if (!this.GetValueFromArg(args[0]).Contains(this.TIC) && !this.IsCellReference(args[0]))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[invalid_Math_argument]);
                return this.ErrorStrings[1].ToString();
            }
            string strValue; int radix = 0;
            try
            {
                strValue = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
                radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
            }
            catch (Exception ex)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[invalid_Math_argument] + ex.Message);
                return this.ErrorStrings[1].ToString();
            }
            int result;
            if (radix < 2 || radix > Base64.Length)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentOutOfRangeException("Base requested outside range, it should be from 2 - 16");
                return this.ErrorStrings[4].ToString();
            }
            strValue = strValue.Trim();
            if (radix <= 36)
                strValue = strValue.ToUpper();
            int pos = 0;
            result = 0;
            // Use lookup table to parse string
            while (pos < strValue.Length && !Char.IsWhiteSpace(strValue[pos]))
            {
                string digit = strValue.Substring(pos, 1);
                int i = Base64.IndexOf(digit);
                if (i >= 0 && i < radix)
                {
                    result *= radix;
                    result += i;
                    pos++;
                }
                else
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentOutOfRangeException("Base requested outside range, it should be from 2 - 16");
                    return this.ErrorStrings[4].ToString();
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return result.ToString();
        }

        /// <summary>
        ///  Returns the interest rate for a fully invested security.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Rate of interest</returns>
        
        public string ComputeIntrate(string argList)
        {
#if _ENABLETIMERS
            string ML = "ComputeIntrate"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(argList);
            int argCount = args.GetLength(0);
            List<DateTime> holidays = new List<DateTime>();

            if (argCount > 5)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            string basis = (argCount == 5) ? this.GetValueFromArg(args[4]).Replace(this.TIC, "") : "0";
            DateTime startDateTime;
            DateTime endDateTime;
            int basisValue;
            double investment, redemption;
            string invest = this.GetValueFromArg(args[2]).Replace(this.TIC, "");
            string redem = this.GetValueFromArg(args[3]).Replace(this.TIC, "");
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime) && int.TryParse(basis, out basisValue) && double.TryParse(invest,out investment) && double.TryParse(redem,out redemption)))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[1].ToString();
            }
            double dim = double.Parse(this.ComputeDatevalue(endDate)) - double.Parse(this.ComputeDatevalue(startDate));
            if ((basisValue > 4 && basisValue < 0) && dim < 1)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (RethrowLibraryComputationExceptions)
                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                return this.ErrorStrings[4].ToString();
            }

            double intrate = (redemption - investment) / (investment * dim);
                
            switch (basisValue)
            {
                case 0:
                    intrate = intrate * 360;
                    break;
                case 1:
                    intrate = intrate * 366;
                    break;
                case 2:
                    intrate = intrate * 360;
                    break;
                case 3:
                    intrate = intrate * 365;
                    break;
                case 4:
                    intrate = intrate * 360;
                    break;
                default:
                    {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                        return this.ErrorStrings[4].ToString();
                    }
            }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return intrate.ToString();
        }

            public string ComputeSeriessum(string arg)
            {
#if _ENABLETIMERS
                string ML = "ComputeSeriessum"; MarkTimeStart(ML);
#endif
                string[] args = SplitArgsPreservingQuotedCommas(arg);
                if (args.Length != 4)
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                double xValue = 0, nValue = 0, mValue = 0, coeff = 0,result = 0;
                string[] arrayArg;
                if (args[3].IndexOf(';') > -1)
                {
                    arrayArg = SplitArguments(args[3].Replace(this.TIC, ""), ';');
                }
                else
                {
                    arrayArg = GetCellsFromArgs(args[3].Replace(this.TIC, ""));
                }
                if (!(double.TryParse(GetValueFromArg(args[0].Replace(this.TIC, "")), out xValue) && double.TryParse(GetValueFromArg(args[1].Replace(this.TIC, "")), out nValue) && double.TryParse(GetValueFromArg(args[2].Replace(this.TIC, "")), out mValue)))
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                        return this.ErrorStrings[1].ToString();
                }
                for (int i = 0; i < arrayArg.Length; i++)
                {
                    if (double.TryParse(GetValueFromArg(arrayArg[i].Replace(this.TIC, "")), out coeff))
                    {
                        result = result + (coeff * Math.Pow(xValue, (nValue + (i * mValue))));
                    }
                    else
                    {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                        if (RethrowLibraryComputationExceptions)
                            throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                        return this.ErrorStrings[1].ToString();
                    }
                }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return result.ToString();
            }

        /// <summary>
        /// Returns the Arabic value of Raman numeric
        /// </summary>
        /// <param name="arg"></param>
        /// <returns></returns>
            public string ComputeArabic(string arg)
            {
#if _ENABLETIMERS
                string ML = "ComputeArabic"; MarkTimeStart(ML);
#endif
                string[] args = SplitArgsPreservingQuotedCommas(arg);
                if (args.Length != 1)
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[wrong_number_arguments]);
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string text = GetValueFromArg(args[0]).Replace(this.TIC, "").ToUpper();
                if (!GetValueFromArg(args[0]).Contains(this.TIC) && string.IsNullOrEmpty(text))
                {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                    if (RethrowLibraryComputationExceptions)
                        throw new ArgumentException(this.FormulaErrorStrings[bad_formula]);
                    return this.ErrorStrings[5].ToString();
                }
                int i = 0;
                string ch = null;
                long result = 0;
                long new_value = 0;
                long old_value = 0;
                old_value = 1000;
                for (i = 1; i <= text.Length; i++)
                {
                    // See what the next character is worth.
                    ch = text.Substring(i - 1, 1);
                    switch (ch)
                    {
                        case "I":
                            new_value = 1;
                            break;
                        case "V":
                            new_value = 5;
                            break;
                        case "X":
                            new_value = 10;
                            break;
                        case "L":
                            new_value = 50;
                            break;
                        case "C":
                            new_value = 100;
                            break;
                        case "D":
                            new_value = 500;
                            break;
                        case "M":
                            new_value = 1000;
                            break;
                        default:
                            {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                                if (RethrowLibraryComputationExceptions)
                                    throw new ArgumentNullException(this.FormulaErrorStrings[bad_formula]);
                                return this.ErrorStrings[1].ToString();
                            }
                    }
                    // See if this character is bigger
                    // than the previous one.
                    if (new_value > old_value)
                    {
                        // The new value > the previous one.
                        // Add this value to the result
                        // and subtract the previous one twice.
                        result = result + new_value - 2 * old_value;
                    }
                    else
                    {
                        // The new value <= the previous one.
                        // Add it to the result.
                        result = result + new_value;
                    }
                    old_value = new_value;
                }

#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return result.ToString();
            }

