        private bool Daysfeb29(DateTime sDate, DateTime eDate)
        {
            DateTime sDateFeb = new DateTime(sDate.Year, 2, 1);
            DateTime eDateFeb = new DateTime(eDate.Year, 2, 1);
#if SILVERLIGHT || WINDOWS_UWP
            int sDateDiff_1 = int.Parse(this.ComputeDatevalue(sDate.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - int.Parse(this.ComputeDatevalue(sDateFeb.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));
            int eDateDiff_1 = int.Parse(this.ComputeDatevalue(eDate.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - int.Parse(this.ComputeDatevalue(sDateFeb.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));

            int sDateDiff_2 = int.Parse(this.ComputeDatevalue(sDate.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - int.Parse(this.ComputeDatevalue(eDateFeb.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));
            int eDateDiff_2 = int.Parse(this.ComputeDatevalue(eDate.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - int.Parse(this.ComputeDatevalue(eDateFeb.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));
#else
            int sDateDiff_1 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));
            int eDateDiff_1 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));

            int sDateDiff_2 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));
            int eDateDiff_2 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));
#endif
                
            if (DateTime.IsLeapYear(sDate.Year) && sDateDiff_1 < 0 && eDateDiff_1 >= 0)
                return true;
            if (DateTime.IsLeapYear(eDate.Year) && sDateDiff_2 < 0 && eDateDiff_2 >= 0)
                return true;
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
            return false;
        }

