                case "parentheses":
                    break;
                case "prefix":
                    break;
                case "protect":
                    break;
                case "row":
                    result = ComputeRow(reference);
                    break;
                case "type":
                    if (ComputeIsBlank(reference) == TRUEVALUESTR)
                        result = "b";
                    else if (ComputeIsText(reference) == TRUEVALUESTR)
                        result = "l";
                    else
                        result = "v";
                    break;
                case "width":
                    break;
                default:
                    break;
            }
            
