        public string ComputeBahtText(string arg)
        {
#if _ENABLETIMERS
            string ML = "ComputBahtText"; MarkTimeStart(ML);
#endif
            string[] args = SplitArgsPreservingQuotedCommas(arg);
            //double result;
            if (args.Length > 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double num = 0;
            if(!double.TryParse(this.GetValueFromArg(args[0]),out num))
            {
#if _ENABLETIMERS
