        public static string getBetween(string strSource, string strStart, string strEnd)
        {
            int Start, End;
            if (strSource.Contains(strStart) && strSource.Contains(strEnd))
            {
                Start = strSource.IndexOf(strStart, 0) + strStart.Length;
                End = strSource.IndexOf(strEnd, Start);
                return strSource.Substring(Start, End - Start);
            }
            else
            {
                return "";
            }
        }
        private static string Spell(int number)
        {
            Hashtable baseWords = new Hashtable();
            baseWords.Add(0, "");
            baseWords.Add(1, "one");
            baseWords.Add(2, "two");
            baseWords.Add(3, "three");
            baseWords.Add(4, "four");
            baseWords.Add(5, "five");
            baseWords.Add(6, "six");
            baseWords.Add(7, "seven");
            baseWords.Add(8, "eight");
            baseWords.Add(9, "nine");
            baseWords.Add(10, "ten");
            baseWords.Add(11, "eleven");
            baseWords.Add(12, "twelve");
            baseWords.Add(13, "thirteen");
            baseWords.Add(14, "fourteen");
            baseWords.Add(15, "fifteen");
            baseWords.Add(16, "sixteen");
            baseWords.Add(17, "seventeen");
            baseWords.Add(18, "eighteen");
            baseWords.Add(19, "nineteen");
            baseWords.Add(20, "twenty");
            baseWords.Add(30, "thirty");
            baseWords.Add(40, "forty");
            baseWords.Add(50, "fifty");
            baseWords.Add(60, "sixty");
            baseWords.Add(70, "seventy");
            baseWords.Add(80, "eighty");
            baseWords.Add(90, "ninety");

            if (number >= 1000)
            {
                return Spell(number / 1000) + " thousand " + Spell(number % 1000);
            }
            if (number >= 100)
            {
                return Spell(number / 100) + " hundred " + Spell(number % 100);
            }
            if (number >= 21)
            {
                return baseWords[number / 10 * 10] + " " + baseWords[number % 10];
            }
            return baseWords[number].ToString();
        }

        /// <summary>
        /// CreateSheetFamilyID is a method to create familyID for a sheet.
        /// </summary>
        /// <returns>Sheet family ID.</returns>
        /// <remarks>
        /// Essential Calculate supports multisheet references within a family of ICalcData objects. To use
        /// this functionality, you use this method to get a unique identifier for
        /// the family. Then in the RegisterGridAsSheet method that you call to add ICalcData objects
        /// to this family, you pass this unique identifier to mark the ICalcData objects as belonging
        /// to this family. You can only cross reference ICalcData objects within the same family.
        /// </remarks>
        public static int CreateSheetFamilyID()
        {
            if (sheetFamilyID == int.MaxValue)
            {
                sheetFamilyID = int.MinValue;
            }

            return sheetFamilyID++;
        }

        private int critbinom(int nTrials, double p, double alpha)
        {
            int checkval = nTrials;
            int half = nTrials;
            double dist = 1;
            double dist1 = 1;
            do
            {
                half = half / 2 + 1;
                if (dist >= alpha)
                {
                    dist1 = this.binomdist(nTrials, checkval - 1, p);
                    if (double.IsNaN(dist1))
                    {
                        return int.MaxValue;
                    }

                    if (dist1 < alpha && dist1 > 0)
                    {
                        break;
                    }

                    checkval = checkval - half;
                }
                else
                {
                    dist1 = this.binomdist(nTrials, checkval + 1, p);
                    if (dist1 >= alpha)
                    {
                        checkval = checkval + 1;
                        break;
                    }

                    checkval = checkval + half;
                }

                dist = this.binomdist(nTrials, checkval, p);
            }
            while (checkval < nTrials && checkval > 0);

            return checkval;
        }

        /// <summary>
