#endif
                    {
                        TokenCount--;

                        int i = (int)modelToSheetID[grid];
                        modelToSheetID[grid] = null;
                        modelToSheetID.Remove(grid);

                        if (sheetFamiliesList != null && sheetFamiliesList.Count > 0)
                        {
                            sheetFamiliesList[i] = null;
                            sheetFamiliesList.Remove(i);
                        }
                    }

                    this.grid.ValueChanged -= new ValueChangedEventHandler(this.grid_ValueChanged);
                }
                if (_formulaInfoTable != null)
                {
                    this._formulaInfoTable.Clear();
                    this._formulaInfoTable = null;
                }
                if (circCheckList != null)
                {
                    this.circCheckList.Clear();
                    this.circCheckList = null;
                }
                if (dependentCells != null)
                {
                    this.dependentCells.Clear();
                    dependentCells = null;
                }
                if (dependentFormulaCells != null)
                {
                    this.dependentFormulaCells.Clear();
                    dependentFormulaCells = null;
                }

                if (iterationValues != null)
                {
                    this.iterationValues.Clear();
                    iterationValues = null;
                }
                if (libraryFunctions != null)
                {
                    this.libraryFunctions.Clear();
                    libraryFunctions = null;
