                }
                this.grid = null;
                if (LibraryFunctions != null)
                {
                    this.LibraryFunctions.Clear();
                    this.libraryFunctions = null;
                }
                _isDisposed = true;
            }
        }

        private double fdensity(double x, int df1, int df2)
        {
            return Math.Pow(x, (df1 - 2) / 2d) / Math.Pow(1 + df1 * x / df2, (df1 + df2) / 2d);
        }

        private double fdist(double x, int df1, int df2)
        {
            int nPanels = 32;

            double leftside = 0;
            double rightside = x;

            double h = (rightside - leftside) / nPanels;
            double mult = h / 3;

            double sum1 = this.fdensity(leftside, df1, df2) + this.fdensity(rightside, df1, df2);
            double sum4 = 0;
            for (int i = 1; i < nPanels; i += 2)
            {
                sum4 += 4 * this.fdensity(leftside + i * h, df1, df2);
            }

            double sum2 = 0;
            for (int i = 2; i < nPanels; i += 2)
            {
                sum2 += 2 * this.fdensity(leftside + i * h, df1, df2);
            }

            double gd = mult * (sum1 + sum2 + sum4);
            double oldgd = gd;
            double eps = 1e-7;

            int k = 0;

            for (k = 0; k < 10; ++k)
            {
                nPanels *= 2;

                sum2 += sum4 / 2;
                sum4 = 0;
                h = (rightside - leftside) / nPanels;
                for (int i = 0; i < nPanels; ++i)
                {
                    if (i % 2 == 1)
                    {
                        double d = this.fdensity(leftside + h * i, df1, df2);
                        sum4 += d;
                    }
                }

                sum4 = 4 * sum4;
                mult = h / 3;
                gd = mult * (sum1 + sum2 + sum4);

                if (Math.Abs((gd - oldgd) / oldgd) < eps)
                {
                    break;
                }

                oldgd = gd;
            }

            return gd;
        }

        private int FindAndCheckPrecedingChar(ref string copy, string op, int loc)
        {
            int loc1 = copy.IndexOf(op, loc);
            if (loc1 > 0)
            {
                while (loc1 > -1 && this.ValidPrecedingChars.IndexOf(copy[loc1 - 1]) == -1)
                {
                    loc1 = copy.IndexOf(op, loc1 + 1);
                }
            }

            return loc1;
        }

        private int FindLastNonQB(string text)
        {
            int ret = -1;
            if (text.IndexOf(BMARKER) > -1)
            {
                int bracketLevel = 0;
                for (int i = text.Length - 1; i >= 0; --i)
                {
                    if (text[i] == this.RIGHTBRACKET)
                    {
                        bracketLevel--;
                    }
                    else if (text[i] == this.LEFTBRACKET)
                    {
                        bracketLevel++;
                    }
                    else if (text[i] == BMARKER && bracketLevel == 0)
                    {
                        ret = i;
                        break;
                    }
                }
            }

            return ret;
        }

        int FindLastqNotInBrackets(string s)
        {
            int found = -1;
            bool lastBracket = false;
            int i = s.Length - 1;
            while (i > -1)
            {
                if (s[i] == 'q' && lastBracket)
                {
                    found = i;
                    break;
                }

                if (s[i] == this.LEFTBRACKET)
                {
                    lastBracket = true;
                }
                else if (s[i] == this.RIGHTBRACKET)
                {
                    lastBracket = false;
                }

                i--;
            }

            return found;
        }

        private bool FindNextSeparator(string formula, ref int location)
        {
            int qCount = 0;
            bool found = false;
            while (!found && location < formula.Length)
            {
                if (formula[location] == 'q')
                {
                    qCount++;
                }
                else if (formula[location] == this.RIGHTBRACKET)
                {
                    qCount--;
                }
                else if (qCount == 0 && formula[location] == ParseArgumentSeparator)
                {
                    found = true;
                    location--;
                }

                location++;
            }

            return found;
        }

        private int FindNonQB(string text)
        {
            int ret = -1;
            if (text.IndexOf(BMARKER) > -1)
            {
                int bracketLevel = 0;
                for (int i = 0; i < text.Length; ++i)
                {
                    if (text[i] == this.RIGHTBRACKET)
                    {
                        bracketLevel--;
                    }
                    else if (text[i] == this.LEFTBRACKET)
                    {
                        bracketLevel++;
                    }
                    else if (text[i] == BMARKER && bracketLevel == 0)
                    {
                        ret = i;
                        break;
                    }
                }
            }

            return ret;
        }

        private bool FindRightBracket(string formula, ref int location)
        {
            int qCount = 0;
            bool found = false;
            while (!found && location < formula.Length)
            {
                if (formula[location] == 'q')
                {
                    qCount++;
                }
                else if (qCount == 0 && formula[location] == this.RIGHTBRACKET)
                {
                    found = true;
                    location--;
                }
                else if (formula[location] == this.RIGHTBRACKET)
                {
                    qCount--;
                }

                location++;
            }

            return found;
        }

        private double finv(double p, int df1, int df2)
        {
            double mult = Math.Exp(this.gammaln((df1 + df2) / 2d) -
                    this.gammaln(df1 / 2d) -
                    this.gammaln(df2 / 2d) +
                    (df1 / 2d) * Math.Log((double)df1 / df2));

            double guess = mult;

            double lastIncrement = guess / 2;
            double gi = 0;
            double eps = 1e-7;
            int k = 100;
            int tries = 3;
            int its = 0;
            while (k == 100 && tries > 0)
            {
                tries--;
                guess = guess / 2;
                lastIncrement = guess / 2;

                for (k = 0; k < 100; ++k)
                {
                    its++;
                    gi = 1 - mult * this.fdist(guess, df1, df2);

                    ////Console.WriteLine("{0}: guess {1}  computed {2}  target {3}", its, guess, gi, p);
                    if (Math.Abs((gi - p) / p) < eps)
                    {
                        break;
                    }

                    ////greater since looking for 1 - xxxx
                    if (gi > p)
                    {
                        guess += lastIncrement;
                    }
                    else
                    {
                        lastIncrement = lastIncrement / 2;
                        if (guess - lastIncrement < 0)
                        {
                            lastIncrement = guess / 2;
                        }

                        guess -= lastIncrement;
                    }
                }
            }

            if (k == 100)
            {
                guess = -1;
            }

            return guess;
        }

        private double gammadensity(double a, double b, double x)
        {
            //// excel version     dist = 1 / (Math.Pow(b, a) * gammaln(a)) * Math.Pow(x, a - 1) * Math.Exp(-x / b);
            //// http://www.itl.nist.gov/div898/handbook/eda/section3/eda366b.htm
            return Math.Pow(x / b, a - 1) * Math.Exp(-x / b) / (b * Math.Exp(this.gammaln(a)));
        }

        private double gammadist(double a, double b, double x)
        {
            int nPanels = 4;

            double h = x / nPanels;  ////h = (b-a)/(3n)
            double mult = x / 12;
            double sum1 = this.gammadensity(a, b, x);
            double sum4 = 4 * (this.gammadensity(a, b, h) + this.gammadensity(a, b, 3 * h));
            double sum2 = 2 * this.gammadensity(a, b, 2 * h);
            double gd = mult * (sum1 + sum2 + sum4);
            double oldgd = gd;
            double eps = 1e-7;

            for (int k = 0; k < 30; ++k)
            {
                nPanels *= 2;

                sum2 += sum4 / 2;
                sum4 = 0;
                h = x / nPanels;
                for (int i = 0; i < nPanels; ++i)
                {
                    if (i % 2 == 1)
                    {
                        double d = this.gammadensity(a, b, h * i);
                        sum4 += d;
                    }
                }

                sum4 = 4 * sum4;
                mult /= 2;
                gd = mult * (sum1 + sum2 + sum4);

                ////Console.WriteLine(gd);
                if (Math.Abs((gd - oldgd) / oldgd) < eps)
                {
                    break;
                }

                oldgd = gd;
            }

            return gd;
        }

        private double gammainv(double p, double a, double b)
        {
            double guess = (a > b) ? b * Math.Abs(Math.Log(b * p)) : a * Math.Abs(Math.Log(a * p));
            if (a == b)
            {
                guess = p;
            }

            double lastIncrement = guess / 2;
            double gi = 0;
            double eps = 1e-7;
            int k = 100;
            int tries = 0;
            double temp = p;

            while (temp < 1)
            {
                temp *= 10;
                tries++;
            }
            
            while (k == 100 && tries > 0)
            {
                tries--;
                guess = guess / 2;
                lastIncrement = guess / 2;

                for (k = 0; k < 100; ++k)
                {
                    gi = this.gammadist(a, b, guess);
                    if (Math.Abs((gi - p) / p) < eps)
                    {
                        break;
                    }

                    if (gi < p)
                    {
                        guess += lastIncrement;
                    }
                    else
                    {
                        lastIncrement = lastIncrement / 2;
                        if (guess - lastIncrement < 0)
                        {
                            lastIncrement = guess / 2;
                        }

                        guess -= lastIncrement;
                    }
                }
            }

            if (k == 100)
            {
                guess = -1;
            }

            return guess;
        }

        private double gammaln(double x)
        {
            double y = x;
            double f = 0d;
            if (y < 7d)
            {
                f = y;
                y++;
                while (y < 7d)
                {
                    f = f * y;
                    if (y < 7d)
                    {
                        y++;
                    }
                }

                f = -Math.Log(f);
            }

            double z = 1d / (y * y);
            return f + (y - 0.5d) * Math.Log(y) - y + gammaAs[0]
            + (((-gammaAs[1] * z + gammaAs[2]) * z - gammaAs[3]) * z + gammaAs[4]) / y;
        }

