        private string GetCellFrom(string range)
        {
            string s = string.Empty;
            string[] cells = this.GetCellsFromArgs(range);
            int last = cells.Length - 1;
            int r1 = this.RowIndex(cells[0]);
            int x;
            if (r1 == this.RowIndex(cells[last]))
            {
                int c1 = this.ColIndex(cells[0]);
                int c2 = this.ColIndex(cells[last]);
                int c = this.ColIndex(this.cell);
                if (c >= c1 && c <= c2)
                {
                    s = string.Format("{0}{1}", RangeInfo.GetAlphaLabel(c), r1);
                }
            }
            else if ((x = this.ColIndex(cells[0])) == this.ColIndex(cells[last]))
            {
                int r2 = this.RowIndex(cells[last]);
                int r = this.RowIndex(this.cell);
                if (r >= r1 && r <= r2)
                {
                    s = string.Format("{0}{1}", RangeInfo.GetAlphaLabel(x), r);
                }
            }

            return s;
        }

        private bool ignoreCellValue = false;
        /// <summary>
        /// A method that retrieves a string array of cells from the range passed in.
        /// </summary>
        /// <remarks>
        ///	Converts arguments in these forms to a string array of individual cells:<para/>
        ///		A1,A2,B4,C1,...,D8<para/>
        ///		A1:A5<para/>
        ///		A1:C5<para/>
        /// </remarks>
        /// <param name="args">String containing a cell range.</param>
        /// <returns>String array of cells.</returns>
        public string[] GetCellsFromArgs(string args)
        {
#if _ENABLETIMERS
            string ML = "GetCellsFromArgs"; MarkTimeStart(ML);
#endif

            this.MarkColonsInQuotes(ref args);

            int row1;
            int col1;

            int i = args.IndexOf(':');
            if (i == -1)
            {
                args = args.Replace(this.MarkerChar, ':');
                i = args.IndexOf(ParseArgumentSeparator);
                if (i == -1)
                {
                    row1 = this.RowIndex(args); ////maybe throw exception
                    col1 = this.ColIndex(args); ////maybe throw exception
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return new string[] { args };
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return SplitArgsPreservingQuotedCommas(args);
                }
            }

            string sheet = string.Empty;
            string argsRet = args;
            int j = args.IndexOf(sheetToken);
            if (j > -1)
            {
                int j1 = args.IndexOf(sheetToken, j + 1);
                if (j1 > -1)
                {
                    sheet = args.Substring(j, j1 - j + 1);
                    args = args.Replace(sheet, string.Empty);
                    i = args.IndexOf(':');
                }
            }

            ////check if column only range
            if (i > 0 && char.IsLetter(args[i - 1]))
            {
                int count = (this.rowMaxCount > 0) ? this.rowMaxCount : 50;
                if (this.grid is ISheetData)
                {
                    count = ((ISheetData)grid).GetLastRow();
                }

                args = args.Substring(0, i) + "1:" + args.Substring(i + 1) + count.ToString();
                i = args.IndexOf(':');
            }
            else if (i > 0 && char.IsDigit(args[i - 1]))
            {
                int k1 = i - 2;
                while (k1 >= 0 && char.IsDigit(args[k1]))
                {
                    k1--;
                }

                if (k1 == -1 || !char.IsLetter(args[k1]))
                {
                    int count = (this.columnMaxCount > 0) ? this.columnMaxCount : 50;
                    if (this.grid is ISheetData)
                    {
                        count = ((ISheetData)grid).GetLastColumn();
                    }
                    args = "A" + args.Substring(0, i) + ":" + RangeInfo.GetAlphaLabel(count) + args.Substring(i + 1);
                    i = args.IndexOf(':');
                }
            }

            // Check Whether rowindex can get from the arguments
            bool isDigit = CanGetRowIndex(args.Substring(0, i));
            if (!isDigit)
            {
                // if unable to get index return the arguments
                ignoreCellValue = true;
                args = argsRet;
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
                return SplitArgsPreservingQuotedCommas(args);
            }
            row1 = this.RowIndex(args.Substring(0, i));
            int row2 = this.RowIndex(args.Substring(i + 1, args.Length - i - 1));
            string[] errorStr = new String[1];
            if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                throw new ArgumentException(this.ErrorStrings[5].ToString());
               // errorStr[0] = this.ErrorStrings[5].ToString();
               // return errorStr;
            }
            if (row1 == -1 && this.grid is ISheetData)
            {
                row1 = ((ISheetData)grid).GetFirstRow();
            }
            col1 = this.ColIndex(args.Substring(0, i));
            if (col1 == -1 && this.grid is ISheetData)
            {
                col1 = ((ISheetData)grid).GetFirstColumn();
            }
            if (row2 == -1 && this.grid is ISheetData)
            {
                row2 = ((ISheetData)grid).GetLastRow();
            }
            int col2 = this.ColIndex(args.Substring(i + 1, args.Length - i - 1));
            if (col2 == -1 && this.grid is ISheetData)
            {
                col2 = ((ISheetData)grid).GetLastColumn();
            }
            if (row1 > row2)
            {
                i = row2;
                row2 = row1;
                row1 = i;
            }

            if (col1 > col2)
            {
                i = col2;
                col2 = col1;
                col1 = i;
            }

            int numCells = (row2 - row1 + 1) * (col2 - col1 + 1);
            string[] cells = new String[numCells];
            int k = 0;
            for (i = row1; i <= row2; ++i)
            {
                for (j = col1; j <= col2; ++j)
                {
                    try
                    {
                        cells[k++] = sheet + RangeInfo.GetAlphaLabel(j) + i.ToString();
                    }
                    catch
                    {
                        continue;
                    }
                }
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return cells;
        }

        /// <summary>
        /// To check whether the row index can be obtained from the arguments
        /// </summary>
        private bool CanGetRowIndex(string s)
        {
            int i = 0;
            bool isLetter = false;
            if (i < s.Length && s[i] == sheetToken)
            {
                i++;
                while (i < s.Length && s[i] != sheetToken)
                {
                    i++;
                }
                i++;
            }

            while (i < s.Length && char.IsLetter(s[i]))
            {
                i++;
            }

            if (i < s.Length)
            {
                if (char.IsDigit(s[i]))
                    return true;
                else
                    return false;
            }
            return false;
        }

        private DateTime GetDateFromSerialDate(int days)
        {
            days -= 1;
            if (Treat1900AsLeapYear && days > 59)
            {
                days -= 1;
            }

            return this.dateTime1900.AddDays(days);
        }

        private double[] GetDoubleArray(string range)
        {
            double d;
            string s1 = string.Empty;
            ArrayList x = new ArrayList();

            this.AdjustRangeArg(ref range);
            string[] ranges = SplitArgsPreservingQuotedCommas(range);
            foreach (string r in ranges)
            {
                ////cell range
                if (r.IndexOf(':') > -1) 
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch 
                        {
                        }
                       
                        ////ignore if empty
                        if (s1.Length > 0) 
                        {
                            if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                            {
                                x.Add(d);
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch
                    {
                    }

                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                        {
                            x.Add(d);
                        }
                    }
                    else
                    {
                        x.Add(0d);
                    }
                }
            }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            return (double[])x.ToArray(typeof(double));
#elif WINDOWS_UWP
            return ListToDouble(x);
#else
            return x.OfType<double>().ToArray();
#endif
        }
