        /// <summary>
        /// Gets the text of any formula at the given row and column of the ICalcData object.
        /// </summary>
        /// <param name="grd">The ICalcData object.</param>
        /// <param name="row">The one-based row in the grd object.</param>
        /// <param name="col">The one-based col in the grd object.</param>
        /// <returns>String containing the text of the formula.</returns>
        /// <remarks>If the data item at row and column is not a formula, the
        /// return value is an empty string.</remarks>
        public string GetFormulaRowCol(ICalcData grd, int row, int col)
        {
            GridSheetFamilyItem family = GetSheetFamilyItem(grd);
            string s = RangeInfo.GetAlphaLabel(col) + row.ToString();
            if (family.SheetNameToParentObject != null)
            {
                string token = family.ParentObjectToToken[grd] as string;
                s = token + s;
            }

            if (this.FormulaInfoTable.ContainsKey(s))
            {
                FormulaInfo formula = this.FormulaInfoTable[s] as FormulaInfo;
                string value = formula.FormulaText;
                this.GetFormulaText(ref value);
                return value;
            }

            return string.Empty;
        }

        /// <summary>
        /// Given a string, it returns a string that is passed through the FormulaParsing event
        /// to allow any listener to modify it.
        /// </summary>
        /// <param name="s">A string that is to be potentially parsed.</param>
        internal void GetFormulaText(ref string s)
        {
            if (this.FormulaParsing != null)
            {
                FormulaParsingEventArgs e = new FormulaParsingEventArgs(s);
                this.FormulaParsing(this, e);
                s = e.Text;
            }
        }

        private int GetSerialDateFromDate(int y, int m, int d)
        {
            int days = 0;
            if (y < 1900)
            {
                y += 1900;
            }

            days = 1 + ((TimeSpan)(new DateTime(y, m, d, 0, 0, 0) - this.dateTime1900)).Days;
            if (Treat1900AsLeapYear && days > 59)
            {
                days += 1;
            }

            return days;
        }

        private double GetSerialDateTimeFromDate(DateTime dt)
        {
            double d = 
#if WINDOWS_UWP
                Syncfusion.XlsIO.Implementation.DateTimeExtension.ToOADate(dt)
#else
                dt.ToOADate() 
#endif
                - this.dateTime1900Double;
            d = 1 + 
#if WINDOWS_UWP
                Syncfusion.XlsIO.Implementation.DateTimeExtension.ToOADate(dt)
#else
                dt.ToOADate() 
#endif
            - this.dateTime1900Double;
            if (Treat1900AsLeapYear && d > 59)
            {
                d += 1;
            }

            return d;
        }

        /// <summary>
        /// Returns the GridSheetFamilyItem for the specified model. If there was no item registered for
        /// the model, a new item is created and cached.
        /// </summary>
        /// <param name="model">The grid model.</param>
        /// <returns>The GridSheetFamilyItem for the specified model.</returns>
        public static GridSheetFamilyItem GetSheetFamilyItem(ICalcData model)
        {
            if (sheetFamilyID == 0)
            {
                if (defaultFamilyItem == null)
                {
                    defaultFamilyItem = new GridSheetFamilyItem();
                }

                return defaultFamilyItem;
            }

            if (sheetFamiliesList == null)
            {
                sheetFamiliesList = new Hashtable();
            }

            int i = (int)modelToSheetID[model];

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            if (sheetFamiliesList[i] == null)
#else
            if(!sheetFamiliesList.ContainsKey(i))
#endif
            {
                sheetFamiliesList.Add(i, new GridSheetFamilyItem());
            }

            return sheetFamiliesList[i] as GridSheetFamilyItem;
        }

        /// <summary>
        /// A method that retrieves the sheetID associated with the given ICalcData object. You can use this method
        /// to retrieve the sheetID required by the PullUpdatedValue method.
        /// </summary>
        /// <param name="grd">The ICalcData object.</param>
        /// <returns>The sheetID.</returns>
        public int GetSheetID(ICalcData grd)
        {
            GridSheetFamilyItem family = GetSheetFamilyItem(grd);
            if (family.SheetNameToParentObject != null)
            {
                string token = family.ParentObjectToToken[grd] as string;
                token = token.Replace("!", string.Empty);
                double d;
                if (double.TryParse(token, NumberStyles.Any, null, out d))
                {
                    return (int)d;
                }
            }

            return -1;
        }

        ////returns the sheet reference if any from the passed in cell or range.
        private string GetSheetTokenFromReference(string r)
        {
            string sheet = string.Empty;
            if (r.Length > 2 && r[0] == sheetToken)
            {
                int i = 1;
                sheet = sheetToken.ToString();
                while (i < r.Length && r[i] != sheetToken)
                {
                    sheet += r[i];
                    i++;
                }

                sheet += sheetToken;
            }

            return sheet;
        }

        /// <summary>
        /// Returns an array of strings from an argument list.
        /// </summary>
        /// <param name="s">A delimited argument list.</param>
        /// <returns>Array of strings from an argument list.</returns>
        public string[] GetStringArray(string s)
        {
#if !(SyncfusionFramework1_0 || SyncfusionFramework1_1)
            System.Collections.Generic.List<string> argList = new System.Collections.Generic.List<string>();
#else
            ArrayList argList = new ArrayList();
#endif
            int argStart = 0;
            bool inQuote = false;
            for (int argEnd = 0; argEnd < s.Length; argEnd++)
            {
                char ch = s[argEnd];
                if (ch == this.TIC[0])
                {
                    inQuote = !inQuote;
                }
                else if (!inQuote && ch == ParseArgumentSeparator)
                {
                    argList.Add(s.Substring(argStart, argEnd - argStart));
                    argStart = argEnd + 1;
                }
            }

            argList.Add(s.Substring(argStart));
            string[] ar = new string[argList.Count];
            argList.CopyTo(ar);
            return ar;
        }

        private string GetValueComputeFormulaIfNecessary(int row, int col, ICalcData grd)
        {
            bool alreadyComputed = false;

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            FormulaInfo formula = this.FormulaInfoTable[cell] as FormulaInfo;
#else
            FormulaInfo formula = this.FormulaInfoTable.ContainsKey(cell) ? this.FormulaInfoTable[cell] as FormulaInfo : null;
#endif
            object o = grd.GetValueRowCol(row, col);
            string val = (o != null && o != string.Empty) ? o.ToString() : string.Empty; ////null; //xx grid[row, col];
            ////GetFormulaText(ref val);
            if (val.EndsWith("}") && val.StartsWith("{"))
            {
                val = val.Substring(1, val.Length - 2);
            }
            if ((val == string.Empty && formula == null) || (val != string.Empty && val[0] != CalcEngine.FormulaCharacter && !val.EndsWith("%")))
            {
                if (formula != null)
                    return formula.FormulaValue;
                else
                    return val;
            }
            if (val.Length > 0 && val[0] == CalcEngine.FormulaCharacter)
            {
                if (formula != null)
                {
                    ////will be set later..
                    //// val = formula.FormulaValue;
                    ////val = ComputeFormula(formula.ParsedFormula);
                }
                else
                {
                    formula = new FormulaInfo();
                    formula.FormulaText = o.ToString();

                    if (!DependentFormulaCells.ContainsKey(cell))
                    {
                        this.DependentFormulaCells.Add(cell, new Hashtable());
                    }

                    bool compute = true;
                    try
                    {
                        formula.ParsedFormula = this.ParseFormula(val);
                    }
                    catch (Exception ex)
                    {
                        if (inAPull)
                        {
                            val = ex.Message;
                            formula = null;
                        }
                        else
                        {
                            formula.FormulaValue = ex.Message;
                        }
                        compute = false;
                    }

                    if (compute)
                    {
                        formula.FormulaValue = this.ComputeFormula(formula.ParsedFormula);
                        alreadyComputed = true;
                    }
                    if (formula != null)
                    {
                        formula.calcID = this.calcID;
                        if(!this.FormulaInfoTable.ContainsKey(this.cell))
                            this.FormulaInfoTable.Add(this.cell, formula);
                        val = formula.FormulaValue != null ? formula.FormulaValue : string.Empty;
                    }
                }
            }

                if (formula != null)
                {
                    if (this.CalculatingSuspended && (!inAPull || alreadyComputed))
                    {
                        val = formula.FormulaValue != null ? formula.FormulaValue : string.Empty;
                    }
                    else if(!alreadyComputed)
                    {
                        if (calcID == formula.calcID)
                        {
                            val = formula.FormulaValue;
                        }
                        else
                        {
                            val = this.ComputeFormula(formula.ParsedFormula);
                            formula.FormulaValue = val;
                            formula.calcID = this.calcID;
                        }
                    }
                    if (treatStringsAsZero && string.IsNullOrEmpty(val))
                    {
                       return "0";
                    }
                }

                if (string.IsNullOrEmpty(val))
                {
                    val = string.Empty;
                }

                if (val.EndsWith("%"))
                {
                    double d;
                    if (double.TryParse(val.Substring(0, val.Length - 1), NumberStyles.Any, null, out d))
                    {
                        val = (d / 100).ToString();
                    }
                }               
            
            return val;
        }

        /// <summary>
        /// A Virtual method to compute the value based on the argument passed in.
        /// </summary>
        /// <remarks>
        /// This method takes the argument and checks whether it is a
        /// parsed formula, a raw number, or a cell reference like A21.
        /// The return value is a string that holds the computed value of
        /// the passed in argument.
        /// </remarks>
        /// <param name="arg">A parsed formula, raw number, or cell reference.</param>
        /// <returns>A string with the computed number in it.</returns>
        public virtual string GetValueFromArg(string arg)
        {
#if _ENABLETIMERS
            string ML = "GetValueFromArg"; MarkTimeStart(ML);
#endif
            double d;
            DateTime tempDate = this.dateTime1900;
            ////handle special characters - probably need to revise...
            ////if(arg.IndexOf("%") > -1)
            ////	Console.WriteLine("special");
            ////arg = arg//.Replace(TRUEVALUESTR, TRUEVALUE.ToString())
            ////		//.Replace(FALSEVALUESTR, FALSEVALUE.ToString())
            ////		.Replace("%", string.Empty);
            if (TextIsEmpty(arg))
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return string.Empty;
            }
            else if (arg[0] == this.TIC[0])
            {
                ////string
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                double doubleValue;
                if (ExcelLikeComputations && UseDatesInCalculations && !double.TryParse(arg.Replace(this.TIC, string.Empty), out doubleValue) && DateTime.TryParse(arg.Replace(this.TIC, string.Empty), CultureInfo.CurrentCulture, DateTimeStyles.None, out tempDate) && this.dateTime1900 <= tempDate)
                {
                    return tempDate.ToOADate().ToString();
                }
                return arg;
            }
            else if (arg[0] == BMARKER || arg[0] == 'q') 
            {
                ////parsed formula
                arg = arg.Replace('{', '(');
                arg = arg.Replace('}', ')');
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return this.ComputedValue(arg);
            }
            else if (arg.Length > 1 && arg.Substring(0, 2) == "ub") 
            {
                ////parsed formula

                arg = arg.Replace('{', '(');
                arg = arg.Replace('}', ')');
                string ggg = arg.Substring(1);
                ggg = this.ComputedValue(ggg);
                double d2 = 0;
                if (double.TryParse(ggg, out d2))
                {
                    d2 = -d2;
                    return d2.ToString();
                }
                return this.ComputedValue(arg);
            }
            else
            {
                if (arg.StartsWith("unu"))
                {
                    arg = "n" + arg.Substring(3);
                }
                else if (arg.StartsWith("un"))
                {
                    arg = "-" + arg.Substring(2);
                }

                arg = arg.Replace('u', '-');
                if (!char.IsUpper(arg[0])
                    && (char.IsDigit(arg[0]) || arg[0] == ParseDecimalSeparator || arg[0] == '-' || arg[0] == 'n'))
                {
                    if (arg[0] == 'n')
                    {
                        arg = arg.Substring(1);
                    }

                    if (double.TryParse(arg, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        return this.GetValueFromArgPreserveLeadingZeros ? arg : d.ToString();
                    }
                    else if (arg.StartsWith(this.TRUEVALUESTR) || arg.StartsWith(FALSEVALUESTR))
                    {
#if _ENABLETIMERS
                        MarkTimeEnd(ML);
#endif
                        return arg;
                    }
                }
            }
            if (ignoreCellValue &&!(arg.StartsWith(this.TRUEVALUESTR) || arg.StartsWith(FALSEVALUESTR)))
            {
                ignoreCellValue = false;
                return arg;
            }

            ////Not a number.
            if ((arg.IndexOfAny(new char[] { '+', '-', '/', '*', ')', ')', '{' }) == -1
                && char.IsUpper(arg[0])) || arg[0] == sheetToken)
            {
                ////Check for circular reference.
                if (arg == this.cell) 
                {
                    ArrayList ht = (ArrayList)DependentCells[arg];
                    if (ht != null && ht.IndexOf(arg) > -1)
                    {
                        ht.Remove(arg);
                    }

                    this.ClearFormulaDependentCells(cell);
                    throw new ArgumentException(this.FormulaErrorStrings[circular_reference_] + arg);
                }

                string s1 = this.GetValueFromParentObject(arg);
                if (arg != this.TRUEVALUESTR && arg != FALSEVALUESTR)
                {
                    if (!GetValueFromArgPreserveLeadingZeros && s1.Length > 0
                        && double.TryParse(s1.Replace(this.TIC, string.Empty), NumberStyles.Any, null, out d))
                    {
                        s1 = d.ToString();
                    }

                    this.UpdateDependencies(arg);
                }
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                if (s1 == this.TIC + this.TIC)
                {
                    return double.NaN.ToString();
                }
                double doubleValue;
                if (ExcelLikeComputations && UseDatesInCalculations && !double.TryParse(s1, out doubleValue) && DateTime.TryParse(s1, CultureInfo.CurrentCulture.DateTimeFormat, DateTimeStyles.None, out tempDate) && this.dateTime1900 <= tempDate)
                {
                    s1 = tempDate.ToOADate().ToString();
                }
                return s1;
               
            }
            ////Must be a formula, so try to parse it and compute.
            arg = arg.Replace('{', '(');
            arg = arg.Replace('}', ')');
            arg = this.Parse(arg);

            if (arg.EndsWith("%") && double.TryParse(arg.Substring(0, arg.Length - 1), NumberStyles.Any, null, out d))
            {
                arg = (d / 100).ToString();
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            if (this.ErrorStrings.Contains(arg))
            {
                return arg;
            }

            return this.ComputedValue(arg);
        }

        /// <summary>
        /// Conditionally gets either the formula value or the cell
        /// value depending upon whether the requested cell is a FormulaCell.
        /// </summary>
        /// <param name="cell1">The alphanumeric cell label, like A1, or EE14.</param>
        /// <returns>String holding either the cell value or the computed formula value.</returns>
        public string GetValueFromParentObject(string cell1)
        {
            if (cell1 == this.TRUEVALUESTR || cell1 == FALSEVALUESTR)
            {
                return cell1;
            }

            int i = cell1.LastIndexOf(sheetToken);
            int row=0, col=0;
            ICalcData grd = this.grid;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            if (i > -1 && family.TokenToParentObject != null)
            {
                this.grid = (ICalcData)family.TokenToParentObject[cell1.Substring(0, i + 1)];
                row = this.RowIndex(cell1);
                if (row == -1 && this.grid is ISheetData)
                {
                    row = ((ISheetData)grid).GetFirstRow();
                }
                col = this.ColIndex(cell1);
                if (col == -1 && this.grid is ISheetData)
                {
                    col = ((ISheetData)grid).GetFirstColumn();
                }
            }
            else if (i == -1)
            {
                int j = 0;
                while (j < cell1.Length && char.IsLetter(cell1[j]))
                {
                    j++;
                }
                if (j == cell1.Length)
                {
                    cell1 = cell1.ToLower(CultureInfo.InvariantCulture);
                    return cell1;
                }
                else
                {
                    row = this.RowIndex(cell1);
                    if (row == -1 && this.grid is ISheetData)
                    {
                        row = ((ISheetData)grid).GetFirstRow();
                    }
                    col = this.ColIndex(cell1);
                    if (col == -1 && this.grid is ISheetData)
                    {
                        col = ((ISheetData)grid).GetFirstColumn();
                    }
                    if (this.IsSheeted && family.ParentObjectToToken != null)
                    {
                        cell1 = family.ParentObjectToToken[grid] + cell1;
                    }
                }
            }

            string saveCell = this.cell;
            this.cell = cell1;

            if (this.iterationMaxCount > 0)
            {
                if (this.circCheckList.IndexOf(this.cell) > -1 && computedValueLevel > 0)
                {
                    this.grid = grd;
                    this.cell = saveCell;

                    if (!IterationValues.ContainsKey(this.cell))
                    {
                        this.IterationValues.Add(cell, "0");
                    }

                    return this.IterationValues[cell].ToString();
                }
                else if (this.IterationValues.ContainsKey(this.cell) && computedValueLevel > 0)
                {
                    return this.IterationValues[cell].ToString();
                }
            }

            string val = this.GetValueComputeFormulaIfNecessary(row, col, grid);

            this.grid = grd;
            this.cell = saveCell;
            return val;
        }

        /// <summary>
        /// Conditionally gets either the formula value or the cell
        /// value depending upon whether the requested cell is a FormulaCell.
        /// </summary>
        /// <param name="grd">The ICalcData object holding the requested cell.</param>
        /// <param name="row">Row index of the requested cell.</param>
        /// <param name="col">Column index of the requested cell.</param>
        /// <returns>String holding either the cell value or the computed formula value.</returns>
        public string GetValueFromParentObject(ICalcData grd, int row, int col)
        {
            GridSheetFamilyItem family = GetSheetFamilyItem(grd);
            string cell1 = (family.ParentObjectToToken == null) ? string.Empty : family.ParentObjectToToken[grd].ToString();
            cell1 = cell1 + RangeInfo.GetAlphaLabel(col) + row.ToString();

            ICalcData saveGrid = this.grid;
            string saveCell = this.cell;
            this.cell = cell1;
            this.grid = grd;

            string val = this.GetValueComputeFormulaIfNecessary(row, col, grd);
            DateTime tempDate;
            double doubleValue;
            if (ExcelLikeComputations && UseDatesInCalculations && !double.TryParse(val, out doubleValue) && DateTime.TryParse(val, CultureInfo.CurrentCulture, DateTimeStyles.None, out tempDate) && this.dateTime1900 <= tempDate)
            {
                val = tempDate.ToOADate().ToString();
            }
            this.grid = saveGrid;
            this.cell = saveCell;
            return val;
        }

        /// <summary>
        /// Conditionally gets either the formula value or the cell
        /// value depending upon whether the requested cell is a FormulaCell.
        /// </summary>
        /// <param name="row">Row index of the requested cell.</param>
        /// <param name="col">Column index of the requested cell.</param>
        /// <returns>String holding either the cell value or the computed formula value.</returns>
        public string GetValueFromParentObject(int row, int col)
        {
            return this.GetValueComputeFormulaIfNecessary(row, col, grid);
        }

        internal void grid_ValueChanged(object sender, ValueChangedEventArgs e)
        {
            if (this.IgnoreValueChanged)
            {
                return;
            }

            ICalcData grd = sender as ICalcData;
            this.grid = sender as ICalcData;

            bool computedValueChanged = true;

            GridSheetFamilyItem family = GetSheetFamilyItem(grd);
            string s = RangeInfo.GetAlphaLabel(e.ColIndex) + e.RowIndex.ToString();
            if (family.SheetNameToParentObject != null && family.SheetNameToParentObject.Count > 0)
            {
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                string token = family.ParentObjectToToken[grd] as string;
#else
                string token = string.Empty;
                object tokenInstance = null;
                family.ParentObjectToToken.TryGetValue(grid, out tokenInstance);
                if (tokenInstance != null)
                {
                    token = tokenInstance.ToString();
                }
#endif
                s = token + s;
            }

            if (e.Value.Length > 0 && e.Value[0] == CalcEngine.FormulaCharacter)
            {
                this.cell = s;
                FormulaInfo formula;
                bool compute = true;
                if (this.FormulaInfoTable.ContainsKey(s))
                {
                    formula = this.FormulaInfoTable[s] as FormulaInfo;
                    if (e.Value != formula.FormulaText || formula.ParsedFormula == null)
                    {
                        formula.FormulaText = e.Value;
                        this.ClearFormulaDependentCells(this.cell);
                        try
                        {
                            formula.ParsedFormula = this.ParseFormula(e.Value);
                        }
                        catch (Exception ex)
                        {
                            formula.FormulaValue = ex.Message;
                            compute = false;
                        }
                    }

                    if (compute)
                    {
                        string s1 = this.ComputeFormula(formula.ParsedFormula);

                        computedValueChanged = (s1 != formula.FormulaValue) || this.forceRefreshCall;

                        formula.FormulaValue = s1;
                    }

                    formula.calcID = this.calcID;
                }
                else
                {
                    formula = new FormulaInfo();
                    formula.FormulaText = e.Value;
                    if (!DependentFormulaCells.ContainsKey(s))
                    {
                        this.DependentFormulaCells.Add(s, new Hashtable());
                    }

                    try
                    {
                        formula.ParsedFormula = this.ParseFormula(e.Value);
                    }
                    catch (Exception ex)
                    {
                        formula.FormulaValue = ex.Message;
                        compute = false;
                    }

                    if (compute)
                    {
                        formula.FormulaValue = this.ComputeFormula(formula.ParsedFormula);
                    }

                    formula.calcID = this.calcID;

                    if (this.FormulaInfoTable.ContainsKey(s))
                    {
                        this.FormulaInfoTable[s] = formula;
                    }
                    else
                    {
                        this.FormulaInfoTable.Add(s, formula);
                    }
                }

                if (this.iterationMaxCount > 0 && compute && !inHandleIterations)
                {
                    if (s == this.cell)
                    {
                        this.HandleIterations(formula);
                    }
                }

                bool saveIVC = this.IgnoreValueChanged;
                this.IgnoreValueChanged = true;
                grd.SetValueRowCol(formula.FormulaValue, e.RowIndex, e.ColIndex);
                if (formula != null && string.IsNullOrEmpty(formula.FormulaValue) && e.Value.StartsWith(CalcEngine.FormulaCharacter.ToString()))
                {
                    this.grid.SetValueRowCol(formula.FormulaText, e.RowIndex, e.ColIndex);
                }
                this.IgnoreValueChanged = saveIVC;
            }
            else if (!inRecalculateRange && this.FormulaInfoTable.ContainsKey(s))
            {
                this.FormulaInfoTable.Remove(s);
                this.ClearFormulaDependentCells(s);
            }

            if (computedValueChanged && this.DependentCells.ContainsKey(s))
            {
                this.dependencyLevel = 0;
                this.Refresh(s);
            }
        }

        public string HandleIteration(string s, FormulaInfo formula)
        {
            if (this.FormulaInfoTable.ContainsKey(s))
            {
                this.FormulaInfoTable[s] = formula;
            }
            else
            {
                this.FormulaInfoTable.Add(s, formula);
            }
            if (this.iterationMaxCount > 0)
            {
                if (s == this.cell)
                {
                    this.HandleIterations(formula);
                }
            }
            return formula.FormulaValue;
        }

        private string HandleEmbeddedEs(string text)
        {
            int j = 0;
            while (j > -1 && ((j = text.IndexOf(this.STRING_EP, j)) > -1))
            {
                if (this.NotInBlock(text, j))
                {
                    int left = j;
                    while (left > 0 && (char.IsDigit(text[left - 1]) || text[left - 1] == ParseDecimalSeparator))
                    {
                        left--;
                    }

                    if (left != j && (left == 0 || !char.IsUpper(text[left - 1])))
                    {
                        int right = j + this.STRING_EP.Length;
                        while (right < text.Length && char.IsDigit(text[right]))
                        {
                            right++;
                        }

                        if (right != j + this.STRING_EP.Length)
                        {
                            text = text.Substring(0, j) + this.CHAR_EP + text.Substring(j + STRING_EP.Length);
                        }
                    }
                }

                j += 1;
            }

            j = 0;
            while (j > -1 && ((j = text.IndexOf(this.STRING_EM, j)) > -1))
            {
                if (this.NotInBlock(text, j))
                {
                    int left = j;
                    while (left > 0 && (char.IsDigit(text[left - 1]) || text[left - 1] == ParseDecimalSeparator))
                    {
                        left--;
                    }

                    if (left != j && (left == 0 || !char.IsUpper(text[left - 1])))
                    {
                        int right = j + this.STRING_EM.Length;
                        while (right < text.Length && char.IsDigit(text[right]))
                        {
                            right++;
                        }

                        if (right != j + this.STRING_EM.Length)
                        {
                            text = text.Substring(0, j) + this.CHAR_EM + text.Substring(j + STRING_EM.Length);
                        }
                    }
                }

                j += 1;
            }

            j = 0;

            ////only look for single e's if expression has not been parsed
            while (j > -1 && ((j = text.IndexOf(this.STRING_E, j)) > -1)
                    && text[0] != BMARKER)
            {
                if (this.NotInBlock(text, j))
                {
                    int left = j;
                    while (left > 0 && (char.IsDigit(text[left - 1]) || text[left - 1] == ParseDecimalSeparator))
                    {
                        left--;
                    }

                    if (left != j && (left == 0 || !char.IsUpper(text[left - 1])))
                    {
                        int right = j + this.STRING_E.Length;
                        while (right < text.Length && char.IsDigit(text[right]))
                        {
                            right++;
                        }

                        if (right != j + this.STRING_E.Length && (left == -1 || !char.IsUpper(text[left])))
                        {
                            text = text.Substring(0, j) + this.CHAR_EP + text.Substring(j + STRING_E.Length);
                        }
                    }
                }

                j += 1;
            }

            return text;
        }

        private string HandleEmbeddedIf(string formula)
        {
            int sep1 = this.IFMarker.Length;
            int sep2 = sep1 + 1;
            double d = 0;

            if (EnsureIFCallDuringShortCircuit)
            {
                if (this.FindNextSeparator(formula, ref sep1))
                {
                    sep2 = sep1 + 1;
                    FindRightBracket(formula, ref sep2);
                    if (sep2 > -1)
                    {
                        LibraryFunction func = (LibraryFunction)this.LibraryFunctions["IF"];
                        if (func != null)
                        {
                            string args = formula.Substring(this.IFMarker.Length, sep2 - this.IFMarker.Length);
                            int embeddedIF = args.IndexOf(this.IFMarker);
                            while (embeddedIF > -1)
                            {
                                int loc = this.MatchingRightBracket(args.Substring(embeddedIF));
                                if (loc > -1)
                                {
                                    args = args.Substring(0, embeddedIF) + this.HandleEmbeddedIf(args.Substring(embeddedIF)) + args.Substring(embeddedIF + loc + 1);
                                }
                                embeddedIF = args.IndexOf(this.IFMarker);
                            }

                            ////check to see if there is a Function call in the if test clause
                            //int locq = args.IndexOf('q');
                            //int loc4 = args.IndexOf(ParseArgumentSeparator);
                            //if (locq > -1 && locq < loc4)
                            //{
                            //    this.FindNextSeparator(args, ref locq);
                            //    string gg = args.Substring(0, locq);
                            //    gg = this.ComputeInteriorFunctions(gg);
                            //    args = gg + args.Substring(locq);
                            //}
                            string result = func(args);
                            if (double.TryParse(result, out d))
                            {
                                if (d < 0)
                                {
                                    result = "nu" + (-d).ToString();
                                }
                                else
                                {
                                    result = "n" + d.ToString();
                                }
                            }
                            formula = result;
                        }
                    }
                }
                return formula;
            }

            if (this.FindNextSeparator(formula, ref sep1))
            {
                sep2 = sep1 + 1;
                if (!FindNextSeparator(formula, ref sep2))
                {
                    sep2 = formula.IndexOf(this.RIGHTBRACKET, sep1);
                    if (sep2 > -1)
                    {
                        formula = formula.Substring(0, sep2) + ParseArgumentSeparator + this.FALSEVALUESTR + formula.Substring(sep2);
                    }
                }

                string ifValue = this.ComputedValue(formula.Substring(IFMarker.Length, sep1 - IFMarker.Length));
                if (ifValue == this.TRUEVALUESTR ||
                    (double.TryParse(ifValue, NumberStyles.Any, null, out d) && d != 0))
                {
                    formula = formula.Substring(sep1 + 1, sep2 - sep1 - 1);
                }
                else
                {
                    int rightBracket = sep2 + 1;
                    if (this.FindRightBracket(formula, ref rightBracket))
                    {
                        formula = formula.Substring(sep2 + 1, rightBracket - sep2 - 1);
                    }
                }

                if (double.TryParse(formula, out d))
                {
                    if (d < 0)
                    {
                        formula = "nu" + (-d).ToString();
                    }
                    else
                    {
                        formula = "n" + d.ToString();
                    }
                }
            }

            return formula;
        }

        private void HandleIterations(FormulaInfo formula)
        {
            this.inHandleIterations = true;
            double oldValue = 0;
            double d = 0;
            int count = 1;
            bool first = true;
            while (count < this.iterationMaxCount - 1 && (first || !CheckUnderTolerance(d, oldValue)))
            {
                first = false;
                if (!IterationValues.ContainsKey(this.cell))
                {
                    this.IterationValues.Add(cell, "0");
                }

                this.IterationValues[this.cell] = formula.FormulaValue == string.Empty  ? "0" : formula.FormulaValue;

                formula.FormulaValue = this.ComputeFormula(formula.ParsedFormula);
                oldValue = d;
                double.TryParse(formula.FormulaValue, NumberStyles.Any, null, out d);
                count++;
            }

            ////save the last iteration
            this.IterationValues[this.cell] = formula.FormulaValue == string.Empty ? "0" : formula.FormulaValue;

            this.inHandleIterations = false;
        }

        private void HandleSheetRanges(ref string text, GridSheetFamilyItem family)
        {
            int sheetLoc = text.IndexOf(sheetToken);
            int start = 0;
            while (sheetLoc > 0)
            {
                int colonLoc = text.Substring(start, sheetLoc).LastIndexOf(':');
                if (colonLoc > -1)
                {
                    string rightSide = text.Substring(start + colonLoc + 1, sheetLoc - colonLoc - 1).ToUpper().Replace("'", string.Empty);
                    if (family.SheetNameToToken.ContainsKey(rightSide.Trim()))
                    {
                        int leftStart = start + colonLoc - 1;
                        if (SortedSheetNames.Contains(rightSide))
                        {
                            leftStart = leftStart - rightSide.Length - 1;
                        }
                        else
                        {
                            while (leftStart > 0 && this.markers.IndexOf(text[leftStart]) == -1)
                            {
                                leftStart--;
                            }
                        }

                        string leftSide = text.Substring(leftStart + 1, colonLoc - leftStart + start - 1).ToUpper().Replace("'", string.Empty);

                        if (family.SheetNameToToken.ContainsKey(leftSide.Trim()))
                        {
                            int rightEnd = sheetLoc + start + 1;
                            if (SortedSheetNames.Contains(leftSide.Trim()))
                            {
                                rightEnd = text.Length - 1;
                            }
                            else
                            {
                                while (rightEnd < text.Length && this.markers.IndexOf(text[rightEnd]) == -1)
                                {
                                    rightEnd++;
                                }
                            }

                            string otherSide = text.Substring(start + sheetLoc + 1, rightEnd - start - sheetLoc - 1);
                            string left = family.SheetNameToToken[leftSide.Trim()].ToString();
                            string right = family.SheetNameToToken[rightSide.Trim()].ToString();
                            ////make sure they are ordered properly
                            if (right.CompareTo(left) == -1) 
                            {
                                string s = left;
                                left = right;
                                right = s;
                            }

                            string replacement = string.Empty;
                            ////family.SheetNameToToken.Keys)
                            foreach (string name in this.SortedSheetNames) 
                            {
                                string s = family.SheetNameToToken[name].ToString(); 
                                int sint = int.Parse(s.Replace("!", string.Empty));
                                int leftint = int.Parse(left.Replace("!", string.Empty));
                                int rightint = int.Parse(right.Replace("!", string.Empty));
                                if (sint.CompareTo(leftint) >= 0 && sint.CompareTo(rightint) <= 0)
                                {
                                    if (replacement.Length > 0)
                                    {
                                        replacement += ParseArgumentSeparator;
                                    }

                                    replacement += name + (char)131 + otherSide;
                                }
                            }

                            text = text.Substring(0, leftStart + 1) + replacement + text.Substring(rightEnd);
                            start = text.Length - rightEnd;
                        }
                        else
                        {
                            start = sheetLoc + start;
                        }
                    }
                    else
                    {
                        start = sheetLoc + start;
                    }
                }
                else
                {
                    start = sheetLoc + start;
                }

                sheetLoc = text.Substring(start + 1).IndexOf(sheetToken) + 1;
            }

            text = text.Replace((char)131, sheetToken);
        }

