        /// <summary>
        /// Determines whether the arg is a valid cell name.
        /// </summary>
        /// <param name="args">Cell name.</param>
        /// <returns>True is the arg is a valid cell name, false otherwise.</returns>
        bool IsCellReference(string args)
        {
            this.PutTokensForSheets(ref args);
            string sheetToken = this.SheetToken(args);
            bool containsBoth = false;
            if (!String.IsNullOrEmpty(sheetToken))
            {
                args = args.Replace(sheetToken, string.Empty);
            }

            bool isAlpha = false, isNum = false;
            if (args.IndexOf(':') != args.LastIndexOf(':'))
            {
                return false;
            }

            foreach (char c in args.ToCharArray())
            {
                if (char.IsLetter(c))
                {
                    isAlpha = true;
                }

                if (char.IsDigit(c))
                {
                    isNum = true;
                }

                if (char.Equals(c, ':'))
                {
                    if (isAlpha && isNum)
                    {
                        containsBoth = true;
                    }
                    isAlpha = false;
                    isNum = false;
                }
            }
            if (args.Contains(":") && !args.Contains(this.TIC))
            {
                if (containsBoth && isAlpha && isNum)
                    return true;
                else if (((isAlpha && !isNum) || (!isAlpha && isNum)) && !containsBoth)
                {
                    return true;
                }
                else
                    return false;
            }
            if (isAlpha && isNum && !args.Contains(this.TIC))
            {
                return true;
            }

            return false;
        }

        private bool IsDate(object o, out DateTime date)
        {
            bool result = true;
            date = this.dateTime1900;
#if SyncfusionFramework2_0
            result = DateTime.TryParse(o.ToString(), out date) && date >= this.dateTime1900;
#else
            double d;
            try
            {
                if (DateTime.TryParse(o.ToString(), out date))
                {
                    result = date >= dateTime1900;
                }
                else if (double.TryParse(o.ToString(), out d))
                {
                    date = Convert.ToDateTime(d);
                    result = date >= dateTime1900;
                }
                else
                {
                    try
                    {
                        if (this.ComputeIsText(o.ToString()).Equals(this.TRUEVALUESTR))
                        {
                            date = Convert.ToDateTime(o);
                            result = date >= dateTime1900;
                        }
                        else
                        {
                            result = false;
                        }
                    }
                    catch
                    {
                        date = Convert.ToDateTime(o);
                        result = date >= dateTime1900;
                    }
                }

            }
            catch
            {
                result = false;
            }
#endif
            return result;
        }

        private bool IsEqual(double d1, double d2)
        {
            return Math.Abs(d1 - d2) < this.ABSOLUTEZERO;
        }

        private bool IsRange(string range)
        {   
            ////checks if range holds a stand-alone range. Used to id when user inputs
            ////a formula that is just a range. Part of the support for using ranges as
            ////operands of binary operators. This method allows a range to be used with
            ////the formula assignment operator, =
            bool isRange = false;
            int i = range.IndexOf(':');
            if (i > 1 && i < range.Length - 2)
            {
                ////check left side
                int j = i - 1;

                if (char.IsDigit(range[j]))
                { 
                    //// left side must end in digit
                    bool needToCheckRightSide = false;
                    j--;
                    while (j > 0 && char.IsDigit(range[j]))
                    {
                        j--;
                    }

                    if (char.IsLetter(range[j]))
                    { 
                        ////letters must come now
                        j--;
                        while (j >= 0 && char.IsLetter(range[j]))
                        {
                            j--;
                        }

                        if (j > -1 && range[j] == STRING_fixedreference[0])
                        {
                            j--;
                        }

                        if (j < 0)
                        {
                            needToCheckRightSide = true; ////might have a range
                        }
                        else
                        {
                            if (range[j] == sheetToken)
                            {
                                if (j-- > 1 && range[j] == this.CHARTIC)
                                {
                                    needToCheckRightSide = range.Substring(0, j - 1).LastIndexOf(this.CHARTIC) == 0;
                                }
                                else if (j > 0 && char.IsDigit(range[j]))
                                {
                                    needToCheckRightSide = range.Substring(0, j).LastIndexOf(sheetToken) == 0;
                                }
                            }
                        }
                    }

                    if (needToCheckRightSide)
                    {
                        ////check right side
                        j = i + 1;

                        ////handle possible sheetnames
                        if (j < range.Length - 6 && range[j] == this.CHARTIC)
                        {
                            j = range.IndexOf(sheetToken, j + 1);
                            if (j < range.Length - 2)
                            {
                                j++;
                            }
                        }

                        if (j < range.Length - 2 && range[j] == STRING_fixedreference[0])
                        {
                            j++;
                        }

                        if (char.IsLetter(range[j]))
                        {
                            j++;
                            while (j < range.Length - 1 && char.IsLetter(range[j]))
                            {
                                j++;
                            }

                            if (char.IsDigit(range[j]))
                            {
                                j++;
                                while (j < range.Length && char.IsDigit(range[j]))
                                {
                                    j++;
                                }

                                isRange = j == range.Length;
                            }
                        }
                    }
                }
            }

            return isRange;
        }

        /// <summary>
        /// Returns True if the ParseArgumentSeparator character is included in a string.
        /// </summary>
        /// <param name="s">The string to be searched.</param>
        /// <returns>True or False.</returns>
        public bool IsSeparatorInTIC(string s)
        {
            int i = s.IndexOf(this.TIC) + 1;
            bool inTic = true;
            while (i > 0 && i < s.Length)
            {
                if (s[i] == ParseArgumentSeparator && inTic)
                {
                    return true;
                }

                if (s[i] == this.TIC[0])
                {
                    inTic = !inTic;
                }

                i++;
            }

            return false;
        }

        private void Mark(ref string copy, ref string text, string op, char token, bool checkPrecedingChar)
        {
            int loc = 0;
            loc = checkPrecedingChar ? this.FindAndCheckPrecedingChar(ref copy, op, loc) : copy.IndexOf(op);
            int len = op.Length; ////the -1 allows the trailing blank on the op to be kept to handle things like 2 or not 3
            while (loc > -1)
            {
                copy = copy.Substring(0, loc) + token + copy.Substring(loc + len);
                text = text.Substring(0, loc) + token + text.Substring(loc + len);
                loc = checkPrecedingChar ? this.FindAndCheckPrecedingChar(ref copy, op, loc) : copy.IndexOf(op, loc);
            }
        }

        private void MarkColonsInQuotes(ref string args)
        {
            bool inQuotes = false;
            for (int i = 0; i < args.Length; ++i)
            {
                if (args[i] == this.TIC[0])
                {
                    inQuotes = !inQuotes;
                }
                else if (args[i] == ':' && inQuotes)
                {
                    args = args.Replace(':', this.MarkerChar);
                }
            }
        }

        private void MarkIF(ref string copy, ref string text)
        {
            int locIF = copy.IndexOf(this.ReservedWordOperators[reservedWord_IF]);
            int locTHEN = copy.IndexOf(this.ReservedWordOperators[reservedWord_THEN]);
            int locELSE = copy.IndexOf(this.ReservedWordOperators[reservedWord_ELSE]);

            if (locELSE > -1 && locTHEN > -1)
            {
                int ifStart = this.ReservedWordOperators[reservedWord_IF].Length;
                int ifLength = locTHEN - ifStart;
                int thenStart = locTHEN + this.ReservedWordOperators[reservedWord_THEN].Length;
                int thenLength = locELSE - thenStart;
                int elseStart = locELSE + this.ReservedWordOperators[reservedWord_ELSE].Length;
                int elseLength = text.Length - elseStart;
                text = string.Format(
                    "IF(({0}){3}({1}){3}({2}))", 
                    text.Substring(ifStart, ifLength),
                    text.Substring(thenStart, thenLength),
                    text.Substring(elseStart, elseLength), 
                    ParseArgumentSeparator);
                copy = string.Format(
                    "IF(({0}){3}({1}){3}({2}))",
                    copy.Substring(ifStart, ifLength),
                    copy.Substring(thenStart, thenLength),
                    copy.Substring(elseStart, elseLength),
                    ParseArgumentSeparator);
            }
            else if (locTHEN > -1)
            {
                int ifStart = 0;
                int ifLength = locTHEN;
                int thenStart = locTHEN + this.ReservedWordOperators[reservedWord_THEN].Length;
                int thenLength = text.Length - thenStart + 1;
                text = string.Format(
                    "IF(({0}){2}({1}))", 
                    text.Substring(ifStart, ifLength),
                    text.Substring(thenStart, thenLength),
                    ParseArgumentSeparator);
                copy = string.Format(
                    "IF(({0}){2}({1}))",
                    copy.Substring(ifStart, ifLength),
                    copy.Substring(thenStart, thenLength), 
                    ParseArgumentSeparator);
            }
        }

        /// <summary>
        /// Tokenizes all library references.
        /// </summary>
        /// <remarks>
        /// Accepts a string such as Sin(A1+A2) and tokenizes it into
        /// bqSIN[A1A2a]b which serves as input to ComputedValue.
        /// </remarks>
        /// <param name="formula">Formula to be tokenized.</param>
        private void MarkLibraryFormulas(ref string formula)
        {
            int rightParens = formula.IndexOf(')');
            if (rightParens == -1)
            {
                this.MarkNamedRanges(ref formula);
            }
            else
            {
                while (rightParens > -1)
                {
                    int parenCount = 0;
                    int leftParens = rightParens - 1;
                    while (leftParens > -1 && (formula[leftParens] != '(' || parenCount != 0))
                    {
                        if (formula[leftParens] == ')')
                        {
                            parenCount++;
                        }
                        else if (formula[leftParens] == ')')
                        {
                            parenCount--;
                        }

                        leftParens--;
                    }

                    if (leftParens == -1)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[mismatched_parentheses]);
                    }

                    int i = leftParens - 1;
                    while (i > -1 && (char.IsLetterOrDigit(formula[i]) || this.validFunctionNameChars.IndexOf(formula[i]) > -1 || formula[i].Equals(parseDecimalSeparator)))
                    {
                        i--;
                    }

                    int len = leftParens - i - 1;
                    if (len > 0 && this.LibraryFunctions[formula.Substring(i + 1, len)] != null)
                    {
                        if (formula.Substring(i + 1, len) == "AREAS")
                            ignoreBracet = true;
                        else
                            ignoreBracet = false;
                        string s = formula.Substring(leftParens, rightParens - leftParens + 1);
                        this.MarkNamedRanges(ref s);
                        formula = formula.Substring(0, i + 1) + 'q' + formula.Substring(i + 1, len) + s.Replace('(', this.LEFTBRACKET).Replace(')', RIGHTBRACKET) + formula.Substring(rightParens + 1);
                    }
                    else if (len > 0)
                    {
                        if (UnknownFunction != null)
                        {
                            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
                            ICalcData grd = this.grid;
                            string sheet = this.SheetToken(cell);
                            string s = cell;
                            if (sheet.Length > 0)
                            {
                                grd = family.TokenToParentObject[sheet] as ICalcData;
                                s = s.Substring(s.LastIndexOf(sheetToken) + 1);
                            }
                             

                            foreach (string key in family.SheetNameToParentObject.Keys)
                            {
                                if (family.SheetNameToParentObject[key].Equals(grd))
                                {
                                    s = key + sheetToken + s;
                                    break;
                                }
                            }

                            UnknownFunctionEventArgs args = new UnknownFunctionEventArgs();
                            args.MissingFunctionName = formula.Substring(i + 1, len);
                            args.CellLocation = s ;
                        
                            UnknownFunction(this, args);
                            if (formula.Substring(i + 1, len) == "AREAS")
                                ignoreBracet = true;
                            else
                                ignoreBracet = false;
                        }
                        throw new ArgumentException(this.FormulaErrorStrings[unknown_formula_name] + " " + formula.Substring(i + 1, len));
                    }
                    else
                    {
                        string s = string.Empty;
                        if (leftParens > 0)
                        {
                            s = formula.Substring(0, leftParens);
                        }

                        s = s + '{' +
                            formula.Substring(leftParens + 1, rightParens - leftParens - 1) + '}';
                        if (rightParens < formula.Length)
                        {
                            s = s + formula.Substring(rightParens + 1);
                        }

                        this.MarkNamedRanges(ref s);
                        formula = s;
                    }

                    rightParens = formula.IndexOf(')');
                }
            }

            formula = formula.Replace('{', '(').Replace('}', ')');
        }

        /// <summary>
        /// Replaces NamedRanges with their values.
        /// </summary>
        /// <remarks>
        /// Accepts a string such as Sin(SumRange) and tokenizes it into
        /// bqSIN[A1A4a]b which serves as input to ComputedValue.
        /// </remarks>
        /// <param name="argList">argList containing named ranges.</param>
        private void MarkNamedRanges(ref string argList)
        {
            ////Console.WriteLine("MarkNamedRanges in#{0}#", argList);
            int rightParens = argList.IndexOf(')');
            char[] markers = new char[] { ')', ParseArgumentSeparator, '}', '+', '-', '*', '/', '<', '>', '=', '&' };

            //  int i = (argList.Length > 0 && argList[0] == '(')
            int i = (argList.Length > 0 && (argList[0] == '(' || argList[0] == '{')) //cb
                        ? 1 : 0; ////start of args
            if (argList.IndexOf("#N/A") > -1)
            {
                argList = argList.Replace("#N/A", "#N~A");
            }
            if (argList.IndexOf("#DIV/0!") > -1)
            {
                argList = argList.Replace("#DIV/0!", "#DIV~0!");
            }
            int end = argList.Substring(i).IndexOfAny(markers);

            while (end > -1 && end + i < argList.Length)
            {
                string scopedRange = string.Empty;
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                string s = (string)this.NamedRanges[argList.Substring(i, end)];
#else
                string s = null;// string.Empty;
                object result = null;
                this.NamedRanges.TryGetValue(argList.Substring(i, end), out result);
                if (result != null)
                {
                    s = result.ToString();
                }
#endif
                if (s == null)
                {
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    if (CheckIfScopedRange(argList.Substring(i, end), out scopedRange))
                    {
                        s = scopedRange;
                    }
                    else if (argList.Substring(i, end).StartsWith(sheetToken.ToString()))
                    {
                        int iii = argList.Substring(i, end).IndexOf(sheetToken, 1);
                        if (iii > 1)
                        {
                            s = (string)this.NamedRanges[argList.Substring(i).Substring(iii + 1, end - iii - 1)];
                        }
                    }
#else
                    if (CheckIfScopedRange(argList.Substring(i, end), out scopedRange))
                    {
                    s = scopedRange;// string.Empty;
                    //object result = null;
                    //this.namedRangesNonScoped.TryGetValue(argList.Substring(i, end), out result);
                    //if (result != null)
                    //{
                    //    s = result.ToString();
                    //}
                    }
#endif
                }
                if (s != null)
                {
                    s = s.ToUpper();
                    this.PutTokensForSheets(ref s);
                    this.MarkLibraryFormulas(ref s); ////recursive call
                }

                if (s != null)
                {
                    argList = argList.Substring(0, i) + s + argList.Substring(i + end);
                    i += s.Length + 1;
                }
                else
                {
                    i += end + 1;
                    while (i < argList.Length && !char.IsUpper(argList[i]) && argList[i] != sheetToken)
                    {
                        i++;
                    }
                }

                end = argList.Substring(i).IndexOfAny(markers);
                while (end == 0 && i < argList.Length - 1)
                {
                    i++;
                    end = argList.Substring(i).IndexOfAny(markers);
                }

                if (end == -1 && i < argList.Length)
                {
                    ////check last part of arglist
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
                    s = this.NamedRanges.Count > 0 ? (string)this.NamedRanges[argList.Substring(i)] : s;
#else
                object resultValue;
                if (this.NamedRanges.Count > 0)
                {
                    if (this.NamedRanges.TryGetValue(argList.Substring(i), out resultValue))
                        s = resultValue.ToString();
                    else
                        s = null;
                }
#endif
                    if (s == null)
                    {
                        if(CheckIfScopedRange(argList.Substring(i), out scopedRange))
                            s = scopedRange;
                    }
                    if (s != null)
                    {
                        s = s.ToUpper();
                        this.PutTokensForSheets(ref s);
                        this.MarkLibraryFormulas(ref s);
                        if (s != null)
                        {
                            argList = argList.Substring(0, i) + s; //// +argList.Substring(i + end);
                            i += s.ToString().Length + 1;
                        }
                    }

                    end = (i < argList.Length) ? argList.Substring(i).IndexOfAny(markers) : -1;
                }
            }
            if (argList.IndexOf("#N~A") > -1)
            {
                argList = argList.Replace("#N~A", "#N/A");
            }

            if (argList.IndexOf("#DIV~0!") > -1)
            {
                argList = argList.Replace("#DIV~0!", "#DIV/0!");
            }
        }

        private void MarkReserveWords(ref string text)
        {
            string copy = text.ToLower();
            if (copy.TrimStart().StartsWith(this.ReservedWordOperators[reservedWord_IF]))
            {
                this.MarkIF(ref copy, ref text);
            }

            this.Mark(ref copy, ref text, ReservedWordOperators[reservedWord_NOT], CHAR_NOTop, true);
            this.Mark(ref copy, ref text, ReservedWordOperators[reservedWord_OR], CHAR_ORop, false);
            this.Mark(ref copy, ref text, ReservedWordOperators[reservedWord_AND], CHAR_ANDop, false);
            this.Mark(ref copy, ref text, ReservedWordOperators[reservedWord_XOR], CHAR_XORop, false);
        }

        private int matchCompare(object o1, object o2)
        {
            string s1 = o1.ToString();
            string s2 = o2.ToString();
            double d1, d2;
            if (double.TryParse(s1, NumberStyles.Any, null, out d1)
                && double.TryParse(s2, NumberStyles.Any, null, out d2))
            {
                return d1.CompareTo(d2);
            }
            else
            {
                return s1.CompareTo(s2);
            }
        }

        private int MatchingRightBracket(string formula)
        {
            int ret = -1;
            int loc = 1;
            int bracketLevel = 0;
            string token = this.SheetToken(formula);
            while (ret == -1 && loc < formula.Length)
            {
                if (formula[loc] == this.RIGHTBRACKET)
                {
                    if (bracketLevel == 0)
                    {
                        ret = loc;
                    }
                    else
                    {
                        bracketLevel--;
                        if (bracketLevel == 0 && loc == formula.Length - 1)
                        {
                            ret = loc;
                        }
                    }
                }
                else if(formula[loc] == 'q')
                {
                    int val = loc + 1;
                    if (val < formula.Length)
                    {
                        string libFunc = this.ProcessUpperCase(ref formula, ref val, ref token);
                        if (libFunc != string.Empty && this.LibraryFunctions.ContainsKey(libFunc))
                            bracketLevel++;
                    }
                }

                loc++;
            }

            return ret;
        }

        private double negbinomdensity(int failures, int successes, double p)
        {
            return this.comb(successes - 1, failures + successes - 1) * Math.Pow(p, successes) * Math.Pow(1 - p, failures);
        }
        const double PI = 3.141592653589793238462643;
        private double normaldensity(double x, double u, double s)
        {
            return 1 / (Math.Sqrt(2 * PI) * s) * Math.Exp(-(x - u) * (x - u) / (2 * s * s));
        }
        
        private double normaldist(double x, double u, double s)
        {
            ////						int nTraps = 4;
            ////
            ////
            ////
            ////						double h = x / 2;
            ////						double sum = normaldensity(-x , u, s) + 2*(normaldensity(-x + h , u, s) + normaldensity(-x + 2 * h , u, s) + normaldensity(-x + 3 * h , u, s)) + normaldensity(x , u, s);
            ////						double gd = h * sum / 2;
            ////						double oldgd = gd;
            ////						double eps = 1e-7;
            ////
            ////						for(int k = 0; k < 30; ++k)
            ////						{
            ////							nTraps *= 2;
            ////
            ////							h = 2 * x / nTraps;
            ////							for(int i = 0; i < nTraps; ++i)
            ////							{
            ////								if(i % 2 == 1)
            ////								{
            ////									double d = normaldensity(-x + h * i, u, s);
            ////									sum += 2 * d;
            ////								}
            ////							}
            ////							gd = h * sum / 2;
            ////							Console.WriteLine(gd);
            ////							if(Math.Abs((gd - oldgd)/oldgd) < eps)
            ////								break;
            ////
            ////							oldgd = gd;
            ////
            ////						}
            ////			    return gd;

            int nPanels = 32;

            double leftside;
            double rightside;
            if (x > u)
            {
                leftside = u - (x - u);
                rightside = x;
            }
            else
            {
                leftside = x;
                rightside = u + (u - x);
            }

            double h = (rightside - leftside) / nPanels;
            double mult = h / 3;

            double sum1 = this.normaldensity(leftside, u, s) + this.normaldensity(rightside, u, s);
            double sum4 = 0;
            for (int i = 1; i < nPanels; i += 2)
            {
                sum4 += 4 * this.normaldensity(leftside + i * h, u, s);
            }

            double sum2 = 0;
            for (int i = 2; i < nPanels; i += 2)
            {
                sum2 += 2 * this.normaldensity(leftside + i * h, u, s);
            }

            double gd = mult * (sum1 + sum2 + sum4);
            double oldgd = gd;
            double eps = 1e-7;

            int k = 0;

            for (k = 0; k < 10; ++k)
            {
                nPanels *= 2;

                sum2 += sum4 / 2;
                sum4 = 0;
                h = h = (rightside - leftside) / nPanels;
                for (int i = 0; i < nPanels; ++i)
                {
                    if (i % 2 == 1)
                    {
                        double d = this.normaldensity(leftside + h * i, u, s);
                        sum4 += d;
                    }
                }

                sum4 = 4 * sum4;
                mult = h / 3;
                gd = mult * (sum1 + sum2 + sum4);

                if (Math.Abs((gd - oldgd) / oldgd) < eps)
                {
                    break;
                }

                oldgd = gd;
            }

            if (x > u)
            {
                ////Add the left tails.
                gd = gd + (1 - gd) / 2;
            }
            else
            {
                ////Return only the left tail.
                gd = (1 - gd) / 2;
            }

            ////Console.WriteLine(k.ToString() + "  " + gd.ToString());
            return gd;
        }
        ///<remarks>
        /// Enabled only when ExcelLikeComputations property is set to true.
        /// </remarks>
        /// <summary>
        /// Computes the inverse normal cumulative distribution for the given probability.
        /// </summary>
        /// <param name="p">probability</param>
        /// <returns>a double value.</returns>
        private double newnormalinv(double p)
        {
            double[] region1 = new double[6]{-3.969683028665376e+01, 2.209460984245205e+02,
                      -2.759285104469687e+02, 1.383577518672690e+02,
                      -3.066479806614716e+01, 2.506628277459239e+00};

            double[] region2 = new double[5]{-5.447609879822406e+01, 1.615858368580409e+02,
                              -1.556989798598866e+02, 6.680131188771972e+01,
                              -1.328068155288572e+01};

            double[] region3 = new double[6]{-7.784894002430293e-03, -3.223964580411365e-01,
                              -2.400758277161838e+00, -2.549732539343734e+00,
                              4.374664141464968e+00, 2.938163982698783e+00};

            double[] region4 = new double[4]{7.784695709041462e-03, 3.224671290700398e-01,
                               2.445134137142996e+00, 3.754408661907416e+00};

            double pLow = 0.02425;
            double pHigh = 1 - pLow;
            double q = 0.0;
            double r = 0.0;

            // For lower region:
            if (p < pLow)
            {
                q = Math.Sqrt(-2 * Math.Log(p));
                return (((((region3[0] * q + region3[1]) * q + region3[2]) * q + region3[3]) * q + region3[4]) * q + region3[5]) /
                                                ((((region4[0] * q + region4[1]) * q + region4[2]) * q + region4[3]) * q + 1);
            }

            // For upper region:
            if (pHigh < p)
            {
                q = Math.Sqrt(-2 * Math.Log(1 - p));
                return -(((((region3[0] * q + region3[1]) * q + region3[2]) * q + region3[3]) * q + region3[4]) * q + region3[5]) /
                                                       ((((region4[0] * q + region4[1]) * q + region4[2]) * q + region4[3]) * q + 1);
            }

            // For central region:
            q = p - 0.5;
            r = q * q;
            return (((((region1[0] * r + region1[1]) * r + region1[2]) * r + region1[3]) * r + region1[4]) * r + region1[5]) * q /
                                     (((((region2[0] * r + region2[1]) * r + region2[2]) * r + region2[3]) * r + region2[4]) * r + 1);
        }

        private double normalinv(double p, double u, double s)
        {
            double guess = u; ////(u == 0) ? 1 : u;
            if (p < .05)
            {
                guess = u - 2 * s;
            }
            else if (p < .5)
            {
                guess = u;
            }
            else if (p < .95)
            {
                guess = u + 2 * s;
            }
            else
            {
                guess = u + 5 * s;
            }

            double lastIncrement = guess / 2;
            double gi = 0;
            double eps = 1e-7;
            int k = 100;
            int tries = 3;
            int its = 0;
            while (k == 100 && tries > 0)
            {
                tries--;
                guess = guess / 2;
                lastIncrement = guess / 2;

                for (k = 0; k < 100; ++k)
                {
                    its++;
                    gi = this.normaldist(guess, u, s);
                    if (Math.Abs((gi - p) / p) < eps)
                    {
                        break;
                    }

                    if (gi < p)
                    {
                        guess += lastIncrement;
                    }
                    else
                    {
                        lastIncrement = lastIncrement / 2;
                        if (guess - lastIncrement < 0)
                        {
                            lastIncrement = guess / 2;
                        }

                        guess -= lastIncrement;
                    }
                }
            }

            if (k == 100)
            {
                guess = -1;
            }

            return guess;
        }

        private bool NotInBlock(string text, int position)
        {
            int i = text.IndexOf(BMARKER);
            bool inBlock = false;
            while (i > -1 && i < position)
            {
                inBlock = !inBlock;
                i = text.IndexOf(BMARKER, i + 1);
            }

            return !inBlock;
        }

        internal string Parse(string text)
        {
#if _ENABLETIMERS
            string ML = "Parse";  MarkTimeStart(ML);
#endif

            if (TextIsEmpty(text))
            {
                return text;
            }

            this.GetFormulaText(ref text);

            if (this.SupportLogicalOperators)
            {
                this.MarkReserveWords(ref text);
            }

            if (FormulaCharacter != (char)0 && FormulaCharacter == text[0])
            {
                text = text.Substring(1);
            }

            ////Special check for single namedrange.
            if (this.NamedRanges.Count > 0)
            {
                if (this.NamedRanges.ContainsKey(text.ToUpper()))
                {
                    text = ((string)this.NamedRanges[text.ToUpper()]).ToUpper();
                }
                else
                {
                    string scopedRange = string.Empty;
                    if (CheckIfScopedRange(text.ToUpper(), out scopedRange))
                    {
                        text = scopedRange.ToUpper();
                    }
                }
            }
            ////Save strings...
            Hashtable formulaStrings = this.SaveStrings(ref text);

            ////Make braces strings...
            text = text.Replace(this.BRACELEFT, TIC);
            text = text.Replace(this.BRACERIGHT, TIC);

            text = text.Replace("-+", "-");
            int i = 0;
            text = text.ToUpper(CultureInfo.InvariantCulture);

            if (text.IndexOf(sheetToken) > -1)
            {
                ////Replace sheet references with tokens.
                GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
                if (family.SheetNameToParentObject != null && family.SheetNameToParentObject.Count > 0)
                {
                    try
                    {
                        this.PutTokensForSheets(ref text);
                    }
                    catch (Exception ex)
                    {
                        if (this.rethrowExceptions)
                        {
                            throw ex; ////Rethrow so the caller can handle the bad parse on formula name.
                        }
                        else
                        {
                            return ex.Message;
                        }
                    }
#if _ENABLETIMERS
                    finally
                    {
                        MarkTimeEnd(ML);
                    }
#endif
                }
            }

            if (this.isRangeOperand)
            {
                this.isRangeOperand = false;
#if _ENABLETIMERS
                string v = this.GetCellFrom(ParseSimple(text));
                MarkTimeEnd(ML);

               return v;
#else
                return this.GetCellFrom(this.ParseSimple(text));
#endif
            }

            ////next 3 lines moved from above - //keep the tic defect#541
            text = text.Replace(" ", string.Empty);
            text = text.Replace("=>", ">=");
            text = text.Replace("=<", "<=");

            try
            {
                this.MarkLibraryFormulas(ref text);
            }
            catch (Exception ex)
            {
                if (this.rethrowExceptions)
                {
                    throw ex; ////Rethrow so the caller can handle the bad parse on formula name.
                }
                else
                {
#if _ENABLETIMERS
                    MarkTimeEnd(ML);
#endif
                    return ex.Message;
                }
            }

            ////Look for inner matching and parse pieces without parens with ParseSimple.
            if (!ignoreBracet)
            {
                while ((i = text.IndexOf(')')) > -1)
                {
                    int k = text.Substring(0, i).LastIndexOf('(');
                    if (k == -1)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[mismatched_parentheses]);
                    }

                if (k == i - 1)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[empty_expression]);
                    }
                    string s = string.Empty;
                    if (ignoreBracet)
                    {
                        s = text.Substring(k, i - k + 1);
                    }
                    else
                        s = text.Substring(k + 1, i - k - 1);
                    text = text.Substring(0, k) + this.ParseSimple(s) + text.Substring(i + 1);
                }
            }

            ////All parens should have been removed.
            if (!ignoreBracet && text.IndexOf('(') > -1)
            {
                throw new ArgumentException(this.FormulaErrorStrings[mismatched_parentheses]);
            }

            string retValue = this.ParseSimple(text);
            if (formulaStrings != null && formulaStrings.Count > 0)
            {
                this.SetStrings(ref retValue, formulaStrings);
            }
#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
            return retValue;
        }

        private bool CheckIfScopedRange(string text, out string scopedRange)
        {
            scopedRange = string.Empty;
            bool b = false;
            int id = GetSheetID(this.grid);
            GridSheetFamilyItem sheet = GetSheetFamilyItem(grid);

            if (text.StartsWith(sheetToken.ToString()))
            {
                int i = text.IndexOf(sheetToken, 1);
                if (i > 1 && int.TryParse(text.Substring(1, i-1), out id))
                {
                    //id reset to proper value
                    text = text.Substring(i + 1);
                }

            }

            string token = '!' + id.ToString() + '!';

            if (sheet.SheetNameToToken == null)
                return b;
            foreach (string name in sheet.SheetNameToToken.Keys)
            {
                if (sheet.SheetNameToToken[name].ToString() == token)
                {
                    string s = (name + '!' + text).ToUpper();
                    if (this.NamedRanges.ContainsKey(s))
                    {
                        scopedRange = ((string)this.NamedRanges[s]).ToUpper();
                        b = true;
                    }
                }
            }
            return b;
        }

        /// <summary>
        /// A method that parses and computes the string formula passed in.
        /// </summary>
        /// <param name="formula">The text formula to be parsed and computed.</param>
        /// <returns>A string holding the computed value.</returns>
        public string ParseAndComputeFormula(string formula)
        {
            if (formula.Length > 0 && formula[0] == CalcEngine.FormulaCharacter)
            {
                formula = formula.Substring(1);
            }

            if (formula.Length > 0 && formula[0] == '+')
            {
                formula = formula.Substring(1);
            }

            if (formula.Length > 1 && formula[0] == ParseDecimalSeparator)
            {
                if (formula[1] >= '0' && formula[1] <= '9')
                    formula = "0" + ParseDecimalSeparator + formula.Substring(1);
            }
            string tempFormula = formula.Replace(" ", string.Empty);
            for (int i = tempFormula.IndexOf("("); i != -1 && i < tempFormula.Length; i++)
            {
                if (i > 0)
                {
                    if (char.IsNumber(tempFormula[i - 1]))
                    {
                        if(!CheckHasCharBeforeNumber( tempFormula.Substring(0 , i)))
                            throw new ArgumentException(this.FormulaErrorStrings[bad_formula] + " " + tempFormula.Substring(0, i + 1));
                    }
                    int next = tempFormula.Substring(i + 1).IndexOf('(');
                    if (next == -1)
                    {
                        break;
                    }
                    else
                    {
                        i += next;
                    }
                }
            }
            for (int i = tempFormula.IndexOf(")"); i != -1 && i < tempFormula.Length - 1; i++)
            {
                if (char.IsNumber(tempFormula[i + 1]))
                {
                    throw new ArgumentException(this.FormulaErrorStrings[bad_formula] + " " + tempFormula.Substring(0, i + 2));
                }
                int next = tempFormula.Substring(i + 1).IndexOf(')');
                if (next == -1)
                {
                    break;
                }
                else
                {
                    i += next;
                }
            }
            multiTick = false;
            string s = this.Parse(formula);
            return this.ComputedValue(s);
        }

        private bool CheckHasCharBeforeNumber(string tempFormula)
        {
            bool check = false;
            for (int x =tempFormula.Length-1; x >0 ; x--)
            {
                if (char.IsLetter(tempFormula[x]))
                {
                    check = true;
                    break;
                }
            }
            return check;
        }

        /// <summary>
        /// A method that parses the text in a formula passed in.
        /// </summary>
        /// <param name="formula">The text formula to be parsed.</param>
        /// <returns>A string holding a parsed representation of the formula.</returns>
        public string ParseFormula(string formula)
        {
            if (formula.Length > 0 && formula[0] == CalcEngine.FormulaCharacter)
            {
                formula = formula.Substring(1);
            }

            if (formula.Length > 0 && formula[0] == '+')
            {
                formula = formula.Substring(1);
            }

            this.isRangeOperand = supportRangeOperands && IsRange(formula);
            if (this.CheckDanglingStack && formula.Replace(" ", string.Empty).IndexOf(this.BRACERIGHTnLEFT) > -1)
            {
                this.computedValueLevel = 0;
                return this.FormulaErrorStrings[improper_formula];
            }
            return this.Parse(formula.Trim());
        }

        private string ParseSimple(string text)
        {
            ////strip leading plus
            if (text.Length > 0 && text[0] == '+')
            {
                text = text.Substring(1);
            }

            if (text == "#N/A" || text == "#N~A")
            {
                return "#N/A";
            }
            else if (text.IndexOf("#N/A") > -1)
            {
                text = text.Replace("#N/A", "#N~A");
            }
            if (text == "#DIV/0!" || text == "#DIV~0!")
            {
                return "#DIV/0!";
            }
            else if (text.IndexOf("#DIV/0!") > -1)
            {
                text = text.Replace("#DIV/0!", "#DIV~0!");
            }
            text = this.HandleEmbeddedEs(text);

            ////TraceUtil.TraceCurrentMethodInfoIf(Switches.FormulaCell.TraceVerbose, text, this);

            System.Text.StringBuilder sb = new System.Text.StringBuilder(text);
            text = sb.Replace(STRING_lesseq, CHAR_lesseq.ToString())
                .Replace(STRING_greatereq, CHAR_greatereq.ToString())
                .Replace(STRING_noequal, CHAR_noequal.ToString())
                .Replace(STRING_fixedreference, STRING_empty)
                .Replace(this.STRING_or, CHAR_or.ToString())
                .Replace(this.STRING_and, CHAR_and.ToString())
                .ToString();
            if (text == string.Empty)
            {
                return text;
            }

            bool needToContinue = true;

            ////doing things sequentially imposes computation hierarchy for 6 levels
            //// 0. E+ E- //handles exponential notation like 1.2e-1 or 1.2e+1 to 1.2e1
            //// 1. ^ exponentiation
            //// 2. * /
            //// 3. + -
            //// 4. < > = <= >= <>
            //// 5. & concatenation
            //// in each level parsing done left to right

            text = this.ParseSimple(text, new char[] { TOKEN_EP, TOKEN_EM }, new char[] { CHAR_EP, CHAR_EM }, ref needToContinue);
            text = this.ParseSimple(text, new char[] { TOKEN_or }, new char[] { CHAR_or }, ref needToContinue);
            if (needToContinue)
            {
                text = this.ParseSimple(text, new char[] { TOKEN_multiply, TOKEN_divide }, new char[] { CHAR_multiply, CHAR_divide }, ref needToContinue);
            }

            if (needToContinue)
            {
                text = this.ParseSimple(text, new char[] { TOKEN_add, TOKEN_subtract }, new char[] { CHAR_add, CHAR_subtract }, ref needToContinue);
            }

            if (needToContinue)
            {
                text = this.ParseSimple(
                    text,
                    new char[] { TOKEN_less, TOKEN_greater, TOKEN_equal, TOKEN_lesseq, TOKEN_greatereq, TOKEN_noequal },
                    new char[] { CHAR_less, CHAR_greater, CHAR_equal, CHAR_lesseq, CHAR_greatereq, CHAR_noequal },
                    ref needToContinue);
            }

            if (this.SupportLogicalOperators && needToContinue)
            {
                text = this.ParseSimple(text, new char[] { TOKEN_NOTop }, new char[] { CHAR_NOTop }, ref needToContinue);
            }

            if (this.SupportLogicalOperators && needToContinue)
            {
                text = this.ParseSimple(text, new char[] { TOKEN_ORop, TOKEN_ANDop, TOKEN_XORop }, new char[] { CHAR_ORop, CHAR_ANDop, CHAR_XORop }, ref needToContinue);
            }

            if (needToContinue)
            {
                text = this.ParseSimple(text, new char[] { TOKEN_and }, new char[] { CHAR_and }, ref needToContinue);
            }
            if (text.IndexOf("#N~A") > -1)
            {
                text = text.Replace("#N~A", "#N/A");
            }

            if (text.IndexOf("#DIV~0!") > -1)
            {
                text = text.Replace("#DIV~0!", "#DIV/0!");
            }
            return text;
        }

        private string ParseSimple(string text, char[] markers, char[] operators, ref bool needToContinue)
        {
            ////TraceUtil.TraceCurrentMethodInfoIf(Switches.FormulaCell.TraceVerbose, text, markers, operators);
            int i;

            ////op is string containing CHAR_xxxx's for each operator in this level
            string op = string.Empty;
            foreach (char c in operators)
            {
                op = op + c;
            }

            ////Mark unary minus with u-token.
            System.Text.StringBuilder sb = new System.Text.StringBuilder(text);

            //Fix for defect: #13790.
            //text = sb.Replace(",-", ",u").Replace(this.LEFTBRACKET + "-", this.LEFTBRACKET + "u").Replace("=-", "=u").Replace(">-", ">u").Replace("<-", "<u").Replace("/-", "/u").Replace("*-", "*u").Replace("+-", "+u").Replace("--", "-u").Replace("w-", "wu").ToString();
            text = sb.Replace("---", "-").Replace("--", "+").Replace(parseArgumentSeparator + "-", ParseArgumentSeparator + "u").Replace(this.LEFTBRACKET + "-", this.LEFTBRACKET + "u").Replace("=-", "=u").Replace(">-", ">u").Replace("<-", "<u").Replace("/-", "/u").Replace("*-", "*u").Replace("+-", "-").Replace("--", "-u").Replace("w-", "wu").ToString();

            ////Get rid of leading pluses.
            text = sb.Replace(",+", ",").Replace(this.LEFTBRACKET + "+", this.LEFTBRACKET.ToString()).Replace("=+", "=").Replace(">+", ">").Replace("<+", "<").Replace("/+", "/").Replace("*+", "*").Replace("++", "+").ToString();

            if (text.Length > 0 && text[0] == '-')
            {
                ////Leading unary minus.
                text = "0" + text;
            }
            else if (text.Length > 0 && text[0] == '+')
            {
                ////Leading plus.
                text = text.Substring(1);
            }

            if (text.IndexOfAny(operators) > -1)
            {
                while ((i = text.IndexOfAny(operators)) > -1)
                {
                    string left = string.Empty;
                    string right = string.Empty;

                    int leftIndex = 0;
                    int rightIndex = 0;

                    bool isNotOperator = this.SupportLogicalOperators && text[i] == CHAR_NOTop;
                    int j;

                    if (!isNotOperator)
                    {
                        if (i < 1 && text[i] != '-')
                        {
                            throw new ArgumentException(this.FormulaErrorStrings[operators_cannot_start_an_expression]);
                        }

                        ////Process left argument.
                        j = i - 1;

                        if (i == 0 && text[i] == '-')
                        {
                            ////Unary minus - block and continue.
                            text = BMARKER + "nu" + text.Substring(1) + BMARKER;
                            continue;
                        }
                        else if (text[j] == this.TIC[0]) 
                        {
                            ////string
                            int k = text.Substring(0, j - 1).LastIndexOf(this.TIC);
                            if (k < 0)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                            }

                            left = text.Substring(k, j - k + 1); ////Keep the tics.
                            leftIndex = k;
                        }
                        else if (text[j] == BMARKER) 
                        {
                            ////Block of already parsed code.
                            int k = this.FindLastNonQB(text.Substring(0, j - 1));
                            if (k < 0)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                            }

                            left = text.Substring(k + 1, j - k - 1);
                            leftIndex = k + 1;
                        }
                        else if (text[j] == this.RIGHTBRACKET) 
                        {
                            ////Library member.
                            int bracketCount = 0;
                            int k = j - 1;
                            while (k > 0 && (text[k] != 'q' || bracketCount != 0))
                            {
                                if (text[k] == 'q')
                                {
                                    bracketCount--;
                                }
                                else if (text[k] == this.RIGHTBRACKET)
                                {
                                    bracketCount++;
                                }

                                k--;
                            }

                            if (k < 0)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[bad_library]);
                            }

                            left = text.Substring(k, j - k + 1);
                            leftIndex = k;
                        }
                        else if (!char.IsDigit(text[j]) && text[j] != '%') 
                        {
                            ////number

                            ////Throw new ArgumentException(FormulaErrorStrings[invalid_char_in_front_of] + text[i]);
                            ////check for namedrange.
                            while (j >= 0 && (char.IsUpper(text[j]) || text[j] == '_' || text[j] == '.'))
                            {
                                j--;
                            }

                            left = text.Substring(j + 1, i - j - 1); ////'n' for number
                            leftIndex = j + 1;
                            string scopedRange = string.Empty;
                                
                            if (this.NamedRanges.ContainsKey(left))
                            {
                                left = this.Parse((string)this.NamedRanges[left]);
                            }
                            else if (CheckIfScopedRange(left, out scopedRange))
                            {
                                left = this.Parse(scopedRange);
                            }
                            else if (left == this.TRUEVALUESTR)
                            {
                                left = 'n' + this.TRUEVALUESTR;
                            }
                            else if (left == this.FALSEVALUESTR)
                            {
                                left = 'n' + this.FALSEVALUESTR;
                            }
                            else
                            {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                                if (RethrowLibraryComputationExceptions)
                                    throw new ArgumentException(this.FormulaErrorStrings[invalid_char_in_front_of] + " " + text[i]);
                                return this.ErrorStrings[5].ToString();
#endif
                            }
                        }
                        else
                        {
                            bool period = false;
                            bool percent = false;

                            while (j > -1 && (char.IsDigit(text[j]) || (!period && text[j] == ParseDecimalSeparator)
                                || (!percent && text[j] == '%')
                                || text[j] == 'u'))
                            {
                                if (text[j] == ParseDecimalSeparator)
                                {
                                    period = true;
                                }
                                else if (text[j] == '%')
                                {
                                    percent = true;
                                }

                                j = j - 1;
                            }

                            ////Add error check for 2%.
                            if (j > -1 && period && text[j] == ParseDecimalSeparator)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[number_contains_2_decimal_points]);
                            }

                            j = j + 1;

                            if (j == 0 || (j > 0 && !char.IsUpper(text[j - 1])))
                            {
                                left = 'n' + text.Substring(j, i - j); ////'n' for number
                                leftIndex = j;
                            }
                            else
                            {
                                ////We have a cell reference.
                                j = j - 1;
                                while (j > -1 && char.IsUpper(text[j]))
                                {
                                    j = j - 1;
                                }

                                ////include any unary minus as part of the left piece
                                if (j > -1 && text[j] == 'u')
                                {
                                    j = j - 1;
                                }

                                if (j > -1 && text[j] == sheetToken)
                                {
                                    j = j - 1;
                                    while (j > -1 && text[j] != sheetToken)
                                    {
                                        j = j - 1;
                                    }

                                    if (j > -1 && text[j] == sheetToken)
                                    {
                                        j = j - 1;
                                    }
                                }

                                if (j > -1 && text[j] == ':')
                                {  
                                    //// handle range operands
                                    j = j - 1;
                                    while (j > -1 && char.IsDigit(text[j]))
                                    {
                                        j = j - 1;
                                    }

                                    while (j > -1 && char.IsUpper(text[j]))
                                    {
                                        j = j - 1;
                                    }

                                    if (j > -1 && text[j] == sheetToken)
                                    {
                                        j--;
                                        while (j > -1 && text[j] != sheetToken)
                                        {
                                            j--;
                                        }

                                        if (j > -1 && text[j] == sheetToken)
                                        {
                                            j--;
                                        }
                                    }

                                    j = j + 1;
                                    left = text.Substring(j, i - j);
                                    left = this.GetCellFrom(left);
                                }
                                else
                                {  
                                    //// handle normal cell reference
                                    j = j + 1;
                                    left = text.Substring(j, i - j);
                                }

                                this.UpdateDependencies(left);
                                leftIndex = j;
                            }
                        }
                    }
                    else
                    {
                        leftIndex = i;
                    }

                    ////Process right argument.
                if (i == text.Length - 1)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[expression_cannot_end_with_an_operator]);
                    }
                    else
                    {
                        j = i + 1;

                        bool isU = text[j] == 'u';
                        if (isU)
                        {
                            j++;  ////ship for now, but add back later
                        }

                        if (text[j] == this.TIC[0]) 
                        {
                            ////string
                            int k = text.Substring(j + 1).IndexOf(this.TIC);
                            if (k < 0)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                            }

                            right = text.Substring(j, k + 2);
                            rightIndex = k + j + 2;
                        }
                        else if (text[j] == BMARKER) 
                        {
                            ////Block of already parsed code.
                            int k = this.FindNonQB(text.Substring(j + 1));
                            if (k < 0)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                            }

                            right = text.Substring(j + 1, k);

                            if (isU)
                            {
                                right = right + "nu1m"; ////multiply quantity by -1...
                            }

                            rightIndex = k + j + 2;
                        }
                        else if (text[j] == 'q') 
                        {
                            ////library
                            int bracketCount = 0;
                            int k = j + 1;
                            while (k < text.Length && (text[k] != this.RIGHTBRACKET || bracketCount != 0))
                            {
                                if (text[k] == this.RIGHTBRACKET)
                                {
                                    bracketCount++;
                                }
                                else if (text[k] == 'q')
                                {
                                    bracketCount--;
                                }

                                k++;
                            }

                            if (k == text.Length)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                            }

                            right = text.Substring(j, k - j + 1);

                            if (isU)
                            {
                                right = 'u' + right;
                            }

                            rightIndex = k + 1;
                        }
                        else if (char.IsDigit(text[j]) || text[j] == ParseDecimalSeparator)
                        {
                            bool period = text[j] == ParseDecimalSeparator;
                            j = j + 1;
                            while (j < text.Length && (char.IsDigit(text[j]) || (!period && text[j] == ParseDecimalSeparator)))
                            {
                                if (text[j] == ParseDecimalSeparator)
                                {
                                    period = true;
                                }

                                j = j + 1;
                            }

                            if (j < text.Length && text[j] == '%')
                            {
                                j += 1;
                            }

                            if (period && j < text.Length && text[j] == ParseDecimalSeparator)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[number_contains_2_decimal_points]);
                            }

                            right = 'n' + text.Substring(i + 1, j - i - 1);
                            rightIndex = j;
                        }
                        else if (char.IsUpper(text[j]) || text[j] == sheetToken || text[j] == 'u')
                        {
                            if (text[j] == sheetToken)
                            {
                                j++;
                                while (j < text.Length && text[j] != sheetToken)
                                {
                                    j++;
                                }
                            }

                            j = j + 1;
                            int j0 = 0;
                            while (j < text.Length && (char.IsUpper(text[j]) || text[j] == '_' || text[j] == '.'))
                            {
                                j++;
                                j0++;
                            }

                            bool noCellReference = (j == text.Length) || !char.IsDigit(text[j]);

                            if (j0 > 4)
                            {
                                while (j < text.Length && (char.IsUpper(text[j]) || char.IsDigit(text[j])))
                                {
                                    j++;
                                }

                                noCellReference = true;
                            }

                            while (j < text.Length && char.IsDigit(text[j]))
                            {
                                j = j + 1;
                            }

                            if (j < text.Length && text[j] == ':')
                            {  
                                //// handle range operands
                                j = j + 1;
                                if (j < text.Length && text[j] == sheetToken)
                                {
                                    j++;
                                    while (j < text.Length && text[j] != sheetToken)
                                    {
                                        j = j + 1;
                                    }

                                    if (j < text.Length && text[j] == sheetToken)
                                    {
                                        j++;
                                    }
                                }

                                while (j < text.Length && char.IsUpper(text[j]))
                                {
                                    j = j + 1;
                                }

                                while (j < text.Length && char.IsDigit(text[j]))
                                {
                                    j = j + 1;
                                }

                                j = j - 1;

                                right = text.Substring(i + 1, j - i);
                                right = this.GetCellFrom(right);
                            }
                            else
                            {  
                                //// handle normal cell reference
                                j = j - 1;
                                right = text.Substring(i + 1, j - i);
                                isU = text[j] == 'u';
                                if (isU)
                                {
                                    right = 'u' + right;
                                }
                            }

                            if (!noCellReference)
                            {
                                this.UpdateDependencies(right);
                            }
                            else
                            {
                                string scopedRange = string.Empty;
                                if (this.NamedRanges.ContainsKey(right))
                                {
                                    right = this.Parse((string)this.NamedRanges[right]);
                                }
                                else if (CheckIfScopedRange(right, out scopedRange))
                                {
                                    right = this.Parse(scopedRange);
                                }
                                else if (right == this.TRUEVALUESTR)
                                {
                                    right = 'n' + this.TRUEVALUESTR;
                                }
                                else if (right == this.FALSEVALUESTR)
                                {
                                    right = 'n' + this.FALSEVALUESTR;
                                }
                                else
                                {
#if _ENABLETIMERS
            MarkTimeEnd(ML);           
#else
                                    if (RethrowLibraryComputationExceptions)
                                        throw new ArgumentException(this.FormulaErrorStrings[invalid_characters_following_an_operator]);
                                    return this.ErrorStrings[5].ToString();
#endif
                                }
                            }

                            rightIndex = j + 1;
                        }
                        else
                        {
                            throw new ArgumentException(this.FormulaErrorStrings[invalid_characters_following_an_operator]);
                        }
                    }

                    int p = op.IndexOf(text[i]);
                    string s = BMARKER + this.ZapBlocks(left) + this.ZapBlocks(right) + markers[p] + BMARKER;
                    if (leftIndex > 0)
                    {
                        s = text.Substring(0, leftIndex) + s;
                    }

                    if (rightIndex < text.Length)
                    {
                        s = s + text.Substring(rightIndex);
                    }

                    s = s.Replace(BMARKER2, BMARKER.ToString());

                    //// s = s.Replace(TIC+TIC, TIC); removed forum post http://64.78.18.34/Support/Forums/message.aspx?MessageID=22483
                    text = s;
                }
            }
            else
            {
                ////No operators  ..must be number, reference, or library method.

                ////Process left argument.
                int j = text.Length - 1;

                ////Block of already parsed code.
                if (text[j] == BMARKER) 
                {
                    int k = this.FindLastNonQB(text.Substring(0, j - 1));
                    if (k < 0)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[cannot_parse]);
                    }
                }
                else if (text[j] == this.RIGHTBRACKET) 
                {
                    ////library member
                    int bracketCount = 0;
                    int k = j - 1;
                    while (k > 0 && (text[k] != 'q' || bracketCount != 0))
                    {
                        if (text[k] == 'q')
                        {
                            bracketCount--;
                        }
                        else if (text[k] == this.RIGHTBRACKET)
                        {
                            bracketCount++;
                        }

                        k--;
                    }

                    if (k < 0)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[bad_library]);
                    }
                }
                else if (!char.IsDigit(text[j])) 
                {
                    ////number
                    ////Throw new ArgumentException(FormulaErrorStrings[invalid_char_in_number]).
                }
                else
                {
                    bool period = false;
                    bool percent = false;

                    while (j > -1 && (char.IsDigit(text[j]) || (!period && text[j] == ParseDecimalSeparator)
                        || (!percent && text[j] == '%')))
                    {
                        if (text[j] == ParseDecimalSeparator)
                        {
                            period = true;
                        }
                        else if (text[j] == '%')
                        {
                            percent = true;
                        }

                        j = j - 1;
                    }

                    if (j > -1 && period && text[j] == ParseDecimalSeparator)
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[number_contains_2_decimal_points]);
                    }
                }

                if (text.Length > 0 && (char.IsUpper(text, 0) || text[0] == sheetToken))
                {
                    ////Check if cell reference.
                    bool ok = true;
                    bool checkLetter = true;
                    bool oneTokenFound = false;
                    for (int k = 0; k < text.Length; ++k)
                    {
                        if (text[k] == sheetToken)
                        {
                            if (k > 0 && !oneTokenFound)
                            {
                                ////ok = false;
                                throw new ArgumentException(this.FormulaErrorStrings[missing_sheet]);
                                ////break;
                            }

                            oneTokenFound = true;
                            k++;
                            while (k < text.Length && char.IsDigit(text[k]))
                            {
                                k++;
                            }

                            if (k == text.Length || text[k] != sheetToken)
                            {
                                ok = false;
                                break;
                            }
                        }
                        else
                        {
                            ////if(!checkLetter && char.IsUpper(text, k))
                            if (!checkLetter && char.IsLetter(text, k))
                            {
                                ok = false;
                                break;
                            }

                            if (char.IsLetterOrDigit(text, k) || text[k] == sheetToken)
                            {
                                checkLetter = char.IsUpper(text, k);
                            }
                            else
                            {
                                ok = false;
                                break;
                            }
                        }
                    }

                    if (ok)
                    {
                        this.UpdateDependencies(text); ////cb
                        needToContinue = false;
                    }
                }
            }

            return text;
        }

        private double pearson(double[] x, double[] y, int n)
        {
            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double sumy2 = 0;
            double d1, d;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                d1 = y[i] - sumy;
                sumxy += d * d1;
                sumx2 += d * d;
                sumy2 += d1 * d1;
            }

            return sumxy / Math.Sqrt(sumx2 * sumy2);
        }

        /// <summary>
        /// Swaps variable names for tokens.
        /// </summary>
        /// <param name="formula">The formula holding variable names.</param>
        /// <returns>The formula with tokens.</returns>
        public string PlaceVariablenameTokensIntoFormula(string formula)
        {
            int left = formula.IndexOf(this.LEFTBRACKET);
            while (left > -1)
            {
                int right = formula.IndexOf(this.RIGHTBRACKET, left);
                if (right > -1)
                {
                    string s = formula.Substring(left + 1, right - 1).ToLower().Trim();
                    s = this.variableNamesToTokens[s].ToString();
                    if (s != null)
                    {
                        string rightPiece = string.Empty;
                        if (right < formula.Length - 1)
                        {
                            rightPiece = formula.Substring(right + 1);
                        }

                        if (left > 0)
                        {
                            formula = formula.Substring(0, left) + s + rightPiece;
                        }
                        else
                        {
                            formula = s + rightPiece;
                        }

                        left = formula.IndexOf(this.LEFTBRACKET);
                    }
                    else
                    {
                        return string.Empty;
                    }
                }
                else
                {
                    return string.Empty;
                }
            }

            return formula;
        }

        bool isErrorString = false;
        private double Pop(Stack _stack)
        {
            object o = _stack.Pop();

            string s;
            if (o != null)
            {
                if (o.ToString() == this.TIC+this.TIC )
                {
                    return double.NaN;
                }
                else
                {
                    s = o.ToString().Replace(this.TIC, string.Empty);
                }
                if (this.ErrorStrings.Contains(s))
                {
                    isErrorString = true;
                    return this.ErrorStrings.IndexOf(s);
                }
                ////moved from ComputedValue above as result of DT26064
                if (s.StartsWith("#")
                    || s == string.Empty)
                {
                    return 0;
                }

                if (s == this.TRUEVALUESTR)
                {
                    return 1;
                }
                else if (s == this.FALSEVALUESTR)
                {
                    return 0;
                }

                double d;
                if (double.TryParse(s, NumberStyles.Any, CultureInfo.CurrentCulture , out d))
                {
                    return d;
                }
                else if (this.useDatesInCalcs)
                {
                    DateTime dt;
                    if (this.IsDate(s, out dt))
                    {
                        return this.GetSerialDateTimeFromDate(dt);
                    }
                    else
                    {
                        return 0;
                    }
                }

                ////else drop out to return 0
            }

            if (treatStringsAsZero)
            {
                return 0;
            }
            else if(o != null && o.ToString().Length > 0)
            {
                return double.NaN;
            }
            return 0;
        }

        bool treatStringsAsZero = true;

        /// <summary>
        /// Gets of sets whether the CalcEngine treats nonempty strings as zeros when they are
        /// encountered during calculations.
        /// </summary>
        /// <remarks>
        /// The default value is true meaning that if a nonempty string is encountered during an arithmetic operation, it will be treated as zero.
        /// </remarks>
        public bool TreatStringsAsZero
        {
            get { return treatStringsAsZero; }
            set { treatStringsAsZero = value; }
        }
 
        ////used for logical binary operators
        private string PopString(Stack _stack)
        {
            object o = _stack.Pop();
            if (o == null)
            {
                o = string.Empty;
            }

            if (this.useDatesInCalcs)
            {
                DateTime dt;
                if (this.IsDate(o, out dt))
                {
                    return this.GetSerialDateTimeFromDate(dt).ToString();
                }
            }

            return this.StripTics(o.ToString());
        }

        private string ProcessUpperCase(ref string formula, ref int i, ref string sheet)
        {
            string s = string.Empty;
            while (i < formula.Length && char.IsUpper(formula[i]))
            {
                s = s + formula[i];
                i = i + 1;
            }

            while (i < formula.Length && char.IsDigit(formula[i]))
            {
                s = s + formula[i];
                i = i + 1;
            }

            if (this.supportRangeOperands && i < formula.Length && formula[i] == ':')
            {
                s = s + formula[i];
                i = i + 1;
                if (i < formula.Length && formula[i] == sheetToken)
                {
                    s = s + formula[i];
                    i = i + 1;

                    while (i < formula.Length && formula[i] != sheetToken)
                    {
                        s = s + formula[i];
                        i = i + 1;
                    }
                }

                while (i < formula.Length && char.IsUpper(formula[i]))
                {
                    s = s + formula[i];
                    i = i + 1;
                }

                while (i < formula.Length && char.IsDigit(formula[i]))
                {
                    s = s + formula[i];
                    i = i + 1;
                }

                s = sheet + s;
                sheet = string.Empty;
                s = this.GetCellFrom(s);
            }
            else
            {
                s = sheet + s;
                sheet = string.Empty;
            }

            return s;
        }

        /// <summary>
        /// This method retrieves the value in the requested cell reference using fresh computations 
        /// for any cells that affect the value of the requested cell.
        /// </summary>
        /// <param name="cellRef"> A cell reference like:   Sheet5!B14</param>
        /// <returns>A freshly computed value for the cell.</returns>
        public string PullUpdatedValue(string cellRef)
        {
            this.inAPull = true;
            ICalcData grd = this.grid;
            string saveCell = this.cell;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            string s = cellRef.ToUpper();
            int i;
            if ((i = s.IndexOf(sheetToken))== -1 && this.cell != string.Empty)
            {
                i = this.cell.IndexOf(sheetToken, 1);
                if (i > -1 && family.TokenToParentObject != null)
                {
                    s = this.cell.Substring(0, i + 1) + s;
                    this.grid = (ICalcData)family.TokenToParentObject[cell.Substring(0, i + 1)];
                }
            }
            else
            {
                if (i > 0 && family.SheetNameToToken != null && family.TokenToParentObject != null)
                {
                    ////need sheet id
                    string token = family.SheetNameToToken[s.Substring(0, i)] as string;
                    s = token + s.Substring(i + 1);
                    this.grid = (ICalcData)family.TokenToParentObject[token];
                    this.cell = s;
                }
            }

            this.UpdateCalcID();
            string txt;
            if (!this.DependentFormulaCells.ContainsKey(s) && !this.FormulaInfoTable.ContainsKey(s))
            {
                txt = this.GetValueFromParentObject(s);
                bool saveIVC = this.IgnoreValueChanged;
                this.IgnoreValueChanged = true;
                int row = this.RowIndex(s);

                int col = this.ColIndex(s);
                if (this.PreserveFormula)
                {
                    string token = this.SheetToken(cellRef);
                    if (token.Equals(string.Empty))
                    {
                        token = "!" + this.GetSheetID(grid) + "!";
                        FormulaInfo formula = this.FormulaInfoTable[token + s] as FormulaInfo;
                        if (formula != null)
                        {
                            this.grid.SetValueRowCol(formula.FormulaText, row, col);
                        }
                    }
                    else
                        this.grid.SetValueRowCol(txt, row, col);
                }
                else
                    this.grid.SetValueRowCol(txt, row, col);

                this.IgnoreValueChanged = saveIVC;
            }
            else
            {
                this.processedCells.Clear();
                this.UpdateDependenciesAndCell(s);
                this.processedCells.Clear();
                txt = this.GetValueFromParentObject(s);
            }

            this.grid = grd;
            this.cell = saveCell;
            this.inAPull = false;
			
            return txt;
        }

        /// <summary>
        /// PullUpdatedValue is a method used to recompute the cells that are referred to compute the requested value.
        /// </summary>
        /// <param name="targetSheetID">Integer identifying the ICalcData object.</param>
        /// <param name="row">The row in the ICalcData object.</param>
        /// <param name="col">The column in the ICalcData object.</param>
        public void PullUpdatedValue(int targetSheetID, int row, int col)
        {
            ICalcData saveGrid = this.grid;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            string token = sheetToken + targetSheetID.ToString() + sheetToken;
            this.grid = family.TokenToParentObject[token] as ICalcData;
            this.inAPull = true;

            string s = token + RangeInfo.GetAlphaLabel(col) + row.ToString();

            this.UpdateCalcID();

            if (!this.DependentFormulaCells.ContainsKey(s)
                && !this.FormulaInfoTable.ContainsKey(s))
            {
                string txt = this.GetValueFromParentObject(s);
                bool saveIVC = this.IgnoreValueChanged;
                this.IgnoreValueChanged = true;

                this.grid.SetValueRowCol(txt, row, col);
                this.IgnoreValueChanged = saveIVC;
            }
            else
            {
                this.processedCells.Clear();
                this.UpdateDependenciesAndCell(s);
                this.processedCells.Clear();
            }

            this.grid = saveGrid;
            this.inAPull = false;
        }

        /// <summary>
        /// Accepts an unparsed formula string and replaces any sheet references with corresponding tokens.
        /// </summary>
        /// <param name="text">The unparsed formula string.</param>
        /// <remarks>
        /// This is an advanced method that lets you replace sheet names with corresponding tokens. You may have need of
        /// this method if you are adding your own functions to the function library.
        /// </remarks>
        public void PutTokensForSheets(ref string text)
        {
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

            if (this.SupportsSheetRanges)
            {
                this.HandleSheetRanges(ref text, family);
            }

            ////family.SheetNameToToken.Keys)
            if (this.SortedSheetNames != null)
            {
                foreach (string name in this.SortedSheetNames)
                {
                    string token = (string)family.SheetNameToToken[name];
                    token = token.Replace(sheetToken, this.tempSheetPlaceHolder);

                    ////keep the tic defect#541 - TODO: Optimize this process - cache tic names for instance
                    string s = "'" + name.ToUpper() + "'" + sheetToken;
                    if (text.IndexOf(s) == -1)
                    {
                        s = name.ToUpper() + sheetToken;
                    }

                    text = text.Replace(s, token);

                    //do it again without the tics
                    s = name.ToUpper() + sheetToken;
                    
                    text = text.Replace(s, token);
                }
            }

            text = text.Replace(this.tempSheetPlaceHolder, sheetToken);
        }

        /// <summary>
        /// This method recalculates any formula cells in the specified range.
        /// </summary>
        /// <remarks>The calculations for non-visible formula cells are performed the next time
        ///  cell are actually displayed. If you want the calculation performed immediately
        ///  on cells (visible or not), call the two argument overload of RecalculateRange,
        ///  passing the forceCalculations argument as True.</remarks>
        /// <param name="range">GridRangInfo object that specifies the cells to be recalculated.</param>
        /// <param name="data">ICalcData object that holds the data to be recalculated.</param>
        public void RecalculateRange(RangeInfo range, ICalcData data)
        {
            this.inRecalculateRange = true;
            for (int row = range.Top; row <= range.Bottom; ++row)
            {
                for (int col = range.Left; col <= range.Right; ++col)
                {
                    data.SetValueRowCol(data.GetValueRowCol(row, col), row, col);
                }
            }

            this.inRecalculateRange = false;
        }

        /// <summary>
        /// Refresh is a method that recalculates any cell that depends upon the passed in cell.
        /// </summary>
        /// <param name="s">A cell such as A21 or EE31.</param>
        public void Refresh(string s)
        {
            ////Don't refresh any cells.
            if (this.CalculatingSuspended) 
            {
                return;
            }

            if (this.dependencyLevel == 0)
            {
                this.refreshedCells.Clear();
            }

            if (this.DependentCells.ContainsKey(s) && this.DependentCells[s] != null)
            {
                this.dependencyLevel++;
                try
                {
                    GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

                    ArrayList ht = (ArrayList)this.DependentCells[s];
                    bool save1 = this.lockDependencies;
                    this.lockDependencies = true;
                    foreach (object o in ht)
                    {
                        string s1 = o as string;
                        if (s1 != null)
                        {
                            ICalcData grd = this.grid;
                            string sheet = this.SheetToken(s1);
                            if (sheet.Length > 0)
                            {
                                this.grid = family.TokenToParentObject[sheet] as ICalcData;
                            }

                            int row = this.RowIndex(s1);
                            int col = this.ColIndex(s1);

                            FormulaInfo info = this.FormulaInfoTable[s1] as FormulaInfo;
                            if (info != null)
                            {
                                string save = this.cell;
                                this.cell = s1;
                                if (this.AlwaysComputeDuringRefresh || info.calcID != this.calcID || info.FormulaValue == string.Empty)
                                {
                                    info.FormulaValue = this.ComputeFormula(info.ParsedFormula);
                                }

                                info.calcID = this.calcID;
                                this.cell = save;
                                bool saveIVC = this.IgnoreValueChanged;
                                this.IgnoreValueChanged = true;
                                this.grid.SetValueRowCol(info.FormulaValue, row, col);
                                this.IgnoreValueChanged = saveIVC;
                                if (!refreshedCells.ContainsKey(s1))
                                {
                                    this.refreshedCells.Add(s1, 0); ////from below ...a
                                    this.Refresh(s1); ////recursive call
                                }
                            }

                            this.grid = grd;
                        }
                    }

                    this.lockDependencies = save1;
                }
                finally
                {
                    if (!refreshedCells.ContainsKey(s))
                    {
                        this.refreshedCells.Add(s, 0);
                    }

                    this.dependencyLevel--;
                    if (this.dependencyLevel == 0)
                    {
                        this.refreshedCells.Clear();
                    }
                }
            }
        }

        /// <summary>
        /// Recalculates every cell that depends upon any cell in the passed-in range.
        /// </summary>
        /// <remarks>For example, if range is RangeInfo(1,1,2,2), and cells (5,6) and
        /// (12,17) hold formulas that reference the cells in the range, then cells (5,6)
        /// and (12,17) will be re-computed as the result of this call.</remarks>
        /// <param name="range">RangeInfo object to be refreshed.</param>
        public void RefreshRange(RangeInfo range)
        {
            ////Loop through the range refreshing the cells...
            for (int r = range.Top; r <= range.Bottom; r++)
            {
                for (int c = range.Left; c <= range.Right; c++)
                {
                    string s = RangeInfo.GetAlphaLabel(c) + r.ToString();
                    this.dependencyLevel = 0;
                    this.Refresh(s);
                }
            }
        }

        /// <summary>
        /// RegisterGridAsSheet is a method that registers an ICalcData object so it can be referenced in a formula from another ICalcData object.
        /// </summary>
        /// <param name="refName">The reference name used to refer to this ICalcData object from formulas in other ICalcData objects.
        /// </param>
        /// <param name="model">The ICalcData from the ICalcData object being registered.
        /// </param>
        /// /// <param name="sheetFamilyID">An integer previously created with a call
        /// to CalcEngine.CreateSheetFamilyID. This number is used to identify
        /// the ICalcData objects as belonging to a particular family of ICalcData objects. You can only reference
        /// ICalcData objects from within the same family.
        /// </param>
        /// <remarks>
        /// Essential Calculate supports multisheet references with its formulas. For example, if you
        /// have two ICalcData objects, then you can reference cells from the first ICalcData object
        /// in the second ICalcData object. For this to work, both ICalcData objects need to be registered using this method.
        /// The syntax for using a sheet reference as part of a formula is to prefix a cell reference
        /// with the sheet reference name followed by an exclamation point.
        /// The formula "= sheet1!A1 + sheet2!C3" would add the value is cell A1 for
        /// the ICalcData object whose reference name is sheet1 to the value from cell C3 in the ICalcData object
        /// whose reference name is sheet2.
        /// </remarks>
        /// <example> Use this code to use cross sheet references:
        /// <code lang="C#">
        ///		//Register three ICalcData objects so cell can be referenced across ICalcData objects:
        ///		int sheetfamilyID = CalcEngine.CreateSheetFamilyID();
        ///		myCalcEngine.RegisterGridAsSheet("summary", calcData1, sheetfamilyID);
        ///		myCalcEngine.RegisterGridAsSheet("income", calcData2, sheetfamilyID);
        ///		myCalcEngine.RegisterGridAsSheet("expenses", calcData3, sheetfamilyID);
        ///		....
        ///		//Sample formula usage for cells in calcData1, the 'summary' data source.
        ///		//This code sums ups some cells from calcData3, the 'expenses' data source
        ///		//and calcData2, the 'income' data source.
        ///		//Sum the range B2:B8 from expenses:
        ///		string sumExpenses = "= Sum(expenses!B2:expenses!B8)";
        ///		//Sum the range B2:B4 from income:
        ///		string sumIncome = "= Sum(income!B2:income!B4)";
        /// </code>
        /// <code lang="VB">
        ///		'Register three ICalcData objects so cell can be referenced across ICalcData objects:
        ///		Dim sheetfamilyID As Integer = CalcEngine.CreateSheetFamilyID();
        ///		myCalcEngine.RegisterGridAsSheet("summary", calcData1, sheetfamilyID)
        ///		myCalcEngine.RegisterGridAsSheet("income", calcData2, sheetfamilyID)
        ///		myCalcEngine.RegisterGridAsSheet("expenses", calcData3, sheetfamilyID)
        ///		....
        ///		'Sample formula usage for cells in calcData1, the 'summary' data source.
        ///		'This code sums ups some cells from calcData3, the 'expenses' data source
        ///		'and calcData2, the 'income' data source.
        ///		'Sum the range B2:B8 from expenses:
        ///		Dim sumExpenses As String = "= Sum(expenses!B2:expenses!B8)"
        ///		'Sum the range B2:B4 from income:
        ///		Dim sumIncome As String = "= Sum(income!B2:income!B4)"
        /// </code>
        /// </example>
        public void RegisterGridAsSheet(string refName, ICalcData model, int sheetFamilyID)
        {
            ////refName = refName.Replace(" ", ""); //keep the spaces defect#541

            if (modelToSheetID != null)
            {
                model.WireParentObject();
                model.ValueChanged += new ValueChangedEventHandler(this.grid_ValueChanged);
            }

            if (modelToSheetID == null)
            {
                modelToSheetID = new Hashtable();
            }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            if (modelToSheetID[model] == null)
#else
            if(!modelToSheetID.ContainsKey(model))
#endif
            {
                modelToSheetID.Add(model, sheetFamilyID);
            }

            GridSheetFamilyItem family = GetSheetFamilyItem(model);
            family.isSheeted = true;

            string refName1 = refName.ToUpper();
            if (family.SheetNameToParentObject == null)
            {
                family.SheetNameToParentObject = new Hashtable();
            }

            if (family.TokenToParentObject == null)
            {
                family.TokenToParentObject = new Hashtable();
            }

            if (family.SheetNameToToken == null)
            {
                family.SheetNameToToken = new Hashtable();
            }

            if (family.ParentObjectToToken == null)
            {
                family.ParentObjectToToken = new Hashtable();
            }

            if (family.SheetNameToParentObject.ContainsKey(refName1))
            {
                string token = (string)family.SheetNameToToken[refName1];
                family.TokenToParentObject[token] = model;
                family.ParentObjectToToken[model] = token;
            }
            else
            {
                string token = sheetToken + TokenCount.ToString() + sheetToken;
                TokenCount++;
                family.TokenToParentObject.Add(token, model);
                family.SheetNameToToken.Add(refName1, token);
                family.SheetNameToParentObject.Add(refName1, model);
                family.ParentObjectToToken.Add(model, token);
                this.sortedSheetNames = null;
            }
        }

        /// <summary>
        /// Registers a list of variable names so you can use it within formulas.
        /// </summary>
        /// <param name="list">List of names.</param>
        public void RegisterVariableNames(string[] list)
        {
            if (this.variableNamesToTokens == null)
            {
                this.variableNamesToTokens = new Hashtable();
                this.variableTokensToNames = new Hashtable();
            }

            foreach (string s in list)
            {
                string s1 = s.Trim().ToLower();
                if (!this.variableNamesToTokens.ContainsKey(s1))
                {
                    string token = "A" + (this.variableNamesToTokens.Count + 1).ToString();
                    this.variableNamesToTokens.Add(s1, token);
                    this.variableTokensToNames.Add(token, s);
                }
            }
        }

        /// <summary>
        /// A method that removes a function from the function library.
        /// </summary>
        /// <param name="name">The name of the function to be removed.</param>
        /// <returns>True if successfully removed, otherwise False.</returns>
        public bool RemoveFunction(string name)
        {
            if (this.LibraryFunctions[name] != null)
            {
                this.LibraryFunctions.Remove(name);
                return true;
            }

            return false;
        }

        /// <summary>
        /// Removes a range from the NamedRanges collection.
        /// </summary>
        /// <param name="name">The name of the range to be removed.</param>
        /// <returns>True if successfully removed, otherwise False.</returns>
        public bool RemoveNamedRange(string name)
        {
            name = name.ToUpper(CultureInfo.InvariantCulture);
            if (this.NamedRanges[name] != null)
            {
                this.NamedRanges.Remove(name);
                PopulateNamedRangesNonScoped();
                return true;
            }

            return false;
        }

        /// <summary>
        /// A method to reset the cached ICalcData object IDs.
        /// </summary>
        public static void ResetSheetFamilyID()
        {
            sheetFamilyID = 0;

            if (modelToSheetID != null)
            {
                modelToSheetID.Clear();
                modelToSheetID = null;
            }

            if (sheetFamiliesList != null)
            {
                sheetFamiliesList.Clear();
                sheetFamiliesList = null;
                //Fix for defect #12445.
                ResetSheetIDs();
            }
        }

        /// <summary>
        /// Resets the internal sheet token marker to 0.
        /// </summary>
        /// <remarks>
        /// When RegisterGridAsSheet is called to add a ICalcData object to a CalcEngine,
        /// this newly added sheet is associated with an integer used in tokenizing formulas.
        /// This sheetID integer is required in the PullUpdatedValue method to specify the ICalcData
        /// object being accessed. The GetSheetID method allows you to retrieve a sheetID given
        /// an ICalcData object. This internal sheet token marker is a static member of CalcEngine,
        /// and is incremented each time a new ICalcData object is registered with the CalcEngine
        /// using RegisterGridAsSheet.
        /// </remarks>
        public static void ResetSheetIDs()
        {
            TokenCount = 0;
        }

        /// <summary>
        /// Clears any variable names registered with the CalcEngine.
        /// </summary>
        public void ResetVariableNames()
        {
            if (this.variableNamesToTokens != null)
            {
                this.variableNamesToTokens.Clear();
                this.variableNamesToTokens = null;
                this.variableTokensToNames.Clear();
                this.variableTokensToNames = null;
            }
        }

        /// <summary>
        /// A method to retrieve the row index from a cell reference.
        /// </summary>
        /// <param name="s">String holding a cell reference such as C21 or AB11.</param>
        /// <returns>An integer with the corresponding row number.</returns>
        public int RowIndex(string s)
        {
            int i = 0;
            int result;

            bool isLetter = false;
            if (i < s.Length && s[i] == sheetToken)
            {
                i++;
                while (i < s.Length && s[i] != sheetToken)
                {
                    i++;
                }

                i++;
            }

            while (i < s.Length && char.IsLetter(s[i]))
            {
                isLetter = true;
                i++;
            }

            if (i < s.Length && int.TryParse(s.Substring(i), out result))
            {
                return result;
            }

            if (isLetter)
            {
                return -1;
            }
            throw new ArgumentException(this.FormulaErrorStrings[bad_index]);
        }

        private Hashtable SaveStrings(ref string text)
        {
            Hashtable strings = null;
            string TICs2 = this.TIC + this.TIC;
            int id = 0;

            int i = -1;
            if ((i = text.IndexOf(this.TIC)) > -1)
            {
                while (i > -1 && i < text.Length)
                {
                    if (strings == null)
                    {
                        strings = new Hashtable();
                    }

                    int j = (i + 1) < text.Length ? text.IndexOf(this.TIC, i + 1) : -1;
                    if (j > -1)
                    {
                        string key = this.TIC + UNIQUESTRINGMARKER + id.ToString() + this.TIC;
                        if (j < text.Length - 2 && text[j + 1] == this.TIC[0])
                        {
                            j = text.IndexOf(this.TIC, j + 2);
                            if (j == -1)
                            {
                                throw new ArgumentException(this.FormulaErrorStrings[mismatched_tics]);
                            }
                        }

                        string s = text.Substring(i, j - i + 1);
                        strings.Add(key, s);
                        s = s.Replace(TICs2, this.TIC);
                        id++;
                        text = text.Substring(0, i) + key + text.Substring(j + 1);
                        i = i + key.Length;
                        if (i < text.Length)
                        {
                            i = text.IndexOf(this.TIC, i);
                        }
                    }
                    else if (j == -1 && text.IndexOf(sheetToken) > -1 && i < text.IndexOf(sheetToken, i))
                    {
                        string sheetName = string.Empty;
                        for (int k = (text.IndexOf(sheetToken, i)) - 1; k > -1; k--)
                        {
                            if (!this.ValidPrecedingChars.Contains(text[k].ToString()))
                                sheetName = text[k] + sheetName;
                            else
                                break;
                        }
                        if (!(sheetName.StartsWith("'") && sheetName.EndsWith("'")))
                        {
                            throw new ArgumentException(this.FormulaErrorStrings[mismatched_tics]);
                        }
                        if (sheetName.StartsWith("'"))
                            sheetName = sheetName.Remove(0, 1);
                        if (sheetName.EndsWith("'"))
                            sheetName = sheetName.Remove(sheetName.Length - 1, 1);
                        if (!this.SortedSheetNames.Contains(sheetName.ToUpper()))
                        {
                            throw new ArgumentException(this.FormulaErrorStrings[missing_sheet]);
                        }
                        if ((i + 1) < text.Length)
                        {
                            i = text.IndexOf(this.TIC, i + 1);
                        }
                    }
                    else
                    {
                        throw new ArgumentException(this.FormulaErrorStrings[mismatched_tics]);
                    }
                }
            }

            return strings;
        }

        private double sd(double[] x, out double xbar)
        {
            int n = x.GetLength(0);
            xbar = 0;
            for (int i = 0; i < n; ++i)
            {
                xbar += x[i];
            }

            xbar = xbar / n;
            double sumx2 = 0;
            double d = 0;

            for (int i = 0; i < n; ++i)
            {
                d = x[i] - xbar;
                sumx2 += d * d;
            }

            return Math.Sqrt(sumx2 / (n - 1));
        }
        /// <summary>
        /// Returns the m parameter of the exponential curve y = b * m^x that best fits the given points. Only the first two Excel parameters are used.
        /// </summary>
        /// <param name="range">Y_range, x_range.</param>
        /// <returns>returns m parameter.</returns>
        public string ComputeLogest(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            bool padXValues = argCount == 1;
            if (argCount == 0 || argCount > 4)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }
            double[] y = GetDoubleArray(args[0]);
            double[] x = null;
            if (argCount > 1 && args[1] == string.Empty)
            {
                x = y;
            }
            else
            {
                x = padXValues ? new double[y.GetLength(0)] : GetDoubleArray(args[1]);
            }
            int n = x.GetLength(0);

            if (n <= 1)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }
            if (padXValues)
            {
                for (int i = 0; i < n; ++i)
                {
                    x[i] = (double)(i + 1);
                }
            }

            for (int i = 0; i < n; ++i)
            {
                y[i] = Math.Log10(y[i]);
            }

            double m = 0;
            double b = 1;

            ComputeLogestMB(y, x, out m, out b);
            return m.ToString();
        }

        /// <summary>
        /// Returns the growth estimate using the exponential curve y = b * m^x that best fits the given points. Only the first two Excel parameters are used.
        /// </summary>
        /// <param name="range">Y_range, x_range.</param>
        /// <returns>returns estimated value.</returns>
        public string ComputeGrowth(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            bool padXValues = argCount == 1;
            if (argCount == 0 || argCount > 4)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }
            double[] y = GetDoubleArray(args[0]);
            double[] x = null;
            if (argCount > 1 && args[1] == string.Empty)
            {
                x = y;
            }
            else
            {
                x = padXValues ? new double[y.GetLength(0)] : GetDoubleArray(args[1]);
            }
            double[] newx = argCount < 3 ? new double[x.GetLength(0)] : GetDoubleArray(args[2]);

            int n = x.GetLength(0);

            if (n <= 2 || n != y.GetLength(0))
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }
            if (padXValues)
            {
                for (int i = 0; i < n; ++i)
                {
                    x[i] = (double)(i + 1);
                }
            }

            for (int i = 0; i < n; ++i)
            {
                y[i] = Math.Log10(y[i]);
            }

            double m = 0;
            double b = 1;

            ComputeLogestMB(y, x, out m, out b);

            int n1 = newx.GetLength(0);
            if (argCount < 3)
            {
                for (int i = 0; i < n1; ++i)
                {
                    newx[i] = x[i];
                }
            }

            for (int i = 0; i < n1; ++i)
            {
                newx[i] = b * Math.Pow(m, newx[i]);
            }
            if (n1 > 1)
            {
                string[] cells = GetCellsFromArgs(args[2]);
                bool isColumn = RowIndex(cells[0]) == RowIndex(cells[1]);
                for (int i = 1; i < n1; ++i)
                {
                    grid.SetValueRowCol(newx[i], RowIndex(cell), ColIndex(cell));
                }
            }
            return newx[0].ToString();
        }
        /// <summary>
        /// Returns the m and b value used in exponential curve y = b * m^x.
        /// </summary>
        /// <param name="y">The set of y-values required in y = b*m^x</param>
        /// <param name="x">The set of x-values in y = b*m^x</param>
        /// <returns>returns calculated b value.</returns>
        internal void ComputeLogestMB(double[] y, double[] x, out double m, out double b)
        {
            m = 0;
            b = 1;


            int n = x.GetLength(0);
            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += (double)x[i];
                sumy += (double)y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = (double)x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }

            b = Math.Pow(10, sumy - sumxy / sumx2 * sumx);
            m = Math.Pow(10, sumxy / sumx2);
        }

        /// <summary>
        /// Returns the b value from the exponential curve y = b * m^x.
        /// </summary>
        /// <param name="range">Y_range, x_range.</param>
        /// <returns>returns calculated b value.</returns>
        public string ComputeLogestb(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            bool padXValues = argCount == 1;
            if (argCount == 0 || argCount > 4)
            {
#if _ENABLETIMERS
                MarkTimeEnd(ML);
#endif
                return FormulaErrorStrings[wrong_number_arguments];
            }
            double[] y = GetDoubleArray(args[0]);
            double[] x = padXValues ? new double[y.GetLength(0)] : GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 2 || n != y.GetLength(0))
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }
            if (padXValues)
            {
                for (int i = 0; i < n; ++i)
                {
                    x[i] = (double)(i + 1);
                }
            }

            for (int i = 0; i < n; ++i)
            {
                y[i] = Math.Log10(y[i]);
            }

            double m = 0;
            double b = 1;

            ComputeLogestMB(y, x, out m, out b);

            return b.ToString();
        }
        private void SetStrings(ref string retValue, Hashtable strings)
        {
            foreach (string s in strings.Keys)
            {
                retValue = retValue.Replace(s, (string)strings[s]);
            }
        }

        private string SheetToken(string s)
        {
            int i = 0;
            string s1 = string.Empty;
            if (i < s.Length && s[i] == sheetToken)
            {
                i++;
                while (i < s.Length && s[i] != sheetToken)
                {
                    i++;
                }

                s1 = s.Substring(0, i + 1);
            }

            if (i < s.Length)
            {
                return s1;
            }

            throw new ArgumentException(this.FormulaErrorStrings[bad_index]);
        }

        /// <summary>
        /// Removes outer quote marks from a string with no inner quote marks.
        /// </summary>
        /// <param name="s">The string with possible outer quote marks.</param>
        /// <returns>The string with any outer quote marks removed.</returns>
        /// <remarks>This is a utility method that removes outer quotes on a string.</remarks>
        public string StripTics(string s)
        {
            if (s.Length > 1 && s[0] == this.TIC[0] && s[s.Length - 1] == this.TIC[0])
            {
                if (s.Substring(1, s.Length - 2).IndexOf(this.TIC) == -1)
                {
                    s = s.Substring(1, s.Length - 2);
                }
                else if (multiTick)
                {
                    s = s.Substring(1, s.Length - 2);
                }
            }

            return s;
        }

        private string StripTics0(string s)
        {
            if (s.Length > 1 && s[0] == this.TIC[0] && s[s.Length - 1] == this.TIC[0])
            {
                s = s.Substring(1, s.Length - 2);
            }

            return s;
        }

