        /// Tests whether a string is NULL or empty.
        /// </summary>
        /// <param name="s">String to be tested.</param>
        /// <returns>True is passed in string is null or empty, otherwise False.</returns>
        static bool TextIsEmpty(string s)
        {
            return s == null || s == string.Empty;
        }

        /// <summary>
        /// An overridden method to display information on the cell currently being calculated.
        /// </summary>
        /// <returns>String with information on the cell currently being calculated.</returns>
        public override string ToString()
        {
            return "CalcEngine { Cell: " + (this.cell != null ? this.cell.ToString() : "null") + " " + (DependentCells != null ? DependentCells.Count : -1).ToString() + "}";
        }

        /// <summary>
        /// Unregisters a grid so it can no longer be referenced in a formula from another grid.
        /// </summary>
        /// <param name="refName">The reference name used to refer to this grid from formulas in other grids.
        /// </param>
        /// <param name="model">The grid model.</param>
        public static void UnregisterGridAsSheet(string refName, ICalcData model)
        {
            GridSheetFamilyItem family = GetSheetFamilyItem(model);
            string refName1 = refName.ToUpper();
            if (family.SheetNameToParentObject != null && family.SheetNameToParentObject.ContainsKey(refName1))
            {
                family.SheetNameToParentObject.Remove(refName1);
                string token = (string)family.SheetNameToToken[refName1];

                family.SheetNameToToken.Remove(refName1);
                family.TokenToParentObject.Remove(token);
                family.ParentObjectToToken.Remove(model);
            }
        }

        /// <summary>
        /// A method that increases the calculation level of the CalcEngine.
        /// </summary>
        /// <remarks>Every formula has a calculation ID level associated with it. Every time
        /// a formula is retrieved, its calculation ID level is compared with the CalcEngine
        /// ID level. If they do not agree, the formula is recomputed. Calling UpdateCalcID
        /// will force any formula to be recomputed the next time it is retrieved.
        /// </remarks>
        public void UpdateCalcID()
        {
            this.calcID++;
            if (this.calcID == int.MaxValue)
            {
                this.calcID = int.MinValue + 1;
            }
        }

        internal void UpdateDependencies(string s)
        {
            ////TraceUtil.TraceCurrentMethodInfoIf(Switches.FormulaCell.TraceVerbose, this);
            if (this.lockDependencies || !this.UseDependencies)
            {
                return;
            }
#if _ENABLETIMERS
            string ML = "UpdateDependencies"; MarkTimeStart(ML);
#endif

            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            string cell1 = this.cell;
#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            if (family.SheetNameToParentObject != null && cell1.IndexOf(sheetToken) == -1)
#else
            if (family.ParentObjectToToken != null && family.ParentObjectToToken.ContainsKey(this.grid) &&
                cell1.IndexOf(sheetToken) == -1)
#endif
            {
                string token = family.ParentObjectToToken[this.grid] as string;
                cell1 = token + cell1;
            }

#if !SILVERLIGHT && !WINDOWS_UWP && !WP
            if (family.SheetNameToParentObject != null && s.IndexOf(sheetToken) == -1)
#else
            if (family.ParentObjectToToken != null && family.ParentObjectToToken.ContainsKey(this.grid)  && 
                s.IndexOf(sheetToken) == -1)
#endif
            {
                string token = family.ParentObjectToToken[this.grid] as string;
                s = token + s;
            }

            if (!DependentCells.ContainsKey(s))
            {
                ArrayList ht1 = new ArrayList();
                this.DependentCells.Add(s, ht1);

                ht1.Add(cell1);

                if (this.DependentFormulaCells.ContainsKey(s))
                {
                    Hashtable ht = (Hashtable)this.DependentFormulaCells[s];
                    if (ht != null)
                    {
                        foreach (object o in ht.Keys)
                        {
                            string s1 = o as string;
                            ArrayList ht2 = (ArrayList)DependentCells[s1];
                            if (ht2 == null)
                            {
                                ht2 = new ArrayList();
                                this.DependentCells.Add(s1, ht2);
                            }

                            if (ht2.IndexOf(cell1) == -1)
                            {
                                ht2.Add(cell1);
                            }
                        }
                    }
                }

                ////	else
                this.AddToFormulaDependentCells(s);

                if (this.DependentCells.ContainsKey(cell1))
                {
                    ArrayList ht = (ArrayList)this.DependentCells[cell1];
                    if (ht != null && ht != ht1)
                    {
                        foreach (object o in ht)
                        {
                            string s1 = o as string;
                            ht1.Add(s1);
                        }
                    }
                }
            }
            else
            {
                ArrayList ht1 = (ArrayList)DependentCells[s];

                if (ht1.IndexOf(cell1) == -1)
                {
                    ht1.Add(cell1);
                }

                this.AddToFormulaDependentCells(s);

                ////maybe remove this block ..... not needed if other dependencies working OK
                if (this.DependentFormulaCells.ContainsKey(s))
                {
                    Hashtable ht = (Hashtable)this.DependentFormulaCells[s];
                    if (ht != null)
                    {
                        foreach (object o in ht.Keys)
                        {
                            string s1 = o as string;
                            ArrayList ht2 = (ArrayList)DependentCells[s1];
                            if (ht2 == null)
                            {
                                ht2 = new ArrayList();
                                this.DependentCells.Add(s1, ht2);
                            }

                            if (ht2.IndexOf(cell1) == -1)
                            {
                                ht2.Add(cell1);
                            }
                        }
                    }
                }
            }

#if _ENABLETIMERS
            MarkTimeEnd(ML);
#endif
        }

        /// <summary>
        /// Triggers a calculation for any value depending upon the given cell.
        /// </summary>
        /// <param name="cell1">The cell.</param>
        public void UpdateDependenciesAndCell(string cell1)
        {
            ICalcData grd = this.grid;
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

            string sheet = this.SheetToken(cell1);
            if (sheet.Length > 0)
            {
                this.grid = family.TokenToParentObject[sheet] as ICalcData;
            }

            if (this.FormulaInfoTable.ContainsKey(cell1))
            {
                FormulaInfo formula = this.FormulaInfoTable[cell1] as FormulaInfo;
                if (formula.calcID != this.calcID)
                {
                    string saveCell = this.cell;
                    this.cell = cell1;

                    if (this.iterationMaxCount > 0 && circCheckList.IndexOf(this.cell) > -1)
                    {
                        this.HandleIterations(formula);
                    }
                    else
                    {
                        formula.FormulaValue = this.ComputeFormula(formula.ParsedFormula);
                    }

                    if (this.DependentCells.ContainsKey(cell1))
                    {
                        ArrayList ht = (ArrayList)this.DependentCells[cell1];
                        foreach (string s in ht)
                        {
                            FormulaInfo f = this.FormulaInfoTable[s] as FormulaInfo;
                            if (f != null)
                            {
                                f.calcID = int.MinValue; ////mark as dirty
                            }
                        }
                    }

                    formula.calcID = this.calcID;
                    this.cell = saveCell;
                }

                bool saveIVC = this.IgnoreValueChanged;
                this.IgnoreValueChanged = true;

                int row = this.RowIndex(cell1);
                int col = this.ColIndex(cell1);
                if(PreserveFormula)
                this.grid.SetValueRowCol(formula.FormulaText, row, col);
                this.IgnoreValueChanged = saveIVC;

                this.grid = grd;

                if (this.processedCells.Contains(cell1))
                {
                    return;
                }
                else
                {
                    this.processedCells.Add(cell1);
                }
                this.grid.SetValueRowCol(formula.FormulaValue, row, col);
                if (this.DependentFormulaCells.ContainsKey(cell1))
                {
                    Hashtable ht = (Hashtable)this.DependentFormulaCells[cell1];
                    foreach (string c in ht.Keys)
                    {
                        this.UpdateDependenciesAndCell(c); ////recursive call
                    }
                }
            }
        }

        private double var(double[] x)
        {
            double sumx = 0;
            int n = x.GetLength(0);
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
            }

            sumx = sumx / n;

            double sumx2 = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumx2 += d * d;
            }

            return sumx2 / (n - 1);
        }

        private string ZapBlocks(string text)
        {
            if (text.IndexOf(BMARKER) > -1)
            {
                int bracketLevel = 0;
                for (int i = text.Length - 1; i > 0; --i)
                {
                    if (text[i] == this.RIGHTBRACKET)
                    {
                        bracketLevel--;
                    }
                    else if (text[i] == this.LEFTBRACKET)
                    {
                        bracketLevel++;
                    }
                    else if (text[i] == BMARKER && bracketLevel == 0)
                    {
                        text.Remove(i, 1);
                    }
                }
            }

            return text;
        }

        private string ZapQuotedColons(string s)
        {
            int start = s.IndexOf(this.TIC);
            while (start > -1)
            {
                int end = s.Substring(start + 1).IndexOf(this.TIC);
                if (end > -1)
                {
                    int i = s.Substring(start + 1).IndexOf(':');
                    while (i > -1 && i < end)
                    {
                        s = s.Substring(i + start) + " " + s.Substring(i + start + 1);
                        i = s.Substring(start + 1).IndexOf(':');
                    }
                }

                start = end;
            }

            return s;
        }

